window.DEEP_STORIES["telescope"] = {"slug":"telescope","title":"The Telescope","emoji":"🔭","tagline":"Two lenses in a tube, and the whole universe opened up","intro":"Look up on a dark night and you can see a few thousand stars. Look through a telescope and you can see billions of galaxies. This Deep Dive is the story of how people learned to do that. It starts with polished crystals and Italian eyeglasses, jumps to a Dutch spectacle shop in 1608, and follows Galileo as he points a homemade spyglass at the sky and finds mountains on the Moon and moons around Jupiter. Then come Newton's mirror, telescopes longer than a ship, a musician who found a new planet, mountaintop giants, and the discovery that our Milky Way is just one galaxy among countless others. We will learn how lenses and mirrors really work, tune in to radio waves from space, fix a broken space telescope, unfold a golden mirror a million miles from home, and peek at the giant telescopes still being built. Twenty parts, 400 years, one amazing tube. Let's look!","outline":[{"n":1,"title":"Eyes on the Sky","when":"Ancient times – 1601"},{"n":2,"title":"Magic Glass: Lenses and Spectacles","when":"About 750 BCE – 1500s"},{"n":3,"title":"1608: The Spyglass Appears","when":"1608 – 1609"},{"n":4,"title":"Galileo Turns It Upward","when":"1609 – 1610"},{"n":5,"title":"Phases, Spots and Trouble","when":"1610 – 1642"},{"n":6,"title":"Kepler's Design and the Super-Long Telescopes","when":"1611 – 1690s"},{"n":7,"title":"Newton's Mirror","when":"1663 – 1720s"},{"n":8,"title":"Fixing the Rainbow: Better Lenses","when":"1730s – 1838"},{"n":9,"title":"The Herschels: A New Planet","when":"1770s – 1840s"},{"n":10,"title":"Telescopes Change Life on Earth","when":"1600s – 1900s"},{"n":11,"title":"The Leviathan and the Great Refractors","when":"1845 – 1897"},{"n":12,"title":"Cameras and Rainbows: Photography and Spectroscopy","when":"1840 – 1925"},{"n":13,"title":"Giant Mirrors and a Universe of Galaxies","when":"1904 – 1949"},{"n":14,"title":"How a Telescope Really Works","when":"The science"},{"n":15,"title":"Invisible Light: Radio Telescopes","when":"1932 – 2022"},{"n":16,"title":"Above the Air: Hubble and the Space Telescopes","when":"1946 – today"},{"n":17,"title":"Mirrors in Pieces and Twinkle-Cancelling","when":"1969 – today"},{"n":18,"title":"JWST: The Golden Eye","when":"1989 – today"},{"n":19,"title":"Trouble in Sight","when":"1600s – today"},{"n":20,"title":"Tomorrow's Telescopes and the Big Picture","when":"Today – 2040s"}],"people":[["Ptolemy (about 100–170 CE)","Greek-Egyptian astronomer whose Earth-centered model ruled for 1,400 years"],["Ibn al-Haytham / Alhazen (about 965–about 1040)","Arab scientist whose Book of Optics founded the experimental study of light"],["Roger Bacon (about 1220–1292)","English friar who wrote about magnifying with lenses"],["Nicolaus Copernicus (1473–1543)","Polish astronomer who proposed the Sun-centered system"],["Tycho Brahe (1546–1601)","Danish astronomer, the most accurate naked-eye observer"],["Hans Lipperhey (about 1570–1619)","spectacle maker in Middelburg; first known telescope patent application, 1608"],["Jacob Metius (about 1571–1628)","Dutch instrument maker who also applied for a telescope patent in 1608"],["Zacharias Janssen (about 1585–about 1632)","Middelburg spectacle maker; his claim to the telescope is doubtful"],["Thomas Harriot (about 1560–1621)","English scientist who drew the Moon through a telescope in July 1609"],["Galileo Galilei (1564–1642)","Italian scientist who made the telescope a scientific tool and found Jupiter's moons"],["Johannes Kepler (1571–1630)","German astronomer who designed the two-convex-lens telescope (1611)"],["Simon Marius (1573–1625)","German astronomer who named Jupiter's four big moons"],["Christoph Scheiner (1573–1650)","Jesuit astronomer who studied sunspots and built Keplerian telescopes"],["William Gascoigne (1612–1644)","English astronomer who invented the telescope micrometer"],["Johannes Hevelius (1611–1687)","Danzig astronomer famous for extremely long telescopes and Moon maps"],["Christiaan Huygens (1629–1695)","Dutch scientist who found Titan and explained Saturn's rings"],["Giovanni Domenico Cassini (1625–1712)","Italian-French astronomer who found four Saturn moons and the Cassini Division"],["Ole Rømer (1644–1710)","Danish astronomer who showed light has a finite speed (1676)"],["James Gregory (1638–1675)","Scottish mathematician who designed a reflecting telescope in 1663"],["Isaac Newton (1643–1727)","English scientist who built the first practical reflecting telescope (1668)"],["Laurent Cassegrain (about 1629–1693)","French priest whose 1672 reflector design is used widely today"],["John Hadley (1682–1744)","English maker of the first really good reflecting telescope (1721)"],["John Flamsteed (1646–1719)","first Astronomer Royal at Greenwich"],["Chester Moor Hall (1703–1771)","English lawyer who first made achromatic lenses (around 1733)"],["John Dollond (1706–1761)","English optician who patented the achromatic lens (1758)"],["Pierre-Louis Guinand (1748–1824)","Swiss craftsman who improved optical glass making"],["Joseph von Fraunhofer (1787–1826)","German optician who mapped dark lines in sunlight and built superb refractors"],["Friedrich Bessel (1784–1846)","German astronomer who first measured a star's distance (1838)"],["William Herschel (1738–1822)","German-British musician-astronomer who discovered Uranus and infrared light"],["Caroline Herschel (1750–1848)","astronomer who discovered comets and nebulae; first woman paid for scientific work"],["Johann Bode (1747–1826)","German astronomer who proposed the name Uranus"],["Ignazio Porro (1801–1875)","Italian inventor of the prism system used in binoculars"],["William Parsons, 3rd Earl of Rosse (1800–1867)","built the 72-inch Leviathan and saw spiral nebulae"],["Urbain Le Verrier (1811–1877)","French mathematician who predicted Neptune's position"],["John Couch Adams (1819–1892)","English mathematician who also predicted Neptune"],["Johann Galle (1812–1910)","German astronomer who first saw Neptune (1846), helped by Heinrich d'Arrest (1822–1875)"],["Léon Foucault (1819–1868) and Carl August von Steinheil (1801–1870)","pioneers of silver-coated glass mirrors"],["Alvan Clark (1804–1887)","American lens maker whose firm made the Lick and Yerkes lenses"],["John William Draper (1811–1882)","took early photographs of the Moon (1840)"],["Henry Draper (1837–1882)","photographed the Orion Nebula (1880); a big star catalog is named for him"],["Gustav Kirchhoff (1824–1887) and Robert Bunsen (1811–1899)","showed elements have unique spectral lines (1859)"],["William Huggins (1824–1910) and Margaret Huggins (1848–1915)","pioneers of astronomical spectroscopy"],["Jules Janssen (1824–1907) and Norman Lockyer (1836–1920)","studied the 1868 solar spectrum line that led to helium"],["Edward Pickering (1846–1919)","Harvard Observatory director who hired the 'Harvard computers'"],["Williamina Fleming (1857–1911)","Harvard astronomer who classified thousands of stars and found the Horsehead Nebula"],["Annie Jump Cannon (1863–1941)","created the OBAFGKM star classification"],["Henrietta Swan Leavitt (1868–1921)","discovered the Cepheid period-luminosity relation (1912)"],["Cecilia Payne-Gaposchkin (1900–1979)","showed stars are mostly hydrogen and helium (1925)"],["Vesto Slipher (1875–1969)","measured the speeds of spiral galaxies from 1912"],["George Ellery Hale (1868–1938)","built Yerkes, Mount Wilson and planned Palomar"],["Harlow Shapley (1885–1972) and Heber Curtis (1872–1942)","opponents in the 1920 Great Debate"],["Edwin Hubble (1889–1953)","proved galaxies lie beyond the Milky Way and measured their recession"],["Milton Humason (1891–1972)","former mule driver at Mount Wilson who became Hubble's key observing partner"],["Georges Lemaître (1894–1966)","Belgian priest-physicist who first proposed the expanding universe (1927)"],["Russell W. Porter (1871–1949)","leader of amateur telescope making and Stellafane"],["John Dobson (1915–2014)","popularized simple, cheap 'Dobsonian' telescopes and sidewalk astronomy"],["Karl Jansky (1905–1950)","Bell Labs engineer who discovered cosmic radio waves"],["Grote Reber (1911–2002)","built the first dish radio telescope in his backyard (1937)"],["Bernard Lovell (1913–2012)","built the Jodrell Bank 76-meter radio telescope"],["Arno Penzias (1933–2024) and Robert Wilson (born 1936)","discovered the cosmic microwave background"],["Maarten Schmidt (1929–2022)","identified the first quasar (1963)"],["Jocelyn Bell Burnell (born 1943)","discovered pulsars as a PhD student (1967)"],["Antony Hewish (1924–2021) and Martin Ryle (1918–1984)","radio astronomers who shared the 1974 Nobel Prize"],["Lyman Spitzer (1914–1997)","proposed space telescopes in 1946"],["Nancy Grace Roman (1925–2018)","NASA's first chief of astronomy, the 'mother of Hubble'"],["Riccardo Giacconi (1931–2018)","pioneer of X-ray astronomy (Uhuru, Chandra)"],["Willard Boyle (1924–2011) and George Smith (1930–2025)","invented the CCD (1969)"],["Jerry Nelson (1944–2017)","designed the segmented mirrors of the Keck telescopes"],["Vera Rubin (1928–2016)","astronomer whose galaxy rotation measurements supported dark matter"],["James Webb (1906–1992)","NASA administrator 1961–1968, namesake of JWST"]],"glossary":[["lens","a curved piece of clear glass that bends light"],["convex lens","bulges outward in the middle and brings light together to a focus"],["refraction","the bending of light when it passes from one material into another, like air into glass"],["refracting telescope (refractor)","a telescope that uses a lens to collect and focus light"],["reflecting telescope (reflector)","a telescope that uses a curved mirror to collect and focus light"],["objective","the big main lens or mirror that collects the light"],["eyepiece","the small lens you look through that magnifies the image"],["focal length","the distance from a lens or mirror to the point where it brings light into focus"],["magnification","how many times bigger something looks; objective focal length divided by eyepiece focal length"],["aperture","the width of the main lens or mirror; the most important number of any telescope"],["resolution","how fine a detail a telescope can show"],["chromatic aberration","rainbow-colored blurring because a lens bends each color by a different amount"],["achromatic lens","two lenses of different glass glued or set together so their color errors cancel"],["spectrum / spectroscopy","light spread into its colors; studying the lines in it to learn what things are made of and how they move"],["electromagnetic spectrum","the whole family of light, from radio waves to gamma rays; our eyes see only a thin slice"],["redshift","light stretched toward longer, redder wavelengths, usually because the source is moving away or space is expanding"],["interferometry","linking several telescopes so they act like one much bigger telescope for seeing fine detail"],["adaptive optics","a system that bends a flexible mirror many times a second to cancel the blur of Earth's air"],["CCD","a light-sensing electronic chip that turns light into a digital image"],["light-year","the distance light travels in one year, about 9.5 trillion km"]],"parts":[{"n":1,"title":"Eyes on the Sky","when":"Ancient times – 1601","summary":"Long before telescopes, people studied the sky with only their eyes. Babylonians wrote star notes on clay, a prince in Samarkand built a measuring track as long as a swimming pool, and a Danish nobleman with a metal nose measured the stars better than anyone before him. But human eyes can only see so much.","sections":[{"heading":"A Sky Full of Pinpricks","paragraphs":["Imagine it is a summer night four thousand years ago, long before anyone had a lens to look through. There are no streetlights, no glowing windows, no cars. When the Sun goes down, the dark is deep and complete. You lie on your back on a warm flat roof and look up, and the sky is crowded with stars, so many that it is hard to pick out the famous patterns. Across the middle runs a pale, misty river of light. That is the Milky Way, and on a night like this it is bright enough to cast a very faint glow on the ground.","So what can a naked eye actually see? First, the Sun and the Moon, of course, the two biggest and brightest objects in the sky. Then there are the planets. Five of them are easy to spot without help: Mercury, Venus, Mars, Jupiter and Saturn. To ancient people they looked like stars, but they behaved strangely. The ordinary stars kept the same patterns night after night, year after year, like dots painted on a giant turning bowl. The planets slowly wandered through those patterns. The word planet comes from an old Greek word meaning wanderer.","Then there are the stars themselves. Astronomers measure how bright a star looks using a scale called magnitude, where smaller numbers mean brighter stars. On a typical dark night, a person with good eyes can see stars down to about magnitude 6. Across the entire sky, both the half above you and the half below the horizon, there are roughly 5,600 stars that bright. Since only half the sky is above you at any moment, and stars near the horizon are dimmed by haze, a person on a dark night sees a few thousand stars at once.","Under very dark skies, a sharp-eyed person can also see a few faint smudges that are not stars at all. One, in the constellation Andromeda, is a dim oval patch of light. Nobody in ancient times could have guessed what it really was. Today we know it is the Andromeda Galaxy, a vast spiral of hundreds of billions of stars, so far away that its light has been travelling for about two and a half million years. To the naked eye, it is just a little cloud. Keep that little cloud in mind, because it will come back much later in this story."]},{"heading":"Clay Tablets and Wandering Lights","paragraphs":["Some of the first people to keep careful written records of the sky lived in Mesopotamia, the land between the Tigris and Euphrates rivers in what is now Iraq. The Babylonians wrote by pressing a wedge-shaped reed into soft clay, making little triangle-shaped marks called cuneiform. Once the clay dried or was baked, the writing could last for thousands of years. Thousands of these tablets have been dug up, and many of them are about the sky.","Why did the Babylonians care so much? Partly for calendars. Their months followed the Moon, but twelve Moon-months add up to only about 354 days, which is about 11 days shorter than a year of seasons. To keep festivals and farming in step with the seasons, they had to add an extra thirteenth month every few years, and to know when, they had to watch the sky. They also believed that events in the sky were signs or messages about events on Earth, such as the fate of the king, the harvest or a war.","One famous tablet, known as the Venus Tablet of Ammisaduqa, records when the planet Venus first appeared and disappeared in the morning and evening sky over a period of about 21 years. Another text, called MUL.APIN, is like a star guide, listing constellations and the times of year when certain stars rise. Later, from roughly the 600s BCE onward, Babylonian scholars kept what historians now call the Astronomical Diaries: night-by-night notes on where the Moon and planets were, plus the weather, river levels and even the price of barley. These diaries were kept going for centuries.","All that patient record-keeping paid off. By comparing old notes, Babylonian astronomers discovered repeating cycles. One of them, now called the saros, is about 18 years long: after one saros, the Sun, Moon and Earth line up in nearly the same way again, so eclipses repeat in a pattern. That meant eclipses could be predicted. They also invented clever arithmetic methods to calculate where planets would be in the future.","The Babylonians also counted in sixties instead of tens. You still use their system every day without noticing. There are 60 seconds in a minute and 60 minutes in an hour, and a circle is divided into 360 degrees. Astronomers split each degree into 60 arcminutes, and each arcminute into 60 arcseconds. These tiny angle units will matter a lot in this story, because the whole history of the telescope is about measuring smaller and smaller angles in the sky."]},{"heading":"The Greeks Build a Model Universe","paragraphs":["The ancient Greeks learned a lot from Babylonian records, but they also tried to build a geometric model of the sky. Many Greek thinkers already knew the Earth was round. They saw that its shadow on the Moon during a lunar eclipse is always curved, and that travellers going south saw new stars rise above the horizon. A few Greeks went further. Aristarchus of Samos, who lived in the 200s BCE, suggested that the Sun, not the Earth, was at the center of everything. Very few people agreed with him. After all, the ground does not feel as if it is moving, so surely the Earth must be standing still.","Another ancient idea was even more amazing. The philosopher Democritus is said to have suggested that the Milky Way might be made of a huge number of stars, too faint and too close together to see one by one. Nobody could check this. It would take a telescope, and Galileo, to prove it.","The greatest Greek astronomy book was written around 150 CE by Claudius Ptolemy, who worked in Alexandria in Egypt. Its Greek title means something like The Mathematical Collection, but it became famous under the name Arab scholars later gave it: the Almagest, from an Arabic phrase meaning the greatest. It has 13 books, or chapters, and it includes a catalog of 1,022 stars arranged in 48 constellations, many of which we still use today, like Orion and Ursa Major.","Ptolemy's universe put a motionless, round Earth in the center. The Moon, Sun, planets and stars all circled around it. But there was a problem. Planets do not move smoothly. Mars, for example, sometimes seems to stop, drift backward for a few weeks, and then turn forward again. To explain this, Ptolemy used circles on top of circles. Each planet moved on a small circle, called an epicycle, whose center travelled around a big circle around the Earth. He added another clever adjustment, a point called the equant, to make the speeds come out right. It was complicated, but it worked well enough to predict planet positions for many centuries.","Ptolemy's system was not silly. With naked-eye measurements, it matched what people saw, and for about 1,400 years it was the standard picture of the universe in Europe, North Africa and the Middle East."]},{"heading":"Observatories of the Islamic World","paragraphs":["After the fall of the western Roman Empire, much of Europe lost touch with Greek science for a long time. But the knowledge did not vanish. From the 800s onward, scholars in Baghdad, Damascus, Cairo, Córdoba and other cities of the Islamic world translated Greek books like the Almagest into Arabic, checked them against the sky, and improved them. Astronomy had practical uses there too: Muslims needed to know the times of the five daily prayers, the direction of Mecca, and the start of each month of the Moon-based calendar.","One of these scholars was the Persian astronomer Abd al-Rahman al-Sufi. In 964 he published the Book of Fixed Stars, a beautifully illustrated guide that updated Ptolemy's star catalog with his own careful observations, including how bright each star looked. Many star names we still use, like Aldebaran, Betelgeuse and Rigel, come from Arabic. Al-Sufi also described a small cloudy patch in the constellation Andromeda. That is the earliest written description we have of the Andromeda Galaxy, the little cloud we met earlier.","The most spectacular observatory of all rose in Samarkand, in what is now Uzbekistan, in the 1420s. It was built by Ulugh Beg, a prince who was also a brilliant mathematician. He was a grandson of the conqueror Timur and ruled Samarkand, but his true love was the sky. Around 1417 to 1420 he built a school, or madrasa, in the city, and then an observatory on a hill outside it, where he gathered astronomers such as Jamshid al-Kashi, Qadi Zada al-Rumi and the young Ali Qushji.","The heart of the observatory was a gigantic instrument called the Fakhri sextant. It was a curved track, like a slice of a huge circle, with a radius of about 40 meters, as long as a big swimming pool. Part of it was dug into a trench in the hill, lined with marble and marked with careful scales. As the Sun or a star crossed the sky, its light fell on the track, and astronomers could read off its exact height. Why so big? With a bigger circle, each degree is spread over a longer stretch, so the markings can be finer and readings more precise. If you cannot make your eye sharper, you can make your ruler longer.","In 1437, Ulugh Beg's team finished a book of tables called the Zij-i Sultani. Its star catalog listed the positions of about 1,000 stars, measured fresh rather than copied from Ptolemy. It was the first major new star catalog since the Almagest. The team also measured the length of the year as 365 days, 5 hours, 49 minutes and 15 seconds, only about 25 seconds too long, which was more accurate than Copernicus's figure a century later.","The story ended sadly. In 1449 Ulugh Beg was killed in a power struggle that involved his own son, and his observatory was soon abandoned and ruined. Its location was lost for centuries until the Russian archaeologist Vassily Vyatkin found the remains of the great sextant in 1908. Visitors to Samarkand can still walk down into the curved stone trench today."]},{"heading":"Copernicus Moves the Sun","paragraphs":["Nicolaus Copernicus was born on 19 February 1473 in the town of Toruń, in what is now Poland. He studied in Kraków and in Italy, learning mathematics, astronomy, law and medicine, and spent most of his working life as a canon, an official of the cathedral, in the small town of Frombork near the Baltic Sea. In his spare time, he thought about the planets.","Copernicus did not like the complicated machinery of Ptolemy's system, especially the equant. Sometime before 1514 he wrote a short handwritten summary, now called the Commentariolus, or Little Commentary, suggesting a startling idea. What if the Sun stood near the center, and the Earth was just one of the planets, spinning once a day and circling the Sun once a year? He shared copies with only a few friends.","His idea explained something beautifully. Remember how Mars sometimes seems to move backward? In Copernicus's system, that happens naturally. Earth moves faster on its inside track, so every couple of years it overtakes Mars, the way a fast car on a racetrack passes a slower car on an outer lane. From the fast car, the slow car seems to slide backward for a while. No extra loops are needed for that.","For decades Copernicus held back from publishing his full book. Then in 1539 a young mathematician named Georg Joachim Rheticus came to visit him and encouraged him to share it. The book, called De revolutionibus orbium coelestium, or On the Revolutions of the Heavenly Spheres, was printed in Nuremberg by Johannes Petreius in 1543. It had six books and was dedicated to Pope Paul III. A Lutheran minister named Andreas Osiander, who helped oversee the printing, added an unsigned preface saying the theory was only a handy tool for calculation, not necessarily the truth. Copernicus died on 24 May 1543 at the age of 70. A well-known story says he was handed a printed copy on his deathbed, but that tale is hard to prove.","Here is the surprising part: in 1543 nobody could really tell who was right. Copernicus still believed planets must move in perfect circles at steady speeds, so he still needed small circles on top of circles to make his predictions work. His tables were about as accurate as Ptolemy's, not much better.","There was also a very good argument against him. If the Earth swings around the Sun in a huge circle, then the nearby stars should seem to shift a little against the farther ones over the year, just as a nearby tree seems to shift against distant hills when you walk past. This shift is called parallax. Nobody could see it. Copernicus answered that the stars must be unimaginably far away, so the shift was too tiny to notice. He was right, but at the time that sounded like an excuse. The shift is real, but it is so small that it was not measured until 1838, using a telescope. With naked eyes alone, the debate was stuck."]},{"heading":"Tycho Brahe's Island of the Stars","paragraphs":["To break the deadlock, someone needed to measure the sky far better than ever before. That person was Tycho Brahe, one of the most colorful characters in the history of science. He was born on 14 December 1546 at Knutstorp, a castle in Scania, which was then part of Denmark and is now in southern Sweden. He came from a rich noble family, and as a teenager he became fascinated by astronomy after an eclipse of the Sun in 1560 made him wonder how such events could be predicted, and how the predictions could be made better.","Tycho was also famously hot-tempered. In December 1566, at age 20, he quarreled with a cousin, reportedly over who was the better mathematician, and the argument ended in a sword duel. Tycho lost part of his nose. For the rest of his life he wore a metal replacement nose, held on with paste. People long said it was made of silver and gold, but after his grave was opened in 2010, a study published in 2012 found that it was most likely made of brass.","On 11 November 1572, Tycho stepped outside and saw something impossible: a brilliant new star in the constellation Cassiopeia, where no star had been before. For a while it was brighter than Venus. Most scholars believed the heavens beyond the Moon were perfect and never changed, so a new star had to be something close to Earth, in the air. Tycho tested this. If the new star were close, it would seem to shift against the background stars as Earth turned through the night. He measured it carefully and found no shift at all. It had to be far beyond the Moon. Today we know he saw a supernova, an exploding star. His little book about it, De nova stella (1573), made him famous.","King Frederick II of Denmark was so impressed that he gave Tycho a whole island, Hven, in the strait between Denmark and Sweden, plus money to build on it. On 8 August 1576 the cornerstone was laid for Uraniborg, the castle of Urania, named after the Greek muse of astronomy. It was a red-brick palace with towers and domes, a library, an alchemy laboratory in the basement, gardens, fishponds, a paper mill and even a printing workshop so Tycho could publish his own books. The building cost an enormous amount, by one estimate around one percent of the Danish state's budget during construction. Over the years, dozens of students and assistants lived and worked there.","Tycho soon found that wind shook the instruments in his tall towers. So in the mid-1580s he built a second observatory nearby called Stjerneborg, the castle of the stars, with its instruments set in pits below ground level, out of the wind and steady on solid foundations."]},{"heading":"Giant Instruments and a Precious Handover","paragraphs":["Walk into Uraniborg in the 1580s and you would not find a single telescope. They had not been invented yet. Instead you would see huge instruments of brass, iron and wood: quadrants (quarter-circles marked with degrees), sextants (sixth-of-a-circle frames), and armillary spheres, which are skeleton globes made of rings that match the circles of the sky. Each one had sights, a bit like the sights on a rifle, a small slit or pinhole at one end and a pointer at the other. You lined the two up with a star, then read its angle off the scale.","The most famous was the great mural quadrant. Mural means wall: it was a giant brass quarter-circle, taller than a grown man, fixed to a wall that ran exactly north to south. A small opening in a different wall served as the sight. As a star crossed the north-south line, one observer called out the moment and its height on the scale while another noted the time on a clock and a third wrote everything down. Inside the arc of the quadrant, the wall was painted with a large picture of Tycho himself, pointing toward the sky, surrounded by his instruments and his assistants at work.","Tycho's instruments were not only big. They were clever. He used finely divided scales with diagonal lines, a trick that let observers read fractions of a degree between the main marks. He built his sights so they could be lined up precisely. He checked each instrument against the others to catch mistakes, and he measured the same stars again and again, night after night, year after year, and averaged the results. He even took into account the way Earth's air bends starlight near the horizon, which makes low stars look slightly higher than they really are.","The result was the most accurate set of sky measurements ever made with the naked eye. Tycho aimed to fix the position of a star or planet to within about 1 arcminute, which is one sixtieth of a degree. How small is that? The full Moon is about 30 arcminutes wide, so 1 arcminute is about one thirtieth of the Moon's width. It is like seeing a coin from the other end of a soccer field and measuring its position exactly. For the brightest stars, he mostly reached that goal. By one estimate, his positions were about five times as accurate as those of the best rival observatory of his day, run by Wilhelm of Hesse. Before he left Hven, he completed a catalog of 1,000 stars.","Tycho never accepted that the Earth moves, partly because he could not detect any star parallax and partly because he could not believe a heavy Earth could fly through space. So in 1588 he proposed his own compromise, now called the Tychonic system. In it, the Sun and Moon circle a still Earth, but all the other planets circle the Sun. It fit the observations of the time just as well as Copernicus's system. Now there were three competing models of the universe, and naked-eye observations could not clearly choose between them.","After King Frederick II died, Tycho fell out of favor with the new king, Christian IV, and his money was cut. In 1597 he left Hven, taking his portable instruments and his precious notebooks. By 1599 he had found a new patron, the Holy Roman Emperor Rudolf II, who made him imperial astronomer in Prague. Tycho worked for a while at a castle at Benátky, outside the city, then moved into Prague itself. Uraniborg was abandoned and later torn down; only its foundations and gardens remain on the island, which now belongs to Sweden.","In 1600 a young German mathematician joined Tycho in Prague. His name was Johannes Kepler. The two were very different. Tycho was a rich, proud nobleman with mountains of observations. Kepler was poor, brilliant and full of theories, but he had poor eyesight and few good measurements of his own. They argued often. Tycho guarded his data jealously and gave Kepler only pieces of it, especially the observations of Mars, the planet whose path was hardest to explain.","In October 1601, Tycho fell ill after a banquet and died on 24 October, about eleven days later, at the age of 54. The exact cause has been debated for centuries; a scientific study of his remains published in 2012 found no evidence that he had been poisoned with mercury, as some had suspected. As he lay dying, he is said to have asked Kepler to finish the great tables of planet positions he had been working on. Kepler inherited the job, and he got access to Tycho's data.","It turned out to be one of the most important handovers in science. Working through Tycho's Mars measurements, Kepler found that no combination of perfect circles fit them. A circle was off by about 8 arcminutes, a difference so small that it would have been ignored with older data. Because Kepler trusted Tycho's accuracy, he could not ignore it. He eventually discovered that planets move in ellipses, slightly squashed circles, with the Sun at one focus. Those discoveries, published from 1609 onward, belong to another part of this story. But they show the power of Tycho's life's work: patient, precise measurement, done entirely without a lens."]},{"heading":"The Limits of the Human Eye","paragraphs":["Tycho had pushed the naked eye about as far as it could go. To understand why, think about your eye as a tiny camera. Light enters through the pupil, the black circle in the middle of the colored part of your eye. A lens behind the pupil focuses that light onto the retina at the back of the eye, a thin layer packed with millions of light-sensing cells. Those cells send signals to the brain, and the brain builds a picture.","The first limit is the size of the opening. The pupil gets smaller in bright light and wider in the dark, which is why your eyes need a while to adjust when you step outside at night. Even fully opened in darkness, a typical adult pupil is only about 7 millimeters across, roughly the width of a pencil. Only the light that fits through that tiny hole can reach the retina. A faint star sends very little light toward Earth, and an even smaller trickle of it lands in your eye. If too little arrives, the star is simply invisible to you.","The second limit is detail. The cells on your retina are packed closely, but not infinitely close, and the eye's own lens is not perfect. As a result, the human eye can usually separate two points only if they are at least about 1 arcminute apart. Notice that number? It is exactly the accuracy Tycho reached. He had hit the wall built into human biology. No matter how big his quadrants were, his eyes could not see finer than that.","These limits explain many ancient mysteries. The Milky Way looked like a glowing cloud because its stars are too faint and too close together for the eye to separate. Planets looked like points of light, so no one could see whether Jupiter had moons, whether Venus had phases like the Moon, or what the surface of Mars looked like. The Andromeda Galaxy was just a fuzzy smudge. And star parallax, the tiny shift that would prove the Earth moves, was far too small to detect.","To go further, people needed a way to give the eye a bigger opening, a way to collect more light than a 7-millimeter pupil could gather, and a way to spread fine details over more of the retina. Strangely, the tools to do it already existed. In shops across Europe, craftsmen were grinding curved pieces of glass every day, and many thousands of people were wearing them. The tools to see more were already sitting on people's noses, they just had to be put together in the right way."]}],"deepDive":"Why could naked-eye astronomy not settle the argument between Ptolemy, Copernicus and Tycho? The answer is that, as geometry, the three systems were nearly equivalent. Ptolemy's epicycles, Copernicus's moving Earth and Tycho's Sun-circling planets all describe the same apparent motions as seen from Earth; they differ mainly in which body is treated as standing still. Copernicus kept uniform circular motion, so his predictions were roughly as accurate as Ptolemy's, sometimes off by a degree or more for Mars. A heavier argument was physical: before Newton, no one had a theory of motion explaining why a spinning, orbiting Earth would not fling off its air, birds and oceans. Tycho's system kept a still Earth while borrowing the mathematical neatness of a Sun-centered arrangement, which is why it was popular with many astronomers for decades. The decisive missing observation was annual stellar parallax. Even the nearest bright stars shift by less than 1 arcsecond, roughly one sixtieth of the 1-arcminute limit of the human eye and of Tycho's instruments. Tycho reasoned that if stars were far enough away to hide their parallax, they would have to be enormous to look as wide as they seemed, because to the naked eye stars appear to have small disks. We now know those apparent disks are an illusion caused by the eye's optics and the blurring of the atmosphere, not the real size of the stars. Historians also point out how much Tycho's accuracy depended on method, not just big instruments: repeated observations, cross-checking instruments, correcting for atmospheric refraction and averaging. His catalog's median error has been estimated at around 1.5 arcminutes, with his best logged observations better still. Kepler's discovery that a circular orbit for Mars missed Tycho's data by about 8 arcminutes is a classic example of how improved data, not just new ideas, can force a scientific revolution. Ulugh Beg's earlier work shows the same principle: his 40-meter sextant was an attempt to beat the eye's limit by spreading the scale over a huge arc. Both men reached the ceiling of what could be done without optics. The next leap needed a new kind of instrument.","funFact":"Tycho Brahe's famous metal nose, long said to be silver and gold, was most likely made of brass, according to a study of his remains published in 2012.","check":{"q":"About how accurately could Tycho Brahe measure the positions of stars and planets without a telescope?","a":"About 1 arcminute, roughly one thirtieth of the full Moon's width","wrong":["About 10 degrees, the width of a fist at arm's length","Exactly 1 arcsecond, as good as a modern telescope","About half the width of the full Moon"]},"sources":[{"title":"Tycho Brahe","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Tycho_Brahe"},{"title":"Uraniborg","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Uraniborg"},{"title":"Ulugh Beg Observatory","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Ulugh_Beg_Observatory"},{"title":"Almagest","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Almagest"},{"title":"Babylonian astronomy","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Babylonian_astronomy"},{"title":"De revolutionibus orbium coelestium","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/De_revolutionibus_orbium_coelestium"},{"title":"Naked eye","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Naked_eye"},{"title":"Pupil","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pupil"}],"photos":[{"src":"img/deep/telescope/01-1.jpg","alt":"Tycho Brahe's great mural quadrant at Uraniborg: Tycho is painted on the wall inside the arc while assistants observe and record.","file":"Tycho-Brahe-Mural-Quadrant.jpg","url":"https://commons.wikimedia.org/wiki/File:Tycho-Brahe-Mural-Quadrant.jpg","author":"Unknown author","license":"Public domain"},{"src":"img/deep/telescope/01-2.jpg","alt":"The curved twin stone track of Ulugh Beg's giant underground sextant in Samarkand, Uzbekistan, built in the 1420s.","file":"MASamarkandObservUlugBeg3.jpg","url":"https://commons.wikimedia.org/wiki/File:MASamarkandObservUlugBeg3.jpg","author":"Ziegler175","license":"CC BY-SA 4.0"},{"src":"img/deep/telescope/01-3.jpg","alt":"Copernicus's 1543 diagram from De revolutionibus: the Sun (Sol) in the middle, circled by the planets and Earth with its Moon.","file":"Copernican heliocentrism diagram-2.jpg","url":"https://commons.wikimedia.org/wiki/File:Copernican_heliocentrism_diagram-2.jpg","author":"Copernican_heliocentrism_diagram.jpg: Own work from Copernicus 1543…","license":"Public domain"}],"words":4365},{"n":2,"title":"Magic Glass: Lenses and Spectacles","when":"About 750 BCE – 1500s","summary":"Curved pieces of crystal and glass can bend light and make things look bigger. Over thousands of years, people went from a mystery crystal in an Assyrian palace to the first eyeglasses in Italy. By 1600, lens shops all over Europe held every piece needed for a telescope.","sections":[{"heading":"The Trick of Bending Light","paragraphs":["Fill a clear glass with water and drop a pencil into it. Look from the side, and the pencil seems to snap in two at the water's surface. Of course, the pencil is fine. What has bent is the light. When light passes from one clear material into another, such as from water into air, it changes direction a little. This bending is called refraction, and it is the secret behind every lens, every pair of glasses and every refracting telescope ever made.","A lens is a piece of clear material, usually glass, shaped with curved surfaces so that it bends light in a useful way. The word lens comes from the Latin word for lentil, because the most common kind of lens, fat in the middle and thin at the edges, looks a lot like a lentil seed.","That fat-in-the-middle kind is called a convex lens. Light rays passing through the outer parts of a convex lens are bent inward, toward the middle, so the rays come together at a point. Hold a convex lens over a page and the letters look bigger. Hold it in sunlight and it can gather the Sun's rays into one tiny, very hot spot. The distance from the lens to that spot is called the focal length. A strongly curved lens bends light sharply and has a short focal length; a gently curved lens bends it only a little and has a long focal length.","The opposite shape is a concave lens, thin in the middle and thick at the edges, like a shallow dish. A concave lens spreads light rays outward instead of gathering them. Look through one and things appear smaller.","These two shapes explain how eyeglasses help people. A farsighted person, or an older person whose eyes can no longer focus on close-up things, needs extra help bending light inward, so a convex lens does the job. A nearsighted person's eye bends light too strongly, bringing distant objects to a focus in front of the retina instead of on it, so a concave lens spreads the light out a little first and fixes the blur. Keep these two shapes in mind. The very first telescope, as you will see in the next part, used one of each.","People discovered the magic of curved, clear materials long before anyone understood why it worked. The story of that discovery stretches over almost 2,500 years, from a palace in ancient Iraq to the glass furnaces of Venice."]},{"heading":"The Mystery Crystal of Nimrud","paragraphs":["In 1850, the British explorer Austen Henry Layard was digging in the ruins of Nimrud, an ancient capital of the Assyrian Empire on the Tigris River in what is now northern Iraq. Layard and his workers uncovered huge stone sculptures of winged bulls and palace walls covered with carved scenes. In one room of the great Northwest Palace, among piles of broken objects, he found something much smaller: an oval piece of rock crystal, a clear form of the mineral quartz, carefully ground and polished.","The object, now called the Nimrud lens or the Layard lens, dates from about 750 to 710 BCE, when Assyrian kings ruled much of the Middle East. It is about 38 millimeters across, a little wider than a large coin, and about 23 millimeters thick. One side is flat. The other side was ground into a gentle curve. When you hold it up, it really does act like a weak magnifying glass, making things look about three times bigger, with a focal length of roughly 12 centimeters.","But here is the puzzle: the focus is far from perfect. The surface is not a smooth, regular curve, and as it was ground, twelve tiny pockets opened up in the crystal, places where bubbles of liquid or gas had been trapped inside the stone when it formed millions of years ago. Was it made to be a magnifier? Or is it simply a decorative piece of polished crystal that happens to magnify a bit?","Experts still argue about it. Some think it could have helped craftsmen see fine details when carving tiny seals and jewelry, or that it might have been used as a burning glass to start fires by focusing sunlight. Others, including curators at the British Museum in London, where the lens is kept today, have suggested it was probably an inlay, a shiny piece set into furniture or decoration, with no clear evidence that anyone used it to see better. Later, an Italian professor named Giovanni Pettinato went much further and suggested it might have been part of an ancient Assyrian telescope. Most specialists in Assyrian history are not convinced. No surviving Assyrian text, even among the many astronomy tablets, mentions anything like a telescope.","So the honest answer is: we do not know what the Nimrud lens was for. That is a good lesson for this whole story. Sometimes an object from the past looks like an invention we recognize, but we cannot be sure the people who made it used it the way we would. What the lens does prove is that, nearly 2,800 years ago, craftsmen could grind and polish clear crystal into smooth curved shapes."]},{"heading":"Burning Glasses and Water Globes","paragraphs":["The ancient Greeks and Romans definitely knew that clear, curved objects could do strange things with light. The clearest early written example comes from a comedy. In 423 BCE, the Athenian playwright Aristophanes staged a play called The Clouds. In one scene, a foolish character named Strepsiades, who is drowning in debt, comes up with a scheme. He will buy a beautiful transparent stone from a shop, the kind people used for lighting fires, stand in the sunshine, and focus the Sun's rays onto the wax tablet where his debt is written down, melting the record away. The audience was expected to know what such a stone was, which tells us burning glasses were familiar in Athens.","Around 400 years later, the Roman writer and thinker Seneca noticed something about letters. In his book Natural Questions, written in the first century CE, he remarked that writing, however small and faint, looks larger and clearer when seen through a glass globe filled with water. It is one of the earliest written descriptions of magnification. Seneca did not take the next step of making a proper magnifying lens, and he did not fully understand why it happened, but he had spotted the effect.","Another Roman writer, Pliny the Elder, wrote in his huge encyclopedia, the Natural History, that balls of crystal held in the sunlight could become hot enough to burn. He also told a famous little story about the emperor Nero, who was said to watch gladiators fighting through a polished emerald. Some people later claimed this made Nero the first person to wear glasses. Historians are not sure what the emerald did. It may have worked as a mirror, or Nero may simply have liked its soothing green color. It is a fun tale, but not good evidence of a vision aid.","The Romans were also skilled glassmakers. Around the first century BCE, craftsmen in the eastern Mediterranean discovered glassblowing, and glass bottles, cups and windows spread across the Roman Empire. But Roman glass was usually tinted green or blue, and full of bubbles and streaks. It was fine for a drinking cup. For lenses, it was not nearly good enough. Making truly clear glass would take more than a thousand more years."]},{"heading":"Ibn al-Haytham: Light Comes Into the Eye","paragraphs":["For a long time, many of the smartest people in the world believed something strange about seeing. Several Greek thinkers, including the mathematician Euclid and later Ptolemy, worked with the idea that the eye sends out invisible rays, like a flashlight, which travel out and touch the things we look at. It sounds odd now, but it helped them do geometry: you could draw straight lines from the eye to an object and work out angles and sizes.","The person who did the most to overturn this idea was Abu Ali al-Hasan ibn al-Haytham, known in Europe by the Latin name Alhazen. He was born around 965 in Basra, in what is now Iraq, and spent most of his working life in Cairo, Egypt, which was then the capital of the Fatimid caliphs. He died around 1040.","There is a famous story about how he came to Cairo. According to this tale, he boasted that he could control the flooding of the Nile River with a dam. The ruler, Caliph al-Hakim, invited him to try. When Ibn al-Haytham traveled up the Nile and saw the size of the river, he realized the plan was impossible with the tools of his time. Afraid of the caliph's anger, he supposedly pretended to be mad and was kept under house arrest until al-Hakim died, using the quiet years to write. It is a dramatic legend, and historians are not sure how much of it is true.","What is certain is that between about 1011 and 1021 he wrote a huge work in seven volumes called Kitab al-Manazir, the Book of Optics. In it he argued that vision works the other way around from what Euclid and Ptolemy had assumed: light travels from objects into the eye, not out of it. Every point on a lit object sends light out in all directions, and some of that light enters our eyes. He also argued that the eye only collects the light; the actual act of seeing is completed in the brain.","What made his work so special was not just the ideas but the way he tested them. He set up careful experiments with dark rooms, small holes, screens, mirrors, and pieces of glass and water. He studied the camera obscura, a darkened room with a tiny hole in one wall, where light from outside paints an upside-down image of the world on the opposite wall, and he used one to watch a partial eclipse of the Sun safely. He measured how light bends when it passes between air, water and glass, and wrote about how curved glass, such as a glass ball, could make objects seen through it appear larger. Because he insisted that ideas should be checked by repeatable experiments, many people call him one of the founders of the scientific method.","He was building on others too. A few decades earlier, around the 980s, a scholar in Baghdad named Ibn Sahl had written a book about burning mirrors and lenses. In it, he described a rule for exactly how much light bends when it enters glass, the same rule that would be rediscovered in Europe more than 600 years later and named Snell's law.","Around the year 1200, an unknown translator turned the Book of Optics into Latin, under titles such as De aspectibus and Perspectiva. It became the most important book on light in medieval Europe, studied by scholars for centuries and later read by Johannes Kepler. In 2015, the United Nations celebrated the International Year of Light, marking about 1,000 years since Ibn al-Haytham's great work. A crater on the Moon and an asteroid are named after him."]},{"heading":"Reading Stones and a Curious Friar","paragraphs":["Now picture a monk in a cold monastery around the year 1200. He is perhaps 50 years old, and for years he has spent his days copying books by hand. Lately the letters have started to blur. This happens to almost everyone in middle age: the lens inside the eye gets stiffer and can no longer focus on things close up. For a scribe, a scholar or a merchant checking accounts, that was a disaster.","One helpful tool was the reading stone. It was a piece of clear material shaped like a dome, roughly half a sphere, flat on the bottom and curved on top. You set the flat side down on a page and slid it along the lines, and the letters underneath looked bigger. Reading stones were made from rock crystal, from a clear gemstone called beryl, and eventually from glass. They were being used in Europe by around the 1000s and 1100s. The German word for eyeglasses, Brille, is thought to come from beryl, a reminder of these early stones.","On the Swedish island of Gotland, archaeologists have found beautifully polished rock-crystal lenses in Viking-age graves from the 1000s or 1100s. These Visby lenses, named after the island's main town, are surprisingly well made. The best one is about 50 millimeters across, and some are set in decorative silver mounts, probably worn as jewelry. Whether anyone used them to read or to see fine work, nobody knows for sure. Like the Nimrud lens, they are a reminder that skilled hands could shape crystal well before anyone wrote down the science.","Meanwhile, European scholars were reading Ibn al-Haytham in Latin. In England, the bishop and scholar Robert Grosseteste wrote about light and how it bends. His ideas inspired a Franciscan friar at Oxford named Roger Bacon, who lived from about 1220 to about 1292. Bacon was fascinated by science and believed knowledge should be tested by experience.","In 1267, at the request of Pope Clement IV, Bacon sent the pope a huge work called the Opus Majus, or Greater Work. One part of it is about optics: how the eye works, how mirrors reflect, and how light refracts through curved glass. Drawing heavily on Ibn al-Haytham, Bacon explained that a piece of glass shaped like a segment of a sphere, placed with its flat side on a page, would make letters look larger, and that this could be useful for old people and people with weak eyes. He even imagined, in theory, that cleverly shaped glass might one day make faraway things seem near. Over the centuries, legends grew up around Bacon, claiming he built a magical talking brass head or secretly invented the telescope. There is no evidence for any of that. But he did write clearly about magnifying with curved glass, just a few years before something new appeared in Italy."]},{"heading":"Eyeglasses Appear in Italy","paragraphs":["Sometime around the 1280s, an unknown craftsman in northern Italy, probably in Pisa or Florence, had a simple but brilliant idea. Instead of sliding a lens across a page, why not hold two small lenses up in front of the eyes, one for each eye? That way you could read normally, turn pages, and even look up from the book. Eyeglasses were born, most likely around 1286.","We know roughly when because of a sermon. On 23 February 1306, a Dominican friar named Giordano da Pisa was preaching in Florence. In the middle of his sermon, he praised a recent invention. As his listeners noted it down, he said: \"It is not yet twenty years since there was found the art of making glasses, which make for good vision.\" He called it one of the best and most necessary arts in the world, and added: \"I saw the one who first discovered and practiced it, and I talked to him.\" Counting back twenty years from 1306 gives about 1286.","Annoyingly, Giordano did not say the inventor's name. A chronicle from the Dominican monastery in Pisa tells of another friar, Alessandro della Spina, who died in 1313. It says that eyeglasses had first been made by someone else who was unwilling to share the secret, but Alessandro worked out how to make them himself and happily shared his knowledge with everyone. So the first inventor kept quiet, and the first known sharer became famous instead.","Centuries later, people tried to fill the gap. In Florence, a story spread that a nobleman named Salvino degli Armati had invented eyeglasses, and a memorial to him was even displayed in a church. Historians have shown that this claim is false; it rests on documents and an inscription that were made up long afterward. The real inventor remains unknown.","Those first glasses looked nothing like the ones people wear today. Each lens was set in a small round frame with a short handle, and the two handles were joined by a rivet at the top. You balanced the pair on your nose or held it in place with one hand. There were no arms going back over the ears; those came much later, in the 1700s. Frames were made of materials such as wood, bone, horn, leather or metal. Some of the oldest surviving rivet spectacles, from around 1400, were found hidden under the floorboards of the Wienhausen convent in northern Germany, where nuns had perhaps dropped them centuries earlier.","Pictures soon followed. In 1352, the painter Tommaso da Modena decorated a room in a monastery in Treviso, near Venice, with portraits of famous Dominican scholars at their desks. One of them, Cardinal Hugh of Saint-Cher, is shown reading with a pair of rivet spectacles perched on his nose. It is the oldest known painting of someone wearing eyeglasses, and it is a little joke of history: Hugh had died in 1263, before glasses were invented, so the painter gave him a gadget he never owned."]},{"heading":"The Glassmakers of Venice","paragraphs":["Good spectacles needed good glass, and in medieval Europe the best glass came from Venice. By around 1300, the city's glassmakers had become rich and famous, and the Venetian government guarded their skills like treasure. In 1291, a law moved most of the city's glass furnaces to the nearby island of Murano. One reason was safety: Venice was crowded with wooden buildings, and a glass furnace roaring all day was a serious fire risk. Another reason was secrecy. Glassmakers on Murano were honored citizens, but they were not allowed to leave the Venetian Republic without permission, and those who ran away to sell their secrets abroad could face harsh punishment.","Venice was also one of the first places to make rules for spectacle-making. Guild regulations from around 1300 mention glass for the eyes, and they warned craftsmen not to pass off cheap ordinary glass as precious rock crystal, which suggests that some lenses were still carved from crystal and that customers were being tricked. Venice became an important center for making spectacle lenses, and they were sold far beyond Italy.","In the 1450s, a Murano glassmaker named Angelo Barovier is generally credited with creating cristallo, a glass so clear and colorless that it looked like rock crystal. The trick involved purifying the ingredients, especially the plant ash used to help the sand melt. Clearer glass meant sharper, brighter lenses. It also made Venetian glassware some of the most wanted luxury goods in Europe.","Making a lens was slow, patient work. A lens-maker took a small blank of glass and rubbed it against a curved metal or stone tool, called a lap, using wet sand or other grits that got finer and finer. A convex lens was ground in a hollow, bowl-shaped tool; a concave lens was ground on a domed one. Then came polishing with very fine powders until the surface shone. Every lens was done by hand, and the quality varied a lot. Many were slightly lopsided, scratched or full of tiny bubbles."]},{"heading":"Spectacles Spread Across Europe","paragraphs":["For more than a century, eyeglasses were almost always convex, meant for people who could not see things up close. The other big group of people with poor eyesight, the nearsighted, who see close things clearly but distant things as a blur, had to wait. Lenses that helped them, concave lenses that spread light outward, appear in records by the mid-1400s. Nobody at the time could fully explain why either kind worked. That explanation came in 1604, from Johannes Kepler, the same Kepler who had inherited Tycho Brahe's data.","Then came a huge boost in demand. Around 1450, Johannes Gutenberg began printing books with movable type in Mainz, Germany. Over the next decades, printed books poured out by the millions, and many more people began to read. More readers meant more people who needed glasses as they grew older. Spectacles became something ordinary people could buy from a peddler or a shop, not just a treasure for rich churchmen. By 1466, the city of Strasbourg had a specialist spectacle shop, and by the 1500s German cities such as Nuremberg had become big centers of spectacle-making.","The trade also reached the Low Countries, the busy, crowded region that is now the Netherlands and Belgium. Dutch towns were full of merchants, sailors, printers and craftsmen, and spectacle-makers set up shop there to serve them. In the town of Middelburg, on an island in the province of Zeeland, several spectacle-makers worked within a few streets of each other around 1600. Each of them kept boxes of convex and concave lenses of different strengths on their benches, testing them for customers, holding them up to the light, and looking through them at the street outside.","So by the year 1600, all the pieces of a telescope were lying around in workshops across Europe. There were convex lenses and concave lenses. There were craftsmen who knew how to grind them. There was reasonably clear glass. And there were thousands of people looking through lenses every day. Why had no one built a telescope yet?","Part of the answer is that spectacle lenses were weak. A reading lens has a long focal length and only a gentle curve, while a telescope needs a strongly curved lens near the eye. Strong concave lenses for very nearsighted people were less common. Another part is quality: two cheap lenses lined up in a row would often give a dim, blurry, distorted view, nothing that would make anyone shout with excitement. And part of the answer may simply be that nobody happened to try the right combination, at the right distance apart, and pay attention to what they saw. For 300 years, people held single lenses in their hands, until someone thought to hold two lenses in a line."]}],"deepDive":"Historians of the eyeglass face a frustrating gap: we can date the invention fairly closely but cannot name the inventor. Giordano da Pisa's sermon of 23 February 1306 says the art was less than twenty years old and that he had spoken with its discoverer, which points to the mid-1280s. The Pisan chronicle praising Alessandro della Spina for sharing what another had kept secret fits a craft that began as a guarded trade technique rather than a scholarly discovery. That matters, because it suggests eyeglasses came out of craft workshops, probably linked to the glass and rock-crystal trades of Tuscany and Venice, rather than straight out of optical theory. Scholars debate how much the Latin translation of Ibn al-Haytham's Book of Optics, and the writings of Grosseteste, Roger Bacon, John Pecham and Witelo, actually influenced the craftsmen. Bacon described magnification by a segment of a glass sphere, but there is no evidence that an artisan read him. Theory and practice seem to have run side by side for centuries, and the theory of how lenses correct vision was not properly worked out until Kepler's Astronomiae Pars Optica of 1604. Even then, the exact mathematical law of refraction, first written down by Ibn Sahl in Baghdad in the 980s, had to be rediscovered by Willebrord Snellius around 1621. A second debate concerns ancient lenses like the Nimrud lens and the Visby lenses. Some writers have argued that they prove ancient magnifiers or even telescopes; most archaeologists are far more cautious, because polished crystal was also prized for jewelry, inlay and burning glasses, and because no written source describes such uses for vision. Why did the telescope take about 320 years to follow eyeglasses? Optical historians point to practical limits. Reading lenses are weak, with focal lengths of tens of centimeters, while a useful spyglass needs a strong eyepiece. Glass of the time was often full of bubbles and streaks, and surfaces were not accurately spherical. Strong concave lenses for severe nearsightedness only became common in the later 1400s and 1500s. The telescope needed both kinds of lens, of good enough quality, in the hands of the same craftsman.","funFact":"The oldest known painting of eyeglasses, made in 1352, shows Cardinal Hugh of Saint-Cher wearing a pair, even though he died in 1263, before eyeglasses had been invented.","check":{"q":"What evidence tells historians that eyeglasses were invented around 1286?","a":"A 1306 sermon by Friar Giordano da Pisa saying they had been invented less than 20 years earlier","wrong":["A patent granted to the inventor in Venice in 1286","A signed letter from Roger Bacon describing his own spectacles","A date carved into the frame of the Nimrud lens"]},"sources":[{"title":"Nimrud lens","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Nimrud_lens"},{"title":"Ibn al-Haytham","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Ibn_al-Haytham"},{"title":"Glasses","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Glasses"},{"title":"History of optics","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/History_of_optics"},{"title":"Reading stone","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Reading_stone"},{"title":"Visby lenses","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Visby_lenses"},{"title":"Roger Bacon","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Roger_Bacon"},{"title":"Murano glass","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Murano_glass"}],"photos":[{"src":"img/deep/telescope/02-1.jpg","alt":"The Nimrud lens, a polished oval of rock crystal about 3,000 years old from Assyria, in the British Museum.","file":"Nimrud lens British Museum.jpg","url":"https://commons.wikimedia.org/wiki/File:Nimrud_lens_British_Museum.jpg","author":"Geni","license":"CC BY-SA 4.0"},{"src":"img/deep/telescope/02-2.jpg","alt":"Tommaso da Modena's 1352 fresco in Treviso: Cardinal Hugh of Saint-Cher writing with spectacles on his nose, the oldest known painting of glasses.","file":"Tommaso da modena, ritratti di domenicani (Ugo di Provenza) 1352 150cm, treviso, ex convento di san niccolò, sala del capitolo (cropped).jpg","url":"https://commons.wikimedia.org/wiki/File:Tommaso_da_modena,_ritratti_di_domenicani_(Ugo_di_Provenza)_1352_150cm,_treviso,_ex_convento_di_san_niccol%C3%B2,_sala_del_capitolo_(cropped).jpg","author":"Tommaso da Modena","license":"Public domain"},{"src":"img/deep/telescope/02-3.jpg","alt":"A diagram of the eye and optic nerve from a 16th-century printed Latin edition of Ibn al-Haytham's Book of Optics.","file":"I.A. Haitham, Diagram of the eye, 16th century Wellcome L0011969.jpg","url":"https://commons.wikimedia.org/wiki/File:I.A._Haitham,_Diagram_of_the_eye,_16th_century_Wellcome_L0011969.jpg","author":"Wellcome Collection","license":"CC BY 4.0"}],"words":3967},{"n":3,"title":"1608: The Spyglass Appears","when":"1608 – 1609","summary":"In 1608 a Dutch spectacle maker named Hans Lipperhey put two lenses in a tube and found that faraway things looked three times closer. Soon other people said they had made one too, and within a year spyglasses were being sold in Paris. In England, Thomas Harriot used one to draw the Moon.","sections":[{"heading":"A Letter to The Hague","paragraphs":["Imagine the autumn of 1608 in The Hague, the town where the leaders of the young Dutch Republic met. The streets are busy with messengers, soldiers, diplomats and merchants. Inside a government hall, the members of the States General, the national assembly of the Dutch provinces, are working through a pile of letters. One of them, dated 2 October 1608, comes from a spectacle maker in the port town of Middelburg. He asks for something unusual: a patent, which is an official promise that only he may make and sell a new invention for a number of years. The invention, he writes, is an instrument 'for seeing things far away as if they were nearby.'","That letter is the oldest written record of a telescope anywhere in the world. Before it, there are rumors, hints and later stories, but no document that clearly describes a working tube for seeing far. After it, the telescope spreads across Europe so quickly that within about a year people in Paris, Milan, Venice and London are peering through them. In this part we will follow that explosion: the men who claimed the invention, how the first spyglass actually worked, why generals and admirals wanted one desperately, and how one English scientist quietly pointed his at the Moon before almost anyone else.","The man who wrote the letter was Hans Lipperhey, whose name is also often spelled Lippershey. He was born around 1570 in Wesel, a town on the river Rhine in what is now Germany. Like many people in those years, he moved west to the Netherlands, which was booming with trade. He settled in Middelburg in 1594, married that same year, and became a citizen of the province of Zeeland in 1602. He ran a shop where he ground lenses and made spectacles, the eyeglasses we met in the last part.","Middelburg was a good place for such a business. It was a wealthy trading town, a home base for ships of the Dutch East India Company, which had been founded in 1602, and it had plenty of customers who read, wrote, kept accounts and needed help seeing their work. A spectacle maker's shop was full of glass blanks, grinding dishes, polishing powders and finished lenses of many different strengths. In other words, it was exactly the kind of place where someone might pick up two lenses, hold them in a line and discover something surprising.","There is a well-known story that children playing in Lipperhey's shop held two lenses up together, saw a distant church weathervane suddenly look close, and ran to tell him. It is a charming tale, and you will find it in many books, but it is a legend. No document from the time says it happened. What we really know is simpler: by the autumn of 1608 Lipperhey had a working instrument, he believed it was valuable, and he wanted the government to protect his idea."]},{"heading":"Rivals at the Door: Metius and the Refused Patent","paragraphs":["Lipperhey was not alone for long. On 17 October 1608, only about two weeks after his letter, the States General received a second request for a patent on the same kind of device. It came from Jacob Metius, an instrument maker and lens grinder who lived in Alkmaar, a town in the north of Holland. Metius came from a clever family. His father, Adriaan Anthonisz, was a mathematician, mapmaker, military engineer and mayor of Alkmaar, and his brother, Adriaan Metius, became a well-known geometer and astronomer.","Metius said that he too had made an instrument that could make far-off things look near. He also claimed that he understood the secrets of glassmaking and that, with some government support, he could build an even better one. In other words, he was saying: Lipperhey may have a tube, but I can do more.","The States General now had a problem. If two different men in two different towns had built the same device within a few weeks of each other, how secret could it really be? The officials also noticed how simple the instrument was. Once you knew that it was just two lenses in a tube, almost any skilled spectacle maker could copy it. A patent is only worth something if an idea is new and hard to guess, and this idea was neither. In the end the patent was refused, partly because it was clear that other people already knew about the invention.","Even so, the government did not send Lipperhey away empty-handed. The States General saw that the instrument could be useful to the army, so they hired him to build more of them, and they paid him well. They also asked him for something new: a version for both eyes. Lipperhey made binocular instruments, two tubes joined side by side, which makes him one of the very first makers of binoculars, more than two centuries before the prism binoculars you might use today. Metius received only a small award. According to later accounts, he felt snubbed, kept his own telescope hidden, and in his will asked for his tools and designs to be destroyed so that nobody else could profit from them.","There were more hints that the idea was floating around. The German astronomer Simon Marius later wrote that a Dutchman had tried to sell a spyglass at the great autumn trade fair in Frankfurt in 1608, though the lens was cracked. Several historians think that the basic trick of combining a convex and a concave lens may have been discovered more than once, by craftsmen who did not write anything down. That is why it is fairest to say that the telescope appeared in the Netherlands in 1608, and that Lipperhey's letter is the first record we have of it, rather than to name one single genius as its inventor."]},{"heading":"The Janssen Puzzle","paragraphs":["If you look up 'who invented the telescope' you will sometimes see a third name: Zacharias Janssen, another spectacle maker in Middelburg, who lived just a few streets from Lipperhey. Some books even say that Janssen built a telescope, and a microscope too, as early as 1590. So why do most historians today doubt this?","The answer lies in when and how the claim was made. Janssen was probably born around 1585, which means that in 1590 he would have been a small child. The story that he invented the telescope did not appear until 1655, about twenty years after his death. In that year a Dutch diplomat named Willem Boreel, who had grown up in Middelburg, tried to find out who had really invented the telescope. Janssen's son, Johannes Zachariassen, gave testimony before a Middelburg magistrate. He said his father had invented the telescope in 1590 and that Lipperhey had stolen the idea.","Johannes's statements, however, did not hang together well. At different times he gave different dates for his father's invention, including 1590 and 1604. Witnesses were trying to remember events from fifty or sixty years earlier, and Boreel may have mixed up the names of spectacle makers he had known as a boy. Records show no clear evidence that Zacharias Janssen worked as a spectacle maker before about 1616. He also had a colorful history: between 1613 and 1619 he was taken to court several times for making counterfeit coins.","A French writer, Pierre Borel, repeated the Janssen claim in a book in 1656, and that is how it spread into many later histories. Modern historians who studied the documents closely, including the telescope historian Albert Van Helden, concluded that Johannes most likely made up or stretched the story, perhaps hoping for fame or money. Sadly, many of Middelburg's old archives were destroyed by bombing in 1940, during the Second World War, so some questions can never be fully settled.","So where does that leave us? The fairest summary is this. Lipperhey made the first known patent request, on 2 October 1608. Metius made a similar request two weeks later. Janssen may possibly have been one of several Middelburg craftsmen experimenting with lenses around the same time, but the claim that he definitely invented the telescope rests on shaky evidence given many years later by his own son."]},{"heading":"Inside the First Spyglass","paragraphs":["What did the very first telescopes actually look like? Picture a tube a little longer than your forearm, made of paper, leather, wood or thin metal. At the far end sits a convex lens, the kind that bulges outward in the middle, like the lenses in reading glasses for farsighted people. Near your eye sits a concave lens, the kind that is thinner in the middle and thicker at the edges, like the lenses for nearsighted people. Look through the small end at a church tower across town, and the tower seems about three times closer than before.","Here is how it works. The front lens is called the objective. When light from a distant tower passes through it, refraction, the bending of light as it moves from air into glass and out again, bends the rays inward so that they start to come together. If nothing stopped them, they would meet at a point called the focus and form a small upside-down image there. The distance from the lens to that point is the focal length. A weakly curved lens has a long focal length, and a strongly curved lens has a short one.","In this early design, the concave lens is placed a little before the light reaches the focus. It catches the gathering rays and spreads them out again just enough that they enter your eye almost parallel, the way light from a far-off object normally does. Your eye then sees an image that is upright, not upside down, and larger than normal. How much larger depends on the two focal lengths: divide the focal length of the objective by the focal length of the eyepiece, and you get the magnification. A front lens with a focal length of about 30 cm combined with an eyepiece lens of about 10 cm gives about 3 times.","That was roughly the power of Lipperhey's instrument. A three-times spyglass does not sound like much today, when cheap binoculars magnify 8 or 10 times. But imagine never having seen anything bigger than your eyes alone could show. Suddenly the face of a person on the far side of a harbor, the flag on a ship, or the numbers on a distant clock became readable. To people in 1608, it was close to magic.","Why had no one put these two lenses together and written about it during the three hundred years that spectacles had existed? Partly because the right combination is not obvious. You need a weak convex lens and a much stronger concave lens, set at just the right distance apart. Ordinary reading glasses were fairly weak, and strong concave lenses for very nearsighted people were less common. The glass of the time was also often bubbly, greenish and unevenly polished, so many lens pairs simply gave a blurry mess. Early makers learned a useful trick: covering the edge of the front lens with a ring of card or metal so that only the middle part was used. This cut down the blur from badly shaped edges, although it also let in less light."]},{"heading":"Eyes for Armies and Navies","paragraphs":["To understand why the Dutch government cared so much, you need to know what was happening in the Netherlands in 1608. For forty years the northern Dutch provinces had been fighting for independence from the King of Spain, in a long struggle later called the Eighty Years' War. The Dutch army was led by Maurice of Nassau, Prince of Orange, one of the most skilled military commanders in Europe. He was famous for training his soldiers carefully and for using mathematics and engineering in war, so a clever new instrument was exactly the sort of thing that would interest him.","Think about what a spyglass meant in a world without radios, radar or airplanes. A general on a hill could study an enemy camp from a safe distance, count the tents and cannons, and see which way troops were moving. A lookout on a city wall could spot an approaching army sooner. At sea, the advantage was even bigger. A ship's captain who could recognize another ship's flags and guns before that ship could see him clearly had time to choose: attack, run, or prepare a defense. For a trading nation whose fleets sailed to Asia, Africa and the Americas, that extra warning could save cargoes worth fortunes and the lives of sailors.","In 1608 peace talks were going on in The Hague between the Dutch and representatives of Spain and its allies, and they led to a pause in the fighting, the Twelve Years' Truce, signed in April 1609. The Spanish side's commander, Ambrogio Spinola, was in The Hague for the talks. A newsletter from the time reported that Spinola was shown the new spyglass, and that he realized at once that it would make it harder for him to hide his own troops from the Dutch. Whether or not every word of that report is exact, it shows how quickly everyone understood the military meaning of the new tube.","This is also why governments were interested in controlling who could make telescopes. If only the Dutch army had them, it would have a real advantage. The trouble was that the device was simple, and secrets about simple devices do not stay secret for long. Within months, armies and navies all over Europe could buy one, and spyglasses became standard equipment for officers and ship captains for the next three hundred years."]},{"heading":"News Travels Fast","paragraphs":["In September 1608 something remarkable arrived in The Hague: an embassy, or official group of diplomats, sent by King Ekathotsarot of Siam, the country we now call Thailand. They had sailed from Asia on Dutch ships and reached The Hague on 10 September 1608. It is thought to have been the first embassy from Siam ever to visit Europe, and it caused a stir. The envoys met Prince Maurice, and a French-language newsletter was printed to describe their visit. Its title can be translated as 'Embassies of the King of Siam sent to His Excellency Prince Maurice.'","At the end of that newsletter, almost as an extra bit of news, was a paragraph about a spectacle maker from Middelburg who had made a device for seeing far. The newsletter claimed that with it one could see, from The Hague, the clock of the town of Delft and the church windows of Leiden, towns that were miles away. Because the newsletter was about a famous and unusual diplomatic visit, it was copied and passed around among educated people, diplomats and scholars across Europe. News of the telescope hitched a ride with news of the Siamese visitors.","Things moved fast after that. In November 1608 a copy of the report reached Paolo Sarpi in Venice. Sarpi was a monk, a scholar and an adviser to the Venetian government, and he was very interested in science. He began trying to learn more about the instrument and wrote to friends about it. Meanwhile, the spyglasses themselves were traveling. Craftsmen in other towns heard what was needed and began making their own, and traders carried Dutch-made ones to fairs and markets.","By April 1609, small three-power spyglasses were on sale in spectacle makers' shops on the Pont Neuf, a famous bridge in Paris lined with stalls. That was less than seven months after Lipperhey's letter. By the summer of 1609 spyglasses had reached several Italian cities, and they were also in London. In an age when a letter could take weeks to cross Europe on horseback, this was astonishing speed. It was one of the first times a new technology spread across a continent in about a single year.","Most people who bought these early spyglasses treated them as a curiosity or a handy gadget. Merchants used them to spot ships coming into port. Wealthy people showed them off to friends at parties. Soldiers took them to war. Very few people thought to aim them carefully at the night sky and write down what they saw. But a few did, and one of them was living just outside London."]},{"heading":"Thomas Harriot's Moon","paragraphs":["Thomas Harriot was one of the most brilliant English scientists of his time, but for centuries few people knew his name. Born around 1560, he studied at the University of Oxford, finishing his degree in 1580. As a young man he worked for the explorer Sir Walter Raleigh, and in 1585 and 1586 he joined an expedition to Roanoke Island, in what is now North Carolina, where he learned some of the Algonquian language spoken by the local people and wrote a famous report about the land. Later he was supported by a rich patron, Henry Percy, the Earl of Northumberland, and lived at Syon House, a grand house beside the river Thames just west of London.","Early in 1609 Harriot got hold of a Dutch spyglass, which the English sometimes called a 'Dutch trunke.' It magnified about six times. On the evening of 26 July 1609, by the old-style calendar still used in England (5 August 1609 by the calendar most of Europe used), he pointed it at the Moon, which was a thin crescent about five days old. Then he did something nobody is known to have done before: he made a drawing of what he saw.","Harriot's sketch is simple. It shows the curved bright edge of the crescent, the jagged line where light meets darkness, and a few dark patches. It is not a detailed map, and Harriot did not explain what the shapes meant. But it is the earliest known drawing of the Moon made through a telescope, made about four months before Galileo began his own famous Moon studies. Harriot kept observing. By 1610 and the following years he had drawn more detailed pictures, and by around 1613 he had made maps of the whole Moon with many craters placed correctly.","Harriot also shared spyglasses with friends. One of them, Sir William Lower, who lived in Wales, wrote to him in 1610 describing the Moon seen through his instrument. Lower compared its speckled look to a tart that his cook had made, with bright and dark spots all over it. It is a wonderfully ordinary comparison for an extraordinary sight, and it shows how strange the newly revealed Moon seemed to people who had always seen it as smooth.","Harriot's work went further. In December 1610 he recorded sunspots, dark marks on the Sun, which is the earliest record we have of anyone observing them through a telescope. Over the next few years he wrote down hundreds of sunspot observations. Yet he published almost none of it. Historians suggest several reasons. His patron, the Earl of Northumberland, had been locked in the Tower of London after the Gunpowder Plot of 1605, which may have made Harriot cautious. He may also have worried about being accused of having dangerous religious ideas. And he seems simply to have preferred working on problems to writing them up. Many of his papers were later lost or forgotten, and his telescope work was only properly recognized centuries later."]},{"heading":"A Toy That Was About to Become a Tool","paragraphs":["So by the summer of 1609, the telescope was already loose in the world. It had been described in a government letter, mentioned in a diplomatic newsletter, sold on a Paris bridge, carried to war, and aimed at least once at the Moon by an English mathematician. Yet in an important sense, the real story had barely begun.","Almost all of these spyglasses were weak, around three to six times. Their lenses were rough, their view was narrow, and the image wobbled whenever your hand shook. Nobody had yet worked out how to make them much stronger in a reliable way. And nobody had yet used one to make a series of careful observations, explain what they meant, and announce them to the world in print. The tube was a gadget. It had not yet become a scientific instrument.","That change needed a particular kind of person: someone who understood the mathematics of how lenses bend light, who had a workshop and skilled hands, who was patient enough to grind and test lens after lens, and who was bold enough to point the result at the heavens and argue about what he found. In 1609 such a person happened to be teaching mathematics at a university in northern Italy, close to Venice, where Paolo Sarpi was busy collecting every rumor he could about the Dutch device.","When the news of the Dutch tube reached this professor, he did not just buy one. He decided to build a better one."]}],"deepDive":"Historians of science such as Albert Van Helden have spent decades sorting through the surviving papers about the telescope's origins, and their conclusions are more interesting than a simple 'who was first' answer. The States General documents show two patent requests in October 1608, from Lipperhey on the 2nd and Metius on the 17th, plus signs that other craftsmen knew the trick. The Janssen claim rests mainly on testimony collected in 1655, decades later, from his son, whose dates contradict each other. Most scholars therefore treat the telescope as an invention that surfaced among Dutch lens makers in 1608, possibly more than once, rather than the work of a single lone genius. The physics explains why it was both easy and hard to discover. The magnification of this kind of telescope equals the objective's focal length divided by the eyepiece's focal length. Spectacle makers described lens strength by focal length too, so with an objective of about 30 cm and a concave eyepiece of about 10 cm you get about 3 times, while reaching 10 or 20 times needs a much weaker objective or a much stronger eyepiece than ordinary spectacle stock. That is one reason early instruments stalled at 3 to 6 times until someone ground special lenses. A second problem is lens quality. Glass of the period contained bubbles and streaks, and the curved surfaces were not perfectly spherical, so rays passing near the edge of a lens focused in the wrong place. Makers discovered that masking the objective down to a smaller opening, called stopping down the aperture, sharpened the image, at the cost of making it dimmer. The design also has a built-in limit: because the concave eyepiece spreads light out, the field of view is very narrow, a weakness that later designs would solve. Finally, the speed of the spread deserves attention. From a single letter in October 1608 to shops on the Pont Neuf by April 1609 and a telescopic Moon drawing in England by July 1609 (old style) took less than a year, carried by printed newsletters, diplomatic letters and traveling traders. It is an early example of how a cheap, easily copied technology can escape any attempt to keep it secret.","funFact":"By April 1609, less than seven months after Lipperhey's patent letter, small spyglasses were already on sale in shops on the Pont Neuf bridge in Paris.","check":{"q":"On what date did Hans Lipperhey write to the Dutch government asking for a patent on his 'device for seeing far'?","a":"2 October 1608","wrong":["7 January 1610","13 March 1781","1 April 1590"]},"sources":[{"title":"Hans Lipperhey","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Hans_Lipperhey"},{"title":"History of the telescope","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/History_of_the_telescope"},{"title":"Jacob Metius","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Jacob_Metius"},{"title":"Zacharias Janssen","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Zacharias_Janssen"},{"title":"Telescope","publisher":"The Galileo Project, Rice University","url":"https://galileo.library.rice.edu/sci/instruments/telescope.html"},{"title":"Thomas Harriot","publisher":"The Galileo Project, Rice University","url":"https://galileo.library.rice.edu/sci/harriot.html"},{"title":"Thomas Harriot","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Thomas_Harriot"},{"title":"Ekathotsarot","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Ekathotsarot"}],"photos":[{"src":"img/deep/telescope/03-1.jpg","alt":"An old engraved portrait of Hans Lipperhey, the Middelburg spectacle maker who asked for the first telescope patent in 1608.","file":"Hans Lipperhey.jpg","url":"https://commons.wikimedia.org/wiki/File:Hans_Lipperhey.jpg","author":"Jacob van Meurs","license":"Public domain"},{"src":"img/deep/telescope/03-2.jpg","alt":"Thomas Harriot's drawing of the crescent Moon seen through a telescope on 26 July 1609, months before Galileo's.","file":"Harriot moon drawing 1609.jpg","url":"https://commons.wikimedia.org/wiki/File:Harriot_moon_drawing_1609.jpg","author":"Thomas Harriot","license":"Public domain"},{"src":"img/deep/telescope/03-3.jpg","alt":"How a Galilean telescope works: a convex front lens (L1) and a concave eyepiece (L2) bend light rays into a bigger image.","file":"GalileoFernrohr.png","url":"https://commons.wikimedia.org/wiki/File:GalileoFernrohr.png","author":"Astrodidge","license":"CC BY-SA 3.0"}],"words":3811},{"n":4,"title":"Galileo Turns It Upward","when":"1609 – 1610","summary":"Galileo, a math teacher in Italy, heard about the Dutch spyglass and built a much stronger one himself. He pointed it at the night sky and saw mountains on the Moon, thousands of new stars, and four moons going around Jupiter. He wrote a little book about it that made him famous almost overnight.","sections":[{"heading":"A Professor in Padua","paragraphs":["In the summer of 1609 Galileo Galilei was 45 years old and, by the standards of the day, a successful but not famous man. He had been born in Pisa in 1564, the son of a musician, and he had studied at the University of Pisa before becoming a mathematics teacher. Since 1592 he had been professor of mathematics at the University of Padua, a famous old university about 40 km from Venice. Padua belonged to the Republic of Venice, a rich trading state with a powerful navy and a government run by the Doge and the Senate.","Galileo was a brilliant teacher and an energetic experimenter. He studied falling objects, swinging pendulums and the strength of materials. He also needed money. His salary was modest, he had to help support his family, and he had three children. To earn extra, he took in students who lived in his house, gave private lessons, and ran a small workshop with a skilled craftsman who built instruments to sell, including a calculating device called a geometric and military compass, useful to soldiers and engineers. So Galileo already knew how to design an instrument, get it made, and sell it to people with money.","He was also part of a lively circle of thinkers in Venice. One of his friends was Paolo Sarpi, the scholarly monk we met in the last part, who had been hearing about the Dutch spyglass since November 1608. Sarpi advised the Venetian government on technical matters, and in 1609 a foreigner reportedly came to Venice hoping to sell the Republic a spyglass for a high price. The government asked Sarpi's opinion, and the purchase did not go ahead. Venice, it seemed, was waiting for something better."]},{"heading":"Cracking the Secret in One Night","paragraphs":["Galileo later told the story himself. While he was in Venice in the summer of 1609, he heard reports that a Dutchman had made an instrument that showed distant things as if they were close. Returning to Padua, he thought about how such a thing could work, using what he knew about refraction, the way glass bends light. According to his own account, he worked out the arrangement in a single night, and the next day he built one: a tube, made of lead, with a convex lens at the far end and a concave lens near the eye. It magnified about three times, just like the Dutch instruments.","Many people could make a three-times spyglass by then. What made Galileo different was what he did next. He understood that to get a stronger instrument, the front lens needed a longer focal length, meaning it should be very gently curved, while the eyepiece needed a shorter focal length, meaning it should be strongly curved. The lenses sold in spectacle shops were not right for this. So Galileo learned to grind and polish his own lenses, rubbing glass against curved metal dishes with finer and finer abrasive powders, hour after hour, then testing each one. Many of his lenses turned out badly, and only a few were good enough to keep.","The numbers show why this was so hard. For a magnification of about 20 times, the front lens of a Galilean telescope needs a focal length of roughly a meter, while the concave eyepiece needs a focal length of only about 5 cm. A lens with a focal length of a meter is so gently curved that it looks almost flat, and every tiny error in its shape shows up as blur. A strongly curved little eyepiece is just as fussy. Galileo had to make both kinds, line them up exactly in a long tube, and then test them on distant objects, again and again, until the image came out sharp.","His progress was fast. Within weeks he had an instrument magnifying about 8 or 9 times. By late autumn of 1609 he had one magnifying about 20 times, nearly a meter long, and later he made instruments reaching about 30 times. Two of Galileo's telescopes survive today in the Museo Galileo in Florence. One is a tube of wooden strips covered in leather, once red and decorated with gold, which magnifies about 21 times. The other is made of two wooden half-shells held together with wire and covered in paper, with a note by Galileo himself about its focal length; it magnifies about 14 times. Their front lenses are only a few centimeters across.","Galileo also learned the hard limits of his instrument. Its glass often had bubbles and a greenish tint. To reduce blurring he covered the edges of the front lens so that only the best central part was used, finding the right opening by trial and error. And the field of view, the patch of sky you could see at once, was tiny. With a typical Galilean telescope of 15 to 20 times, you could see only a small part of the full Moon at once, by some estimates about a quarter of it. Aiming it was tricky, and holding it steady was harder still, so he mounted it on a stand. Seeing through it well took skill and practice, which is one reason Galileo stayed ahead of his rivals for months."]},{"heading":"Senators on the Bell Tower","paragraphs":["Galileo knew he had something valuable, and he knew who would want it most: the government of Venice. A city of sailors, merchants and warships cares a great deal about seeing ships approach. In August 1609 he brought his telescope, then magnifying about 8 or 9 times, to Venice to show it off.","Picture the scene. A group of Venice's important men, some of them old and dressed in long official robes, climb high up to look out over the lagoon and the sea beyond, by tradition from the top of the great bell tower of St Mark's Square. Galileo hands them the tube. One after another they put it to their eyes and gasp. Distant boats that look like specks become ships with sails, rigging and crews. People on islands far across the water can be seen going about their business. Galileo wrote that ships could be seen about two hours before they could be spotted with the naked eye.","On 25 August 1609 Galileo formally presented a telescope to the Doge and the Venetian government as a gift. The gift paid off. The Senate gave him a job at Padua for life and roughly doubled his salary, to about 1,000 florins a year. For a professor who had struggled with money, it was a huge reward.","There was a catch, though. Soon after, ordinary spyglasses began appearing in Venetian shops at low prices, and some senators grumbled that they had paid a great deal for something anyone could buy. Galileo's answer, in practice, was to keep improving. The spyglasses on sale were weak toys. His were far better, and he was about to use them for something no merchant or senator had imagined."]},{"heading":"The Moon Has Mountains","paragraphs":["For about two thousand years, many educated Europeans had followed the ideas of the ancient Greek thinker Aristotle about the heavens. Everything above the Moon, he taught, was made of a perfect, unchanging substance, and heavenly bodies were perfect smooth spheres. The dark patches on the Moon, which you can see with your own eyes, were explained in various ways, but the Moon itself was supposed to be a flawless ball.","On 30 November 1609 Galileo turned his 20-power telescope toward the Moon, which was then a crescent a few days old. Over the next few weeks, until about 18 December, he watched it again and again as its phase changed. What he saw did not look like a flawless ball at all. The line between the lit part and the dark part of the Moon, called the terminator, was not a smooth curve. It was ragged and broken. Small bright points of light appeared in the dark part, separated from the lit area, and over a few hours they grew and joined up with it.","Galileo realized what these bright points must be. Think about sunrise in a mountain valley on Earth. The first rays of the Sun light up the tops of the highest peaks while the valley below is still in darkness. Then, as the Sun climbs, the light creeps down the slopes until the whole landscape is lit. The bright points in the Moon's dark side were mountain tops catching the sunrise before the land around them. He also saw dark shadows on the lit side that pointed away from the Sun and grew shorter as the Sun rose higher over them, just as shadows of hills do on Earth. And he saw round hollows with bright rims, which we now call craters.","Galileo did not stop at describing. He used geometry to estimate how tall the mountains were. By measuring how far from the terminator a lit peak sat, compared to the width of the whole Moon, he worked out how high it must stand to catch sunlight that early. His answer was that some lunar mountains were more than four Italian miles high, taller than any mountain he knew in Europe. Modern measurements show that the Moon's highest peaks really do rise several kilometers above the plains around them, so his method worked well.","There was something else. When the Moon is a thin crescent, you can often see the rest of its disk glowing faintly, a ghostly grey shape cradled in the bright curve. This is called earthshine. Galileo explained that it is sunlight reflected off the Earth onto the Moon, the same way moonlight is sunlight reflected off the Moon onto the Earth. (Leonardo da Vinci had written down the same explanation about a century earlier, in notebooks that were not published.) To Galileo it meant that the Earth shone in space just like the planets, which fitted nicely with the idea that Earth was itself a planet.","Galileo had trained in drawing as a young man, and it showed. He made beautiful ink-wash paintings of the Moon at different phases, with soft shading that captures craters and shadows. Compare them with Harriot's simple sketch from a few months earlier and you can see the difference: Harriot recorded what he saw, but Galileo understood it and explained it, turning shapes into a landscape."]},{"heading":"Stars Beyond Counting","paragraphs":["Next Galileo pointed his telescope at the stars, and here too the sky changed before his eyes. Everywhere he looked, there were far more stars than anyone had ever counted. In the small cluster called the Pleiades, sometimes called the Seven Sisters, where sharp eyes see six or seven stars, he found about three dozen. Around the belt and sword of Orion, where the naked eye sees a handful, he counted roughly 80 more. Huge numbers of stars, he realized, were simply too faint for human eyes alone.","He also noticed a curious difference between stars and planets. Through his telescope the planets looked like tiny round disks, little moons. The stars, however, still looked like sharp points of light, only brighter. This hinted that the stars were incredibly far away, much farther than the planets, a clue that the universe might be enormously bigger than people imagined.","Then he turned to the Milky Way, the pale band of light that stretches across a dark sky. People had argued for centuries about what it was. Some thought it was a glow in the air, others some kind of heavenly mist. Galileo settled the question: through his telescope, the Milky Way broke up into countless faint stars packed together, too dim and close to see one by one with the eye. Other small fuzzy patches in the sky, which astronomers called nebulas, from the Latin word for cloud, also split into clusters of stars. Not every nebula would turn out to be made of stars, as later parts of this story show, but on the question of the Milky Way, Galileo was right."]},{"heading":"Four New Worlds Around Jupiter","paragraphs":["On the evening of 7 January 1610, Galileo aimed his telescope at the planet Jupiter, which was shining brightly in the sky. Next to it he noticed three small, bright points of light lying in a straight line with the planet, two on the east side and one on the west. He assumed they were ordinary background stars that happened to be nearby, though he was curious that they lay in such a neat line. (Today we know that one of the three was actually two moons, Io and Europa, so close together that his telescope could not separate them.)","The next night, 8 January, he looked again, perhaps by chance. Now all three points were on the west side of Jupiter, closer together. That was puzzling. If they were fixed stars, then Jupiter must have moved, but in the wrong direction compared with the predictions in astronomers' tables. He waited eagerly for the next night, but clouds covered the sky. On 10 January he saw only two of the points, both to the east. Where had the third gone? Galileo guessed it was hidden behind Jupiter.","Night after night he kept watching and drawing little diagrams in his notebook: a circle for Jupiter and stars beside it, with notes on their positions. On 13 January he saw four small points at once for the first time. By 15 January he had worked it out. These were not background stars at all. They were moving with Jupiter across the sky, and moving back and forth around it. They were moons circling Jupiter, just as our Moon circles the Earth. He kept observing them until 2 March 1610.","It is hard to overstate how surprising this was. For all of human history, people had known of exactly one moon, our own. Now there were four more, circling another world. And this mattered in a huge argument about the universe. Many people who rejected Copernicus's Sun-centered idea asked: if the Earth really moved around the Sun, wouldn't it leave the Moon behind? But here was Jupiter, which everyone agreed moved, carrying four moons along with it. Jupiter's moons did not prove that the Earth went around the Sun, but they showed that not everything in the heavens circled the Earth, and they knocked down one of the objections to Copernicus.","Galileo was not the only person to see these moons that winter. The German astronomer Simon Marius later said he had seen them first, in late 1609. When historians match up the different calendars then in use, Marius's first clear record turns out to be from 8 January 1610, one day after Galileo, and he very likely discovered them independently. But Galileo published first, and publishing is what put his name on the discovery.","Today we know a great deal about these four moons. Io, the closest to Jupiter, races around it in less than two days and is covered in erupting volcanoes. Europa, a little smaller than our Moon, has an icy crust that probably hides an ocean of salty water. Ganymede, which takes about a week per orbit, is the largest moon in the whole Solar System, bigger than the planet Mercury. Callisto, the outermost, takes about 16.7 days and is covered with ancient craters. Galileo simply numbered them I, II, III and IV from the inside out. The names we use now came from Marius, who took a suggestion from Johannes Kepler to name them after figures from Greek myths linked to Zeus, the Greek version of Jupiter. Kepler also gave us another word from this discovery: he was the one who started calling such moons 'satellites.'"]},{"heading":"Why Galileo, and Not Someone Else?","paragraphs":["Galileo did not invent the telescope, and he was not the first person to point one at the sky. Thomas Harriot drew the Moon months earlier, Simon Marius was watching Jupiter at almost the same time, and others with spyglasses surely glanced upward too. So why is it Galileo whose name is tied to these discoveries? Historians usually point to a handful of reasons, and together they tell us a lot about how science works.","First, he had better tools. Most spyglasses of 1609 magnified three to six times. Galileo's best magnified about 20 times or more, because he had taught himself to grind special lenses instead of using spectacle lenses from a shop. At six times, Jupiter's moons are very hard to pick out, and the Moon's mountains look like vague smudges. At 20 times, the moons appear as clear points and the Moon's terminator shows sharp, jagged detail. Other astronomers needed about six months to get instruments good enough to see what he had seen.","Second, he observed patiently and systematically. He did not just look once and say 'how interesting.' He returned to the Moon night after night as its phase changed, and he tracked Jupiter's little points of light through January, February and into March, writing down their positions and drawing them each time. It was the pattern over many nights, not any single glance, that proved the points were moons.","Third, he explained what he saw. Harriot drew the Moon's ragged edge, but Galileo worked out that it was caused by mountains and shadows and even measured their height with geometry. Seeing is only half of discovery; understanding is the other half.","Fourth, and very importantly, he published, quickly and clearly, in a language every scholar could read. A discovery locked in a private notebook, like Harriot's, cannot change what anyone else thinks. A printed book can travel across a continent in weeks. Finally, Galileo was a gifted writer and a skilled self-promoter who knew how to win powerful supporters. That talent helped him greatly in 1610. As the next part shows, it would also help to land him in serious trouble."]},{"heading":"The Starry Messenger","paragraphs":["Galileo knew he had to announce his discoveries quickly, before someone else did. He wrote a short book in Latin, the language that scholars all over Europe could read, and rushed it into print in Venice. It was published on 13 March 1610, just about two months after he first saw Jupiter's moons. Its title was Sidereus Nuncius, which can be translated as 'The Starry Messenger' or 'The Starry Message.' It was the first published scientific book based on observations made with a telescope.","The book is short, only a few dozen pages, but it is packed. It describes how Galileo built his instrument and how others could check his work. It shows his pictures of the Moon's mountains and craters, his maps of the extra stars in the Pleiades and Orion, and his explanation of the Milky Way. And it includes many little diagrams of Jupiter with its moons in different positions, night by night, so readers could follow the discovery as he made it. Around 550 copies were printed, and they are said to have sold out within days.","Galileo was also thinking carefully about his career. He dedicated the book to Cosimo II de' Medici, the young Grand Duke of Tuscany, who had once been his pupil. At first he wanted to call the moons the 'Cosmian Stars' after Cosimo himself, but he changed it to the 'Medicean Stars,' in honor of Cosimo and his three brothers, four brothers for four moons. He sent telescopes to important rulers so they could see the moons for themselves. The plan worked. In the summer of 1610 he was named chief mathematician and philosopher to the Grand Duke of Tuscany and soon moved to Florence, with a good salary and no teaching duties, free to spend his time on research.","Not everyone was convinced. Some scholars claimed the new moons were just tricks of the lenses, flaws in the glass rather than real objects. A few refused to look at all. Others could not see the moons with the poor spyglasses they owned. But Johannes Kepler, the great German astronomer, wrote a public letter in support of Galileo in April 1610, and as better telescopes spread, more and more astronomers saw the moons for themselves. The arguments that followed belong to the next part of this story.","By now the instrument needed a proper name. Galileo called it a perspicillum, a Latin word, and Italians called it an occhiale, an eyeglass. On 14 April 1611, Prince Federico Cesi held a banquet in Rome to welcome Galileo as a member of his scientific society, the Accademia dei Lincei, or Academy of the Lynxes, named after the sharp-eyed wild cat. At that banquet a Greek scholar named Giovanni Demisiani suggested a new word built from two Greek parts: tele, meaning far, and skopein, meaning to look. The word was telescope, and it stuck.","In less than a year, a spyglass made for spotting ships had shown mountains on the Moon, uncounted stars in the Milky Way and four moons circling Jupiter. Moons around Jupiter showed that not everything circles the Earth. And the next discoveries would put Galileo on a collision course with powerful people."]}],"deepDive":"How did Galileo measure a mountain he could never visit? His method in Sidereus Nuncius is a lovely piece of geometry. Imagine the Moon as a ball, with the terminator marking where sunlight just skims the surface. A peak standing in the dark part beyond the terminator lights up when its top pokes high enough to catch a sunbeam that grazes the surface at the terminator. That grazing sunbeam, the Moon's radius from the center to the terminator, and the line from the center up to the peak's summit form a right-angled triangle. Galileo judged that some bright points sat about one-twentieth of the Moon's diameter away from the terminator. Taking the Moon's diameter as about 2,000 Italian miles, a figure based on the size estimates of his day, the Pythagorean theorem gives a height of a few miles, and Galileo announced that some lunar mountains were more than four miles high. The method is sound; the main uncertainties are judging tiny distances by eye through a wobbly 20-power telescope and the old estimate of the Moon's size. Modern measurements show the Moon's tallest peaks rise roughly 5 km above their surroundings, so Galileo was in the right range. His telescope's design limits are just as interesting. A Galilean telescope's field of view shrinks as magnification rises, because the concave eyepiece cannot gather the outer rays coming from the objective. At about 20 times, Galileo could see only part of the Moon at once, and to find Jupiter he had to aim along the tube with great care. The glass, full of bubbles and streaks, forced him to stop down the objective, so the working opening was noticeably smaller than the lens itself, which made faint objects even harder to see. Historians also discuss the calendar puzzle in the Jupiter story. Catholic Italy used the new Gregorian calendar, while Protestant parts of Germany, where Marius lived, still used the older Julian calendar, ten days behind. Once dates are converted, Marius's first record falls on 8 January 1610, one day after Galileo's. Most scholars accept that Marius saw the moons independently, while Galileo deserves credit for the first publication and for proving the objects were orbiting Jupiter.","funFact":"Ganymede, one of the four moons Galileo discovered around Jupiter, is the largest moon in the Solar System and is even bigger than the planet Mercury.","check":{"q":"What name did Galileo give to the four moons he discovered circling Jupiter in January 1610?","a":"The Medicean Stars","wrong":["The Lincei Lights","The Dutch Stars","The Venetian Moons"]},"sources":[{"title":"Galileo Galilei","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Galileo_Galilei"},{"title":"Sidereus Nuncius","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Sidereus_Nuncius"},{"title":"Galilean moons","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Galilean_moons"},{"title":"Telescope","publisher":"The Galileo Project, Rice University","url":"https://galileo.library.rice.edu/sci/instruments/telescope.html"},{"title":"Satellites of Jupiter","publisher":"The Galileo Project, Rice University","url":"https://galileo.library.rice.edu/sci/observations/jupiter_satellites.html"},{"title":"The Moon","publisher":"The Galileo Project, Rice University","url":"https://galileo.library.rice.edu/sci/observations/moon.html"},{"title":"Galileo's instruments","publisher":"Museo Galileo, Florence","url":"https://www.museogalileo.it/en/galileo/instruments-en.html"},{"title":"Jupiter Moons","publisher":"NASA Science","url":"https://science.nasa.gov/jupiter/jupiter-moons/"}],"photos":[{"src":"img/deep/telescope/04-1.jpg","alt":"Galileo's ink-wash drawings of the Moon from 1609, showing craters and the ragged line between light and shadow.","file":"Galileo moon phases.jpg","url":"https://commons.wikimedia.org/wiki/File:Galileo_moon_phases.jpg","author":"Galileo Galilei","license":"Public domain"},{"src":"img/deep/telescope/04-2.jpg","alt":"Part of a page of Sidereus Nuncius (1610): Galileo's sketches of Jupiter (circle) with its moons (stars) on different nights.","file":"Sample of Sidereus Nuncius drawings of Jupiter and the Medicean Stars (medicean stars iautheme).jpg","url":"https://commons.wikimedia.org/wiki/File:Sample_of_Sidereus_Nuncius_drawings_of_Jupiter_and_the_Medicean_Stars_(medicean_stars_iautheme).jpg","author":"History of Science Collections, University of Oklahoma Libraries","license":"CC BY 4.0"},{"src":"img/deep/telescope/04-3.jpg","alt":"Galileo's two surviving telescopes, made around 1609-1610, on display at the Museo Galileo in Florence.","file":"Galilei telescopes, Museo Galileo, Florence, Inv. 242, 2428, 224088.jpg","url":"https://commons.wikimedia.org/wiki/File:Galilei_telescopes,_Museo_Galileo,_Florence,_Inv._242,_2428,_224088.jpg","author":"Zde","license":"CC BY-SA 4.0"}],"words":3846},{"n":5,"title":"Phases, Spots and Trouble","when":"1610 – 1642","summary":"Galileo kept looking, and the sky kept surprising him: Venus grew and shrank like a little Moon, the Sun had dark spots, and Saturn seemed to have ears. His discoveries showed that the Earth goes around the Sun, but some powerful people did not want to hear it, and Galileo spent his last years stuck at home.","sections":[{"heading":"Venus Puts On a Moon Costume","paragraphs":["In the autumn of 1610 Galileo Galilei was busier and more famous than he had ever been. His little book The Starry Messenger had made him a celebrity across Europe, and that summer he had left his teaching job in Padua to become Chief Mathematician and Philosopher to Cosimo II de' Medici, the Grand Duke of Tuscany, in Florence. No more lectures to bored students. Now he could spend his nights doing what he loved most: pointing his best telescope, about 20 times magnification, at anything bright enough to catch.","One of the brightest things in the evening sky that autumn was Venus. To the naked eye, Venus is a dazzling white dot, so bright that people sometimes mistake it for an airplane's landing light. Through Galileo's tube it was a small disk. But week after week, starting around September 1610 and continuing to the end of the year, he watched that disk do something remarkable. At first it looked almost round, like a tiny full Moon. Then it grew larger and, at the same time, lost part of its light, becoming a half-circle like a quarter Moon. Later still it became a big, thin crescent, like a fingernail clipping of light.","In other words, Venus has phases, just as our Moon does. And it changes size dramatically while doing so. Modern measurements show that Venus looks about seven times wider when it is a thin crescent near Earth than when it is a small, nearly full disk on the far side of the Sun.","Why was this such a big deal? Think back to the old Earth-centered system of Ptolemy, which most scholars still used in 1610. In Ptolemy's arrangement, Venus always stayed between the Earth and the Sun, riding on its own little circle. A planet that stays on the near side of the Sun would always have its sunny side facing mostly away from us. We would see it as a crescent or a thin sliver, never anything close to full. But Galileo saw Venus nearly full. The only way that can happen is if Venus sometimes goes around to the far side of the Sun, so that its whole sunlit face points toward us. That means Venus circles the Sun.","This was the first direct, observed proof that at least one planet orbits the Sun rather than the Earth. It did not prove every part of Copernicus's idea. A clever compromise invented by Tycho Brahe, in which the planets circle the Sun while the Sun circles a motionless Earth, could also explain the phases of Venus. But the classic Ptolemaic system, the standard picture of the heavens for more than 1,400 years, was now in serious trouble.","Galileo was worried someone else might announce the discovery first. In December 1610 he did something sneaky that scientists of his time often did: he sent a scrambled sentence, an anagram, to Kepler by way of the Tuscan ambassador in Prague. The jumbled Latin letters read, roughly, 'These unripe things are now read by me in vain.' A few weeks later he revealed the unscrambled message: 'Cynthiae figuras aemulatur mater amorum,' which means 'The mother of love imitates the shapes of Cynthia.' The mother of love was Venus, the goddess of love, and Cynthia was a poetic name for the Moon. In a single coded line, Galileo had claimed the discovery and kept it secret at the same time.","Was Galileo really first? Historians have noticed that his former student Benedetto Castelli wrote to him in December 1610 asking whether Venus might show phases through a telescope. Whether Castelli was giving Galileo the idea or responding to news Galileo had already shared is still debated. What is certain is that Galileo made the observations carefully, understood what they meant, and published them in 1613."]},{"heading":"Spots on the Perfect Sun","paragraphs":["For about 2,000 years, many European scholars followed the Greek philosopher Aristotle, who taught that everything above the Moon was perfect, eternal and unchanging. The Sun, in this view, was a flawless ball of heavenly fire. Galileo had already shown that the Moon was rough and mountainous. Now the Sun itself was about to get messy.","Dark spots on the Sun had actually been seen long before telescopes. Chinese astronomers recorded them with the naked eye more than 2,000 years ago, when haze or a low sunset dimmed the glare enough to make a big spot visible. But in Europe such reports were usually explained away, for example as a planet passing in front of the Sun.","Once telescopes appeared, several people spotted sunspots within a few months of each other. The English scientist Thomas Harriot sketched them in December 1610 but never published his drawings. In Germany, a young man named Johannes Fabricius, working with his father David, saw them in early 1611 and printed the first published description that same year. Galileo said he had been watching sunspots since 1610 and showing them to visitors.","Then came Christoph Scheiner, a Jesuit priest and mathematics professor at the university in Ingolstadt, Bavaria. In 1611 Scheiner and his student Johann Baptist Cysat studied the spots carefully. Because Jesuits were cautious about publishing controversial ideas, Scheiner wrote three letters about them to a wealthy Augsburg merchant and scholar named Mark Welser, signing them with a pen name: 'Apelles,' after a famous painter of ancient Greece who supposedly hid behind his paintings to hear what people said about them. Welser had the letters printed in January 1612.","Scheiner's explanation tried to protect the perfect Sun. He suggested the spots were not on the Sun at all, but were swarms of small dark bodies, perhaps tiny planets or moons, circling close to it and passing in front of its face.","Galileo strongly disagreed. Welser sent him the Apelles letters, and Galileo answered with three long letters of his own, which the Accademia dei Lincei, a scientific society in Rome that had made him a member, published in 1613 as Letters on Sunspots. Galileo's arguments were clever. He pointed out that spots near the edge of the Sun look squashed and thin, while the same spots look wider in the middle of the disk. That is exactly what you would expect from markings on the surface of a turning ball, the same way a picture printed on a basketball looks squeezed when it rotates toward the edge. Spots also changed shape, merged, split, appeared and vanished. They behaved like clouds or stains on the Sun, not like solid little planets. And they all moved across the face together, which showed the Sun itself was spinning, about once a month.","Galileo also had a better way to see them. Instead of squinting at the Sun, his circle used a method credited to Castelli: aim the telescope at the Sun and let the image fall on a sheet of white paper held behind the eyepiece. The spots could then be traced with a pen. The book's 38 detailed engravings of the Sun made the spots look strikingly real.","The argument turned personal. Galileo hinted that he deserved credit for seeing the spots first, and Scheiner felt insulted. The quarrel lasted for years. To be fair to Scheiner, he became one of the finest sunspot observers of his century. In his huge book Rosa Ursina, printed between 1626 and 1630, he published detailed observations, described his own instruments for projecting the Sun, and measured the Sun's rotation at about 27 days. By then he had accepted that the spots really were on the Sun. Today we know sunspots are cooler, darker patches where tangled magnetic fields stop some heat from rising to the surface. Each one can be bigger than the whole Earth."]},{"heading":"Safety Box: Never Look at the Sun Through a Telescope","paragraphs":["Before we go any further, here is the most important rule in this whole Deep Dive. Never, ever look at the Sun through a telescope, binoculars, a camera viewfinder or any other magnifying device unless it has a proper, certified solar filter fitted securely over the front end, the end that faces the Sun.","Here is why. A telescope's whole job is to collect light and squeeze it together. A small backyard telescope might collect hundreds of times more light than your eye. When it is pointed at a dim galaxy, that is wonderful. When it is pointed at the Sun, it focuses an enormous amount of light and heat into one tiny spot, like a magnifying glass burning a leaf. The retina at the back of your eye has no pain nerves, so it can be badly and permanently damaged in a fraction of a second before you even feel anything.","Ordinary sunglasses are not safe for looking at the Sun, not even several pairs at once. Eclipse glasses that meet the international safety standard called ISO 12312-2 are safe for looking at the Sun with your bare eyes, but NASA warns that they must never be used together with binoculars, telescopes or cameras, because the concentrated light can burn straight through them. Optical instruments need their own special filters made for solar viewing, mounted on the front, and it is wise to ask an experienced astronomer to help.","The safest easy way to watch the Sun is the way Galileo's circle traced sunspots: projection. You can poke a tiny hole in an index card, stand with your back to the Sun, and let sunlight through the hole form a small image of the Sun on another card or on the ground. During a partial eclipse, that little image even shows the Moon taking a bite out of the Sun. Just remember: look at the image, never through the hole at the Sun."]},{"heading":"The Planet With Ears","paragraphs":["In July 1610, before he saw the phases of Venus, Galileo pointed his telescope at Saturn, the slowest and most distant planet known at the time. He expected a simple round disk. Instead, Saturn looked strange, as if it were three objects: a large central ball with a smaller blob stuck tightly on each side. Galileo wrote that Saturn seemed to be made of three bodies that almost touched one another and never moved relative to each other.","Once again he protected his claim with an anagram. He sent out a string of 37 seemingly random letters: smaismrmilmepoetaleumibunenugttauiras. When unscrambled, it read 'Altissimum planetam tergeminum observavi,' meaning 'I have observed the highest planet to be triple.'","Then Saturn played a trick. In late 1612, Galileo looked again and the side blobs had vanished completely. Saturn was a plain, lonely ball. He was baffled and admitted in writing that he did not know what to say about something so surprising and so new.","The blobs came back in 1613. Later Galileo drew Saturn with two curved shapes on its sides like the handles of a sugar bowl or a pair of ears. The 'ears' grew and shrank over the years in a way nobody could explain.","Today we know the answer. Saturn is surrounded by enormous, flat, very thin rings made of countless chunks of ice and rock. They stretch hundreds of thousands of kilometers across but are mostly only about 10 meters to perhaps 1 kilometer thick. Galileo's small telescope could not show the gap between the planet and the rings, so they looked like attached lumps. And because Saturn is tilted, Earth sees the rings from different angles as Saturn travels its 29-year orbit. About every 13 to 15 years, the rings line up exactly edge-on to us. Seen from the side, something that thin almost disappears, which is exactly what happened in 1612.","Galileo never solved the puzzle. It took about 45 more years, a better telescope and a sharp-eyed young Dutchman to figure it out, and that story belongs to the next part."]},{"heading":"Believers, Doubters and a Borrowed Telescope","paragraphs":["When The Starry Messenger came out in March 1610, many readers were thrilled, but many others were suspicious. Remember, almost nobody else had a telescope as good as Galileo's. Cheap Dutch spyglasses magnified only about three times, which was not enough to see Jupiter's moons clearly. So when Galileo claimed he had found four new worlds circling Jupiter, plenty of scholars wondered whether he was seeing reflections, flaws in the glass, or things that were not there at all.","One of the most famous doubters was Cesare Cremonini, a philosophy professor at Padua and actually a friend and colleague of Galileo's. Cremonini was a devoted follower of Aristotle. According to accounts from the time, when he was invited to look at the Moon's mountains through the telescope, he refused even to put his eye to it, insisting that Aristotle had already shown the Moon must be a perfect sphere. Another Aristotelian professor, Giulio Libri of Pisa, is also said to have refused. Their refusal has become a famous symbol of closing your eyes to evidence, though to be fair, looking through a wobbly early telescope was genuinely tricky, and even people who did look sometimes could not see what Galileo described.","The most important supporter was Johannes Kepler, the Imperial Mathematician to the Holy Roman Emperor in Prague, the same Kepler who had inherited Tycho Brahe's records. Galileo sent him a copy of the book and asked his opinion. Kepler did not yet own a telescope good enough to check, but in April 1610 he published a short, enthusiastic reply called Conversation with the Starry Messenger. He said he trusted Galileo's honesty and began thinking about what the new discoveries might mean.","Kepler still wanted to see for himself. Later in 1610 he borrowed a telescope that Galileo had sent to Duke Ernest of Cologne, a nobleman who was visiting Prague. Over several nights at the end of the summer, Kepler and a few witnesses took turns at the eyepiece. To keep the test honest, each observer is said to have drawn what he saw separately, using chalk on a board, and then they compared their sketches. The tiny points of light beside Jupiter were really there. Kepler quickly published a short report, Narration About Four Wandering Satellites of Jupiter, which was one of the first independent confirmations of Galileo's discovery. It was Kepler who began using the word 'satellite,' from a Latin word for an attendant who follows an important person around, for moons circling a planet.","Support soon came from an unexpected place. The Jesuit astronomers at the Collegio Romano in Rome, led by the respected mathematician Christopher Clavius, managed to get a good telescope and confirmed Jupiter's moons and the phases of Venus. When Galileo visited Rome in the spring of 1611, the Jesuits honored him with a special event, and he was welcomed by cardinals and even Pope Paul V. It was during this visit that he was made a member of the Accademia dei Lincei. Galileo's discoveries were accepted as real. What people would do with them was a different question."]},{"heading":"The Warning of 1616","paragraphs":["Seeing that Venus circles the Sun was one thing. Saying that the Earth itself moves around the Sun was another. In the early 1600s, many religious leaders read certain lines of the Bible, such as a passage in the Book of Joshua where the Sun is commanded to stand still, as meaning the Sun moves and the Earth stays put. Galileo's growing fame drew attention to Copernicus's idea, and some critics began to say that it contradicted Scripture.","Galileo did not keep quiet. In a letter written in 1613 to his former student Castelli, and then in a much longer letter to the Grand Duke's mother, Christina of Lorraine, in 1615, he argued that the Bible was meant to teach people how to go to heaven, not how the heavens go. If careful observation proved something about nature, he said, then the Bible should be read in a way that fit the facts. At the time, some churchmen thought a mathematician had no business telling theologians how to read Scripture. Copies of the letter to Castelli were sent to the Roman Inquisition, the Church court in charge of fighting heresy, which means beliefs that go against official teaching.","In February 1616 the Inquisition asked a panel of theologians to judge two statements: that the Sun is the motionless center of the world, and that the Earth moves. On 24 February they declared the first one foolish, absurd in philosophy and formally heretical, and the second one at least an error in faith. Two days later, on 26 February 1616, the powerful Cardinal Robert Bellarmine called Galileo in and told him to abandon the Copernican opinion and not to hold or defend it. Exactly what else Galileo was told that day, and whether he was forbidden to discuss the idea in any way at all, became a crucial question many years later, because the surviving records do not completely agree.","On 5 March 1616 the Congregation of the Index, the office that kept a list of forbidden books, suspended Copernicus's On the Revolutions until it was 'corrected.' The corrections, issued a few years later, were mostly small edits that made the Sun-centered system sound like a calculating trick rather than a description of reality. Books arguing that the Earth really moves were banned. Galileo himself was not punished, and he went home to Florence and studied other things for several years."]},{"heading":"A Dialogue and a Trial","paragraphs":["In 1623 everything seemed to change. A Florentine cardinal named Maffeo Barberini, who admired Galileo and had once written a poem praising him, was elected Pope Urban VIII. Galileo traveled to Rome and met the new pope several times. He came away believing he could write about the Copernican system, as long as he presented it fairly as one possible idea alongside the traditional one, and did not claim it was proven.","He spent years writing a big book called Dialogue Concerning the Two Chief World Systems. Instead of a dry textbook in Latin, he wrote it in lively Italian so that ordinary educated readers could enjoy it. It takes the form of a conversation over four days among three friends: Salviati, a brilliant scientist who argues for Copernicus; Sagredo, an intelligent, open-minded nobleman; and Simplicio, a loyal follower of Aristotle and Ptolemy. After getting official permission from Church censors, the book was printed in Florence, and the first copy was presented to Grand Duke Ferdinando II on 22 February 1632.","The trouble was that the book did not feel balanced. Salviati's arguments shine, Sagredo usually agrees with him, and Simplicio, whose name sounds like 'simpleton' in Italian even though it came from an ancient philosopher named Simplicius, often looks silly. Worse, Galileo put one of the pope's own favorite arguments into Simplicio's mouth near the end of the book. Urban VIII was furious and felt betrayed. Within months, sales were stopped and Galileo was ordered to come to Rome.","Galileo was 68, unwell, and begged to be excused, but he had to go. He arrived in Rome in February 1633 and was questioned by the Inquisition from April onward. The key accusation was that he had disobeyed the order given to him in 1616. Galileo claimed his book did not truly defend Copernicus, which was hard to believe for anyone who had read it. In his last questioning he was threatened with torture if he did not tell the truth about his beliefs. This threat was a standard legal step at the time, and historians agree it was not carried out on him.","On 22 June 1633 the court gave its verdict: Galileo was 'vehemently suspected of heresy.' Kneeling in a hall of the convent of Santa Maria sopra Minerva in Rome, dressed in the white robe of a penitent, the old scientist read aloud a statement in which he abjured, which means formally took back, cursed and rejected the idea that the Sun is the center and the Earth moves. The Dialogue was banned, and it stayed on the list of forbidden books until 1835. He was sentenced to prison at the Inquisition's pleasure, but the next day this was changed to house arrest.","You may have heard that as he stood up, Galileo muttered 'Eppur si muove,' 'And yet it moves.' It is a wonderful line, but it is a legend. There is no evidence he said it, and the story first appears in writing more than a century after his death. Saying such a thing in front of the Inquisition would also have been extremely dangerous. Another myth says Galileo was burned at the stake. He was not. The philosopher Giordano Bruno had been burned in Rome in 1600, but for a long list of religious beliefs, not for astronomy alone, and Galileo's punishment was very different."]},{"heading":"The Prisoner of Arcetri","paragraphs":["Galileo first spent several months in Siena as the guest of his friend Archbishop Ascanio Piccolomini, who treated him kindly and encouraged him to work. Then, at the end of 1633, he was allowed to move to his small country house, called Il Gioiello, which means 'the jewel,' in the hills of Arcetri just outside Florence. He chose it partly to be near the convent where his eldest daughter lived as a nun. Her name was Sister Maria Celeste, and her warm, funny, worried letters to her father still survive. Sadly, she died in April 1634, only months after he arrived, and Galileo was heartbroken.","House arrest meant he could not leave without permission, and visitors were watched. But Galileo did not give up science. He went back to work he had begun decades earlier on how things move and how strong materials are, from falling objects to swinging pendulums to why giant animals need thick bones. The result was his book Two New Sciences. Because his works could not be printed in Catholic Italy, the manuscript was smuggled out and published in 1638 in the Netherlands, the same country where the telescope had first appeared. Many scientists consider it the start of modern physics.","By then Galileo's eyes were failing. He lost sight in one eye and then, around 1638, became completely blind. Doctors today are not sure exactly why. Eye diseases such as cataracts or glaucoma are possible explanations, and there is no good evidence that looking at the Sun was the cause. Yet his mind kept working. Late in life, while blind, he even described a design for a clock controlled by a pendulum to his son Vincenzo, who later tried to build it.","He had some remarkable visitors. Young students came to help him: Vincenzo Viviani, who later wrote his biography, and Evangelista Torricelli, who would soon invent the barometer. The young English poet John Milton later wrote that he had visited the famous Galileo, grown old and a prisoner of the Inquisition.","Galileo died at Arcetri on 8 January 1642, at the age of 77. The Grand Duke wanted to give him a grand tomb, but the pope objected, so he was buried quietly in a side room of the Basilica of Santa Croce in Florence. Only in 1737, nearly a century later, was he moved to a splendid monument in the main church, where visitors can see it today. During that move, a few of his fingers and a tooth were removed by admirers. One of his fingers is still on display at the Museo Galileo in Florence, pointing upward toward the sky.","The story had one more chapter, 350 years later. In 1979 Pope John Paul II asked scholars to study the Galileo case again, and in 1981 a special commission was formed. On 31 October 1992, in a speech to the Pontifical Academy of Sciences, the pope acknowledged that the theologians who condemned Galileo had made a mistake, because they had confused the Bible's meaning with one particular way of reading it. By then, of course, spacecraft had flown past every planet Galileo knew, and one of them, NASA's Galileo probe, was on its way to orbit Jupiter and study the very moons he had discovered.","Yet even in Galileo's lifetime, his famous tube was already being left behind. It had a hidden weakness: looking through it was like peering through a keyhole, with a field of view so tiny that only a small part of the Moon fit inside at once. And his correspondent Kepler had already worked out a better design, on paper."]}],"deepDive":"Historians now see the Galileo affair as more complicated than a simple fight between science and religion. On the science side, Galileo's telescope evidence was powerful but not complete. The phases of Venus ruled out Ptolemy, yet they fit Tycho Brahe's geo-heliocentric system just as well, and many Jesuit astronomers switched to Tycho's model rather than to Copernicus's. A real proof that the Earth moves needed things nobody could yet measure: stellar parallax, the tiny yearly shift in a nearby star's position, was not detected until 1838, and the aberration of starlight was found by James Bradley in 1729. Galileo's own favorite proof, that Earth's motion causes the tides, was wrong; the Moon's gravity is the main cause, as Kepler had suspected. Galileo also ignored Kepler's discovery that planets move in ellipses, which made the Copernican system far more accurate. On the legal side, the trial turned on an unsigned document in the Inquisition's files saying that in 1616 Galileo had been forbidden to 'hold, teach or defend' the idea 'in any way whatever.' Galileo produced a certificate from Bellarmine that said only that he must not hold or defend it. Scholars still argue whether the stricter note was an accurate record, a misunderstanding, or improperly made. Politics mattered too: Urban VIII was under attack during the Thirty Years' War for being too soft on heresy, and Galileo's apparent mockery came at a bad moment. None of this makes the verdict right; the Church itself said in 1992 that it was a mistake. But it reminds us that big scientific ideas usually win through accumulating evidence, careful argument and time, not a single dramatic moment. Within about 50 years of Galileo's death, Newton's laws of motion and gravity explained why planets orbit the Sun, and by the 1700s educated people across Europe accepted that the Earth moves. Catholic restrictions on Sun-centered books were gradually lifted, with works teaching Earth's motion as physical fact formally allowed by the 1820s, and the Dialogue left the Index in 1835.","funFact":"Galileo died in January 1642, and Isaac Newton, who would go on to build the first practical reflecting telescope, was born in England at the end of that same year.","check":{"q":"Why did seeing a nearly full Venus show that Venus goes around the Sun?","a":"Venus can only look nearly full if it sometimes passes behind the Sun, so it must orbit the Sun","wrong":["Because Venus is closer to the stars than Earth is","Because Venus was seen to have its own moons","Because Venus stayed exactly the same size all year"]},"sources":[{"title":"Phases of Venus","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Phases_of_Venus"},{"title":"Letters on Sunspots","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Letters_on_Sunspots"},{"title":"Christoph Scheiner","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Christoph_Scheiner"},{"title":"Galileo affair","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Galileo_affair"},{"title":"Galileo Galilei","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Galileo_Galilei"},{"title":"Dialogue Concerning the Two Chief World Systems","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Dialogue_Concerning_the_Two_Chief_World_Systems"},{"title":"Rings of Saturn","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Rings_of_Saturn"},{"title":"Eclipse Safety","publisher":"NASA Science","url":"https://science.nasa.gov/eclipses/safety/"}],"photos":[{"src":"img/deep/telescope/05-1.jpg","alt":"Galileo's drawing of sunspots on the Sun's disk, made on 23 June 1612, like those in his 1613 Letters on Sunspots.","file":"Sunspots recorded by Galileo (iau1508a).jpg","url":"https://commons.wikimedia.org/wiki/File:Sunspots_recorded_by_Galileo_(iau1508a).jpg","author":"The Galileo Project/M. Kornmesser","license":"CC BY 4.0"},{"src":"img/deep/telescope/05-2.jpg","alt":"'Galileo before the Holy Office' (Robert-Fleury, 1847): an imagined scene of Galileo facing the Inquisition in Rome in 1633.","file":"Galileo before the Holy Office.jpg","url":"https://commons.wikimedia.org/wiki/File:Galileo_before_the_Holy_Office.jpg","author":"Joseph-Nicolas Robert-Fleury","license":"Public domain"},{"src":"img/deep/telescope/05-3.jpg","alt":"Frontispiece and title page of Galileo's Dialogue (Florence, 1632): Aristotle, Ptolemy and Copernicus talking together.","file":"Galileos Dialogue Title Page.png","url":"https://commons.wikimedia.org/wiki/File:Galileos_Dialogue_Title_Page.png","author":"Giovanni Battista Landini","license":"Public domain"}],"words":4367},{"n":6,"title":"Kepler's Design and the Super-Long Telescopes","when":"1611 – 1690s","summary":"Kepler figured out a better telescope using two bulging lenses, but it turned everything upside down. To get sharp pictures, astronomers built telescopes longer than a ship, some with no tube at all, and used them to find new moons of Saturn, explain its rings, and even measure the speed of light.","sections":[{"heading":"Kepler's Telescope on Paper","paragraphs":["In the summer of 1610, Johannes Kepler was in Prague, still excited about Galileo's discoveries. He had just peered through a borrowed telescope and seen Jupiter's moons for himself. But Kepler was not mainly an observer. His eyesight had been weak since a childhood illness, and his real talent was thinking. So instead of polishing lenses, he sat down to work out, with geometry, exactly how lenses bend light and why a telescope works at all.","By September 1610 he had finished a manuscript, and it was printed in 1611 under the title Dioptrice, from a Greek word for seeing through. It was one of the first books to explain the optics of lenses in a scientific way. Kepler described how a convex lens, one that bulges outward, brings light rays together, and how a concave lens, one that dips inward, spreads them apart. He explained the difference between a real image, which is formed where light rays actually meet and can be caught on a screen, and a virtual image, which only seems to be there when you look through the glass. And he showed how the focal length of each lens, the distance at which it brings light to a focus, controls how much a telescope magnifies.","Then Kepler proposed something new. Galileo's telescope, like the original Dutch spyglass, used a convex lens at the front and a concave lens at the eye. That arrangement gives an upright image, which is perfect for looking at ships or soldiers. But the concave eyepiece has a big drawback. Light from the edges of the view spreads out and misses your pupil, so you see only a small circle in the middle. Looking through one of Galileo's best telescopes, at about 20 times magnification, the view was only about half as wide as the full Moon, so you could never see the whole Moon at once. Finding anything was frustrating, and following a moving planet was worse.","Kepler's idea was to use two convex lenses. The front lens, the objective, brings light from a distant object to a focus and forms a small real image inside the tube. The second convex lens, the eyepiece, is placed just beyond that focus and acts like a magnifying glass for looking at the image. Because the eyepiece gathers the rays and sends them neatly into your eye, the field of view is much wider and you can see much more of the sky at once. Crucially, because the image inside the tube really exists at one spot, anything placed at that spot, such as a thin wire, appears sharp and in focus against the stars. That fact would turn out to be extremely important.","There was a catch. When light rays cross over at the focus, the picture flips. A Keplerian telescope shows everything upside down and reversed left to right. If you are a sailor trying to read a flag on a distant ship, that is annoying. But a star or a planet has no right way up, so for astronomers it barely mattered. Kepler himself does not seem to have built one. His design waited a few years for craftsmen to try it."]},{"heading":"Scheiner's Experiments and Gascoigne's Spider","paragraphs":["One of the first people to put Kepler's design to work was Christoph Scheiner, the Jesuit sunspot observer who had quarreled with Galileo. In the 1610s and 1620s Scheiner experimented with telescopes made of two convex lenses and described them in his giant sunspot book, Rosa Ursina. The wide field of view made it much easier to project and trace the whole disk of the Sun. Scheiner also realized that adding a third convex lens could flip the image back the right way up, an idea that led to later spyglasses for use on land. In Naples, a lawyer turned lens maker named Francesco Fontana was building Keplerian telescopes in the 1630s and 1640s and used them to draw the Moon and planets. By the middle of the 1600s, most serious astronomers had switched to Kepler's design.","The most important trick of the Keplerian telescope was discovered almost by accident, and it involved a spider. Around 1638 to 1640, a young astronomer named William Gascoigne was observing at his home at Middleton, near Leeds in the north of England. While he was using a Keplerian telescope, a spider spun a thread inside it. To Gascoigne's surprise, the strand was sharp and clear, laid perfectly across the image of the sky. It happened to sit exactly at the focus, where the real image forms.","Gascoigne understood what this meant. If a thread at the focus looks sharp, you can put crossed threads there on purpose, a crosshair, and use it to aim the telescope at a star with great precision. Until then, astronomers measuring star positions used open sights, a bit like the notch and post on an old rifle, just as Tycho Brahe had done. With a telescopic sight, an instrument's pointer could now be as accurate as the telescope's sharp vision.","He went further. By placing two pointers at the focus that could be moved closer together or farther apart with a finely threaded screw, he could measure the width of a planet or the Moon's disk. Each turn of the screw moved the pointers a known tiny amount, so counting the turns gave the size. This invention is called the micrometer, from Greek words meaning small measure. Gascoigne used it to measure the apparent sizes of the Moon and planets more accurately than anyone before him.","Sadly, Gascoigne did not live to make his work famous. He fought for the king in the English Civil War and was killed at the Battle of Marston Moor in 1644, at about 32 years old. Many of his papers were lost. But his friend the astronomer William Crabtree had seen his instruments and written excitedly about them to Jeremiah Horrocks, and later scientists such as Richard Towneley and Robert Hooke improved the micrometer. Within a few decades, telescopic sights and micrometers were standard on the measuring instruments in the great observatories. A surprising number of later discoveries, from planet sizes to the speed of light, depended on being able to measure tiny angles with a crosshair."]},{"heading":"Two Kinds of Blur","paragraphs":["Even with Kepler's better layout, telescopes in the 1600s had a big problem: the images were blurry, and the more you magnified, the worse it got. There were two separate reasons, and both came from the lenses themselves.","The first is called spherical aberration. Lens makers ground their lenses by rubbing glass against a curved metal or stone tool, which naturally produces a surface shaped like part of a sphere, a perfect ball. A sphere is easy to make, but it is not quite the right shape to bring all the light to one point. Rays passing through the outer edge of the lens bend a little too much and come to a focus slightly closer to the lens than rays passing through the middle. Instead of a sharp point, a star becomes a small smudge. Kepler and the French philosopher René Descartes both worked out that other curves, such as a hyperbola, would focus perfectly, but nobody in the 1600s could grind glass into those shapes accurately.","The second problem is called chromatic aberration, and it is even trickier. White light is really a mixture of all the colors of the rainbow. When light passes from air into glass, it bends, which is called refraction. But glass bends each color by a slightly different amount: violet and blue light bend the most, red light bends the least. So a simple lens does not have one focus. It has a whole row of them, blue closest to the lens and red farthest away. When you focus on the yellow-green middle, which our eyes are most sensitive to, the other colors are slightly out of focus and spread into colored halos. A bright planet or the edge of the Moon ends up surrounded by fringes of purple and orange, and fine details melt away.","Nobody in the early 1600s fully understood why the colors appeared. That explanation would come later in the century from a young English scientist and a glass prism. But telescope makers did discover by trial and error something very useful: both kinds of blur get much less serious when the lens is curved only very gently. A gently curved lens bends light only a little, so its focus is far away, which means it has a very long focal length. The spread between the colors stays roughly the same size, but compared with the large image made by a long lens, it becomes a much smaller fraction of the picture. Christiaan Huygens worked out that to keep the blur under control while magnifying more, the length of the telescope had to grow much faster than its magnification.","The result was one of the strangest chapters in the history of science. To see more sharply, astronomers began building telescopes that were absurdly, comically long."]},{"heading":"The Brewer's Giant in Danzig","paragraphs":["Picture the Baltic port city of Danzig, today called Gdańsk in Poland, in the 1640s. Among its tall merchant houses lives Johannes Hevelius, a wealthy brewer and city councillor who spends his nights on the roof. Above several joined houses he has built a private observatory, one of the finest in Europe, with platforms, instruments and a little rotating hut. In 1647 he publishes Selenographia, a beautiful atlas of the Moon with maps he engraved himself, which earned him the title of founder of lunar mapping. Most of his names for the Moon's features were later replaced, but his idea of naming lunar mountain ranges after mountains on Earth lives on in names like the lunar Alps and Apennines.","Hevelius chased sharper images the same way everyone else did, by making telescopes longer and longer. His most famous one had a lens about 20 centimeters (8 inches) across and a focal length of about 46 meters, or 150 feet. That is longer than an Olympic swimming pool is wide, and about the length of four school buses parked end to end. A solid tube that long would have been impossibly heavy, so the tube was an open framework of wooden planks and wire, more like a long ladder than a pipe, with a series of round screens inside to block stray light.","The whole thing hung from a tall mast set up outside the city, held by a web of ropes and pulleys. Engravings in his book Machina Coelestis, from 1673, show teams of assistants hauling on ropes to raise or swing it while the astronomer peers in at the bottom. It must have looked more like rigging a sailing ship than doing astronomy. The slightest breeze set the long frame swaying and shivering, and the wood bent and twisted as the temperature and humidity changed. Honestly, the giant was more impressive to look at than useful to look through.","Hevelius is also remembered for something stubborn. For measuring star positions, he refused to use telescopic sights, insisting his naked-eye instruments were just as good. When the young English astronomer Edmond Halley visited Danzig in May 1679 on behalf of the Royal Society to test that claim, he was surprised to find that Hevelius's measurements really were impressively accurate. Hevelius was one of the last great astronomers to work that way. His wife, Elisabeth Koopman Hevelius, was an expert observer who worked beside him for years and, after his death in 1687, prepared his unfinished books for publication. Some historians call her one of the first women astronomers whose work we know in detail. Tragically, in September 1679 a fire destroyed the rooftop observatory, its instruments and many of his books."]},{"heading":"Huygens: A New Moon and the Secret of the Rings","paragraphs":["In the Netherlands, the country where the telescope had been born, two brothers were grinding lenses. Christiaan Huygens and his older brother Constantijn came from a famous, wealthy family in The Hague. Their father was a poet and diplomat, and the boys received a superb education. In 1655 the brothers began making their own lenses, which were among the best in Europe. A few years later, Christiaan also invented a better eyepiece, made from two lenses, that reduced some of the color blur. It is still called the Huygens eyepiece.","On 25 March 1655, Christiaan pointed one of the brothers' new telescopes at Saturn. Close to the planet he noticed a faint star. Over the following nights the star moved along with Saturn and swung from one side of it to the other, returning to the same spot about every 16 days (15 days and 22 hours, to be exact). It was a moon, the first moon of Saturn ever found, and only the second set of moons ever found around another planet after Jupiter's. Huygens called it simply Saturni Luna, Latin for Saturn's moon. We now call it Titan. It is Saturn's largest moon and the second-largest in the solar system, even bigger than the planet Mercury, and it is the only moon known to have an atmosphere thicker than Earth's. The name Titan was suggested almost two centuries later, in 1847, by the astronomer John Herschel.","With his sharper telescope, Huygens also tackled the puzzle that had defeated Galileo: Saturn's ears. Over several years he watched them carefully and realized that one simple shape explained everything. Saturn, he proposed, is surrounded by a thin, flat ring that does not touch the planet anywhere and is tilted compared with the path of the planets. When we see the ring tilted toward us, it looks like two handles. When Earth lines up with the flat edge of the ring, the ring is so thin that it seems to vanish, just as Galileo had seen in 1612. Huygens even predicted when the next disappearance would happen.","Like Galileo, he first announced his idea as a scrambled anagram, to claim credit while he gathered more evidence. In 1659 he published the full explanation in a book called Systema Saturnium, The Saturn System, together with his discovery of Titan. Not everyone agreed at first; some astronomers proposed other shapes. But the ring explained the observations so neatly that within a few decades it was widely accepted. Huygens thought the ring was solid. Much later, in 1859, James Clerk Maxwell showed mathematically that a solid ring would break apart, and that it must be made of countless separate pieces, which spacecraft have confirmed.","Huygens was one of the greatest scientists of his century. In 1657 he patented the first accurate pendulum clock, which made clocks many times more accurate and became vital for astronomy. In 1666 he moved to Paris to become a leading member of the new French Academy of Sciences, and later he developed a wave theory of light. But his telescopes were about to get even stranger."]},{"heading":"Telescopes With No Tubes","paragraphs":["If a 150-foot frame flexes in the wind, why have a tube at all? The tube's only real jobs are to hold the two lenses in line and block stray light, and at night the sky is dark anyway. So astronomers, especially the Huygens brothers, came up with the aerial telescope.","Here is how it worked. The objective lens was mounted in a short metal holder at the top of a tall pole, a tree trunk or a tower, on a swiveling ball joint so it could point in any direction. Far below, on the ground, the observer held the eyepiece in a small frame, sometimes resting on a stand for support. A long, tight cord connected the two. By pulling the cord, the astronomer turned the distant lens to line it up with the eyepiece and the target. Some versions used a lantern to help find the lens in the dark. The Huygens brothers described their method in a short book, Astroscopia Compendiaria, in 1684.","The numbers are astonishing. In 1686 the Huygens brothers made objective lenses about 8 inches across with focal lengths of 170 and 210 feet, about 52 and 64 meters. In 1690 Constantijn Huygens gave the Royal Society in London a lens with a focal length of 123 feet, about 37 meters, and decades later James Bradley used a 212-foot lens to measure the size of Venus. The French astronomer Adrien Auzout and others reportedly made lenses of 300 to 600 feet, and Auzout even proposed one with a focal length of 1,000 feet, about 300 meters, which was never practical.","Imagine trying to use one. You stand in a dark field, holding a tiny eyepiece, staring up at a lens you can barely see on top of a very tall pole, while the Earth's rotation slowly carries your target away. Every few minutes you have to re-aim. The faintest wind makes the cord quiver. Yet with great patience, skilled observers made real discoveries this way.","Aerial telescopes only lasted a few decades. By the 1720s, a new kind of telescope that used mirrors instead of lenses, made practical by John Hadley in 1721, could do the same job in a short tube. A few decades later, lenses made of two types of glass solved the color problem. Today a working replica of an aerial telescope, with a 4-meter focal length, unveiled in 2014, can be seen at the Old Observatory in Leiden in the Netherlands."]},{"heading":"Cassini and the King's Observatory","paragraphs":["In the 1660s, kings and governments began to realize that astronomy was useful. Better star maps meant better maps of countries and safer navigation for ships, which meant more trade and stronger navies. So they began to build official observatories, buildings paid for by the state with salaried astronomers.","In Paris, King Louis XIV and his powerful minister Jean-Baptiste Colbert founded the Royal Academy of Sciences in 1666 and, the next year, the Paris Observatory. On Midsummer's Day 1667, academy members marked out the building's outline on the ground, with its center line running exactly north and south along what became the Paris meridian. Designed by the architect Claude Perrault, the grand stone building was finished in 1671. It is the oldest observatory in the world still working today. In England, King Charles II founded the Royal Observatory at Greenwich in 1675, with John Flamsteed as the first Astronomer Royal, given the job of making the star tables needed to find a ship's position at sea.","To run his new observatory, Louis XIV lured a star from Italy: Giovanni Domenico Cassini, born in 1625 in the village of Perinaldo and professor of astronomy at the University of Bologna. Cassini was a superb observer who had already measured how fast Jupiter and Mars spin and published very accurate tables predicting the motions of Jupiter's moons. He arrived in Paris in 1669, and although he was supposed to stay only a short time, he never went back. He became a French citizen and directed the observatory until his death in 1712. Three more generations of his family, his son, grandson and great-grandson, ran it after him.","Cassini used the best long telescopes in the world, many with lenses made by the master Italian lens grinder Giuseppe Campani, and some later hung from a tall wooden tower moved to the observatory grounds from the royal estate at Marly. With them he found four more moons of Saturn: Iapetus in 1671, Rhea in 1672, and Tethys and Dione in 1684. Iapetus came with a mystery. Cassini noticed he could see it easily when it was on one side of Saturn but not on the other. He correctly guessed that one half of the moon is much darker than the other and that the moon always keeps the same face toward Saturn, the way our Moon does toward Earth. Spacecraft images centuries later confirmed that Iapetus really is two-toned, one side as dark as coal and the other bright as snow.","In 1675 Cassini made one more famous discovery. Looking at Saturn's ring, he saw that it was not one smooth band but two, with a dark gap between them. This gap, about 4,800 kilometers wide, is still called the Cassini Division. It was a hint that the ring was not one solid object. Centuries later, NASA and the European Space Agency named their great Saturn mission after him: the Cassini spacecraft, which carried a probe named Huygens that parachuted onto Titan in 2005."]},{"heading":"Rømer and the Speed of Light","paragraphs":["Jupiter's moons, Galileo's great discovery, had one more surprise in store, and it was perhaps the most important of all. It came from a young Danish astronomer named Ole Rømer, who came to work at the Paris Observatory in 1672.","Jupiter's innermost large moon, Io, circles the planet every 42 and a half hours. Each time around, it passes into Jupiter's shadow and suddenly disappears, an eclipse that can be timed to the minute with a good telescope and a pendulum clock. Because Io's orbit is so regular, astronomers like Cassini could publish tables predicting these eclipses months in advance. Such tables were valuable, because comparing the predicted time with the local time an eclipse was actually seen could help mapmakers work out positions on land.","But Rømer, studying years of observations, noticed something odd. The eclipses did not keep perfect time. When the Earth, traveling around the Sun, was moving toward Jupiter, the eclipses came a little early. When the Earth was moving away from Jupiter, they came a little late. Over half a year, the difference added up to many minutes.","Rømer realized that Io was not misbehaving. The difference was caused by the light. When the Earth is on the far side of its orbit from Jupiter, the light showing the eclipse has to travel an extra distance, the whole width of Earth's orbit, to reach us. If light takes time to travel, the news of the eclipse arrives late. Cassini had briefly suggested the same idea in August 1676 but then dropped it. Rømer did not. In 1676 he predicted that a reappearance of Io due in mid-November would be seen about 10 minutes later than the old tables said. When the night came, the observers in Paris saw that it was indeed about 10 minutes late.","Until then, many scientists, following Descartes, believed light traveled instantly. Rømer showed it does not: light has a finite speed. His estimate was that light needs about 22 minutes to cross the full width of Earth's orbit. The true figure is closer to 16 and a half minutes, so his estimate was too large, partly because the timings were hard to measure precisely. Nobody knew the exact size of Earth's orbit either, so he could not give a speed in kilometers per second. Christiaan Huygens used Rømer's timing to calculate a speed of a little over 200,000 kilometers per second. The modern value is about 299,792 kilometers per second, fast enough to circle the Earth about seven and a half times in one second, and light from the Sun takes about 8 minutes and 20 seconds to reach us. Rømer's idea was right, even though his numbers were rough. It was not fully accepted until 1729, when James Bradley found a completely different effect of light's speed, called the aberration of starlight, that confirmed it.","Rømer later returned to Denmark in 1681, where he became a professor in Copenhagen, introduced a national system of weights and measures, and even served as the city's chief of police, bringing in its first oil street lamps. He also designed a temperature scale that inspired Daniel Fahrenheit. But his greatest legacy came from staring at a tiny moon through a long telescope and realizing that the light reaching us is always a message from the past.","By the 1670s, though, many astronomers were tired of fighting rainbow fringes with ever-longer telescopes. One young scientist in England decided that lenses would never beat the rainbow problem. So he threw away the big lens altogether and used a mirror instead."]}],"deepDive":"Why did length help? For a simple lens, chromatic aberration produces a blur whose size depends mainly on the lens's aperture and on how much the glass's bending power changes from blue to red light, which opticians measure with a quantity now called the Abbe number. For ordinary crown glass, the red and blue focal points are separated by roughly 1.5 to 2 percent of the focal length. The blur circle a star makes at the best focus is therefore roughly proportional to the aperture, not to the focal length. A longer focal length makes the image of a planet larger while the color blur stays about the same, so the fringes become a smaller fraction of the image and the eyepiece can magnify more before detail disappears. Huygens worked out an empirical rule: to double the useful magnification, the focal length had to grow about four times, which is why lengths exploded from a few feet to more than 200 feet. Spherical aberration also shrinks dramatically with gentler curves; for a fixed aperture it falls off very steeply as the focal ratio grows. A 17th-century objective working at f/150 or slower was far more forgiving than one at f/10. The cost was mechanical: long tubes sagged, vibrated and were hard to point. Keplerian telescopes also introduced the real focal plane, which made possible crosshairs, micrometers, and eventually measuring instruments called filar micrometers and transit circles, the backbone of precision astrometry for three centuries. Rømer's result shows how good measurement turns into deep physics. His 22 minutes compares with the modern 16.6 minutes for light to cross Earth's orbit; historians suggest errors in timing eclipse start and end, and the slowly changing geometry of Jupiter's orbit, inflated it. Some historians also point out that Cassini later doubted the finite-speed explanation, and that the debate in Paris continued for decades. The modern speed of light is defined exactly as 299,792,458 meters per second, and since 1983 the meter itself has been defined by how far light travels in a fraction of a second.","funFact":"Johannes Hevelius's famous long telescope had a focal length of about 150 feet (46 meters), so long that it had to hang from a mast with ropes and pulleys like the rigging of a ship.","check":{"q":"How did Ole Rømer show in 1676 that light takes time to travel?","a":"By noticing that eclipses of Jupiter's moon Io came later when Earth was farther from Jupiter","wrong":["By timing a lantern flashed between two hilltops","By measuring how long sunlight took to heat a thermometer","By watching the phases of Venus through a Galilean telescope"]},"sources":[{"title":"Refracting telescope","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Refracting_telescope"},{"title":"William Gascoigne (scientist)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/William_Gascoigne_(scientist)"},{"title":"Aerial telescope","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Aerial_telescope"},{"title":"Johannes Hevelius","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Johannes_Hevelius"},{"title":"Christiaan Huygens","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Christiaan_Huygens"},{"title":"Giovanni Domenico Cassini","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Giovanni_Domenico_Cassini"},{"title":"Rømer's determination of the speed of light","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/R%C3%B8mer%27s_determination_of_the_speed_of_light"},{"title":"Iapetus","publisher":"NASA Science","url":"https://science.nasa.gov/saturn/moons/iapetus/"}],"photos":[{"src":"img/deep/telescope/06-1.jpg","alt":"Hevelius's giant open-frame telescope hangs from a tall mast by ropes as a crowd watches near Danzig (1673).","file":"Telescope 140 foot Johann Hevelius.jpg","url":"https://commons.wikimedia.org/wiki/File:Telescope_140_foot_Johann_Hevelius.jpg","author":"Johannes Hevelius, from his book Machina coelestis (first part), published…","license":"Public domain"},{"src":"img/deep/telescope/06-2.jpg","alt":"Huygens's tubeless 'aerial telescope' (1684): the lens sits high on a pole, the observer stands on the ground.","file":"Huygens Aerial telescope, 1684, retouch.jpg","url":"https://commons.wikimedia.org/wiki/File:Huygens_Aerial_telescope,_1684,_retouch.jpg","author":"Christiaan Huygens","license":"Public domain"},{"src":"img/deep/telescope/06-3.jpg","alt":"Page from Huygens's Systema Saturnium (1659) showing how Saturn's rings look different as it circles the Sun.","file":"Huygens Systema Saturnium.jpg","url":"https://commons.wikimedia.org/wiki/File:Huygens_Systema_Saturnium.jpg","author":"Christiaan Huygens","license":"Public domain"}],"words":4316},{"n":7,"title":"Newton's Mirror","when":"1663 – 1720s","summary":"A young Isaac Newton split sunlight into a rainbow with a glass prism and realized lenses would always smear stars with color. So he built a tiny telescope that used a shiny curved mirror instead. It was only about as long as a pencil, but it worked as well as telescopes many times longer.","sections":[{"heading":"A Rainbow on the Wall","paragraphs":["In 1665 a terrible outbreak of plague reached England, and Cambridge University closed its doors so students would not spread the disease. One of the students sent home was a quiet young man of 22 named Isaac Newton. He went back to his family's farmhouse at Woolsthorpe in Lincolnshire, and over the next two years, mostly away from his teachers and classmates, he thought about mathematics, gravity and light. Some of the most famous ideas in the history of science began in that farmhouse and in his rooms at Cambridge when he returned.","Light was one of Newton's favorite puzzles. In early 1666 he bought a triangular glass prism. Prisms were sold at fairs as curiosities, because they turned sunlight into pretty colors, but nobody really understood why. Most thinkers of the time believed that white light was pure and simple, and that a prism somehow added color to it, perhaps by darkening or bending the light in different ways.","Newton set up an experiment that he later described in a famous letter. He darkened his room, made a small round hole in the window shutter, and let a thin beam of sunlight shine in. He put the prism in the beam, and on the far wall appeared a band of colors: red at one end, then orange, yellow, green, blue and violet at the other.","Here is what puzzled him. The hole was round, so he expected the colored patch to be round too. Instead it was a long strip, about five times longer than it was wide. Something inside the light was being spread out. Newton tested every boring explanation he could think of. Was the glass bumpy? Did the size of the hole matter? Was the prism in a strange position? None of these changed the result.","Then he tried what he called his crucial experiment, or experimentum crucis in Latin. He let the rainbow from the first prism fall on a board with a tiny hole in it, so that only one color could get through. That single color then traveled on to a second board with another hole, and behind it a second prism. When the light was already one pure color, like red, the second prism bent it but did not split it into any new colors. Red stayed red. Blue stayed blue. And the blue light was always bent more than the red light.","Newton's conclusion was bold. White light, he said, is not pure at all. It is a mixture of many colors, and each color bends by its own amount when it passes through glass. The prism does not add colors; it sorts them, the way a sieve sorts sand from pebbles. He even showed the opposite trick: by using a lens or a second prism to bring the colors back together, he could make white light again."]},{"heading":"Why Lenses Paint Stars with Color","paragraphs":["Newton realized at once what his prism meant for telescopes. As we saw in the last part, the lens telescopes of the 1600s had a nagging fault: bright objects were surrounded by fuzzy rainbow fringes. Astronomers blamed this on lens-makers. They thought that if only somebody could grind the glass into a more perfect shape, the colors would vanish.","Newton disagreed. A lens is really just a prism that has been rounded off. Near its edge, the glass surfaces are tilted toward each other, exactly like the faces of a prism. So a lens bends violet light a little more strongly than red light. That means the violet light comes to a focus slightly closer to the lens, and the red light comes to a focus slightly farther away. There is no single spot where every color is sharp at once. If you focus the red, the blue is a blurry halo; if you focus the blue, the red is blurry. This problem is called chromatic aberration, which simply means color error.","In his famous letter to the Royal Society in 1672, Newton argued that the real limit on telescopes was not the shape of the glass but the nature of light itself, a mixture of rays that bend by different amounts. That is why Johannes Hevelius and Christiaan Huygens, whom we met in Part 6, had built such enormously long telescopes. A very weakly curved lens bends all the colors only a little, so the color errors stay small. But that made telescopes 30, 60 or even more than 100 feet long, wobbling on masts and ropes.","Newton saw a cleverer way out. What if a telescope did not send light through glass at all? A mirror does not bend light the way glass does. It simply bounces it back. When light hits a mirror, it leaves at the same angle it arrived, and that rule is exactly the same for red, green, blue and violet. Every color takes the same path. A curved mirror can therefore bring all the colors to one single focus. No rainbow fringes. This is the big idea behind every reflecting telescope ever made, from a backyard Newtonian to the James Webb Space Telescope.","There was one catch, and Newton noticed it too. Because a mirror bounces light back instead of letting it pass through, any tiny bump or dent on its surface throws the light off course much more than the same bump would on a lens. A mirror has to be shaped and polished with extraordinary care. That catch would haunt reflecting telescopes for more than a century."]},{"heading":"Gregory's Telescope on Paper","paragraphs":["Newton was not the first person to dream of a mirror telescope. People had known for a very long time that a curved mirror can focus light, just as a lens can. The great Arab scientist Ibn al-Haytham had written about curved mirrors in his Book of Optics in the 11th century. Soon after the spyglass appeared, Italian thinkers discussed the idea of a mirror version, and the Jesuit scholar Niccolò Zucchi later said he had tried looking at a concave bronze mirror through a lens around 1616. The picture he got was too poor to be useful. In the 1620s and 1630s, the French friar Marin Mersenne and the Italian mathematician Bonaventura Cavalieri both wrote about mirror designs, and Mersenne described an arrangement with two mirrors, though he never tried to build it.","The most important early design came from a young Scottish mathematician named James Gregory. In 1663, when he was about 24, Gregory published a book called Optica Promota, which means something like The Advance of Optics. In it he described a reflecting telescope with two curved mirrors.","Here is how the Gregorian telescope works. Light from a star enters the open front of the tube and travels down to a large concave mirror at the back. Concave means curved inward, like the inside of a bowl. This main mirror bounces the light back up the tube and squeezes it toward a focus. Just past that focus sits a second, much smaller concave mirror, which sends the light back down again, through a hole cut in the center of the big mirror, and into an eyepiece behind it. You look in from the back, just as you would with a normal spyglass, and because the light has been flipped twice, the image is the right way up.","Gregory's design was clever, and the mathematics was sound. He wanted his mirrors shaped like parabolas, special curves that bring parallel light from a distant star to a perfect point. But he had a problem: he was a mathematician, not a craftsman. He looked for someone who could grind and polish the mirrors, but he could find no optician able to make them accurately enough. The project was abandoned. Gregory's telescope existed only as drawings and equations.","It finally worked about ten years later. In 1673, with the help of Robert Hooke, the Royal Society's brilliant experimenter, a working Gregorian telescope was built. By then, however, someone else had already beaten Gregory to the first working reflector. Gregory's name did live on: Gregorian telescopes were popular in the 1700s, and versions of his two-mirror idea are still used today in some solar telescopes and in the planned Giant Magellan Telescope in Chile."]},{"heading":"Newton Builds His Own","paragraphs":["Newton knew about Gregory's idea, and he may have read Optica Promota. But he thought Gregory's design was harder than it needed to be, and he had something Gregory lacked: amazing skill with his hands. As a boy, Newton had built model windmills, water clocks and sundials. Now he decided to build his own telescope, every part of it.","In late 1668, at Cambridge, Newton finished it. He made the tube, the mount and the fittings himself. He mixed and cast the metal for the mirror, ground it into a concave curve, and polished it. He may even have been the first person to polish a mirror on a lap made of pitch, a sticky, tar-like material that slowly molds itself to the mirror and is still used by expert mirror-makers today. Newton also invented his own tools and tests. He also studied the faint colored rings, now called Newton's rings, that appear when a curved piece of glass rests on a flat one.","His design was simple and elegant. At the bottom of a short tube sat the main mirror, a disk of shiny metal only about 33 millimeters across, roughly the width of a large coin. Light from the sky came down the tube, hit this curved mirror, and bounced back up toward a focus. But if the focus had been in the middle of the tube, Newton's own head would have blocked the light. So, partway up the tube, he placed a tiny flat mirror tilted at 45 degrees. It caught the converging light and sent it sideways, out through a hole in the side of the tube, where an eyepiece lens magnified the image. To this day, a telescope with this arrangement is called a Newtonian telescope, and the side-mounted eyepiece is its trademark.","The whole instrument was tiny. The tube was only about six to eight inches long (accounts differ), shorter than a school ruler. Yet it magnified about 40 times. According to Newton's own letters, it did a better job than an ordinary refracting telescope about six feet long. Through it he could see the four moons of Jupiter that Galileo had discovered, and the thin crescent shape of Venus. And there were no rainbow fringes around the bright planets.","Imagine the surprise of anyone who picked it up. Astronomers on the Continent were hanging lenses from tall poles and sighting along 100-foot ropes. And here was a Cambridge scholar with a telescope he could hold in one hand, doing the same job."]},{"heading":"Speculum Metal: Shiny but Stubborn","paragraphs":["Today a telescope mirror is made of glass with a thin coating of aluminum or silver on top. Newton had no such option. Nobody yet knew how to put a good, long-lasting reflective coat on glass, so the mirror itself had to be made of polished metal. The metal used was called speculum metal, from the Latin word speculum, meaning mirror.","Speculum metal is a kind of bronze, a mixture of mostly copper and tin, usually about two parts copper to one part tin, sometimes with a pinch of arsenic added to make it whiter and shinier. Freshly polished, it looks like a silvery mirror. People had made shiny bronze mirrors for a very long time; in China, high-tin bronze mirrors go back more than 2,000 years.","But speculum metal was a stubborn material. It was hard and brittle, almost like glass, so it could crack if cooled too fast after casting, and it could not be hammered or bent into shape. Every bit of its curve had to be patiently ground and polished by hand. Newton later wrote about how difficult it was to get a smooth, regular surface, because the metal was full of tiny pores and tended to scratch.","Worse, even a perfect speculum mirror wasted a lot of light. It reflected only about two-thirds of the light that hit it. A modern aluminum coating reflects about 90 percent. And because Newton's telescope used two mirrors, the main one and the little flat one, the losses added up. Then there was tarnish. Speculum metal slowly darkened in air, especially in damp weather, much like a silver spoon left out for weeks. After a few months, a mirror could lose its shine and have to be polished all over again, which risked spoiling its carefully made shape. Later telescope-makers often kept two mirrors for each telescope, so one could be in use while the other was being re-polished.","Newton made one more compromise. The best shape for a telescope mirror is a paraboloid, a bowl whose curve gets slightly flatter toward the edge, because that shape sends parallel light from a star to one perfect point. A sphere, like the inside of a ball, is much easier to grind, because any two spherical surfaces rubbed together stay spherical. So Newton ground his mirror as part of a sphere. That caused a little spherical aberration, the blurry focus we met in Part 6, but with such a small mirror the blur was tolerable.","Add it all up and you can see why Newton's telescope, brilliant as it was, did not instantly take over the world. Its tiny mirror gathered less light than the big lenses of the day, so faint things looked dim. It was hard to make. It tarnished. For decades, most astronomers kept using their long refractors. But Newton had proved that the idea worked, and that was the hardest part."]},{"heading":"The Royal Society Takes Notice","paragraphs":["Newton was not a man who liked to show off his work. He was secretive and touchy, and he hated arguments. For about three years his little telescope stayed mostly a private marvel, known to a few friends at Cambridge. In 1669 he became Lucasian Professor of Mathematics at Cambridge, taking over from his teacher Isaac Barrow, and he began giving lectures on optics.","Word of the telescope still got out. Newton built a second, improved reflector, which he said was noticeably better than the first. Late in 1671, Isaac Barrow carried it to London and showed it to members of the Royal Society, the club of scientists and gentlemen founded in 1660 to study nature by experiment. The members were amazed. In January 1672 it was even shown to King Charles II, who was a keen supporter of the Society and was interested in anything that might help his navy.","Henry Oldenburg, the Society's secretary, moved quickly. He worried that someone in another country might copy the design and claim it as their own, so he wrote a description of the telescope and sent it to the famous Dutch scientist Christiaan Huygens, to put Newton's priority on record. On 11 January 1672, Isaac Newton, then 29 years old, was elected a Fellow of the Royal Society. The little mirror telescope had opened the door to Britain's leading scientific club.","Encouraged, Newton sent the Society a long letter dated 6 February 1672, explaining his experiments with the prism and his new theory that white light is a mixture of colors. It was read aloud at a meeting two days later and printed in the Society's journal, the Philosophical Transactions, later that month. It was one of the first great scientific papers ever published in a journal.","Not everyone agreed. Robert Hooke, the Society's curator of experiments, who had his own theory of light and colors, criticized Newton's conclusions. Others in Europe said they could not repeat his results. Newton found the arguments so painful that he pulled back from public debate for years. He did not publish his full book on light, called Opticks, until 1704, the year after Hooke died. By then Newton was the President of the Royal Society and the most famous scientist in Europe."]},{"heading":"Cassegrain's Hole in the Mirror","paragraphs":["Only a few months after Newton joined the Royal Society, a rival design appeared in France. On 25 April 1672, a French scientific publication printed a letter describing a new reflecting telescope by a man named Cassegrain. For a long time nobody was even sure of his first name. In 1997 two French researchers identified him as most likely Laurent Cassegrain, a Catholic priest who taught science at a school in Chartres and lived from about 1629 to 1693.","Cassegrain's design looks a bit like Gregory's at first. The big main mirror has a hole in its center, and you look in from the back of the telescope. The difference is the second mirror. Gregory used a small concave mirror placed beyond the main focus. Cassegrain used a small convex mirror, one that bulges outward like the back of a spoon, placed before the light reaches the focus. This convex mirror catches the converging light and sends it back down through the hole in the main mirror.","That small change had a big advantage. Because the convex secondary sits closer to the main mirror and stretches the focus outward, a Cassegrain telescope can be much shorter than a Gregorian with the same power. It folds a long path of light into a compact tube, like folding a long piece of paper into a short packet.","Cassegrain received little thanks at the time. Huygens criticized the design harshly in June 1672, and Newton himself wrote that he saw no advantage in it and thought it would have problems. The arguments helped push Cassegrain's name into obscurity. Like Gregory, Cassegrain also lacked the means to build a really good version with the materials of the 1670s.","History has been kinder to him than his critics were. The Cassegrain arrangement became the most common layout for big research telescopes. In the early 1910s, George Willis Ritchey and Henri Chrétien invented an improved version with two specially curved mirrors that keep stars sharp across a wide field of view. This Ritchey-Chrétien design, a kind of Cassegrain, is used by the Hubble Space Telescope, the giant Keck telescopes in Hawaii and the Very Large Telescope in Chile. Many radio dishes and satellite ground-station antennas use a Cassegrain layout too, with a small curved reflector on legs in front of the big dish, bouncing the signal back toward the center. A priest whose name was nearly forgotten ended up shaping the most powerful eyes humanity has built."]},{"heading":"John Hadley Makes Reflectors Work","paragraphs":["For about 50 years after Newton, the reflecting telescope remained more of a curiosity than a working tool. Craftsmen struggled to grind speculum mirrors accurately, especially into the tricky parabolic shape. The person who finally cracked the problem was an English gentleman named John Hadley, born in London in 1682.","Hadley was a mathematician with a talent for careful, practical work, and he spent years learning how to make and test mirrors. He worked out methods for grinding speculum metal into accurate parabolic and other non-spherical shapes, and for checking the curve as he went. In 1721 he presented a Newtonian telescope to the Royal Society. Its main mirror was about 6 inches, or 15 centimeters, across, roughly 20 times the area of Newton's first mirror, and it was the first Newtonian with a properly parabolic mirror. The telescope was roughly 5 feet long.","The Royal Society asked two skilled astronomers, James Bradley and his uncle James Pound, to test it. They compared it with one of the most famous telescopes in England: a giant aerial telescope whose lens had been made by Constantijn Huygens, the brother of Christiaan. That lens was about 7.5 inches across with a focal length of about 123 feet, and it had been given to the Royal Society in 1690. Using it meant hoisting the lens up a tall pole and lining it up with an eyepiece far away on the ground.","The result was a triumph for the reflector. Pound reported in the Philosophical Transactions that Hadley's telescope could magnify as much as the 123-foot giant and showed things distinctly. The images were not quite as bright and clear as the giant's, the testers admitted, because speculum metal still lost light. But the reflector was less than one twentieth of the length, sat on a sturdy mount, and could be turned to any part of the sky in moments. A telescope that once needed a pole as tall as a church tower could now be replaced by one that fit inside a room.","Hadley also taught London instrument-makers his methods, so good reflectors became something you could actually buy. Through the 1700s, Gregorian and Newtonian reflectors became popular with wealthy amateurs, scientists and instrument shops. Hadley went on to other inventions, including a reflecting octant in 1730 for measuring the height of the Sun or stars above the horizon at sea; an American named Thomas Godfrey came up with a similar instrument independently at about the same time. It is a nice irony that a mirror-lover helped sailors find their way.","Still, the problems of speculum metal never fully went away. Large metal mirrors were heavy, tarnished, and wasted about a third of the light. Reflectors would not truly rule astronomy until the mid-1800s, when scientists learned to coat glass mirrors with a thin layer of silver, a story for a later part. In the meantime, someone else was quietly working on the other side of the problem. Newton had declared that lens telescopes could never be cured of their rainbows. He was the greatest scientist of his age, and on this point he was wrong."]}],"deepDive":"Why did Newton conclude that refracting telescopes were hopeless? From his prism experiments he believed that the amount a material spreads colors apart (its dispersion) always goes together with how strongly it bends light overall (its refractive power). If that were true for every kind of glass, you could never combine two lenses so that their color errors cancel while still bending the light to a focus: whenever you cancelled the colors, you would cancel the focusing too. It was a reasonable guess from the materials he tested, and his enormous authority meant few people challenged it for decades. It turned out to be false: different glasses, such as lead-rich flint glass and ordinary crown glass, have different ratios of dispersion to bending power, which is exactly what the achromatic lens of the next part exploits. Newton's reflector also had real optical faults. Its spherical mirror suffered from spherical aberration, and the flat diagonal mirror blocked part of the incoming light, a central obstruction that every Newtonian, Cassegrain and Gregorian telescope still has, and which slightly lowers contrast. Historians also argue about priority. Gregory published first (1663), and earlier writers such as Zucchi, Cavalieri and Mersenne had discussed mirror telescopes, so it is fair to say Newton did not invent the idea of a reflector, but he built the first practical working one (1668). The Cassegrain story is murkier still: the 1672 report was second-hand, the design was attacked by Huygens and Newton, and Cassegrain's first name was only identified with reasonable confidence in 1997. Finally, the numbers on Newton's telescope come mostly from his own letters, so modern sources describe them as approximate: a mirror about 33 mm across at roughly f/5, a tube roughly 6 to 8 inches long, and a magnification of roughly 35 to 40 times. Hadley's 1721 success shows that the bottleneck was craftsmanship, not theory: the optics of reflectors were understood by the 1670s, but accurate parabolic metal mirrors took another half-century to master.","funFact":"Newton's first reflecting telescope, only about 6 to 8 inches long, did as well as a refracting telescope about 6 feet long, according to Newton himself.","check":{"q":"Why does a mirror telescope avoid the rainbow-colored fringes that troubled lens telescopes?","a":"A mirror reflects every color at the same angle, so all colors come to the same focus","wrong":["Mirrors absorb all the colors except white","Mirror telescopes are always longer than lens telescopes","Newton painted his mirror black to block the colors"]},"sources":[{"title":"Newtonian telescope","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Newtonian_telescope"},{"title":"Reflecting telescope","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Reflecting_telescope"},{"title":"A Letter of Mr. Isaac Newton ... containing his New Theory about Light and Colors (1672)","publisher":"The Newton Project, University of Oxford","url":"https://www.newtonproject.ox.ac.uk/view/texts/normalized/NATP00006"},{"title":"History of the telescope","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/History_of_the_telescope"},{"title":"Laurent Cassegrain","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Laurent_Cassegrain"},{"title":"Cassegrain reflector","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Cassegrain_reflector"},{"title":"Speculum metal","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Speculum_metal"},{"title":"John Hadley","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_Hadley"}],"photos":[{"src":"img/deep/telescope/07-1.jpg","alt":"Replica of Isaac Newton's small reflecting telescope of 1672, with its eyepiece on the side of the tube.","file":"NewtonsTelescopeReplica.jpg","url":"https://commons.wikimedia.org/wiki/File:NewtonsTelescopeReplica.jpg","author":"User:Solipsist (Andrew Dunn)","license":"CC BY-SA 2.0"},{"src":"img/deep/telescope/07-2.jpg","alt":"Inside a Newtonian telescope: the curved main mirror sends light to a small flat mirror, then out to the eyepiece.","file":"Newtontelescope.png","url":"https://commons.wikimedia.org/wiki/File:Newtontelescope.png","author":"Szőcs Tamás Tamasflex","license":"CC BY-SA 3.0"},{"src":"img/deep/telescope/07-3.jpg","alt":"Newton's own sketch of his two-prism experiment, from his 1672 letter to the Royal Society about light and colour.","file":"NewtonDualPrismExperiment.jpg","url":"https://commons.wikimedia.org/wiki/File:NewtonDualPrismExperiment.jpg","author":"Isaac Newton","license":"Public domain"}],"words":3909},{"n":8,"title":"Fixing the Rainbow: Better Lenses","when":"1730s – 1838","summary":"Clever lens-makers found that two different kinds of glass, stuck together, could cancel out the rainbow blur that Newton thought was impossible to fix. An orphan boy who was pulled alive from a collapsed house grew up to make the best lenses in the world. With one of his instruments, an astronomer finally measured how far away a star is.","sections":[{"heading":"Was Newton Wrong?","paragraphs":["At the end of the last part, Isaac Newton had declared that lens telescopes could never escape their rainbow fringes. Because he was the most respected scientist in Europe, many people simply believed him. For more than half a century, if you wanted a sharp view of a planet without colored halos, you either used a mirror telescope or a lens telescope so long it needed a mast.","But a few thinkers had a nagging doubt, and it came from a surprising place: the human eye. Your eye is a lens system. Light passes through the clear cornea at the front, then a watery liquid, then the lens inside your eye, then a jelly-like fluid, each with slightly different properties. In 1747 the great Swiss mathematician Leonhard Euler argued that if a combination of different transparent materials can make sharp images in our eyes, then a combination of different materials might also make a color-free lens. A Swedish scientist named Samuel Klingenstierna also showed mathematically that Newton's reasoning about colors did not have to be true for all materials.","The secret lies in a word we met before: dispersion, which means how much a material spreads light out into its colors. Newton had assumed that any glass that bends light strongly would spread the colors by a matching amount, as if bending power and color-spreading were always locked together. They are not. Different kinds of glass bend light by different amounts, and, separately, spread colors by different amounts.","Two kinds of glass mattered most. Crown glass was the ordinary glass used for windows, made from sand, soda or potash and lime. It bends light moderately and spreads colors only a little. Flint glass was a heavier, sparklier glass rich in lead, first made in England in the 1660s and 1670s for fine drinking glasses and named after the flint stones once used as its source of pure silica. Flint glass spreads colors much more strongly than crown glass, even though its overall bending power is only a bit greater.","Now picture the trick. Take a convex lens of crown glass, which bulges outward and brings light to a focus. On its own it would make rainbow fringes, with blue light focusing a little too close. Then add a weaker concave lens of flint glass, which caves inward and spreads light out. The flint lens spreads the colors backward by about the same amount the crown lens spread them forward, because flint is so good at spreading colors. But because the flint lens is weaker, it does not undo all the focusing. The pair still brings light together, now with red and blue meeting at almost the same point. This two-part lens is called an achromatic lens, from Greek words meaning without color.","An achromat is not absolutely perfect. It brings two colors, usually red and blue, to exactly the same focus, and the colors in between land very close by. A faint purple or green tinge, called the secondary spectrum, can still be seen around very bright objects. But compared with a single lens, the improvement was enormous. A telescope no longer needed to be 100 feet long to give a crisp view."]},{"heading":"The Lawyer Who Kept a Secret","paragraphs":["The first person known to make an achromatic lens was not a famous scientist but an English lawyer and amateur inventor named Chester Moor Hall, born in 1703 in Leigh in Essex. In 1729 or 1733 (the accounts differ), he worked out that crown and flint glass could be combined to cancel each other's colors, and he had lenses made and built at least one small achromatic telescope.","Hall seems to have wanted to keep his idea private. According to the most often told version of the story, he cleverly split the work between two London opticians, Edward Scarlett and James Mann, ordering the crown lens from one and the flint lens from the other, so that neither would understand what he was making. But both opticians were busy and quietly handed the jobs to the same subcontractor, a lens grinder named George Bass. Bass noticed that the two lenses were for the same customer and had matching curves. When he put them together, he discovered that the pair gave an image free of color. Hall's secret was out, at least in one workshop.","Strangely, nothing much happened next. Hall did not publish his discovery or patent it, and Bass made achromatic lenses for some customers without announcing them to the world. Hall lived quietly at New Hall in Sutton, near Southend, and died in 1771. For about 25 years, the achromatic lens existed in England, but almost no one knew."]},{"heading":"Dollond's Patent and the Great Quarrel","paragraphs":["The man who made the achromatic lens famous was John Dollond. He was born in 1706 in Spitalfields, London, the son of a Huguenot, a French Protestant who had fled to England to escape religious persecution. Like his father, John worked as a silk weaver, but in his spare time he taught himself Latin, Greek, mathematics and optics. His son Peter opened a shop making optical instruments in London in 1750, and two years later, at about age 46, John left weaving to join him.","At first John Dollond defended Newton. When Euler suggested that a color-free lens was possible, Dollond argued that Newton's experiments proved otherwise. But he was an honest experimenter. Around 1757 he tested the question himself, using prisms of crown and flint glass, and found that he could indeed cancel the colors while still bending the light. Newton's assumption had been wrong.","In 1758 Dollond read a paper about his experiments to the Royal Society, and that same year he was granted a patent on achromatic lenses and awarded the Society's Copley Medal, its top prize for scientific work. In 1761 he became a Fellow of the Royal Society and optician to King George III. He died later that year, aged 55.","Did Dollond know about Hall's earlier lenses? It seems that George Bass told him about them in the 1750s, so the honest answer is that Dollond probably knew the idea had been tried, but he was the one who studied it scientifically, made it work reliably, published it and turned it into a business. That made the patent controversial. Other London opticians were furious, because they had made or sold achromatic lenses too, and now they were forbidden to.","After John's death, his son Peter Dollond enforced the patent firmly in the courts, suing rival opticians who made achromats without paying. Rivals petitioned against the patent and challenged it, but it was upheld. In the case of Watkin versus Dollond, the judge, Lord Mansfield, ruled that the person who locked an invention away in his desk was not the one who ought to profit from it, but the one who brought it out for the benefit of the public. That is a neat summary of the whole affair. When the patent finally expired in 1772, the price of achromatic lenses in England fell by about half.","The Dollond name became one of the most famous in optics. Dollond telescopes were used by sailors, scientists and kings. One sailed with Captain James Cook on his 1768 to 1771 voyage to observe the transit of Venus, and Admiral Lord Nelson owned Dollond spyglasses. The family firm lasted for centuries; in 1927 it merged with another company to become Dollond and Aitchison, a chain of opticians on British high streets."]},{"heading":"The Trouble with Glass","paragraphs":["Knowing how to design an achromatic lens was one thing. Making a big one was another. The problem was the glass itself, especially flint glass. Flint glass is heavy with lead, and when it is melted in a furnace, the heavy lead tends to sink while lighter ingredients rise, a bit like a salad dressing separating in the bottle. When the glass cooled, it was often full of bubbles, grains of unmelted sand, and streaks called striae: wavy bands where the glass was slightly denser or thinner. You can sometimes see similar wiggly lines in old window panes.","For a drinking glass, a few streaks do not matter. For a telescope lens they are a disaster, because every streak bends light by a slightly different amount and smears the image. Opticians could usually find a small clear piece in a batch, but a flawless disk wider than about 4 inches, roughly 10 centimeters, was extremely rare. That put a ceiling on how big achromatic telescopes could be. In England, a heavy tax on glass made the problem worse by discouraging glassmakers from experimenting.","The breakthrough came from an unlikely corner of Europe: the Jura mountains of Switzerland. Pierre-Louis Guinand was born in 1748 in La Sagne, in the Principality of Neuchâtel, and worked as a carpenter and a watchmaker in a region famous for its skilled clock and watch craftsmen. He became fascinated by telescopes, tried to make his own lenses, and discovered how hard it was to get good flint glass. So, starting in the 1780s, he taught himself glassmaking and began years of patient experiments with a small furnace.","Guinand's key idea was simple but powerful: stir the glass. While the glass was molten, he stirred it with a rod made of fireclay, the same heat-proof clay used to make the melting pot. Stirring mixed the heavy and light parts evenly and helped bubbles escape, so the glass cooled into a much more uniform block. It took him many failed melts to get the timing, temperature and stirring right, but by the early 1800s he could make disks of clear flint glass larger than anyone else. Stirring molten optical glass is still part of how high-quality glass is made today.","Guinand's glass was so good that a group of businessmen and instrument-makers in Bavaria, in southern Germany, invited him to bring his secrets to their new optical workshop. There, he would meet a teenage apprentice who would take his methods further than he could have imagined."]},{"heading":"The Boy Pulled from the Rubble","paragraphs":["Joseph Fraunhofer was born on 6 March 1787 in Straubing, Bavaria, the 11th child of a glazier, a craftsman who made and fitted glass. Glass was in the family, but there was not much money and there was a lot of sadness. His mother died when he was 10, and his father died a year later. At about 12, the orphaned boy was sent to Munich as an apprentice to a mirror maker and decorative glass cutter named Philipp Anton Weichselberger. It was a hard life. He worked long hours, and his master did not let him attend school or read much.","Then, in July 1801, when Joseph was 14, disaster struck. His master's old house collapsed, burying him under the rubble. Rescuers worked for hours to dig him out, and astonishingly he was pulled out alive. The rescue caused such a stir that the ruler of Bavaria, Prince-Elector Maximilian Joseph, came to the scene. Moved by the boy's escape, he gave Joseph a gift of gold coins, 18 ducats according to the usual account, which was a good deal of money.","The accident changed his life. Another important man who came to the site was Joseph von Utzschneider, a government official and businessman. He took an interest in the clever, quiet boy, gave him books on mathematics and optics, and made sure he could attend Sunday school. Joseph used part of the Elector's gold to buy a glass-cutting machine and to free himself from the rest of his apprenticeship early.","In 1806, Utzschneider brought him into a new optical company in Munich, run with the engineer Georg von Reichenbach. The next year the glass furnaces moved to a former monastery at Benediktbeuern, in the foothills of the Alps. Pierre-Louis Guinand was working there, and young Fraunhofer learned Guinand's glassmaking methods. Then he improved on them, using careful measurements and mathematics where Guinand had used trial and error. Fraunhofer designed better polishing machines, better ways of testing lens shapes, and better lens designs. He became a partner in the firm in 1809 and director of its optical institute in 1818. Thanks largely to him, Bavaria overtook England as the world center of fine optics."]},{"heading":"Hundreds of Dark Lines in the Rainbow","paragraphs":["To design a perfect achromatic lens, Fraunhofer needed to know exactly how much each kind of glass bent each color. But colors blend smoothly into one another. Where exactly does red end and orange begin? To measure accurately, he needed sharp, fixed markers in the rainbow, like the marks on a ruler.","Around 1814 he found them in an unexpected place. He set up a prism in front of the small telescope of a theodolite, a surveying instrument for measuring angles very precisely, and let sunlight from a narrow slit pass through the prism. Looking at the magnified rainbow, he saw that it was not smooth at all. It was crossed by many thin dark lines, as if someone had drawn on it with a fine pencil.","An English chemist, William Hyde Wollaston, had glimpsed a few of these lines in 1802 but thought they were just the gaps between colors. Fraunhofer studied them carefully. He mapped 574 of them, measured their exact positions, and showed that they were always in the same places in sunlight, no matter which prism he used. He labeled the strongest ones with letters from A to K. For example, the pair he called D sits in the yellow, at a wavelength of about 589 nanometers. Astronomers and physicists still use some of his letters today. Fraunhofer also found that sunlight reflected from the Moon and planets showed the same lines, while the light of other stars, such as Sirius, showed different patterns.","Fraunhofer used the lines as his ruler, and they let him measure his glass more accurately than anyone ever had. But he did not know what they were. In 1821 he also developed the diffraction grating, a surface ruled with many very fine parallel lines that spreads light into a spectrum even more precisely than a prism, and used it to measure wavelengths of light.","The meaning of the dark lines was solved about 45 years after his discovery, when scientists showed that each chemical element absorbs its own special set of colors. That story, and how it let astronomers learn what stars are made of, comes in Part 12. But it all started with a glassmaker who needed a better ruler. Today his name is everywhere: the dark lines are called Fraunhofer lines, and they mark the birth of spectroscopy, the study of light's colors to learn about the things that give it off."]},{"heading":"The Great Dorpat Refractor","paragraphs":["Fraunhofer's masterpiece was a telescope built for the observatory at Dorpat, a university town in what was then the Russian Empire and is now Tartu in Estonia. It was finished in 1824. Its achromatic objective lens was about 24 centimeters, or roughly 9.5 inches, across, made of flawless crown and flint glass from Benediktbeuern, and its focal length was more than 4 meters. At the time it was the largest and finest refracting telescope in the world.","The lens was only part of the wonder. Fraunhofer mounted the telescope on a new kind of stand, now called a German equatorial mount. One axis of the mount was tilted to point at the celestial pole, parallel to Earth's own axis, so that turning the telescope around that single axis followed the stars as they slowly wheeled across the sky. A heavy counterweight on the other side balanced the long tube. And it was driven by clockwork, a falling weight regulated like a clock, which turned the telescope smoothly to keep a star in view while the Earth rotated underneath. An astronomer no longer had to keep nudging the tube by hand every few seconds. The German equatorial mount became the standard design for big refractors, and you can still buy small telescopes on one today.","The astronomer who used it was Friedrich Georg Wilhelm Struve, the director of the Dorpat Observatory. Struve specialized in double stars, pairs of stars that appear very close together in the sky, many of which orbit each other. Between 1824 and 1837 he used the great refractor to examine and measure 2,714 double stars, a gigantic project that needed both sharp optics and a steady, motorized mount. Later he founded the Pulkovo Observatory near St Petersburg, which became one of the leading observatories in the world.","Fraunhofer was honored for his work. He received an honorary doctorate, and in 1824 he was knighted, becoming Joseph von Fraunhofer. But he did not live to enjoy it for long. He died in Munich on 7 June 1826, only 39 years old. His death is often blamed on years of breathing poisonous heavy-metal fumes from the glass furnaces, though tuberculosis has also been suggested. He was buried in Munich, and his gravestone bore a Latin phrase that sums him up perfectly: Approximavit sidera, which means He brought the stars closer."]},{"heading":"How Far Away Is a Star?","paragraphs":["For thousands of years, one of the biggest questions in astronomy had no answer: how far away are the stars? Since Copernicus, astronomers had believed that Earth orbits the Sun. If that is true, then as Earth swings from one side of its orbit to the other over six months, nearby stars should seem to shift very slightly against more distant stars behind them. This tiny shift is called parallax.","You can see parallax with your own thumb. Hold your thumb up at arm's length, close one eye, and line it up with something across the room. Now switch eyes. Your thumb seems to jump sideways, because you are looking from two different positions. Bring your thumb closer and it jumps more; move it farther and it jumps less. Measure the jump, know the distance between your eyes, and a little geometry tells you how far away your thumb is. Astronomers use Earth's orbit, about 300 million kilometers across, as their pair of eyes.","The trouble was that the stars are so far away that their parallax jump is unbelievably small. Even Tycho Brahe, the best naked-eye observer in history, could not detect any, and many astronomers had tried and failed with telescopes. To measure it you needed a telescope with superb optics, an extremely precise way to measure tiny angles, and a lot of patience.","Friedrich Wilhelm Bessel had all three. Born in 1784 in Minden, Germany, he left school at 14 to work as an apprentice clerk at a trading company in Bremen. Interested in navigation, he taught himself astronomy and mathematics, and in 1804, at about age 20, he calculated a new orbit for Halley's Comet. In 1810, aged 25 and with no university degree, he was made director of the new observatory at Königsberg in Prussia.","Bessel chose his target cleverly. Instead of a bright star, he picked 61 Cygni, a faint pair of orange stars in the constellation Cygnus, the Swan. It had been nicknamed the Flying Star because the Italian astronomer Giuseppe Piazzi had found that it moves across the sky faster than any other star you can see with the naked eye. Bessel reasoned that a star moving that fast across our view was probably close by.","His instrument was a heliometer made by Fraunhofer's workshop, which arrived after Fraunhofer's death. A heliometer is a refracting telescope whose objective lens is cut in half. The two halves can be slid past each other with a very fine screw, making two images of the sky. By sliding them until the image of one star sits exactly on top of another, an astronomer can measure the angle between the two stars with superb accuracy. From 1837 to 1838, Bessel measured the position of 61 Cygni against fainter background stars again and again.","In 1838 he announced the result: a parallax of about 0.314 arcseconds. An arcsecond is 1/3,600 of a degree, so this is about the angle a small coin makes when seen from roughly 16 kilometers away. It meant 61 Cygni was about 10.3 light-years away, around 100 trillion kilometers. The modern value is about 11.4 light-years, so Bessel was remarkably close. At almost the same time, Thomas Henderson measured the parallax of Alpha Centauri from South Africa, and Struve, at Dorpat, measured Vega. But Bessel's careful result is usually counted as the first reliable distance to a star beyond the Sun.","The meaning was staggering. Light from 61 Cygni, traveling about 300,000 kilometers every second, takes about 11 years to reach us. And it is one of our closest neighbors. The universe was far, far bigger than most people had imagined, and lens telescopes, which Newton had said could never be perfected, had measured it."]}],"deepDive":"The achromatic doublet works because glasses differ in two independent properties: refractive index (how strongly they bend light) and dispersion (how much the index changes with color). Optical designers today summarize the second using the Abbe number; a crown glass typically has a high Abbe number (low dispersion) and a flint glass a low one. To make an achromat, the designer chooses a positive crown element and a negative flint element whose powers are in the right ratio so that the total color error at two chosen wavelengths, usually red and blue, adds to zero while the total power stays positive. The leftover error at other wavelengths, the secondary spectrum, is why astronomers later developed apochromats with three elements or special glasses. Priority for the achromat is still debated. Hall made achromats first, around 1729 to 1733 depending on the account, and Bass made them for some customers, but Dollond independently investigated the physics, published it in 1758 and turned it into a product, so historians usually credit Hall with the invention and Dollond with its introduction. Some details of the Hall story, such as the trick of using two opticians, come from accounts told decades later during the patent disputes, so they should be treated with some caution. Fraunhofer's lines were also not entirely his discovery: Wollaston saw several in 1802. But Fraunhofer mapped 574 of them precisely, recognized they were a property of sunlight and not of the prism, and saw that stars showed different patterns, which is why spectroscopy is often dated from his 1814 work. The parallax race of 1838 is another fair-credit story. Henderson's Alpha Centauri measurements were made earlier at the Cape of Good Hope but published after Bessel's, and Struve's Vega value was less certain. Bessel's 0.314 arcsecond result, compared with the modern value of about 0.286 arcseconds, gave a distance roughly 10 percent too small, an impressive achievement given that the angle he was measuring was smaller than the apparent width of a coin many kilometers away.","funFact":"Joseph von Fraunhofer, who became one of the greatest lens-makers in history, was rescued from the ruins of a collapsed house in Munich at age 14, and the ruler of Bavaria gave him 18 gold ducats.","check":{"q":"Which two kinds of glass are paired in an achromatic lens to cancel out rainbow fringes?","a":"Crown glass and flint glass","wrong":["Window glass and mirror glass","Speculum metal and quartz","Two pieces of the same crown glass"]},"sources":[{"title":"Achromatic lens","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Achromatic_lens"},{"title":"John Dollond","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_Dollond"},{"title":"Peter Dollond","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Peter_Dollond"},{"title":"Joseph von Fraunhofer","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Joseph_von_Fraunhofer"},{"title":"Fraunhofer lines","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Fraunhofer_lines"},{"title":"Friedrich Georg Wilhelm von Struve","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Friedrich_Georg_Wilhelm_von_Struve"},{"title":"Friedrich Bessel","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Friedrich_Bessel"},{"title":"61 Cygni","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/61_Cygni"}],"photos":[{"src":"img/deep/telescope/08-1.jpg","alt":"Engraved portrait of Joseph von Fraunhofer, the German glassmaker and optician who made superb telescope lenses.","file":"Joseph von Fraunhofer, engraving by Christian Gottlob Scherff.jpg","url":"https://commons.wikimedia.org/wiki/File:Joseph_von_Fraunhofer,_engraving_by_Christian_Gottlob_Scherff.jpg","author":"Christian Gottlob Scherff, b. ca.1793 (engraver)","license":"Public domain"},{"src":"img/deep/telescope/08-2.jpg","alt":"Fraunhofer's own hand-coloured etching of the Sun's spectrum, with its dark lines labelled A to I.","file":"Fraunhofer Spektrum Medium.jpg","url":"https://commons.wikimedia.org/wiki/File:Fraunhofer_Spektrum_Medium.jpg","author":"Joseph Fraunhofer","license":"CC BY-SA 4.0"},{"src":"img/deep/telescope/08-3.jpg","alt":"Fraunhofer's great refractor, built for Dorpat (now Tartu) Observatory in Estonia, on display in the old observatory.","file":"798PX-TEADUSFOTO 2015 - 04 bearbeitet.jpg","url":"https://commons.wikimedia.org/wiki/File:798PX-TEADUSFOTO_2015_-_04_bearbeitet.jpg","author":"Elen Torb","license":"CC BY-SA 4.0"}],"words":3770},{"n":9,"title":"The Herschels: A New Planet","when":"1770s – 1840s","summary":"A music teacher and his sister turned their house in Bath into a telescope factory. One night in 1781 William spotted a 'star' that was really a brand-new planet: Uranus. Then Caroline became a famous comet hunter, and together they built a telescope so big that people could walk through its tube.","sections":[{"heading":"The Oboe Player Who Fell for the Stars","paragraphs":["Imagine a busy, fashionable city in the west of England in the 1770s. Rich visitors stroll between hot-spring baths, ballrooms and concert halls. The city is Bath, and one of its best-known musicians is a tall, friendly man from Germany named William Herschel. He teaches dozens of pupils, writes music, conducts choirs and plays the organ every Sunday. Nobody in the concert crowd would guess that he will soon change astronomy forever.","William was born Friedrich Wilhelm Herschel on 15 November 1738 in Hanover, a German state whose ruler was also, at that time, the King of Great Britain. His father was an oboe player in the Hanoverian army band, and William and his brother Jakob followed him into military music. In 1757, during the Seven Years' War, the French army defeated Hanover's forces at the Battle of Hastenbeck. Teenage William, aged 19, decided army life was not for him. He slipped away to England, changed his name to the English-sounding William, and began scraping a living as a musician.","For about ten years he moved around northern England, copying music, teaching, leading small orchestras and composing. He was very good at it. Over his life he wrote 24 symphonies, many concertos and a lot of church music, and some of it is still performed and recorded today. In 1766 he won the job of organist at the brand-new Octagon Chapel in Bath, and he played his first concert there on 1 January 1767.","Music and mathematics are close cousins. Herschel wanted to understand the science of harmony, so he read a book on the mathematics of music by a Cambridge professor named Robert Smith. Smith had also written a famous textbook called A Compleat System of Opticks, all about lenses, mirrors and telescopes. Herschel picked it up, and then a popular astronomy book by the Scottish writer James Ferguson. By 1773, when he was in his mid-thirties, he was hooked. He did not just want to read about the sky. He wanted to see it.","There was one problem. Good telescopes were expensive, and the ones he could rent or buy were small. Long refractors of the kind you met in part 6 were clumsy, and the achromatic lenses of part 8 could only be made in small sizes. So Herschel made a bold decision that would shape the rest of his life. He would build reflecting telescopes, the mirror type invented by Newton, and he would make the mirrors himself."]},{"heading":"A House Turned into a Mirror Factory","paragraphs":["A telescope mirror of the 1770s was not glass. It was a disc of speculum metal, a hard, brittle mixture of mostly copper and tin that could be polished until it shone like silver. To make one, you first had to melt the metal and pour it into a mould to make a rough disc called a blank. Then came the long part: grinding the face into a shallow curve with gritty powders, and then polishing it, hour after hour, until it was smooth and had exactly the right shape. A curve that is wrong by even a tiny fraction of the thickness of a hair can turn stars into fuzzy blobs.","Herschel turned his home into a workshop. His younger brother Alexander, a clever mechanic, built a lathe in one of the bedrooms and made eyepieces and metal parts. Tubes and stands were built in the drawing room. The smell of hot metal and the grinding noise filled the house. Herschel's records show that he made hundreds of mirrors over his lifetime, more than 400 by some counts, from about 6 inches up to 48 inches across, and at least 60 complete telescopes.","Polishing could not be stopped halfway, because if you lifted your hands the shape could be spoiled. So Herschel sometimes polished for up to 16 hours at a stretch. His sister Caroline later remembered feeding him bites of food while he worked, and reading aloud to him, from books like Don Quixote and the Arabian Nights, to help the hours pass. It sounds funny, but it was also exhausting and serious work.","Casting the metal was the most dangerous step. Herschel later tried to cast a very large mirror in the basement of one of their Bath houses, using a mould partly made from horse manure, which was a known trick for making moulds that could stand the heat. Caroline described how the molten metal leaked out across the floor and made the stone flagstones crack and fly apart, while everyone ran for safety. Nobody was badly hurt, but the mirror was ruined. Making telescopes was not a quiet hobby.","All this effort paid off. Herschel's mirrors were famous for being some of the best in the world. He used them in Newtonian telescopes, where a small flat mirror near the top of the tube sends the light out to an eyepiece on the side. One of his favourites was a reflector with a mirror about 6.2 inches across and a tube about 7 feet long. With it he could use very high magnifications and still get sharp images, because the mirror's shape was so good."]},{"heading":"Caroline Comes to Bath","paragraphs":["Caroline Lucretia Herschel was born in Hanover on 16 March 1750, the second youngest of the Herschel children. When she was about 10, she caught typhus, a dangerous fever. She survived, but the illness stunted her growth. As an adult she stood only about 4 feet 3 inches (about 1.30 metres) tall, and she lost some of the sight in one eye. Her mother expected her to stay at home as an unpaid housekeeper for the rest of her life and saw little point in educating her.","William had other ideas. In August 1772 he came back to Hanover and took Caroline, then 22, to live with him in Bath. The plan was that she would keep house for him and train as a singer for his concerts. She practised hard, took lessons two or three times a day, and became a skilled soprano. In April 1778 she was the main soloist in a performance of Handel's Messiah in Birmingham, and she was offered more singing work.","But the house was slowly filling up with telescopes, and Caroline was pulled into the new passion too. At first she helped by grinding, copying, fetching and writing down William's observations as he called them out in the dark. She learned mathematics, especially the sums needed to turn telescope readings into star positions, often teaching herself at the breakfast table. She would later say, a little sadly, that she had become a tool that her brother had trained. Yet she was far more than a tool, as we will see.","Picture the scene on a clear night. William stands at the eyepiece in the garden, wrapped against the cold. Caroline sits at a desk near an open window with a candle shaded from the telescope, a clock and a big record book. William calls out what he sees and where, and Caroline writes it down, notes the exact time and later turns it all into neat, usable tables. Without that partnership, many of William's discoveries would never have been recorded properly."]},{"heading":"13 March 1781: The Star That Wasn't","paragraphs":["By 1781 the Herschels were living at 19 New King Street in Bath, a narrow stone townhouse that still stands today as the Herschel Museum of Astronomy. William had set himself an enormous task. He was going to examine every star in the sky down to a certain faintness, one by one, looking especially for double stars, pairs of stars that sit very close together. It was patient, careful, repetitive work, exactly the kind of work that turns up surprises.","On the night of Tuesday 13 March 1781, he was working in the garden with his 6.2-inch homemade reflector, sweeping through the stars near the border of the constellations Taurus and Gemini. One object caught his eye. To most observers it would have looked like any other faint star. But to Herschel, whose telescope was unusually sharp, it did not look like a tiny point. It looked like a little disc.","Here is why that mattered. Stars are so far away that even through a big telescope they stay as points of light; turning up the magnification does not make them look wider. Planets and comets are much closer, so they show a real size. Herschel switched to higher magnifications, hundreds of times, and the object grew larger, while the stars around it did not. Over the following nights, he saw that it had moved slightly against the background stars. Something nearby was travelling across the sky.","What was it? Herschel's first guess was a comet, because new moving objects almost always were comets. In his journal he wrote that it was either a 'nebulous star' or perhaps a comet, and when he reported it to the Royal Society on 26 April 1781, he called it a comet. Nobody had discovered a new planet in all of recorded history. The five planets you can see with your eyes, Mercury, Venus, Mars, Jupiter and Saturn, had been known since ancient times. The idea that a sixth one beyond Saturn could be waiting out there just did not occur to most people.","Astronomers across Europe began to track the new object. But it did not behave like a comet. It had no tail and no fuzzy head, and it moved slowly. When mathematicians tried to work out its path, they found it went around the Sun in a nearly circular orbit far beyond Saturn, not on the long stretched-out path of a comet. The Swedish-born astronomer Anders Johan Lexell, working in Russia, was the first to calculate such an orbit, and the German astronomer Johann Bode also concluded that it must be a planet. By 1783 Herschel himself agreed. A music teacher with a homemade telescope had found the first planet ever discovered with a telescope.","It turned out that others had actually seen it before, without realising. The first Astronomer Royal, John Flamsteed, had recorded it in 1690 and listed it as a star called 34 Tauri. The French astronomer Pierre Charles Le Monnier noted it many times between 1750 and 1769. They had all thought it was a star. Herschel was the one who looked carefully enough, with a good enough telescope, to see that it was different.","The discovery doubled the size of the known solar system in one go. Saturn sits about 9.5 times farther from the Sun than Earth does. The new planet sits about 19 to 20 times farther, around 3 billion kilometres away, and takes about 84 years to go around the Sun once. That means someone born on the day of its discovery would have had to live to 84 to see it return to the same place in the sky."]},{"heading":"George's Star, or Uranus?","paragraphs":["A new planet needed a name. Herschel, living in England and hoping for royal support, suggested Georgium Sidus, Latin for George's Star, after King George III. To British ears that made sense. To astronomers in the rest of Europe, naming a planet after a British king sounded strange. The French astronomer Jérôme Lalande suggested calling it Herschel, and other people proposed names such as Neptune and Minerva.","In 1782 Johann Bode suggested Uranus, after the ancient Greek god of the sky. His reasoning was neat: Saturn was the father of Jupiter in the old myths, and Uranus was the father of Saturn, so the new planet beyond Saturn should be named for him. Most of Europe gradually adopted Uranus. Britain held on to the Georgian name for decades. The last holdout, the British Nautical Almanac Office, only switched to Uranus in 1850, long after both Herschel and the king had died.","The name argument did not hurt Herschel at all. In 1781 he was elected a Fellow of the Royal Society and awarded its Copley Medal, the society's top prize. In 1782 he was invited to show his telescope to King George III at Windsor. The king was impressed and made him the King's Astronomer, with a salary of 200 pounds a year, on the condition that he live near Windsor Castle so the royal family could look through his telescopes. (This is a different job from the Astronomer Royal at Greenwich, whom you will meet in part 10.)","Two hundred pounds was less than Herschel had been earning as a busy musician, but it freed him to do astronomy full time. In August 1782 the family moved to Datchet, near Windsor, and in 1786 they settled in a house at Slough that became known as Observatory House. To boost their income, William built and sold telescopes to customers around Europe, including royalty and observatories. He gave up his music career, and Caroline, rather unhappily at first, gave up her singing career too."]},{"heading":"Caroline the Comet Hunter","paragraphs":["William gave Caroline her own small telescope and asked her to 'sweep' the sky, slowly moving the telescope back and forth to look for nebulae, faint fuzzy patches of light, and for comets. She began keeping her own observing record book on 28 August 1782. At first she found it lonely and dull. Then she started making discoveries.","On 26 February 1783 she found a nebula that was not in the famous list of fuzzy objects published by the French comet hunter Charles Messier. That same year she independently found a small companion galaxy of the great Andromeda Galaxy, now known as M110. Of course, nobody yet knew that these fuzzy patches could be whole galaxies. That discovery was still 140 years away.","On the night of 1 August 1786, while William was away in Germany delivering a telescope, Caroline spotted a fuzzy object that moved. It was a comet, and she became one of the very first women ever credited with discovering one. She wrote careful letters announcing it to leading astronomers, the news spread quickly, and visitors came to Slough to see the famous lady comet hunter. Between 1786 and 1797 she discovered eight comets in all. In 1795 she also found a comet that turned out to be a return of one seen before, now known as Comet Encke. One comet still carries her name today: 35P/Herschel-Rigollet, which goes around the Sun only about once every century and a half.","In 1787 King George III granted Caroline a salary of 50 pounds a year as her brother's assistant. This made her the first woman in Britain to be paid an official salary for scientific work, and she is often described as the first professional woman astronomer. Fifty pounds was not a fortune, but for Caroline it meant something huge: money of her own, earned by her own skill.","Caroline also did enormous behind-the-scenes work that helped every astronomer. In 1798 the Royal Society published her index and catalogue to John Flamsteed's star observations, in which she found and listed more than 560 stars that Flamsteed had observed but left out of his famous catalogue. She also kept William's huge lists of nebulae in order. Together the Herschels discovered more than 2,400 nebulae and star clusters, and Caroline's careful organising helped lay the groundwork for the New General Catalogue, the list that still gives many galaxies their NGC numbers.","After William died in 1822, Caroline moved back to Hanover. She kept working, finishing a catalogue of the nebulae for her nephew John. In 1828, at the age of 77, she received the Gold Medal of the Royal Astronomical Society; no woman would receive it again until 1996. In 1835 she and the Scottish scientist Mary Somerville became the first women made honorary members of the society. At 96 she received a gold medal for science from the King of Prussia. She died in Hanover on 9 January 1848, aged 97. Caroline was not just William's helper. She was a discoverer in her own right."]},{"heading":"The Forty-Foot Giant","paragraphs":["Herschel knew the lesson you will meet again and again in this Deep Dive: the bigger the mirror, the more light it collects, and the fainter the things you can see. He already had an excellent telescope with a mirror about 18.7 inches across and a tube 20 feet long, which he used for most of his observations. But he dreamed bigger. In 1785 King George III gave him 4,000 pounds to build a monster, plus 200 pounds a year for its upkeep.","The result, finished in 1789 in the garden at Slough, was the famous 40-foot telescope. The name came from the length of its iron tube, about 40 feet (12 metres), wide enough for a grown person to walk through. Its main mirror was about 48 inches (1.2 metres) across. The first mirror, cast in 1785, turned out to be too thin to hold its shape, so a second, thicker mirror was cast in 1788 and finished in 1789. The whole tube sat in a huge wooden frame of poles, ladders and pulleys that could be turned around on a circular track. Workers had to crank it into position.","Herschel did something clever to save light. Instead of using a small second mirror to send the light out to the side, which would have lost some light in the speculum metal, he tilted the main mirror slightly so that the image formed near the top edge of the tube. He then stood or sat in a little platform at the mouth of the tube, high in the air, and looked down into the mirror through an eyepiece, with his back to the sky. This 'front-view' design is now often called a Herschelian telescope. A speaking tube carried his words down to Caroline or another helper writing at the desk below.","Before it was finished, the telescope became a tourist attraction. A well-known story says that King George III, walking through the empty tube with the Archbishop of Canterbury, joked: 'Come, my Lord Bishop, I will show you the way to Heaven!' It may or may not be exactly what he said, but it shows how amazing the giant tube looked to visitors. In February 1787 Herschel had already tested it by lying inside the unfinished tube and holding an eyepiece by hand to look at the Orion Nebula.","In the summer and autumn of 1789, around the time the telescope came into full use, Herschel discovered two new moons of Saturn: Enceladus on 28 August 1789 and Mimas on 17 September 1789. Earlier, on 11 January 1787, using his 20-foot telescope, he had found the two largest moons of Uranus, now called Titania and Oberon. Historians note that he was using several telescopes at that time, so it is not completely certain which ones deserve the credit for the Saturn moons.","The giant had problems. Its speculum mirror tarnished quickly in the damp English air and had to be taken out and repolished often, which was a heavy, risky job. It took a long time to set up, and English nights are often cloudy, so it was used less than its builder had hoped. Herschel's smaller 20-foot telescope did more of the everyday science.","Still, the 40-foot was the largest telescope in the world for about 50 years. In 1839, its wooden frame was rotting, and William's son John took it down for safety. Around New Year 1840, the Herschel family gathered inside the old tube, now lying on the ground, and sang a song written for the occasion. A section of the tube survives at the Royal Observatory, Greenwich, and the first, too-thin mirror is kept at the Science Museum in London."]},{"heading":"Mapping the Milky Way and Feeling Invisible Light","paragraphs":["Herschel wanted to know more than what was in the sky. He wanted to know the shape of everything. In the 1780s he invented a method called star gauging. He pointed his 20-foot telescope at hundreds of small patches spread across the sky and counted how many stars he could see in each. His idea was simple: if you see lots of stars in one direction, the starry system must stretch farther that way; if you see only a few, its edge must be close.","From these counts, published in 1785, he drew the first map of the shape of the Milky Way, based on real measurements. It came out as a flattened, ragged disc, a bit like a grindstone or a thick pancake, much wider than it is thick. That basic idea, that we live in a flat disc of stars, is correct. But his map put the Sun near the middle, which turned out to be wrong. Herschel did not know that clouds of dark dust between the stars block the light of distant stars, so he could not see the true size of the galaxy or where its center lay. That puzzle would be solved in the twentieth century.","He also found that many double stars are not just two stars that happen to line up by chance. By watching some pairs for more than 20 years, he showed in 1803 that they slowly go around each other. That proved the same gravity that holds the solar system together also works among distant stars, a big step in showing that the laws of physics are the same everywhere. He listed more than 800 double and multiple stars.","Then, in 1800, came one of his most surprising discoveries, and it did not even need a telescope. Herschel was testing coloured filters for looking at the Sun safely, and he noticed that some colours felt warmer than others. So he set up an experiment. He used a glass prism to spread sunlight into a rainbow spectrum and placed thermometers with blackened bulbs in the different colours. He kept other thermometers nearby, out of the light, to show the normal room temperature for comparison.","The temperature rose from violet toward red, which already surprised him. Then he moved a thermometer just past the red end, where there was no visible light at all. The temperature there was the highest yet. Some kind of invisible ray was falling on the thermometer and warming it. Herschel called these 'calorific rays', meaning heat rays. Today we call them infrared light. He had discovered, for the first time, that there is light our eyes cannot see. This was a giant clue that the rainbow we see is only a small part of a much bigger family of light, an idea that later parts of this Deep Dive will explore.","Herschel kept observing for many more years. He married a widow named Mary Pitt in 1788, and their only child, John, was born in 1792. In 1816 he received a Hanoverian knighthood, and in 1820 he became the first president of the new Astronomical Society of London, later the Royal Astronomical Society. He died at Observatory House in Slough on 25 August 1822, aged 83. John Herschel became a great astronomer too. In the 1830s he took telescopes to the Cape of Good Hope in southern Africa and surveyed the southern skies, finishing the family project of mapping the whole heavens.","Look at what the Herschels achieved, starting with nothing but music money and a kitchen-table workshop: a new planet, new moons, eight comets, thousands of nebulae, the first measured shape of our galaxy and the first invisible light. And they did it all with telescopes they built themselves. Telescopes were now finding planets. But far from the great observatories, they were also quietly changing life on Earth: on ships, maps, battlefields and backyards."]}],"deepDive":"Why did Herschel recognise Uranus when Flamsteed, Le Monnier and others had logged it as an ordinary star? The answer is optics. A star's image in a telescope is set by diffraction and by the blurring of the air, so it never grows into a real disc however much you magnify it. Uranus, by contrast, has a true angular size of only about 3.3 to 4 arcseconds, roughly one five-hundredth of the width of the full Moon. Seeing that as a disc needs a mirror with an excellent figure and high magnification. Herschel's 6.2-inch reflector had a focal length of about 7 feet, and he could use eyepieces giving magnifications of a few hundred times and higher. At low power Uranus looked like a star; at high power it swelled while true stars did not. The second test was motion: over several nights it shifted slightly against the stars. Herschel's careful habit of reporting what he saw honestly, a 'comet or nebulous star', helped others follow it up quickly. Turning a moving dot into a planet needed mathematics. With only a few weeks of observations, the path could fit many orbits. Lexell and others found that a near-circular orbit at about 19 times the Earth-Sun distance fit well, while a comet's long ellipse did not. Remarkably, this distance closely matched a numerical pattern called the Titius-Bode rule, which predicted a planet at about 19.6 times the Earth-Sun distance. That match encouraged astronomers to search for a 'missing planet' between Mars and Jupiter, which led to the discovery of Ceres in 1801. Later, the rule failed badly for Neptune, and today it is seen as a coincidence rather than a law. Historians also discuss how to describe Caroline. Her 1787 royal salary is the earliest known case of a woman in Britain being paid officially for scientific work, but some older accounts presented her only as William's assistant. Her comet discoveries, nebula catalogues and her index to Flamsteed's observations show independent skill. Finally, Herschel's star-gauging model of the galaxy is a good example of reasonable science that was wrong for a hidden reason: he assumed space was transparent. Interstellar dust, only proven in the 1930s, dims distant starlight and fooled his counts into placing the Sun near the center.","funFact":"Before he discovered a planet, William Herschel was a busy professional composer, and he wrote 24 symphonies, some of which are still performed today.","check":{"q":"What did William Herschel first think Uranus was when he spotted it in 1781?","a":"A comet","wrong":["A new moon of Saturn","A double star","A distant galaxy"]},"sources":[{"title":"William Herschel","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/William_Herschel"},{"title":"Caroline Herschel","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Caroline_Herschel"},{"title":"Uranus","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Uranus"},{"title":"40-foot telescope","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/40-foot_telescope"},{"title":"Infrared Waves","publisher":"NASA Science","url":"https://science.nasa.gov/ems/07_infraredwaves/"},{"title":"History of the telescope","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/History_of_the_telescope"}],"photos":[{"src":"img/deep/telescope/09-1.jpg","alt":"William Herschel, painted by Lemuel Francis Abbott in 1785, a few years after he discovered Uranus.","file":"William Herschel01.jpg","url":"https://commons.wikimedia.org/wiki/File:William_Herschel01.jpg","author":"Lemuel Francis Abbott","license":"Public domain"},{"src":"img/deep/telescope/09-2.jpg","alt":"Engraving of Herschel's giant 40-foot telescope in its wooden frame of ladders, from the 1797 Encyclopaedia Britannica.","file":"40 foot telescope 120 cm 48 inch reflecting telescope William Herschel.png","url":"https://commons.wikimedia.org/wiki/File:40_foot_telescope_120_cm_48_inch_reflecting_telescope_William_Herschel.png","author":"Andrew Bell and Colin Macfarquhar","license":"Public domain"},{"src":"img/deep/telescope/09-3.jpg","alt":"Caroline Herschel, astronomer and comet hunter, in a portrait painted in 1829.","file":"Herschel Caroline 1829.jpg","url":"https://commons.wikimedia.org/wiki/File:Herschel_Caroline_1829.jpg","author":"M. F. Tielemanm","license":"Public domain"}],"words":4278},{"n":10,"title":"Telescopes Change Life on Earth","when":"1600s – 1900s","summary":"Telescopes didn't only look at stars. Sailors used them to spot ships and read flag signals, map-makers used them to measure whole countries, and theatre-goers used little ones to see the actors. Later, ordinary people started building their own telescopes in their backyards and even discovered comets.","sections":[{"heading":"Spyglasses at Sea and on the Battlefield","paragraphs":["Stand on the swaying deck of a wooden sailing ship in the 1700s. The lookout high on the mast shouts that he can see a sail on the horizon. Is it a friendly merchant ship, a warship of your own navy, or an enemy? The captain pulls a brass tube from his coat, stretches it out to its full length, braces against the rail and peers through it. Within a minute he can see the shape of the hull, the number of gun ports and, most important, the flag. That simple act, repeated thousands of times a day on oceans around the world, is one of the biggest ways the telescope changed life on Earth.","As you read in part 3, the very first Dutch telescopes of 1608 were immediately seen as military tools. Someone who can see the enemy first can decide whether to fight, flee or prepare. By the 1700s, most naval officers carried a spyglass. Many were made to collapse, with several brass tubes, called draw tubes, sliding inside one another, so a telescope a metre long when open could fit in a pocket or under an arm when closed. Inside, most used Keplerian-style convex lenses, plus extra lenses to turn the image the right way up, because an upside-down ship is confusing.","Telescopes also made it possible to send messages across water. Navies used systems of coloured signal flags hoisted on the masts, each flag or group of flags standing for a number, letter or order. An admiral could control a whole fleet spread over kilometres of sea, but only if his captains could read his flags. Without telescopes, flag signals would have been useless beyond a short distance.","On land, generals climbed hills or church towers to watch battles through telescopes and send orders by messenger. Lookouts on forts watched roads and harbours. Later, in the 1790s, France built a chain of 'semaphore' towers with moving wooden arms, invented by Claude Chappe, which passed messages from tower to tower across the country. Operators in each tower read the arms on the next tower through a telescope, so a message could travel hundreds of kilometres in less than an hour. It was a kind of optical internet, made possible by lenses.","One of the most famous telescope stories comes from the Battle of Copenhagen, fought on 2 April 1801 between a British fleet and the Danish navy. The British second-in-command, Vice-Admiral Horatio Nelson, had lost the sight in his right eye in an earlier battle. During the fighting, his senior commander, Admiral Sir Hyde Parker, hoisted a signal giving permission to stop fighting and pull back. According to the story, Nelson raised his telescope to his blind eye and said something like 'I really do not see the signal', and kept fighting. The battle ended in a truce that favoured the British.","It is a famous tale, and it gave English the phrase 'to turn a blind eye', meaning to pretend not to notice something. Accounts of it come from people who were there, but they were written down later, and historians still discuss exactly what was said and whether Parker's signal was meant as a strict order or as permission Nelson could ignore. So enjoy it as a great story about a telescope, but remember that the exact words are not certain."]},{"heading":"The Longitude Puzzle and the Clock in the Sky","paragraphs":["For sailors, the biggest problem in the world for about 300 years was not enemy ships. It was not knowing exactly where they were. Finding your latitude, how far north or south you are, was fairly easy: you measure the height of the Sun at noon or the height of the Pole Star at night. But finding your longitude, how far east or west you are, was fiendishly hard. Ships that guessed wrong could run onto rocks, miss islands where they needed fresh water, or take weeks longer than planned while sailors fell ill.","The key to longitude is time. Earth turns once in 24 hours, which is 360 degrees, so it turns 15 degrees every hour. If it is noon where you are, because the Sun is at its highest, and you somehow know that at that same moment it is 3 in the afternoon in your home port, then you must be 45 degrees west of home. The problem was knowing the home time, far out at sea, without a clock that kept perfect time on a rolling ship.","Galileo had an idea. Jupiter's four big moons, which he had discovered in 1610 (part 4), go around Jupiter like the hands of a clock, and they regularly slip into Jupiter's shadow and vanish. Those disappearances happen at the same instant for everyone on Earth who can see them. In 1612 Galileo proposed that if someone made accurate tables predicting the times of these events, anyone with a telescope could look up and read the 'clock in the sky', compare it with their local time, and work out their longitude.","Galileo spent years trying to sell this idea. In 1616 he applied for a longitude prize offered by the King of Spain, and later he approached the Dutch government. He even designed a strange helmet called the celatone, with a telescope attached, that was supposed to let an observer keep Jupiter in view on a moving ship. It did not work well. Keeping a small, bright dot steady in a long, narrow telescope while the deck heaves up and down is almost impossible, and the method was never used successfully at sea.","On land, though, the idea was brilliant. In 1668 the Italian astronomer Giovanni Domenico Cassini, soon to become director of the Paris Observatory (part 6), published excellent tables of Jupiter's moons. French astronomers took telescopes and clocks around France, timed the moons' eclipses and compared them with the times predicted for Paris. They found that older maps had drawn the Atlantic coast of France too far west. The new, accurate map made the country look noticeably smaller. King Louis XIV is said to have joked that the astronomers had taken more land from him than all his enemies had taken in war. The Academy's map of France based on this work came out in 1744.","At sea, two other methods finally won. In 1714 the British Parliament passed the Longitude Act, offering up to 20,000 pounds, a huge fortune, for a practical way to find longitude at sea. The clockmaker John Harrison spent decades building ever-better marine clocks, called chronometers, and his small watch-like H4 passed a sea trial to Jamaica in 1761 and 1762 with astonishing accuracy. Meanwhile, astronomers perfected the 'lunar distance' method, which used the Moon's movement against the stars as the sky clock. Sailors measured the angle between the Moon and a star with a sextant, an instrument that often had a small telescope on it, and looked up the answer in tables. In the end, chronometers became the main method, but only once they became cheap enough, in the 1800s. Telescopes and star tables remained the backup for decades."]},{"heading":"Greenwich: An Observatory for Sailors","paragraphs":["If you visit London today, you can climb a hill in Greenwich Park to a red-brick building with a little domed tower. This is the Royal Observatory, and it was built for sailors. In 1675 King Charles II ordered it to be built, and construction began that August. The architect was Sir Christopher Wren, who also designed St Paul's Cathedral and who was himself a former professor of astronomy. The main building, now called Flamsteed House, was finished in 1676.","The job of the observatory was written down very clearly: to make the most exact observations of the stars and the motions of the Moon, to find 'the so much desired longitude of places for the perfecting of the art of navigation'. The idea was that if astronomers made a perfect map of the stars and could predict the Moon's movements, sailors could use the Moon as a sky clock.","The first Astronomer Royal was John Flamsteed, appointed in 1675. He was a careful, stubborn and often sickly man who was paid just 100 pounds a year and had to buy many of his own instruments. He used telescopes with crosshairs mounted on huge, precisely marked metal arcs fixed to walls, called mural arcs, and noted exactly when each star crossed his line of sight. Over more than 40 years he measured the positions of about 3,000 stars far more precisely than ever before. His great star catalogue was published in 1725, after his death. (It was in this work that he logged Uranus as an ordinary star, 34 Tauri, as you read in part 9.)","Later Astronomers Royal built on this work. Nevil Maskelyne began publishing The Nautical Almanac, with tables for the year 1767, giving sailors the pre-calculated numbers they needed for the lunar distance method. It became one of the most important books on any ship. In 1833 a bright red time ball was placed on top of the observatory. Every day at 1 pm it drops down its pole, so that ships on the River Thames could check their chronometers. It still drops today.","In 1851 the Astronomer Royal George Airy installed a large telescope called the Airy Transit Circle, which could swing only north and south along one exact line. Astronomers timed stars crossing that line to keep perfect time. In 1884, at an international meeting in Washington, D.C., countries agreed to use the line through that very telescope as the world's prime meridian, zero degrees of longitude. That is why world time was long based on Greenwich Mean Time, and why every longitude on every map today is measured east or west of a telescope in a London park."]},{"heading":"Measuring Countries Through a Tube","paragraphs":["Before satellites and GPS, how did anyone make an accurate map of a whole country? The answer is a clever method called triangulation, and telescopes made it work. Surveyors measure one straight line on the ground extremely carefully; this is called a baseline. Then, from each end of the baseline, they measure the angle to a distant landmark, such as a church tower or a hilltop. With one known length and two angles, simple geometry gives the size of the whole triangle. That triangle's new sides become the starting points for more triangles, and soon a net of triangles stretches across the land.","Everything depends on measuring angles accurately, and that means pointing exactly at a faraway target. In the 1600s, instrument makers began putting small telescopes with crosshairs onto their angle-measuring tools instead of simple open sights. The French astronomer Jean Picard was a pioneer of this, using telescopic sights in his famous measurement of part of France around 1669 to 1670. A telescope lets the surveyor pin a tower many kilometres away right on the crosshairs.","The surveyor's main tool became the theodolite: a telescope mounted so it can turn sideways and tilt up and down, with finely marked circles that show exactly how far it has turned. One of the most famous was built by the London instrument maker Jesse Ramsden and delivered in 1787. It was a giant. It weighed about 200 pounds (91 kilograms), and its main measuring circle was 36 inches (about 91 centimetres) across. It could measure horizontal angles to within about one arcsecond, which is the width of a coin seen from about 4 kilometres away.","Ramsden's great theodolite was made for General William Roy's Anglo-French Survey, which ran from 1784 to 1790. Its goal was to link the Royal Observatory at Greenwich and the Paris Observatory with a precise chain of triangles across the English Channel, so the two great observatories would know exactly where they stood relative to each other. Soldiers carried the heavy instrument from hill to hill in a special sprung carriage.","This work grew into the Ordnance Survey, Britain's national mapping agency, founded in 1791. From 1799 the great theodolite was used for the Principal Triangulation of Great Britain, a vast net of triangles covering the whole island, which was finally completed in 1853. Sadly, the first Ramsden theodolite was destroyed in 1941, when bombs hit the Ordnance Survey's headquarters in Southampton during the Second World War. A second one, completed in 1791, survives in the Science Museum in London.","Similar surveys were carried out around the world. The Great Trigonometrical Survey of India, started in 1802, measured triangles across the whole subcontinent with huge theodolites. In the 1850s its computers used those measurements to show that a mountain known as Peak XV was the highest on Earth. It was later named Mount Everest after George Everest, a former head of the survey. Every time you look at a modern map, you are looking at the result of countless hours of people squinting through small telescopes."]},{"heading":"Two Tubes Are Better Than One: Binoculars","paragraphs":["Humans have two eyes, so it is natural to want two telescopes side by side. As you read in part 3, the Dutch government reportedly asked Hans Lipperhey to make two-eyed versions of his spyglass in 1608. For the next 250 years, though, most binoculars were simple Galilean designs: a convex lens at the front and a concave lens at the eye in each tube. They were short and gave an upright image, but they could only magnify a little and showed a narrow view.","In the 1800s, small Galilean binoculars became fashionable as opera glasses. In grand theatres in Paris, Vienna, London and New York, audiences in the upper balconies raised elegant little glasses, often decorated with mother-of-pearl or gold, to see the singers' faces. Some had a handle so they could be held up like a mask. Opera glasses still use the same design today, because they need only about 2 to 4 times magnification.","The big breakthrough came from an Italian engineer and surveyor named Ignazio Porro. In 1854 he patented a system that uses glass prisms instead of extra lenses to turn the image the right way up. Here is the trick. Light from the front lens enters a prism shaped like a triangle with a right angle. It bounces off two of the prism's inside faces, a bit like a ball bouncing off two walls of a corner, and comes back out going the opposite way, flipped over. A second prism set at right angles to the first does the same thing in the other direction. Together, the two prisms turn the upside-down, back-to-front image of a Keplerian telescope right way round.","The prisms do something else useful. Because the light zig-zags back and forth inside them, a long light path can fit inside a short body. That is why classic binoculars have their zig-zag shape, with the big front lenses set wider apart than the eyepieces, which also improves your sense of depth. It took several decades, and better optical glass made by Otto Schott and the scientist Ernst Abbe in Jena, Germany, before Porro's idea took off. In 1894 the Carl Zeiss company began selling modern prism binoculars, and they spread quickly.","Have you seen numbers like 7x50 or 10x42 printed on binoculars? The first number is the magnification: 7x means things look seven times closer. The second number is the width of each front lens in millimetres. Divide the second by the first, and you get the size of the little circle of light coming out of the eyepiece, called the exit pupil. For 7x50 binoculars it is about 7 millimetres, nicely matching a dark-adapted human pupil, which is why 7x50s were long the favourite of navies and stargazers alike.","Prism binoculars became essential for armies and navies in the World Wars, and for people who watch birds, ships, sports and wildlife. They are also one of the best first astronomy instruments. Through ordinary binoculars you can see Jupiter's four big moons, craters on the Moon and thousands of stars in the Milky Way, more than Galileo saw with his first telescope."]},{"heading":"Bigger Ideas: A Universe Without a Center","paragraphs":["Telescopes changed more than ships and maps. They changed how people thought about their place in everything. Before 1609, almost everyone in Europe was taught that Earth sat still at the center of the universe, with the Sun, Moon, planets and stars circling it. After Galileo's telescope showed moons going around Jupiter and the full set of phases of Venus (parts 4 and 5), that picture became harder and harder to defend.","Over the following century, the Sun-centered system spread from experts to ordinary readers. In 1686 the French writer Bernard de Fontenelle published a lively book called Conversations on the Plurality of Worlds, in which a philosopher explains astronomy to a curious noblewoman on walks in a garden at night. It became a bestseller across Europe and was translated into many languages. Ideas that had been dangerous in Galileo's time were becoming common knowledge.","Telescopes also kept making the universe bigger. Each improvement showed more stars, fainter nebulae and more detail. When Friedrich Bessel finally measured the distance to the star 61 Cygni in 1838 (part 8), people learned that even a nearby star is about 11 light-years away, around 100 trillion kilometres. Herschel's star counts (part 9) showed that the Sun is just one of a huge number of stars in a vast disc. Earth went from being the center of a small, cozy universe to being a small planet near an ordinary star in an enormous one.","Many people found this exciting rather than frightening. In the 1700s and 1800s, public lectures with telescopes, mechanical models of the solar system called orreries, and popular astronomy books drew big crowds. In cities around the world, street astronomers set up telescopes on corners and charged passers-by a small coin for a look at the Moon or Saturn. Looking through a telescope became something that ordinary people, not only scholars, could do."]},{"heading":"Backyard Astronomers and Homemade Telescopes","paragraphs":["In the early 1900s, a good telescope was still expensive. So some people decided to make their own, just as William Herschel had done. The most important leader of this movement was Russell W. Porter, an American explorer, architect and inventor who had been on expeditions to the Arctic. In 1920 he started teaching a class in mirror-making to a group of workers at a machine-tool company in Springfield, Vermont. They called themselves the Springfield Telescope Makers.","Making a telescope mirror at home sounds impossible, but Porter showed it could be done with simple tools. You take two round discs of glass, put wet grinding powder between them and rub one over the other, round and round, for hours. Slowly the top disc wears into a shallow hollow, the right shape for a mirror. Then you polish it with finer and finer powders and test it with a lamp and a razor blade, a simple test invented by the French scientist Léon Foucault. Finally, the glass gets a thin, shiny coating of metal. Done well, a homemade mirror can be as good as a professional one.","On a hilltop called Breezy Hill near Springfield, the club built a small pink clubhouse in 1923 and named the place Stellafane, from Latin words meaning 'shrine to the stars'. In 1926 they held their first meeting for amateur telescope makers. Except for a few breaks, the Stellafane Convention has been held every summer since, making it the longest-running astronomy convention in the United States. Porter also built unusual telescopes there, including the Porter Turret Telescope of 1930, where the observer sits inside a warm room while the telescope points at the sky outside.","The movement spread across America thanks to Albert Ingalls, an editor at the magazine Scientific American, who wrote articles about Porter's group and helped put together a famous how-to book called Amateur Telescope Making. Thousands of people, many of them teenagers, learned to grind their own mirrors. Porter himself later went to California to help design the giant 200-inch Palomar telescope, which you will meet in part 13, and his detailed cut-away drawings of it are famous.","Decades later, a very different person made big telescopes cheap for everyone. John Dobson was born in 1915 in Beijing, China, the son of missionary parents. In 1944 he joined a Hindu monastery of the Vedanta Society in San Francisco as a monk. There he started building telescopes from whatever he could find: glass from old ship portholes ground into mirrors, cardboard tubes meant for pouring concrete, plywood scraps and even plumbing parts. He was so keen to share the sky that, after he had to leave the monastery in 1967, he helped found the San Francisco Sidewalk Astronomers in 1968. They set up big telescopes on city sidewalks and invited anyone walking by to look at the Moon and planets, for free.","Dobson's real gift was a design. Instead of a complicated, expensive mount, he put his telescope tube in a simple wooden box that swung up and down and turned left and right on smooth pads, like a cannon. It was cheap, sturdy and easy to use. Today, telescopes of this type are called Dobsonians, and they are among the most popular telescopes in the world for anyone who wants a big mirror for not much money. Dobson kept showing people the sky until he died in 2014, aged 98.","Amateur astronomers are not just hobbyists. They still make real discoveries. On the night of 23 July 1995, two American amateurs, Alan Hale in New Mexico and Thomas Bopp in Arizona, independently spotted the same new comet. Bopp, who did not own a telescope, was looking through a homemade Dobsonian telescope, 44 centimetres across, that belonged to his friend Jim Stevens. Comet Hale-Bopp grew into one of the brightest comets of the twentieth century, and in 1997 millions of people around the world could see it with their own eyes. Amateurs also find exploding stars in distant galaxies, track asteroids and watch for changes on the planets.","From the captain's brass spyglass to the surveyor's theodolite, from opera glasses to a cardboard-tube Dobsonian on a city sidewalk, telescopes had spread into every corner of everyday life. Meanwhile, professional astronomers wanted something no backyard could hold: telescopes so big they needed their own buildings and their own mountains."]}],"deepDive":"Why was longitude so hard, and why did the Jupiter method fail at sea? Because Earth turns 15 degrees per hour, each 4 minutes of time error equals 1 degree of longitude. At the equator, 1 degree is about 111 kilometres, so a clock that is wrong by only 1 minute puts a ship about 28 kilometres off. The 1714 Longitude Act offered 10,000 pounds for a method accurate to within 1 degree and 20,000 pounds for within half a degree, which meant keeping time to within about 2 minutes after weeks at sea. Galileo's Jupiter-moon clock was accurate enough in principle, because the moons' eclipses happen at the same instant for every observer. The problem was practical. Seeing the moons needs magnification of at least about 20 to 30 times, and at that power a slight movement of the observer's head sweeps Jupiter right out of view; a ship's roll makes it hopeless. Jupiter is also invisible for weeks at a time when it is near the Sun in the sky. On land, the method worked very well. After Cassini's 1668 tables and Rømer's discovery that light takes time to cross the solar system (which slightly shifts eclipse times), Jupiter's moons became a standard tool for mapping coastlines and continents into the 1800s. At sea, the race was between Harrison's chronometers and the lunar distance method. Chronometers were more precise but expensive at first; lunar distances needed only a sextant, an almanac and lots of arithmetic. Most navies used both well into the 1800s. Historians also discuss the Nelson story. Several people at Copenhagen later described Nelson's joke about his blind eye, but accounts differ in wording, and some historians think Parker's signal was intended to be discretionary, meaning Nelson was allowed to ignore it if he judged it safe to keep fighting. Finally, a note on binocular numbers: a pair's exit pupil is the objective diameter divided by magnification. Young eyes in the dark open to about 7 millimetres, but the maximum pupil size shrinks with age, so many adults gain less from very large exit pupils than young people do.","funFact":"Comet Hale-Bopp, found partly through a friend's homemade backyard telescope, stayed visible to the naked eye for about 18 months, a record for any comet.","check":{"q":"Which Italian inventor patented the prism system used in classic binoculars in 1854?","a":"Ignazio Porro","wrong":["Galileo Galilei","Giovanni Cassini","Jesse Ramsden"]},"sources":[{"title":"History of longitude","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/History_of_longitude"},{"title":"Royal Observatory, Greenwich","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Royal_Observatory,_Greenwich"},{"title":"Ramsden theodolite","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Ramsden_theodolite"},{"title":"Binoculars","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Binoculars"},{"title":"Battle of Copenhagen (1801)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Battle_of_Copenhagen_(1801)"},{"title":"Stellafane","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Stellafane"},{"title":"John Dobson (amateur astronomer)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_Dobson_(amateur_astronomer)"},{"title":"Comet Hale-Bopp","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Comet_Hale%E2%80%93Bopp"}],"photos":[{"src":"img/deep/telescope/10-1.jpg","alt":"George Washington's brass and wood draw-tube field telescope and leather case, at the National Museum of American History.","file":"George Washington's field telescope, used during the Revolutionary War - National Museum of American History - DSC00167.jpg","url":"https://commons.wikimedia.org/wiki/File:George_Washington%27s_field_telescope,_used_during_the_Revolutionary_War_-_National_Museum_of_American_History_-_DSC00167.jpg","author":"Daderot","license":"CC0"},{"src":"img/deep/telescope/10-2.jpg","alt":"Flamsteed House at the Royal Observatory, Greenwich, with the red time ball that drops at 1 pm every day.","file":"London Royal Observatory with the time ball - panoramio.jpg","url":"https://commons.wikimedia.org/wiki/File:London_Royal_Observatory_with_the_time_ball_-_panoramio.jpg","author":"Nikolai Karaneschev","license":"CC BY 3.0"},{"src":"img/deep/telescope/10-3.jpg","alt":"Cutaway of Porro prism binoculars: light passes the big lens, zigzags through two prisms, then reaches the eyepiece.","file":"Porro binocular.jpg","url":"https://commons.wikimedia.org/wiki/File:Porro_binocular.jpg","author":"Tamasflex","license":"CC BY-SA 3.0"}],"words":4039},{"n":11,"title":"The Leviathan and the Great Refractors","when":"1845 – 1897","summary":"An Irish earl built a telescope so huge that it hung between two castle-sized stone walls, and with it he saw that some faraway clouds in space are shaped like whirlpools. Meanwhile, a French mathematician found a brand-new planet using only pencil, paper and gravity. In America, giant lens telescopes rose on mountaintops, until lenses simply could not grow any bigger.","sections":[{"heading":"A Giant Grows in an Irish Castle","paragraphs":["Picture a small town in the middle of Ireland in the early 1840s. Green fields, peat bogs, a river, and a grey stone castle. In the castle grounds, dozens of local men are building something nobody in the world has ever seen: a telescope tube as long as a city bus, made of wood held together with iron hoops, so wide that, according to a famous story, a church dean once walked through it holding an open umbrella. The town was called Parsonstown back then (today it is Birr), and the man in charge was William Parsons, the 3rd Earl of Rosse.","Lord Rosse, born in 1800, was a nobleman and member of Parliament, but at heart he was an engineer who loved machinery, metalwork and mathematics. When he inherited the family estate in 1841, he gained the money and land to try something enormous: the biggest light-collecting telescope on Earth, able to see deeper into the faint, misty patches of the night sky than anyone ever had. He aimed for a mirror 72 inches (about 1.83 meters) across, roughly the height of a grown man.","There was no factory anywhere that could make such a thing, so Rosse built his own. He trained workers from his estate, many of them farm laborers with no special schooling, to become metal casters, blacksmiths and mirror grinders. There were no glass mirrors yet for telescopes; instead the mirror had to be cast from speculum metal, a hard, shiny mix of mostly copper and tin. Speculum is brittle, a bit like a giant cookie made of metal. If it cools too fast, it cracks. If it cools unevenly, it warps.","Rosse had already learned a great deal by building an earlier reflector about 36 inches wide. For the 72-inch disk, his team melted metal in furnaces on the estate, poured it into a mold, and let the glowing disk cool slowly for weeks in a special oven. Not every casting worked, and it took several attempts to produce two good mirrors. Why two? Speculum tarnishes, and repolishing changes its shape and takes a long time, so one mirror could sit in the telescope while the other was being polished.","Each finished mirror was about 5 inches (13 cm) thick and weighed almost 3 tons, about as much as two cars. The wooden tube was around 54 feet (16.5 meters) long, and with the mirror inside it weighed about 12 tons. The design was Newtonian: light bounced off the big curved mirror at the bottom and back up to a small flat mirror near the top, which turned it sideways to the eyepiece. So the observer had to stand way up at the top end, on galleries high above the ground.","Something so heavy could not be swung around freely. Instead, Rosse built two huge stone walls, each several stories high, standing side by side in a north-south line, with the tube hanging in the gap between them. Its bottom end sat on a giant swivel joint. Chains and a winch raised or lowered it, and beams and gears let it swing a little east or west. So the telescope could follow an object for only about an hour as Earth's turning carried it past the gap between the walls. Observers had to wait for their target to drift into view, then work fast.","The telescope was first used in early 1845. People soon nicknamed it the Leviathan of Parsonstown, after a giant sea monster in the Bible. It was the largest telescope in the world from 1845 until 1917, when the 100-inch Hooker Telescope in California was finished. That is more than 70 years at the top!","The Leviathan was born at a hard moment. In 1845 a disease struck Ireland's potato crop, the main food of millions of poor families, and the Great Famine followed. About a million people died over the next several years and many more left the country. Lord Rosse turned much of his attention to helping people on his estate, and regular observing was delayed. While the Leviathan looked at the stars, the people around it were living through one of the saddest times in their country's history."]},{"heading":"The Whirlpool in the Dark","paragraphs":["Ever since telescopes were invented, astronomers had noticed small faint smudges in the sky that did not look like sharp points of starlight. They called them nebulae, from the Latin word for clouds or mist. In the 1700s the French comet hunter Charles Messier made a list of these fuzzy objects so he would not confuse them with comets. On 13 October 1773 he found one near the handle of the Big Dipper and listed it as number 51. Today we call it M51.","Through Messier's small telescope, M51 looked like a faint round glow. Through Herschel's larger instruments it looked a bit more detailed, but still like a ring or a blob. Then, in the spring of 1845, Lord Rosse pointed the Leviathan at it. With so much more light pouring into his eye, he could see something astonishing: the glow was not a plain blob at all. It had curving arms, wrapping around a bright center like water swirling down a drain, with a smaller companion glow at the end of one arm.","Rosse made a careful drawing of what he saw. His sketch of M51 is one of the most famous pictures in the history of astronomy, because it was the first time anyone had seen spiral structure in a nebula. Later observers nicknamed M51 the Whirlpool, and some even called it Rosse's Galaxy. Over the following years he and his assistants found spiral shapes in several other nebulae too, and Rosse suggested that their shapes must come from some kind of motion governed by the laws of physics, since a spiral looks like something that is spinning.","Here is the amazing part: nobody in 1845 knew what a spiral nebula actually was. A small swirl of gas inside our Milky Way, perhaps a new solar system being born? Or a whole separate collection of stars, unimaginably far away? There was no way yet to measure their distance, and the answer would take almost 80 more years, as we will see in Part 13. Today we know M51 is a galaxy about 31 million light-years away and roughly 77,000 light-years wide, not far from the size of our Milky Way. The light Rosse saw had left it long before there were any humans on Earth.","Lord Rosse made other famous drawings too. Even before the Leviathan was finished, he sketched a nebula in the constellation Taurus with his earlier 36-inch telescope. The drawing looked, to people at the time, a bit like a crab with legs, and the name stuck: we still call it the Crab Nebula. Rosse also claimed in 1845 that the great telescope broke the Orion Nebula up into separate stars. John Herschel, William Herschel's son, disagreed, and he was right to be doubtful; the Orion Nebula really is a cloud of glowing gas, as the next part of our story will show.","Using the Leviathan was hard work. Ireland's skies are cloudy and damp, so clear nights were precious, and the observer, high on wooden galleries in the cold, had to draw everything by hand because cameras could not yet capture faint nebulae. After the 3rd Earl died in 1867, his son, the 4th Earl, kept the telescope working. The astronomer J. L. E. Dreyer used it from 1874 to 1878 and later compiled the New General Catalogue, the NGC, a giant list of nebulae and star clusters whose numbers astronomers still use. Observations made at Birr with Lord Rosse's telescopes added more than 200 objects to it.","The Leviathan was used until about 1890. After the 4th Earl died in 1908 it was partly taken apart, and in 1914 one of its speculum mirrors went to the Science Museum in London. For decades only the stone walls and old tube remained, like the bones of a dinosaur. In the 1990s engineers rebuilt it from old drawings, finishing the structure in 1997 and adding a new aluminium mirror in 1999. Right next door, a modern radio telescope station called I-LOFAR, opened in 2017, now listens to the sky in a way Lord Rosse never imagined."]},{"heading":"A Planet Found with Pencil and Paper","paragraphs":["While Lord Rosse was building his giant, astronomers had a planet-sized mystery on their hands. In Part 9 we met William Herschel, who discovered Uranus in 1781. Once astronomers knew about Uranus, they went back and calculated exactly where it should be in the sky year after year, using Isaac Newton's law of gravity and the pull of the Sun, Jupiter and Saturn. But Uranus refused to behave. Sometimes it was a little ahead of where the math said it should be, and sometimes a little behind.","Two young mathematicians took up the challenge, without knowing about each other. In England, John Couch Adams, a student and then young fellow at Cambridge University, began working on the problem in the 1840s and by 1845 had an estimate of where the unknown planet might be. He tried to interest George Airy, the Astronomer Royal at Greenwich, but the search in England started slowly. When the Cambridge Observatory finally did look, under its director James Challis, it did not compare its observations quickly enough to notice the new planet.","In France, Urbain Le Verrier worked independently. Imagine working backwards from Uranus's small wobbles to the position of a planet nobody had ever seen, with no computer, only pages and pages of hand-written sums. Le Verrier did exactly that and published a predicted position in June 1846, then sent his detailed results, including an estimated mass and orbit, to someone he hoped would search quickly: Johann Gottfried Galle at the Berlin Observatory in Germany.","Galle received Le Verrier's letter on the morning of 23 September 1846. That same day he asked the observatory's director, Johann Franz Encke, for permission to search, and got it. That night Galle sat at the observatory's 9-inch refractor, a fine lens telescope made by the Munich workshop that Joseph von Fraunhofer, whom we met in Part 8, had made famous. A young student astronomer, Heinrich d'Arrest, eagerly asked to help.","d'Arrest had a clever idea: compare the sky with a brand-new, detailed star chart of exactly that area, called Hora XXI. Galle called out the stars he saw one by one, and d'Arrest checked each against the chart. Just after midnight, Galle described a faint star of about 8th magnitude. According to the famous account, d'Arrest exclaimed that that star was not on the map! It was the new planet, less than one degree, about two full-Moon widths, from Le Verrier's predicted spot. The next night they checked again: it had moved, just as a planet should.","The discovery was a sensation. For the first time, a planet had been found not by accident, as Uranus had been, but because mathematics said it must be there. It was one of the greatest triumphs of Newton's law of gravity. Le Verrier was hailed as the man who discovered a planet with the point of his pen.","Then came the quarrel. British astronomers, including Airy, pointed out that Adams had made a prediction earlier, and French scientists felt the British were trying to grab credit for a French discovery. The Royal Society gave its Copley Medal to Le Verrier in 1846 and to Adams in 1848. Adams himself graciously credited Le Verrier. Historians still discuss it: studies of old documents, including work by Nicholas Kollerstrom, suggest Adams's predictions were less certain than the traditional story said. Today most give the main credit to Le Verrier and Galle, while recognizing Adams's impressive independent work.","Even the name caused arguments. The French astronomer François Arago wanted to call the planet Le Verrier. Others objected, and in the end astronomers agreed on a name from mythology to match the other planets: Neptune, the Roman god of the sea, fitting for a deep blue world. Just 17 days after the planet's discovery, the English brewer and amateur astronomer William Lassell, observing with a homemade reflector, found its largest moon, Triton.","Neptune is about 4.5 billion kilometers from the Sun, about 30 times farther than Earth. One trip around the Sun takes it about 165 years, so it was only in 2011 that Neptune finished its first full orbit since its discovery. And here is a twist: Galileo had actually seen Neptune through his telescope in 1612 and 1613, while watching Jupiter's moons, but he thought it was just a faint background star. The telescope Galle used to find Neptune still exists and is on display at the Deutsches Museum in Munich."]},{"heading":"Silver on Glass: Goodbye, Heavy Metal","paragraphs":["The Leviathan showed both the power and the problem of metal mirrors. Speculum was heavy, it cracked easily while cooling, and it tarnished. Even freshly polished, it reflected only around two-thirds of the light hitting it, and less as it grew dull. Re-polishing meant grinding away a thin layer of the surface, which could ruin the mirror's exact curve, so it had to be reshaped and tested all over again.","The answer came from chemistry. In 1835 the German chemist Justus von Liebig found a way to make a thin, even coat of silver form on glass using a chemical reaction in a liquid bath. He improved the method in 1856, and soon it was used to make household mirrors better and more cheaply. Two clever opticians saw that this could change telescopes forever.","In 1856 and 1857, the German optician Carl August von Steinheil and the French physicist Léon Foucault each made telescope mirrors in a new way. First, they ground and polished a disk of glass into exactly the right curved shape. Then they coated just the front surface with an ultra-thin layer of silver, much thinner than a sheet of paper. The light bounced off the silver without ever going into the glass. These were the first optical-quality front-surface glass mirrors.","Why was this so much better? Glass is far lighter than speculum, so mirrors could grow bigger, and it can be polished to a more accurate shape that it holds well. Fresh silver reflects much more light than speculum, so the same size mirror shows fainter things. Best of all, when the silver tarnished, you simply removed it with chemicals and put on a new coat, without touching the precious curved glass.","Foucault is also famous for hanging a long pendulum in the Panthéon in Paris in 1851, whose slowly turning swing showed that Earth spins. For telescopes, his key gift came in 1858: a simple way to test a mirror's shape. You shine a tiny point of light at the mirror and, where its reflection focuses, slide a knife edge across the beam while looking at the mirror. A perfect mirror darkens evenly; bumps and dips show up as light and shadow, like a landscape lit at sunset. Before this, mirror testing was largely trial and error. Mirror makers still use versions of the Foucault test, and the basic idea of a glass mirror with a whisper-thin metal skin (today usually aluminium, a method John Strong developed around 1930) is used in almost every big telescope."]},{"heading":"The Painter Who Became a Lens Maker","paragraphs":["While mirrors were improving in Europe, the best big lenses of the late 1800s came from a surprising place: a workshop in Cambridgeport, Massachusetts, run by a former portrait painter. Alvan Clark, born in 1804 in Ashfield, Massachusetts, earned his living painting portraits and making engravings, but he was deeply curious about telescopes. By about age 40 he had taught himself to grind and polish lenses, and he turned out to have an extraordinary gift for it. With his sons Alvan Graham Clark and George Bassett Clark he founded the firm of Alvan Clark & Sons.","The Clarks did not make their own raw glass. Pouring huge, flawless disks of optical glass was a specialty of a few glassworks in England and France, and the Clarks bought their blanks there. What they did was the delicate final shaping, called figuring. A large achromatic lens, as you remember from Part 8, is really two lenses, one of crown glass and one of flint glass, working together to cancel out rainbow fringes. Each of their four surfaces must be curved almost perfectly. The Clarks were famous for figuring by hand and eye, rubbing the glass with polishing tools and their own thumbs, testing it on a star, then going back to adjust a tiny spot by a fraction of a wavelength of light.","To test their lenses, the Clarks looked at double stars, pairs so close together that only a very good telescope can split them, and Alvan Clark discovered several new ones himself. In 1862, Alvan Graham Clark was testing a new 18.5-inch lens when he spotted a very faint point of light right next to Sirius, the brightest star in the night sky. Astronomers had predicted from Sirius's wobbling motion that it had a hidden companion. This companion, Sirius B, is a white dwarf, the tiny, super-dense leftover core of a dead star.","Clark lenses soon went into observatories across America and beyond. A 26-inch Clark refractor was installed at the U.S. Naval Observatory in Washington, and in 1877 the astronomer Asaph Hall used it to discover Phobos and Deimos, the two small moons of Mars. Time after time, the Clarks made the largest refracting telescope lens in the world, then beat their own record. Their two greatest lenses, 36 inches and 40 inches across, are the stars of the next section. Today a crater on the Moon and a crater on Mars are named after Alvan Clark."]},{"heading":"Monuments on the Mountains: Lick and Yerkes","paragraphs":["James Lick was a carpenter and piano maker who became one of the richest men in California by buying land in San Francisco before the city boomed. When he grew old, he wanted to leave something that would make him remembered. He is said to have considered building giant statues or even a pyramid, but friends steered him toward science. In the end he left 700,000 dollars, a huge fortune in the 1870s, to build the most powerful telescope in the world.","The site chosen was the summit of Mount Hamilton, just east of San Jose, at about 1,283 meters (4,209 feet), above much of the valley's haze. To get there, Santa Clara County built a winding road, finished in 1876, that never gets steeper than a 6.5 percent slope, so horse-drawn wagons could haul up heavy parts. It is still in use today as California State Route 130.","Alvan Clark & Sons were asked to make the great lens in 1880; getting flawless glass disks that big from the glassmakers took years and many failed attempts. The finished lens, 36 inches (91 cm) across, arrived in December 1886. James Lick had died in 1876, and in 1887 his body was placed in a tomb inside the foundation of the telescope's pier, the massive column right under the instrument. A brass plaque there says, simply, that here lies the body of James Lick.","The Great Lick Refractor saw first light on 3 January 1888. In May of that year the University of California took over the observatory, and it became the first permanently staffed observatory on a mountaintop anywhere in the world. Astronomers and their families lived on the summit year-round. One of them, the brilliant observer Edward Emerson Barnard, used the 36-inch in 1892 to discover Amalthea, a small moon of Jupiter. It was the first new moon of Jupiter found since Galileo spotted the big four in 1610, almost three centuries earlier.","The Lick refractor's record lasted less than ten years. A young astronomer from Chicago named George Ellery Hale, who would become the greatest telescope builder of the next century, wanted to create an even bigger one. As it happened, Alvan Clark & Sons had two giant 40-inch glass disks on their hands, originally ordered for an observatory planned in Southern California whose money had run out. Hale persuaded Charles Tyson Yerkes, a rich Chicago businessman who ran the city's streetcar lines, to pay for a telescope built around them.","The observatory, run by the University of Chicago, was built at Williams Bay, Wisconsin, on the shore of Lake Geneva. Before installation, the telescope's enormous mounting and tube were shown off at the 1893 World's Columbian Exposition in Chicago. The lens, 40 inches (about 1.02 meters) across, weighs about 225 kilograms, and its focal length is about 19.3 meters. To let astronomers reach the eyepiece, the dome's floor was built as a giant elevator that rose and fell. In 1897, shortly before the opening, the floor's supports broke and it crashed down, luckily when no one was on it.","Yerkes Observatory was dedicated on 21 October 1897. Its 40-inch refractor became, and still is, the largest refracting telescope ever successfully used for astronomy. Albert Einstein toured it in 1921, Edwin Hubble did his graduate work there, and the great astrophysicist Subrahmanyan Chandrasekhar worked there for many years. The observatory closed in 2018, but a nonprofit group took it over in 2020, and since 2022 visitors can again stand under the great tube, which is being restored.","One important warning: Yerkes is the biggest refractor, not the biggest telescope. As we will see right away, mirror telescopes had already been built much larger, and they would soon leave the lens telescopes far behind."]},{"heading":"Why Lenses Stopped Growing","paragraphs":["If the 40-inch was so wonderful, why did nobody build a 60-inch or 100-inch lens? People did try to go a little bigger. For the Paris World's Fair of 1900, a giant refractor with a lens about 1.25 meters (49 inches) across was built, with a tube so long it had to lie flat while a big moving mirror fed it light. It was an exhibition wonder, but it was never used for serious research and was taken apart after the fair. The real lesson was clear: lens telescopes had reached their limit, for several reasons.","The first problem is gravity. A lens must let light pass through, so you can only hold it by its edge, like a dinner plate held by its rim. As the telescope tilts, the middle of a big, heavy lens sags very slightly. The sag is far too small to see, but optical surfaces must be accurate to a tiny fraction of a wavelength of light, so a sagging lens blurs the image. Experts reckon the practical limit for a refractor lens is about 1 meter, just the size of the Yerkes lens.","The second problem is the glass itself. All the light must travel through the full thickness of the lens, and glass absorbs some of it, especially the blue and ultraviolet light that old photographic plates were most sensitive to. A few percent more is reflected away at every air-glass surface. Every tiny bubble or streak inside spoils the image, and making a huge, flawless disk of two kinds of glass was so difficult that one failure could cost years. Even then, achromatic lenses still leave a faint purple halo of leftover color, worse in big lenses, and their long tubes need huge, costly domes.","Mirrors avoid almost all of these troubles. Light never passes through a mirror, only bounces off its front surface, so the glass inside does not need to be perfectly clear and its color does not matter. Reflection treats all colors the same, so there is no rainbow fringing at all. Only one surface needs to be shaped perfectly, instead of four. And because nobody needs to see through the back of a mirror, it can be supported from behind across its whole surface, so it does not sag. That is why, after Yerkes, every record-breaking optical telescope has been a reflector.","Great refractors are still treasured for teaching, public viewing and special jobs, but for gathering the faintest light from deep space the future belonged to mirrors. And even the biggest eye forgets what it sees, so astronomers were about to hand the job to something that never blinks: the camera."]}],"deepDive":"Two scientific stories in this part are worth a closer look. The first is the Neptune prediction. Le Verrier and Adams both solved what mathematicians call an inverse perturbation problem: instead of starting with planets and computing how they tug on one another, they started from the tugs (the small errors in Uranus's position) and worked backwards to the planet causing them. Both assumed, partly guided by the old Titius-Bode pattern of planetary spacing, that the new planet lay roughly twice as far from the Sun as Saturn, near 38 astronomical units. In fact Neptune orbits at about 30. Their predicted orbits were therefore wrong in size and period, yet the predicted direction in the sky in 1846 was close, because over the few decades of good observations the effect of a closer, lighter planet and a farther, heavier one looked similar. Some historians call this a lucky coincidence of timing; others stress that the method was sound and the direction was the part that mattered for finding it. The credit debate has also shifted. Papers rediscovered in the late 1990s, studied by Nicholas Kollerstrom and others, suggest Adams's predictions varied quite a bit and were not communicated as firm results, which strengthens Le Verrier's priority. The second story is the race between lenses and mirrors, which comes down to numbers. Light grasp scales with area, so the Leviathan's 72-inch mirror had about (72/40)^2, or 3.2 times the area of the Yerkes 40-inch lens. But speculum reflected only roughly 60 to 65 percent of visible light, while a big achromatic lens passes most of the light that enters it, so in practice the gap was smaller than the raw area suggests. The Leviathan also suffered from Irish weather, the stiff limits of its walls, and the difficulty of keeping a 3-ton metal mirror in perfect shape as temperatures changed. The refractors, meanwhile, delivered steady, sharp images, which is why astronomers measuring double stars and planets loved them. What tipped the balance for good was silvered glass, which removed speculum's weakness, plus the fact that a mirror can be supported across its whole back. That opened a path from 60 inches (1908) to 100 inches (1917) to 200 inches (1948), and eventually to the 8- and 10-meter mirrors of today.","funFact":"James Lick, who paid for the Lick Observatory, is buried inside the foundation of the 36-inch telescope's pier, so the great refractor has been resting on his tomb since 1887.","check":{"q":"What did Lord Rosse discover when he looked at the nebula M51 through the Leviathan in 1845?","a":"It had a spiral shape, like a whirlpool","wrong":["It was a new planet beyond Uranus","It had a ring like Saturn","It was a comet heading toward Earth"]},"sources":[{"title":"Leviathan of Parsonstown","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Leviathan_of_Parsonstown"},{"title":"Whirlpool Galaxy","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Whirlpool_Galaxy"},{"title":"Discovery of Neptune","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Discovery_of_Neptune"},{"title":"Neptune: Facts","publisher":"NASA Science","url":"https://science.nasa.gov/neptune/facts/"},{"title":"Silvering","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Silvering"},{"title":"Lick Observatory","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Lick_Observatory"},{"title":"Yerkes Observatory","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Yerkes_Observatory"},{"title":"Crab Nebula","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Crab_Nebula"}],"photos":[{"src":"img/deep/telescope/11-1.jpg","alt":"Lithograph of Lord Rosse's Great Telescope, the Leviathan, between its stone walls at Birr Castle, Ireland, as its giant mirror arrives","file":"Astronomy; a large refracting telescope, at Birr Castle, Ire Wellcome V0025755.jpg","url":"https://commons.wikimedia.org/wiki/File:Astronomy;_a_large_refracting_telescope,_at_Birr_Castle,_Ire_Wellcome_V0025755.jpg","author":"Wellcome Collection","license":"CC BY 4.0"},{"src":"img/deep/telescope/11-2.jpg","alt":"Lord Rosse's 1845 sketch of the Whirlpool Galaxy (M51), the first time anyone saw a spiral shape in space","file":"M51Sketch.jpg","url":"https://commons.wikimedia.org/wiki/File:M51Sketch.jpg","author":"William Parsons, 3rd Earl of Rosse (Lord Rosse)","license":"Public domain"},{"src":"img/deep/telescope/11-3.jpg","alt":"The 40-inch Great Refractor, the largest lens telescope ever used, inside its dome at Yerkes Observatory, Wisconsin","file":"Yerkes 40 inch Refractor Telescope-2006.jpg","url":"https://commons.wikimedia.org/wiki/File:Yerkes_40_inch_Refractor_Telescope-2006.jpg","author":"user Kb9vrg","license":"Public domain"}],"words":4396},{"n":12,"title":"Cameras and Rainbows: Photography and Spectroscopy","when":"1840 – 1925","summary":"Astronomers learned to point cameras through telescopes, and the cameras could soak up starlight for hours and show things no eye had ever seen. They also learned to split starlight into rainbows, and the dark and bright lines in those rainbows told them what stars are made of and how fast they move. A team of women at Harvard sorted hundreds of thousands of stars and found a ruler for measuring the universe.","sections":[{"heading":"Teaching the Telescope to Remember","paragraphs":["For more than 200 years after Galileo, every discovery made with a telescope had to pass through one tiny, imperfect instrument: the human eye. The astronomer looked, then turned to a notebook and drew what he or she remembered, often by the glow of a dim lamp, with cold fingers, at three in the morning. Two observers looking at the same nebula could draw it quite differently. There was no way to check later. The eye saw, and then the image was gone.","In 1839 the Frenchman Louis Daguerre announced the daguerreotype, the first practical photograph: an image captured on a silver-coated copper plate made sensitive to light with chemicals. Almost at once, people wondered whether such a plate could capture the sky. Daguerre himself tried to photograph the Moon in 1839, but the Moon moved across the sky during the long exposure and the picture came out as a blur.","The first real success came from New York. John William Draper, born in 1811 in St Helens, England, had moved to America and become a professor of chemistry at New York University. He was one of the first people in America to experiment with photography, and around 1840 he photographed his sister, Dorothy Catherine Draper, in one of the earliest surviving portraits of a person. In March 1840 he turned his camera on the Moon. Using a reflecting telescope about 5 inches across and an exposure of about 20 minutes, he captured a small, fuzzy, but genuine image of the lunar surface, one of the very first astronomical photographs ever made.","Draper did not stop there. In 1843 he made daguerreotypes of the Sun's spectrum, the band of colors you get by spreading sunlight out, and his plates recorded lines beyond the ends of the visible colors, in infrared and ultraviolet light that eyes cannot see. That was a hint of the future: cameras could record kinds of light that people are blind to.","Stars were harder than the Moon, because a star is so much fainter. In 1850, at Harvard College Observatory in Cambridge, Massachusetts, William Cranch Bond and the photographer John Adams Whipple used Harvard's 15-inch Great Refractor to take the first daguerreotype of a star: Vega, one of the brightest stars in the summer sky. It was just a tiny dot, but it proved the idea worked."]},{"heading":"Hours of Starlight in One Picture","paragraphs":["Why is a camera so much better than an eye for faint things? Your eye works like a video camera that refreshes itself many times a second. It collects light for only about a tenth of a second, then starts over. If very little light arrives in that tiny moment, you see nothing, no matter how long you stare. A photographic plate is different. It keeps adding up every bit of light that falls on it for as long as the shutter stays open. Leave it open for an hour and it collects about 36,000 times as much light as your eye gathers in a tenth of a second. A smudge too dim for any human to see slowly builds up into a clear picture.","There was a catch. Early wet photographic plates had to be coated, exposed and developed within minutes, before the chemicals dried, which made long exposures almost impossible. In the 1870s and 1880s, dry plates arrived: glass sheets coated with a light-sensitive gelatin layer that stayed sensitive for a long time and could be exposed for hours. At the same time, telescope makers improved clock drives, motors that slowly turned the telescope to follow the stars as Earth rotated. Even so, astronomers had to sit at the telescope all through a long exposure, watching a guide star through a separate eyepiece and making tiny corrections by hand to keep the picture sharp.","One of the great pioneers was Henry Draper, John William Draper's son. Henry was a doctor and a professor of medicine, but his real passion was astronomy, and he built a private observatory at his family's country home at Hastings-on-Hudson, New York. In 1872 he photographed the spectrum of a star showing its dark absorption lines, one of the first such pictures. On 30 September 1880, using an 11-inch Clark refractor and an exposure of about 50 minutes, he became the first person to photograph the Orion Nebula, the glowing cloud in the sword of Orion where new stars are being born.","Henry Draper died suddenly of an illness in 1882, at only 45. His wife, Mary Anna Palmer Draper, who had worked alongside him, wanted his work to continue. She gave money to Harvard College Observatory to photograph and classify the spectra of stars in his memory. That gift led to the famous Henry Draper Catalogue, which we will meet later in this part, and many stars are still known by their HD numbers.","In 1883 the English amateur astronomer Andrew Ainslie Common took even longer exposures of the Orion Nebula with a 36-inch reflector, and for the first time a photograph showed stars too faint for the human eye to see through the same telescope. From then on, the camera, not the eye, was the astronomer's most powerful tool for faint objects.","Photographs had another superpower: they were permanent records. Astronomers could measure them carefully by day, compare plates of the same patch of sky taken years apart, and spot anything that had moved or changed brightness, like asteroids, comets and variable stars. In 1887 astronomers from many countries met in Paris and launched the Carte du Ciel, a plan for 18 observatories around the world to photograph the entire sky. It was so huge that it was never fully finished, but it showed how photography had turned astronomy into a science of careful, shareable measurement."]},{"heading":"Barcodes of Light","paragraphs":["Cameras showed what objects looked like. The other great invention of this period told astronomers what they were made of. To understand it, we need to go back to rainbows.","Isaac Newton had shown in the 1660s that a glass prism spreads white sunlight into a band of colors, which he called a spectrum. In 1802 the English scientist William Hyde Wollaston looked more carefully and noticed a few dark gaps in the Sun's spectrum. Then, as we saw in Part 8, Joseph von Fraunhofer used superb prisms and a small telescope to map hundreds of these dark lines in 1814. He labeled the strongest ones with letters, such as the D lines in the yellow. But nobody knew what the lines meant.","In 1835 the French philosopher Auguste Comte wrote that some things would forever be impossible to know, and one of his examples was the chemical makeup of the stars. How could anyone ever take a sample of a star? Within about 25 years, he was proven wrong.","The answer came from Heidelberg, Germany, where the chemist Robert Bunsen and the physicist Gustav Kirchhoff worked together in the late 1850s. Bunsen had helped develop a gas burner, now called the Bunsen burner, whose flame is hot and almost colorless. When a pinch of a chemical was held in that flame, it glowed with its own color: sodium bright yellow, potassium violet, copper green. Kirchhoff suggested sending that colored light through a prism. Together they built a spectroscope, a prism plus small telescopes for viewing the spread-out light.","What they saw was amazing. Each glowing element produced not a full rainbow but a few sharp, bright lines of particular colors, always in exactly the same places. Sodium, for example, always made a close pair of yellow lines. Every element had its own pattern, like a barcode at the supermarket or a fingerprint. And sodium's yellow pair sat in exactly the same spot as Fraunhofer's dark D lines in sunlight.","In 1859 Kirchhoff worked out why. A hot, dense object, like a glowing solid or the deep layers of the Sun, gives off a smooth rainbow with every color. A thin, hot gas gives off only its own bright lines. And when the smooth rainbow shines through a cooler, thinner gas, that gas soaks up exactly the same colors it would give off when hot, leaving dark lines. So the dark D lines in sunlight meant there must be sodium in the Sun's outer layers. In one stroke, Kirchhoff and Bunsen had done what Comte said could never be done: they had found out what the Sun is made of from 150 million kilometers away. They soon matched other dark lines with iron, calcium, magnesium and more.","The spectroscope worked on Earth too. In 1860 and 1861, by examining mineral water and rocks, Bunsen and Kirchhoff found lines that matched no known element, and so discovered two new elements: cesium, named from the Latin for sky-blue after its blue lines, and rubidium, named from the Latin for deep red. Nobody yet understood why atoms made these lines. That explanation, involving electrons jumping between energy levels inside atoms, came only in 1913. But astronomers did not need to know why. They now had a way to take a chemical sample of anything that shines."]},{"heading":"Glowing Gas and an Element from the Sun","paragraphs":["In south London, at 90 Upper Tulse Hill, a wealthy silk merchant's son named William Huggins built a private observatory in his garden. When he heard about Kirchhoff's discovery, he later recalled that it was like finding water in a dry land. He teamed up with his neighbor, the chemist William Allen Miller, and attached a spectroscope to his telescope to study the stars. They found that stars have dark lines like the Sun's, showing familiar elements such as iron, sodium and hydrogen. The stars, it turned out, are made of the same kinds of stuff as the Sun and the Earth.","Then, on the evening of 29 August 1864, Huggins pointed his spectroscope at a small, bluish-green planetary nebula in the constellation Draco, known today as NGC 6543, the Cat's Eye Nebula. He expected to see a rainbow crossed by dark lines, the signature of a crowd of stars. Instead he saw just a single bright line, and then a couple of fainter ones, with darkness between them. A smooth rainbow means stars; a few bright lines mean a thin, glowing gas. This nebula was not a swarm of distant stars at all. It was a cloud of hot gas.","That settled an old argument. Some nebulae, like the Orion Nebula, which Lord Rosse had hoped was made of stars, showed bright gas lines. Others, like the Andromeda nebula, showed starlike spectra. So there were at least two quite different kinds of fuzzy objects in the sky. Huggins and Miller shared the Royal Astronomical Society's Gold Medal in 1867 for their work.","In 1875 William married Margaret Lindsay Murray, a young woman from Dublin, born in 1848, who had loved astronomy since childhood and was skilled at drawing and photography. She became his full scientific partner. Margaret pushed the observatory to use the new dry photographic plates to record spectra, which was far more accurate than squinting through an eyepiece. Together they published a grand atlas of star spectra in 1899. William later served as President of the Royal Society from 1900 to 1905.","Meanwhile, the Sun had a surprise of its own. On 18 August 1868, a total eclipse of the Sun passed over India. At Guntur, the French astronomer Jules Janssen watched the glowing gas around the hidden Sun through a spectroscope and saw a bright yellow line, close to, but not quite matching, sodium's famous yellow pair. Later in 1868, the English astronomer Norman Lockyer studied the same line, which he named D3, and found he could see it even without an eclipse. Lockyer concluded that it came from an element unknown on Earth. He named it helium, after helios, the Greek word for the Sun.","Many chemists doubted him. An element that existed only in the Sun? But in 1895 the Scottish chemist William Ramsay released a gas from a uranium mineral called cleveite, and its spectrum showed the very same yellow line. In the same year, Per Teodor Cleve and Abraham Langlet in Sweden found it independently. Helium is the most famous example of an element discovered in space before it was found on Earth. Today it fills party balloons and cools the giant magnets in hospital MRI scanners, and we now know it is the second most common element in the whole universe."]},{"heading":"Stretching Light: The Doppler Shift","paragraphs":["Spectral lines held one more secret: they could reveal motion. You have probably heard this effect with sound. When an ambulance races toward you, its siren sounds higher; the moment it passes and speeds away, the pitch drops. As the ambulance approaches, each sound wave is sent out a little closer to the one before, so the waves are squeezed together and the pitch is higher. As it moves away, the waves are stretched out and the pitch is lower. The Austrian physicist Christian Doppler described this kind of effect in 1842, and it is named after him.","Light is a wave too. If a star is moving away from us, its light waves get stretched to longer wavelengths, shifting toward the red end of the rainbow. This is called a redshift. If a star is coming toward us, its light is squeezed toward the blue end, a blueshift. In 1848 the French physicist Hippolyte Fizeau suggested that astronomers could use the shift of spectral lines to measure stars' motions.","The trick is to have something to compare against. Hydrogen, sodium or iron in a laboratory always make their lines at exactly known wavelengths. If the same pattern of lines in a star's spectrum is shifted a little to the red, the star is moving away; the bigger the shift, the faster. Like a barcode slid along a ruler, the whole pattern moves together, so astronomers can be sure which element they are looking at. In 1868 Huggins measured a redshift in the spectrum of Sirius and used it to estimate the star's speed along our line of sight. It was a fiendishly difficult measurement, because even fast-moving stars shift their lines by only a tiny amount.","Photography made such measurements far more accurate, and the Doppler shift became one of the most powerful tools in astronomy. It revealed pairs of stars too close together to see separately, because the lines in their combined light shifted back and forth as the two stars circled each other. It measured how fast stars, gas clouds and, later, whole galaxies were moving, and, as we will see at the end of this part, it led to one of the biggest surprises in the history of science."]},{"heading":"The Women Who Read the Sky","paragraphs":["At Harvard College Observatory, the director Edward Pickering faced a mountain of glass. Telescopes at Harvard and at its station in Peru were photographing the sky night after night, often with a thin prism in front of the lens so that every star on the plate appeared as a tiny smeared-out spectrum. Hundreds of thousands of plates would pile up over the years. Someone had to examine each tiny spectrum with a magnifying glass, measure star positions and brightness, and do endless calculations. In those days a computer was not a machine; it was a person who computed.","Pickering hired women for this work, more than 80 over the years. One reason, sadly, was that women could be paid much less than men, usually about 25 to 50 cents an hour, similar to unskilled workers. Women were also mostly shut out of university science jobs at the time, so many brilliant, highly educated women took these posts. The group became known as the Harvard computers, and they changed astronomy.","One of the first was Williamina Fleming. Born in Dundee, Scotland, in 1857, she came to Boston in 1878 and, after her marriage fell apart, worked as a maid in Pickering's house. Pickering gave her part-time work at the observatory in 1879 and a full job in 1881. She went on to do most of the classifications for the first Henry Draper Catalogue, published in 1890, which listed more than 10,000 stars. She discovered 59 gaseous nebulae, more than 310 variable stars and 10 novae, and in 1888 she found the dark Horsehead Nebula on a photographic plate. In 1898 she became Curator of Astronomical Photographs, the first woman to hold the post.","Annie Jump Cannon, born in 1863 in Dover, Delaware, studied physics and astronomy at Wellesley College. An illness, scarlet fever, left her nearly deaf, but it did not slow her down. She joined Harvard in 1896 and became the fastest and most accurate star classifier who ever lived, able to sort about three stars a minute just by glancing at their spectra. Building on earlier schemes by Fleming and her colleague Antonia Maury, she arranged stars into the classes O, B, A, F, G, K and M. Students still remember the order with the rhyme Oh Be A Fine Girl, or Guy, Kiss Me.","We now know the letters line up by temperature. O stars are the hottest, blazing blue-white at tens of thousands of degrees. M stars are the coolest, glowing a dull red. Our Sun is a yellowish G star. In 1922 the International Astronomical Union adopted Cannon's system for the whole world. Over her lifetime she classified about 350,000 stars, more than anyone in history, and her work filled the giant Henry Draper Catalogue, published from 1918 to 1924. In 1925 she became the first woman to receive an honorary doctorate from the University of Oxford."]},{"heading":"Leavitt's Ruler for the Universe","paragraphs":["Henrietta Swan Leavitt was born in 1868 in Lancaster, Massachusetts. She studied at what would become Radcliffe College, and an illness gradually left her deaf. Pickering hired her in 1902 to measure the brightness of stars on photographic plates. Her special task was finding variable stars, stars whose brightness rises and falls. She would lay a plate of the same patch of sky taken on one night over a plate from another night, and hunt for any star that had changed.","Her hunting ground was the Magellanic Clouds, two misty patches of stars visible only from the Southern Hemisphere, photographed from Harvard's station in Peru. Leavitt found 1,777 variable stars in them, publishing her list in 1908. Among them were Cepheids, a type named after the star Delta Cephei. A Cepheid swells and shrinks in a steady rhythm, getting brighter and dimmer over a regular period of days or weeks.","Leavitt noticed something remarkable. In the Small Magellanic Cloud, the Cepheids that were brighter took longer to complete their cycle. In 1912 she published a study of 25 of these stars, showing a clear rule: the longer the period, the brighter the star. It came out as a Harvard circular under Pickering's name, though it stated that Leavitt had prepared it.","Why was this so important? Because all the stars in the Small Magellanic Cloud are at roughly the same distance from us, like a crowd of people standing together in a distant field. So any difference in how bright they look must come from real differences in how bright they truly are, not from some being nearer. Her rule meant that if you timed a Cepheid's rhythm, you would know its true brightness. Compare that with how bright it looks from Earth, and you can work out how far away it is, just as you could judge the distance of a lamp if you knew its wattage. A year later, the Danish astronomer Ejnar Hertzsprung used nearby stars to calibrate the scale. Leavitt had handed astronomers a measuring tape that could stretch across the universe.","Leavitt died of cancer in December 1921, at 53, before anyone used her ruler for its greatest triumph. In 1924 a Swedish mathematician, Gösta Mittag-Leffler, wrote to Harvard hoping to nominate her for a Nobel Prize, not knowing she had died. Nobel Prizes are not given after death. Edwin Hubble, whose most famous discoveries depended on her work, later said she deserved one."]},{"heading":"What Stars Are Made Of, and Which Way Galaxies Go","paragraphs":["Cecilia Payne was born in 1900 in Wendover, England. She studied at Cambridge University, which at that time did not give degrees to women, no matter how well they did. Hearing that America offered more chances, she went to Harvard in 1923 to work under its new director, Harlow Shapley. For her doctorate, earned through Radcliffe College because Harvard did not then grant doctorates to women, she studied the spectra in Harvard's huge plate collection.","Using new physics about how hot atoms behave, Payne worked out that the strength of a star's lines depends mostly on its temperature, not just on how much of each element it contains. When she corrected for temperature, she reached a startling result in her 1925 thesis: stars are made overwhelmingly of hydrogen and helium, the two lightest elements, while the iron, calcium and other elements that seemed so common are only a tiny sprinkling. Most scientists then believed stars had about the same mix of elements as Earth. The leading astronomer Henry Norris Russell persuaded her to describe her result as probably not real. About four years later, Russell reached the same conclusion himself, and for years he often got the credit. The astronomer Otto Struve later called Payne's work the most brilliant PhD thesis ever written in astronomy. She went on to become, in 1956, the first woman promoted to full professor from within Harvard's Faculty of Arts and Sciences.","Far away in Flagstaff, Arizona, another quiet spectroscope expert was making a different discovery. Vesto Slipher worked at Lowell Observatory, founded by Percival Lowell. Starting in 1912, he took spectra of the faint spiral nebulae, the same kind of whirlpools Lord Rosse had sketched. Their light was so dim that a single spectrum needed exposures over several nights. His first result was for the Andromeda nebula: its lines were shifted toward the blue, meaning it was rushing toward us at about 300 kilometers per second, far faster than any star then known.","Slipher kept going. By 1917 he had measured 25 spiral nebulae, and all but three were redshifted, racing away from us, some at hundreds of kilometers per second. Such speeds seemed far too great for objects held by the Milky Way's gravity. Were the spirals separate star systems, flying apart? Slipher had the speeds, and Leavitt had built the ruler for distances. What was missing was a telescope big enough to find Cepheids in the spirals and put the two together."]}],"deepDive":"Why do elements make lines at all, and how precise were these measurements? Each kind of atom has electrons that can sit only at certain energy levels, like rungs on a ladder. When an electron drops from a higher rung to a lower one, the atom gives off light with exactly the energy of that gap, which means one exact wavelength. When an electron absorbs light of exactly that energy, it jumps up. That is why a gas emits and absorbs the same set of wavelengths, as Kirchhoff found, though the ladder picture came only with Niels Bohr's model in 1913. Hydrogen's red line, called H-alpha, sits at about 656.3 nanometers. The Doppler shift for speeds much less than light is simple: the fractional change in wavelength equals the speed divided by the speed of light (about 300,000 km/s). Slipher's Andromeda result of about 300 km/s is one-thousandth of light speed, so H-alpha would shift by only about 0.66 nanometers, roughly one-thousandth of the way across the visible spectrum. Measuring that on a tiny, faint smear of light on a glass plate, after many hours of exposure, was a triumph of patience. Payne's achievement rested on new theory from the Indian physicist Meghnad Saha, whose 1920 ionization equation showed how temperature controls which atoms are ionized and therefore which lines appear. Many spectral differences between stars that looked like differences in composition were really differences in temperature. Historians now point to her thesis as the moment astronomers learned that hydrogen dominates the cosmos, and to Russell's reaction as an example of how the scientific establishment can resist a correct result from a young outsider. Similar debates surround the Harvard computers. Pickering is praised for giving women a path into astronomy at a time when universities shut them out, and criticized because that path was poorly paid and the work was often published under his name. Cannon, Leavitt, Fleming, Maury and Payne are now widely recognized as major scientists, not just assistants, and the Henry Draper Catalogue designations they created are still used for hundreds of thousands of stars.","funFact":"Helium was discovered in the Sun's spectrum in 1868, 27 years before chemists found it on Earth, and it is named after helios, the Greek word for the Sun.","check":{"q":"What did Henrietta Swan Leavitt discover about Cepheid variable stars in 1912?","a":"Brighter Cepheids take longer to pulse, so their period reveals their true brightness and distance","wrong":["Cepheids are made mostly of helium","Cepheids are moving away from Earth","Cepheids are found only in the Orion Nebula"]},"sources":[{"title":"John William Draper","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_William_Draper"},{"title":"Astrophotography","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Astrophotography"},{"title":"Gustav Kirchhoff","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Gustav_Kirchhoff"},{"title":"William Huggins","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/William_Huggins"},{"title":"Helium","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Helium"},{"title":"Harvard Computers","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Harvard_Computers"},{"title":"Henrietta Swan Leavitt","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Henrietta_Swan_Leavitt"},{"title":"Cecilia Payne-Gaposchkin","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Cecilia_Payne-Gaposchkin"}],"photos":[{"src":"img/deep/telescope/12-1.jpg","alt":"John W. Draper's 1840 daguerreotype of the Moon, one of the first photographs of anything in space (now spotted with age)","file":"John W Draper-The first Moon Photograph 1840.jpg","url":"https://commons.wikimedia.org/wiki/File:John_W_Draper-The_first_Moon_Photograph_1840.jpg","author":"John William Draper","license":"Public domain"},{"src":"img/deep/telescope/12-2.jpg","alt":"The Harvard computers, women who measured and sorted stars on glass photo plates at Harvard College Observatory, around 1890","file":"Astronomer Edward Charles Pickering's Harvard computers.jpg","url":"https://commons.wikimedia.org/wiki/File:Astronomer_Edward_Charles_Pickering%27s_Harvard_computers.jpg","author":"Harvard College Observatory","license":"Public domain"},{"src":"img/deep/telescope/12-3.jpg","alt":"Henrietta Swan Leavitt working at her desk at Harvard College Observatory","file":"Leavitt henrietta b1.jpg","url":"https://commons.wikimedia.org/wiki/File:Leavitt_henrietta_b1.jpg","author":"Margaret Harwood","license":"Public domain"}],"words":4079},{"n":13,"title":"Giant Mirrors and a Universe of Galaxies","when":"1904 – 1949","summary":"A man named George Ellery Hale kept building bigger and bigger mirror telescopes on California mountaintops. With one of them, Edwin Hubble found a special blinking star in a fuzzy cloud called Andromeda and proved it was a whole other galaxy. Suddenly the universe was full of galaxies, and they were all rushing apart!","sections":[{"heading":"The Boy Who Built Observatories","paragraphs":["Some people collect stamps. George Ellery Hale collected telescopes, and then, when he grew up, he collected the money to build the biggest ones on Earth. Four times in his life he helped create the largest telescope of its kind in the world, a record few people, if anyone, have ever matched.","Hale was born in Chicago on 29 June 1868. His father had grown rich making elevators for the city's new tall buildings, and he was happy to spend money on his curious son. By the time George was 14 he had his first telescope, and soon he had a real laboratory in the family home, packed with prisms, batteries and chemicals. As a teenager he set up his own little observatory behind the house, called the Kenwood Observatory.","Hale did not mainly want to look at pretty sights. He wanted to understand what stars actually are, and the nearest star is the Sun. While he was still a student at MIT, around 1890, he invented a clever instrument called the spectroheliograph. It photographed the Sun in the light of just one color, the color given off by one single chemical element. That way you could see where, say, glowing calcium or hydrogen gas was swirling on the Sun's surface.","Hale was also a born organizer. He became editor of the Astrophysical Journal, which became the most important astronomy magazine in the world, and in the 1890s he persuaded the Chicago businessman Charles Yerkes to pay for the giant Yerkes refractor that you met in Part 11. But as soon as that great lens was working, Hale realized something that would shape the rest of his life: lenses had reached their limit. A lens can only be held at its edges, so a very big one sags under its own weight. A mirror, on the other hand, can be supported from behind across its whole back. The future, he decided, belonged to mirrors.","He also realized that a great telescope in a smoky, cloudy city was wasted. Light from street lamps and the wobbling air near the ground blurred everything. In 1903 he made the hard trip up a rough trail to the top of Mount Wilson, a peak about 1,740 meters (5,700 feet) high above Pasadena in Southern California. The air there was often wonderfully calm and steady, and the sky was dark. Hale fell in love with the place.","Now he needed money, a lot of it. Luckily, the steel tycoon Andrew Carnegie had just set up the Carnegie Institution of Washington to fund science. In 1904 Hale won its support, and the Mount Wilson Solar Observatory was born. At first it was mainly for studying the Sun, and in 1908 Hale made one of the great discoveries of solar science there: sunspots are giant regions of powerful magnetism. He showed this by looking at how the spectral lines in sunlight from a sunspot split apart, a sign of strong magnetic fields."]},{"heading":"Mules, a Mountain and the 60-Inch","paragraphs":["Hale already had a mirror waiting. Back in 1896 his father had bought him a 60-inch (1.5-meter) glass disk, cast by the famous Saint-Gobain glassworks in France. The disk weighed about 860 kilograms (1,900 pounds), about as much as a small car. It had been sitting around for years because there was no telescope to put it in.","Turning a plain glass disk into a telescope mirror is slow, careful work. The front must be ground into a curve called a paraboloid, a shape like a very shallow bowl that sends all the starlight that hits it to one single point. Grinding started in 1905 and took about two years. The optician George Willis Ritchey worked the glass with rotating tools and grinding powder, testing it again and again until the surface was correct to a tiny fraction of the width of a hair. Then a thin coating of silver was laid on the glass to make it shine like a mirror.","Getting all the heavy parts to the top of Mount Wilson was an adventure of its own. There was no paved road up the mountain in those days, only a narrow, twisting trail. Steel parts, building materials and equipment were hauled up by mule trains and, later, by special trucks crawling along a widened path. One of the young men who drove the mules up and down the mountain was a teenager named Milton Humason. Remember his name, because he will come back in this story as a scientist.","The 60-inch telescope saw first light on 13 December 1908. First light is what astronomers call the very first time starlight enters a new telescope. The 60-inch was immediately the largest working telescope in the world. It was used to take photographs of nebulae and to spread the light of stars into spectra, and it showed what a big mirror on a good mountain could do.","But Hale was already dreaming bigger. Even before the 60-inch was finished, he had found a new donor."]},{"heading":"The Hooker 100-Inch: King of the Mountain","paragraphs":["John D. Hooker was a Los Angeles businessman who loved science. In 1906 he gave Hale 45,000 dollars to buy and grind a mirror 100 inches (2.5 meters) across. It would collect almost three times as much light as the 60-inch, because the light a mirror catches depends on its area, not just its width.","Saint-Gobain in France was asked to cast the glass. Making a disk that large was at the edge of what any factory could do. The French glassmakers cast it in 1906 from several batches of molten glass, and when the finished disk arrived in California in 1908 people were alarmed: it was full of small bubbles and layers. Some feared it could never hold a perfect curve. After much worry and many tests, Ritchey and his team decided to try anyway. Grinding and polishing took years, and in the end the mirror turned out superbly well.","The telescope that would hold it was a monster for its time. The whole moving structure weighed about 100 tons, yet it had to turn smoothly enough to follow a star across the sky for hours. To make that easier, much of its weight floated on a bath of mercury, a heavy liquid metal, so that it could be turned with surprisingly little effort. A huge dome was built around it on the mountaintop.","The Hooker telescope saw first light on 2 November 1917. According to a story often told at Mount Wilson, the first images that night looked terrible, smeared into several overlapping blobs, and Hale went to bed fearing disaster. When the team looked again after midnight, the stars were sharp. The dome had been left open during the day, and the Sun had warmed the mirror unevenly; as the glass cooled in the night air, it settled into its correct shape. Whether or not every detail of that story is exact, it teaches a real lesson that telescope builders still worry about: a big mirror must be at the same temperature as the air around it.","For the next 30 years, the Hooker would be the largest telescope on Earth, and it was used for some of the most important observations in the history of science. In 1920 the physicist Albert Michelson fitted it with a special attachment, a stellar interferometer, which used two small mirrors set far apart on a beam across the top of the telescope. With it, astronomers measured the size of the giant red star Betelgeuse in Orion. It was the first time anyone had measured the width of a star other than the Sun.","Meanwhile, the mule driver Milton Humason had come back to Mount Wilson in 1917 as a janitor. He had left school at 14 and had no diploma at all. But he loved the telescopes, and he started volunteering as a night assistant, helping astronomers with their equipment. He turned out to be astonishingly skillful and patient at the telescope. In 1919 Hale made him a member of the scientific staff, a very unusual step for someone without even a high school diploma. That same year, a tall, confident young astronomer named Edwin Hubble arrived on the mountain."]},{"heading":"The Great Debate: How Big Is Everything?","paragraphs":["By 1920, astronomers had photographed thousands of faint, fuzzy patches in the sky called nebulae, from the Latin word for clouds. Many of them had a beautiful spiral shape, like a pinwheel or a whirlpool, just as Lord Rosse had sketched in 1845. The biggest and brightest was in the constellation Andromeda. On a dark night you can see it with no telescope at all as a faint smudge. The Persian astronomer Abd al-Rahman al-Sufi described it as a little cloud in his Book of Fixed Stars around the year 964.","The huge question was: what are these spirals? One idea said they were fairly small, nearby clouds of gas, maybe new solar systems forming, all inside our own Milky Way. In that case the Milky Way was the whole universe. The other idea, sometimes called the island universe theory, said each spiral was a gigantic, faraway collection of billions of stars, a whole galaxy as big as our own, so distant that it looked like a tiny smudge.","On 26 April 1920, two astronomers argued the question in front of the National Academy of Sciences, at the Smithsonian's U.S. National Museum in Washington, D.C. Each gave a talk of about 40 minutes. It is remembered today as the Great Debate.","On one side stood Harlow Shapley, a brilliant young astronomer from Mount Wilson. Using the 60-inch telescope and Henrietta Leavitt's Cepheid ruler, he had measured the distances to big ball-shaped star clusters and found that the Milky Way was enormous, perhaps 300,000 light-years across, far bigger than anyone had thought. He also showed that the Sun is not at the center of the Milky Way but far out toward its edge. If the Milky Way was that huge, he argued, the spirals were probably just parts of it.","Shapley had some evidence that sounded strong. Another Mount Wilson astronomer, Adriaan van Maanen, claimed to have measured the spiral nebulae slowly turning on photographs taken years apart. If the spirals were really far away, then to turn that much they would have to spin faster than light, which is impossible. Shapley also pointed to a 'new star' that had blazed up in Andromeda in 1885 and briefly shone almost as brightly as the whole nebula. How could a single star outshine a whole galaxy?","On the other side stood Heber Curtis of the Lick Observatory. He thought the Milky Way was smaller, about 30,000 light-years across, and that the spirals were separate island universes. He pointed out that astronomers had spotted more exploding stars, called novae, in the Andromeda nebula than in any area of similar size in the Milky Way, and that those novae looked very faint, which suggested they were very far away. He noted that spirals were moving away from us at huge speeds, measured by Vesto Slipher, too fast to be held by the Milky Way's gravity. And he explained why no spirals were seen along the band of the Milky Way: thick dark dust in our galaxy's flat disk blocks the view.","So who won? In a way, both did. Shapley was closer to correct about the size of the Milky Way and right that the Sun is far from its center. Curtis was right about the biggest question: the spirals are galaxies of their own. Van Maanen's measurements of spinning nebulae turned out to be mistakes, and the bright 1885 'nova' in Andromeda was really a supernova, a far more powerful explosion that can briefly outshine an entire galaxy. But in 1920 nobody could prove any of this. They needed a measurement, not an argument."]},{"heading":"VAR! The Star That Changed the Universe","paragraphs":["Edwin Hubble was born in 1889 in Marshfield, Missouri. As a young man he was a star athlete. He studied science at the University of Chicago, then went to Oxford University in England as a Rhodes Scholar, where he studied law, partly to please his father. He even served as an officer in the U.S. Army in World War I. But astronomy kept pulling him back. He earned his PhD at Yerkes Observatory and in 1919 joined the staff at Mount Wilson, where he could use the most powerful telescope on Earth.","Hubble set out to photograph the Andromeda nebula again and again, hunting for novae. On the night of 5 October 1923, continuing into the early hours of 6 October, he took a 45-minute exposure with the Hooker telescope. The air was unsteady that night, but the plate showed something interesting. A photographic plate is a sheet of glass coated with light-sensitive chemicals, the ancestor of a digital camera sensor. Hubble spotted three tiny dots that he thought might be novae, and marked each one with the letter N.","Then he did the careful part. He compared his new plate with older plates of the same patch of Andromeda, taken over many years by other astronomers. One of his 'novae' was not a nova at all. It was there on some old plates, faint on others, brighter on some. It was getting brighter and fainter over and over again, like a slow heartbeat. Hubble crossed out the N and, in excited capital letters, wrote 'VAR!' beside it, short for variable star. That glass plate still exists at the Carnegie Observatories, and it is one of the most famous objects in the history of astronomy.","By studying the star over many nights, Hubble found that it brightened and dimmed with a period of about 31.4 days. That pattern meant it was a Cepheid variable, exactly the kind of star Henrietta Leavitt had studied at Harvard (Part 12). Leavitt had discovered that a Cepheid's period tells you its true brightness: the slower it pulses, the more powerful it really is. Once you know how bright a star truly is, and you measure how bright it appears, you can work out its distance, just as you can judge how far away a streetlight is if you know its real wattage.","Hubble did the math. The answer was astonishing. The star, now called V1, was roughly a million light-years away. By the end of 1924, after finding a dozen Cepheids, he settled on about 900,000 light-years. Even Shapley's giant Milky Way was only about 300,000 light-years across. The Andromeda nebula had to lie far outside our galaxy. It was a galaxy itself.","Hubble was a careful, even cautious, man, and he waited until he had more stars before going public. His results were read aloud at a meeting of the American Astronomical Society in Washington, D.C., on New Year's Day 1925. According to the astronomer Cecilia Payne-Gaposchkin, who was in Shapley's office when Hubble's letter about the Cepheids arrived, Shapley held it out and said something like, 'Here is the letter that has destroyed my universe.'","Today we know Andromeda is even farther than Hubble thought: about 2.5 million light-years away. Hubble's number was too small because astronomers did not yet know that there are two different kinds of Cepheid stars with different brightnesses. But his main conclusion was completely right. When you look at Andromeda tonight, the light entering your eye left that galaxy about 2.5 million years ago, long before modern humans existed."]},{"heading":"A Universe Full of Galaxies","paragraphs":["It is hard to imagine how big a change this was. Before 1925, many astronomers thought the Milky Way was everything. After 1925, the Milky Way was just one galaxy, and the sky was sprinkled with others, each one an enormous city of stars. Every faint spiral smudge on every photographic plate was suddenly a whole galaxy. The universe had grown in size not by a little bit, but by an amount almost impossible to picture.","Andromeda itself turned out to be a giant. Modern measurements show its main disk is about 150,000 light-years across, somewhat bigger than our own Milky Way, and it contains perhaps a trillion stars. It is also coming toward us at roughly 300 kilometers per second. Astronomers have calculated that the two galaxies might collide and merge billions of years from now, though newer studies suggest this is far from certain.","Hubble went on to sort galaxies by shape. In 1926 he created the scheme now called the Hubble sequence, sometimes drawn as a tuning fork. On the handle are elliptical galaxies, smooth balls and ovals of stars. Then the fork splits into two prongs: ordinary spiral galaxies, with arms winding out from the center, and barred spirals, where the arms start from the ends of a straight bar of stars through the middle. Galaxies without any clear shape he called irregular. Astronomers still use his labels today."]},{"heading":"Everything Is Rushing Apart","paragraphs":["Remember Vesto Slipher from Part 12? Starting in 1912 at Lowell Observatory in Arizona, he had measured the speeds of spiral nebulae using the Doppler shift: light from something moving away from us is stretched to longer, redder wavelengths, called a redshift. Slipher found that most spirals were racing away from us, some at hundreds of kilometers per second. Nobody knew why.","Now Hubble could measure distances. All he needed were more speeds, especially for very faint, very distant galaxies. That job fell largely to Milton Humason, the former mule driver. Getting a spectrum of a faint galaxy was brutally hard. The light was so feeble that Humason sometimes had to keep the telescope pointed perfectly at the same spot across more than one night, guiding by hand in the cold dark dome while the photographic plate slowly soaked up light. He became the best in the world at it.","In 1929 Hubble published a short paper with a simple graph. Along one side he put distance; along the other, speed. The dots were scattered, but they clearly made a rising line: the farther away a galaxy was, the faster it was moving away from us. In 1931 Hubble and Humason extended the result to galaxies much farther away, and the pattern held. This rule, speed equals a constant number times distance, became known as Hubble's law.","What does it mean? Imagine a loaf of raisin bread rising in the oven. As the dough swells, every raisin moves away from every other raisin. A raisin right next to you drifts away slowly, but a raisin on the far side of the loaf moves away much faster, because there is more dough between you to stretch. And it does not matter which raisin you sit on; from every raisin, all the others seem to be moving away. That is what the galaxies were doing. The universe itself is expanding.","But Hubble was not the first to put this idea together, and fair credit matters here. In 1927 a Belgian Catholic priest and physicist named Georges Lemaître had published a paper showing that Albert Einstein's theory of gravity allowed for an expanding universe, and that if the universe was expanding, galaxies' speeds should rise with their distance. Using Slipher's speeds and the best distances available, he even estimated the expansion rate. Sadly, his paper appeared in a Belgian journal that few astronomers elsewhere read. Lemaître recalled that when he told Einstein about his idea, Einstein said his math was correct but his physics was 'abominable.' Einstein later changed his mind after the observations came in, and in 1931 he visited Mount Wilson and met Hubble.","Lemaître went further. If everything is flying apart now, then long ago everything must have been packed together. In 1931 he proposed that the universe began from what he called a 'primeval atom.' This was the first version of what we now call the Big Bang theory.","So the discovery of the expanding universe belongs to several people: Slipher, who measured the speeds; Leavitt, whose ruler made distances possible; Lemaître, who predicted and first estimated the pattern; and Hubble and Humason, who nailed it down with the Hooker telescope. In 2018, members of the International Astronomical Union voted to recommend calling it the Hubble-Lemaître law, and about 78 percent of those who voted said yes."]},{"heading":"The 200-Inch Giant of Palomar","paragraphs":["Even the Hooker was not enough for George Ellery Hale. To see galaxies even farther away, he wanted a mirror twice as wide, 200 inches (5.1 meters), which would collect four times as much light. In 1928 he wrote a magazine article called 'The Possibilities of Large Telescopes', and that same year he won a grant of 6 million dollars from the Rockefeller Foundation, an enormous sum at the time. The new observatory would be run by the California Institute of Technology, Caltech, which Hale had helped grow into a top science university. A site was chosen on Palomar Mountain in northern San Diego County, far from the bright city lights that were starting to spoil the sky over Mount Wilson.","The first plan was to make the mirror out of fused quartz, a super-pure glass that hardly changes shape when it warms or cools. The General Electric company tried for years, but the quartz disks kept failing and the costs climbed. So the job went to Corning Glass Works in Corning, New York, which made a special heat-resistant glass called Pyrex, the same kind of glass used for baking dishes. Pyrex expands much less than ordinary glass when heated, so a Pyrex mirror would keep its shape better as the night air cooled.","Casting a 200-inch disk had never been done. To keep it from being impossibly heavy, the engineers designed a mold with a pattern of blocks underneath, so the back of the mirror would be a honeycomb of ribs instead of solid glass. That cut the amount of glass needed from over 40 tons to about 20. On 25 March 1934, in front of reporters and a crowd of visitors, workers ladled the glowing glass into the mold. But the heat made some of the blocks in the mold break loose and float up through the molten glass. That first disk was ruined. (It still exists and is displayed at the Corning Museum of Glass.)","Corning tried again. The second disk was cast on 2 December 1934. Glass this thick must cool extremely slowly, or it will crack from uneven shrinking. The disk was held at a high temperature for over a month, then cooled bit by bit for about ten months. Finally, the disk was ready.","On 26 March 1936 the 20-ton disk left Corning on a specially prepared railroad car, standing on its edge inside a protective steel crate. Sixteen days later, on 10 April 1936, it arrived at the Caltech optical shop in Pasadena.","Then came the grinding and polishing, which lasted about eleven and a half years, slowed down by World War II, when many workers left for war jobs. Over those years about 10,000 pounds (about 4.5 tonnes) of glass were ground away, leaving a mirror of about 14.5 tons with a curve accurate to a few millionths of a centimeter. Instead of silver, the finished mirror was coated with a thin layer of aluminum, which lasts longer.","George Ellery Hale never saw it finished. He died on 21 February 1938. On 3 June 1948, the great telescope was dedicated and given his name: the Hale Telescope. Its moving parts weigh about 530 tons, yet it is balanced so well that it can be turned precisely to follow the stars. On 26 January 1949, Edwin Hubble took the telescope's first official photograph, of a small fan-shaped nebula called NGC 2261.","The Hale Telescope was the largest effective telescope in the world for about 25 years. A Soviet telescope with a 6-meter mirror was finished in the mid-1970s but never worked as well, and only in 1993 did the 10-meter Keck telescope in Hawaii clearly beat it. The 200-inch is still used for research today. Hubble himself died in 1953, a few years after taking that first photograph. Every bigger telescope since has stood on the shoulders of the giant mirrors Hale dreamed up.","Those giant mirrors did not work by magic, though. Every one of them, from Galileo's little tube to the 200-inch, relies on the same few rules of light. Before we go further, let's open up a telescope and see exactly how it pulls off its tricks."]}],"deepDive":"Hubble's 1929 graph gave an expansion rate of about 500 kilometers per second per megaparsec (a megaparsec is about 3.26 million light-years). Today's value is about 70, roughly seven times smaller. Why was Hubble so far off? His distances were too short. In the early 1950s Walter Baade, using the Palomar 200-inch, showed that there are two different populations of Cepheid variable stars with different true brightnesses; astronomers had been calibrating Andromeda's Cepheids with the wrong kind. Correcting this roughly doubled the size of the known universe overnight. Other errors followed: some of Hubble's 'brightest stars' in distant galaxies were actually glowing gas clouds. Allan Sandage and others spent decades pushing the number down. The difference mattered enormously. If you run the expansion backward, the expansion rate gives a rough age of the universe. Hubble's 500 implied about 2 billion years, less than the age of the Earth as measured from radioactive rocks, which was a serious puzzle. Modern values give about 13.8 billion years. Today there is a new argument called the Hubble tension. Measurements using nearby stars and supernovae tend to give about 73, while calculations from the afterglow of the Big Bang give about 67 to 68. The gap is small but stubborn, and some astronomers think it may hint at new physics. There is also a historical puzzle. When Lemaître's 1927 paper was translated into English in 1931, the section estimating the expansion rate was left out. Some writers suspected someone was protecting Hubble's priority. In 2011 the astrophysicist Mario Livio found letters showing that Lemaître himself removed those paragraphs, apparently because newer data had made them out of date. Historians also stress that Hubble, in 1929, was cautious about saying the universe was expanding; he described an empirical relation between redshift and distance and left the interpretation open. The 2018 IAU recommendation to say 'Hubble-Lemaître law' was a vote by members, not a binding rule, but it reflects a growing effort to give credit fairly.","funFact":"The very first 200-inch mirror disk that Corning cast in 1934 failed, and instead of being thrown away it was kept and is now displayed at the Corning Museum of Glass in New York.","check":{"q":"What did Edwin Hubble write on his photographic plate of the Andromeda nebula in October 1923 when he realized one of his 'novae' was really a Cepheid?","a":"VAR!","wrong":["NOVA!","GALAXY!","EUREKA!"]},"sources":[{"title":"Hooker Telescope","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Hooker_Telescope"},{"title":"Great Debate (astronomy)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Great_Debate_(astronomy)"},{"title":"Hubble Views the Star that Changed the Universe","publisher":"NASA","url":"https://science.nasa.gov/missions/hubble/hubble-views-the-star-that-changed-the-universe/"},{"title":"The Hale Telescope","publisher":"Caltech Palomar Observatory","url":"https://sites.astro.caltech.edu/palomar/about/telescopes/hale.html"},{"title":"Hale Telescope","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Hale_Telescope"},{"title":"Hubble's law","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Hubble%27s_law"},{"title":"Georges Lemaître","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Georges_Lema%C3%AEtre"},{"title":"Milton L. Humason","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Milton_L._Humason"}],"photos":[{"src":"img/deep/telescope/13-1.jpg","alt":"The 100-inch Hooker Telescope in its dome at Mount Wilson Observatory, which Edwin Hubble used to study galaxies","file":"100 inch Hooker Telescope 900 px.jpg","url":"https://commons.wikimedia.org/wiki/File:100_inch_Hooker_Telescope_900_px.jpg","author":"Ken Spencer","license":"CC BY-SA 3.0"},{"src":"img/deep/telescope/13-2.jpg","alt":"The Andromeda Galaxy, with Hubble's 1923 glass plate (bottom right) where he wrote \"VAR!\" by the star V1","file":"Snapshots of the star that changed the Universe (opo1115d).jpg","url":"https://commons.wikimedia.org/wiki/File:Snapshots_of_the_star_that_changed_the_Universe_(opo1115d).jpg","author":"Illustration Credit: NASA, ESA and Z. Levay (STScI). Credit: NASA, ESA and…","license":"CC BY 4.0"},{"src":"img/deep/telescope/13-3.jpg","alt":"The giant white dome of the 200-inch Hale Telescope on Palomar Mountain, California","file":"Palomar Observatory 2012 01.jpg","url":"https://commons.wikimedia.org/wiki/File:Palomar_Observatory_2012_01.jpg","author":"Photograph by Mike Peel (www.mikepeel.net).","license":"CC BY-SA 4.0"}],"words":4371},{"n":14,"title":"How a Telescope Really Works","when":"The science","summary":"A telescope is really a light bucket: its big lens or mirror catches far more light than your tiny eye can. Then a small lens called the eyepiece makes the picture bigger. The wider the telescope, the fainter the things it can see and the sharper the details it can show.","sections":[{"heading":"Bending Light: The Trick Inside Every Lens","paragraphs":["Put a straw in a glass of water and look at it from the side. The straw seems to snap in two right at the water's surface. Nothing has happened to the straw, of course. What has changed is the path of the light coming from it. This bending of light as it passes from one material into another is called refraction, and it is the secret behind every lens ever made, from Galileo's spyglass to your reading glasses.","Why does light bend? Because it changes speed. In empty space, light travels at about 300,000 kilometers per second. In air it is only a tiny bit slower. But in ordinary glass it slows to about 200,000 kilometers per second, and in water to about 225,000. When a beam of light hits glass at a slant, one side of the beam enters the glass and slows down a moment before the other side does. The beam swings around, like a marching band turning a corner where the players on the inside of the turn take shorter steps. Coming out of the glass the opposite happens, and the beam bends again.","Now shape the glass cleverly. A convex lens is thicker in the middle than at the edges. Light passing near the edge hits the glass at a steeper slant and gets bent more, while light going straight through the center is not bent at all. The result is that a whole bundle of parallel rays, such as the light from a distant star, gets bent inward and comes together at one point behind the lens. That point is called the focus. The distance from the lens to the focus is called the focal length. A strongly curved lens has a short focal length; a gently curved lens has a long one. That is why the old astronomers in Part 6 had to build such ridiculously long telescopes when they used very gently curved lenses.","If you have ever used a magnifying glass to make a tiny bright dot of sunlight on a leaf, you have seen a focus. (Never look at the Sun through the lens while doing this!) That bright dot is actually a tiny picture of the Sun. A convex lens does the same for anything: it makes a small, upside-down picture, called an image, of whatever it is pointed at, hanging in the air at the focus. Hold a magnifying glass between a window and a white sheet of paper, move the paper back and forth, and at the right distance you will see a little upside-down picture of the window and the trees outside. That floating picture is the heart of a telescope.","There is one catch. Visible light is made of many colors, with wavelengths from about 400 nanometers (violet) to about 700 nanometers (red). A nanometer is a billionth of a meter, so these waves are tiny: roughly 150 to 200 of them would fit across the thickness of a sheet of paper. Glass slows violet light a little more than red light, so violet bends a little more. That is exactly how a prism spreads white light into a rainbow, and it is also why a simple lens gives colored fringes around bright objects. This is the chromatic aberration you met in Parts 6 to 8, and it is why astronomers worked so hard on achromatic lenses and mirrors."]},{"heading":"Two Jobs: Catch the Light, Then Enlarge It","paragraphs":["Every telescope, from a 20-dollar toy to a giant on a mountaintop, does two separate jobs. The first job belongs to the objective, the big lens or mirror at the front or bottom of the telescope. Its job is to collect as much light as possible and bring it to a focus, making that small image in the air. The second job belongs to the eyepiece, the little lens you put your eye to. Its job is to act like a magnifying glass and let you look closely at that image.","Instead of a lens, the objective can be a curved mirror. A mirror shaped like a shallow bowl, curved in a special shape called a paraboloid, sends every ray of starlight that hits it to the same single point. Because the light bounces off the front surface instead of passing through glass, every color is treated exactly the same, so there are no rainbow fringes. A mirror can also be held up from behind across its whole back, so it can be made enormous without sagging. That is why every large research telescope in the world today uses a mirror.","Many big modern telescopes do not even have an eyepiece. Instead, a camera or another scientific instrument sits at the focus and records the image directly. The objective is still doing the most important job; the camera simply takes the place of your eye.","Here is something surprising: with the same objective, you can change how much the telescope magnifies just by swapping eyepieces. That is because magnification is set by a simple formula. Magnification equals the focal length of the objective divided by the focal length of the eyepiece.","Let's try it. Suppose your telescope's objective has a focal length of 1,000 millimeters. Put in an eyepiece with a focal length of 10 millimeters. 1,000 divided by 10 is 100, so the telescope magnifies 100 times, written 100x. The Moon, which looks a little smaller than a pea held at arm's length, now looks 100 times wider. Swap in a 25-millimeter eyepiece: 1,000 divided by 25 is 40, so now you have 40x, a lower power with a wider view. Swap in a 5-millimeter eyepiece and you get 200x.","Notice what this means. Short-focal-length eyepieces give high power; long ones give low power. And a telescope with a longer focal length gives more magnification with the same eyepiece. Eyepieces are usually labeled with their focal length in millimeters, so you can work out the power of any combination in your head.","Telescope owners have one more trick for changing power, called a Barlow lens. It is a small concave lens, like the one in Galileo's eyepiece, placed in the tube just before the eyepiece. It spreads the light cone out a little so that the objective acts as if its focal length were two or three times longer. A 2x Barlow turns a 25-millimeter eyepiece that gave 40x into one that gives 80x, which saves buying a whole extra set of eyepieces. It is named after the English mathematician Peter Barlow, who worked on this kind of lens in the 1800s.","But wait. If magnification is that easy to change, why don't telescope makers just sell tiny eyepieces and claim 1,000x? Because, as we will see, magnification is the least important thing a telescope does. The real powers of a telescope are hidden in one number: its aperture."]},{"heading":"A Bucket for Catching Light","paragraphs":["Aperture is just the width of the objective, the main lens or mirror. A small backyard telescope might have an aperture of 70 or 100 millimeters. A popular amateur telescope has 200 millimeters, about 8 inches. The Hooker telescope from Part 13 has 2.5 meters, and the Hale Telescope 5.1 meters. Astronomers care about this number more than any other, for two reasons. The first is light.","Think of a telescope as a bucket standing out in the rain, except the rain is made of light. Light from a faint galaxy is falling on Earth all the time, spread thinly over everything. Your eye catches only the light that happens to drop into your pupil, the black opening in the middle of your eye. Even in total darkness, after your eyes have adjusted for half an hour, your pupil opens only about 7 millimeters wide. That is a very small bucket.","A telescope is a much bigger bucket. It gathers all the light falling on its objective and squeezes it down into a beam narrow enough to fit through your pupil. Because the light caught depends on the area of the objective, not just its width, the advantage grows very quickly. Double the width and the area becomes four times bigger, so you collect four times the light. Triple the width and you get nine times the light. The rule is: light grows with the width multiplied by itself, the width squared.","Let's compare an 8-inch telescope with your eye. Its aperture is 200 millimeters, and your pupil is 7 millimeters. 200 divided by 7 is about 28.6. Multiply that by itself and you get about 816. So an 8-inch telescope gathers roughly 800 times more light than your naked eye. Stars and galaxies that were 800 times too faint to see suddenly become visible.","Now try the giants. The Hooker's 2,540-millimeter mirror, divided by 7 and then squared, gathers about 130,000 times as much light as an eye. The Hale Telescope's 5,080-millimeter mirror gathers more than half a million times as much. Put a camera behind it and let the light pile up on the sensor for an hour, and the advantage grows even larger. That is how astronomers photograph galaxies billions of light-years away.","Astronomers describe how bright a star looks using magnitudes, an old scale that goes back to ancient Greek star catalogs. Strangely, bigger numbers mean fainter stars. The brightest stars are around magnitude 0 or 1, and under a truly dark country sky the faintest stars you can see with your eyes alone are around magnitude 6. Every 5 magnitudes means 100 times fainter. An 8-inch telescope, gathering about 800 times more light than your eye, lets an observer see stars down to roughly magnitude 13 or 14, which is hundreds of times fainter than anything visible without it. Within that range lie thousands of galaxies, nebulae and star clusters that no one before the telescope could ever have known existed.","This is the real reason astronomers kept building bigger telescopes. Not to make things look bigger, but to catch more of the faint trickle of light from things that are very far away or very dim. In astronomy, the size of your bucket decides how deep into the universe you can see."]},{"heading":"Seeing Fine Detail, and Why Stars Twinkle","paragraphs":["The second power of aperture is resolution, the ability to show fine detail. Imagine two stars very close together in the sky. Through a small telescope they blend into one blob. Through a bigger telescope they split into two separate points. The bigger telescope has better resolution.","Why should width matter for sharpness? Because light travels as waves. When waves pass through an opening, they spread out a little at the edges, an effect called diffraction. Even a perfect telescope cannot focus a star into a perfect point; it makes a tiny disk surrounded by faint rings. The wider the aperture, the smaller that disk, so the finer the detail that can be separated.","Astronomers measure tiny angles in the sky in arcseconds. There are 60 arcminutes in a degree and 60 arcseconds in an arcminute. The full Moon is about 30 arcminutes, or about 1,800 arcseconds, wide. A person with good eyesight can separate details about 1 arcminute apart, which is about the accuracy Tycho Brahe reached without a telescope in Part 1.","A handy rule used by observers of double stars, called the Dawes limit, says that a telescope can split two equal stars about 116 divided by its aperture in millimeters arcseconds apart. For a 100-millimeter telescope that is about 1.2 arcseconds. For an 8-inch, 200-millimeter telescope it is about 0.6 arcseconds, around a hundred times finer than your eye. In theory, the 5-meter Hale Telescope could split stars just a few hundredths of an arcsecond apart.","In practice, it cannot, at least not without help. The problem is the air above us. Earth's atmosphere is always churning, with pockets of warmer and cooler air sliding past each other. Each pocket bends light slightly differently, because light travels at slightly different speeds through air of different temperatures. As starlight passes through these moving pockets, it gets jiggled this way and that, many times a second. Astronomers call the steadiness of the air the seeing.","You have seen this yourself. Stars twinkle because their light is being jostled by turbulent air. A star is so far away that it is basically a single point of light, so the jostling makes it flicker and dance. Planets usually twinkle less, because they appear as tiny disks rather than points, and the flickering from different parts of the disk tends to average out. Twinkling is lovely to look at, but it is the enemy of sharp telescope images. It is the same shimmering you see over a hot road in summer, just much fainter.","On an ordinary night at an ordinary place, the seeing blurs star images to about 1 to 3 arcseconds. At the best mountaintop sites, like Maunakea in Hawaii or La Palma in the Canary Islands, it can sometimes be as good as 0.4 arcseconds. That means that on most nights any telescope wider than roughly 10 to 20 centimeters cannot show finer detail than a smaller telescope would, because the air is the limit. Big telescopes still win at collecting light, but for sharpness, the air sets the rules. That is why astronomers moved telescopes to high mountains, and, as later parts show, eventually above the air altogether, or learned to cancel the twinkle with bending mirrors."]},{"heading":"Four Designs Side by Side","paragraphs":["Over 400 years, telescope makers have invented many ways to arrange lenses and mirrors. Four classic designs explain almost everything you will see in a telescope shop or an observatory.","The Galilean telescope, the original Dutch spyglass that Galileo improved, has a convex objective at the front and a concave eyepiece near your eye. The concave eyepiece catches the light before it reaches the focus. Its big advantage is that the image is right side up, which made it perfect for looking at ships and soldiers. Its big weakness is a tiny field of view: at higher powers you see only a small patch of sky, as if looking through a keyhole. That is part of why Galileo's work was so hard. Simple opera glasses still use this design today.","The Keplerian telescope, which Kepler described in 1611, uses a convex lens for the eyepiece too. The light comes to a focus first, making a real image inside the tube, and the eyepiece then magnifies it. The image is upside down, but the field of view is much wider, and there is a real image where crosshairs or measuring scales can be placed, as William Gascoigne discovered. Almost all lens telescopes since the 1600s, including the giant Yerkes refractor, use this basic design. For stars, upside down does not matter at all; there is no 'up' in space.","The Newtonian telescope, Isaac Newton's 1668 invention, uses a curved main mirror at the bottom of an open tube. Light comes in the top, travels down, bounces off the main mirror, and heads back up toward the focus. Before it gets there, a small flat mirror tilted at 45 degrees sends it out the side of the tube, where the eyepiece sits. Newtonians are simple, cheap to make in large sizes, and free of color fringes, which is why so many amateur astronomers own one. The eyepiece is near the top of the tube, which on a big telescope can mean climbing a ladder.","The Cassegrain telescope, based on Laurent Cassegrain's 1672 design, also uses a concave main mirror, but with a hole in its center. A small convex mirror near the top sends the light back down through the hole, and the eyepiece or camera sits behind the main mirror. Because the light path is folded back on itself, a long focal length fits inside a short, stubby tube. That makes Cassegrain-type telescopes compact and easy to mount, and it lets heavy instruments hang at the bottom, where they are easy to balance. The Hubble Space Telescope, the Keck telescopes, and most big research telescopes use versions of the Cassegrain design. Many popular amateur telescopes, called Schmidt-Cassegrains, add a thin correcting lens across the front.","So which is best? It depends on the job. A small refractor is rugged and gives crisp, steady views. A Newtonian gives the most aperture for your money. A Cassegrain packs a long focal length into a portable package. For the very biggest telescopes, there is no contest: mirrors win, because only mirrors can be made many meters wide."]},{"heading":"Mounts: Keeping Up With a Spinning Earth","paragraphs":["A telescope is useless if it shakes or cannot point steadily. At 100x magnification, every tiny wobble is also magnified 100 times. That is why the mount, the stand that holds and steers the telescope, is just as important as the optics.","There is another problem. The Earth spins, so the stars seem to drift across the sky, rising in the east and setting in the west. At high magnification, a star can drift right out of your view in less than a minute. A good mount must let you follow it.","The simplest kind is the altazimuth mount. It moves in two directions, just like a camera tripod: up and down (altitude) and left and right (azimuth). It is easy to understand and use. The popular Dobsonian telescope, which John Dobson made famous (Part 10), is a Newtonian sitting in a simple altazimuth box that swivels on the ground. To follow a star, though, you must nudge it both up and sideways at the same time, at rates that keep changing as the star moves across the sky.","The equatorial mount solves this with a clever tilt. One axis, called the polar axis, is lined up parallel to the Earth's own axis, pointing at the celestial pole, which in the Northern Hemisphere is very close to the North Star, Polaris. The angle of that tilt matches your latitude. Because this axis is lined up with the Earth's spin, you can follow any star by turning just this one axis at a steady speed, one full turn every 23 hours 56 minutes, the time it takes Earth to spin once relative to the stars. Add a motor or clockwork drive, and the telescope tracks the sky automatically. Joseph von Fraunhofer built a famous version, the German equatorial mount, for the Dorpat refractor in 1824, and it is still the most common type for amateur astrophotography. The Hale Telescope rides on a giant horseshoe-shaped equatorial mount.","Today, the very largest telescopes have gone back to altazimuth mounts. An altazimuth mount is much more compact and stronger for its weight, and it holds the mirror with gravity always pulling in a simpler way. The tricky part, moving both axes at changing speeds and slowly turning the instrument to stop the image from rotating, is now done by computers, many times a second. Even small amateur telescopes often have computerized 'go-to' mounts that find and follow thousands of objects at the push of a button."]},{"heading":"Why More Power Just Makes a Bigger Blur","paragraphs":["Walk into a toy store and you may see a small telescope in a box covered with pictures of colorful galaxies and the words '675x power!' This is one of the oldest tricks in telescope selling, and now you know enough to see through it.","Magnification does not create detail. It only enlarges what the objective has already captured. If a small lens can only resolve detail down to about 2 arcseconds, then blowing the image up more and more is like zooming in on a small, low-quality photo on a computer. At first, things get easier to see. But beyond a certain point you just see bigger, fuzzier blobs. Astronomers call this empty magnification.","A popular rule of thumb among amateur astronomers is that the most useful magnification for a telescope is about 2 times its aperture in millimeters, or about 50 times per inch. For a 60-millimeter toy telescope, that is about 120x, not 675x. And on most nights, the seeing will limit even large telescopes to a few hundred times at most, no matter how big they are.","Too much magnification causes other problems too. The image gets dimmer, because the same amount of light is spread over a bigger picture. The field of view shrinks, so objects are harder to find and drift out of view faster. Every shake of the mount and every shimmer of the air becomes huge. Most experienced observers spend most of their time at low or medium power, where the view is bright, wide and steady, and only push to high power on calm nights for small, bright objects like planets, the Moon or close double stars.","So the next time someone asks you how powerful your telescope is, you can give the expert answer: what matters most is not how much it magnifies, but how wide it is. Aperture gathers light. Aperture shows detail. Magnification just lets your eye see what the aperture caught.","Everything in this part has been about visible light, the colors from violet to red that our eyes evolved to see. But visible light is only a tiny slice of the light in the universe, and the first person to 'see' outside that slice was not an astronomer at all. He was a phone engineer chasing static."]}],"deepDive":"The resolution limit of a telescope comes from the wave nature of light. A circular aperture of diameter D focuses a point of light into a pattern called the Airy disk: a bright central spot surrounded by faint rings. Lord Rayleigh's criterion says two points are just resolved when the center of one Airy disk falls on the first dark ring of the other, at an angle of about 1.22 times the wavelength divided by D (in radians). For green-yellow light at 550 nanometers, that works out to about 138 divided by D in millimeters, in arcseconds. The Dawes limit, about 116/D, came from the 19th-century English observer William Rutter Dawes, who found by experience that skilled observers could split equal double stars slightly closer than Rayleigh's formula. Notice the wavelength in the formula: at longer wavelengths, resolution gets worse for the same aperture. That is why radio telescopes, working with waves centimeters to meters long, must be huge or linked together, and why an infrared telescope needs a bigger mirror than a visible-light one to match its sharpness. The atmosphere's blurring is described by the Fried parameter, r0, roughly the width of a patch of air that behaves as one steady piece of glass. It is typically about 10 to 20 centimeters at a good site in visible light, and only about 5 centimeters at many sea-level locations. A telescope larger than r0 is 'seeing-limited': its sharpness is set by r0, not by its own aperture. Mirror quality matters too. A common standard is that the surface must be correct to about a quarter of a wavelength of light, which for a mirror used in visible light means errors of only about 0.1 to 0.15 micrometers across the whole surface, roughly a thousandth of a hair's width. Another useful number is the focal ratio, the focal length divided by the aperture. A 'fast' telescope like the f/3.3 Hale Telescope gives a bright, wide field good for photographing faint, spread-out objects, while a 'slow' f/10 or f/15 telescope gives higher magnification with a given eyepiece and suits planets and double stars. Finally, the exit pupil, the aperture divided by the magnification, explains the low-power limit: if the beam leaving the eyepiece is wider than about 7 millimeters, some of the collected light misses your pupil entirely.","funFact":"Even a perfect telescope cannot focus a star into a true point: because light is a wave, every star image is a tiny disk with faint rings around it, and only a wider telescope can make that disk smaller.","check":{"q":"A telescope's objective has a focal length of 1,000 mm. What magnification do you get with a 10 mm eyepiece?","a":"100x","wrong":["10x","1,010x","10,000x"]},"sources":[{"title":"Optical telescope","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Optical_telescope"},{"title":"Astronomical seeing","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Astronomical_seeing"},{"title":"How Do Telescopes Work?","publisher":"NASA Space Place","url":"https://spaceplace.nasa.gov/telescopes/en/"},{"title":"Equatorial mount","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Equatorial_mount"},{"title":"The Hale Telescope","publisher":"Caltech Palomar Observatory","url":"https://sites.astro.caltech.edu/palomar/about/telescopes/hale.html"},{"title":"Dawes' limit","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Dawes%27_limit"},{"title":"Cassegrain reflector","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Cassegrain_reflector"},{"title":"Refractive index","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Refractive_index"}],"photos":[{"src":"img/deep/telescope/14-1.jpg","alt":"Diagram: parallel light rays bend through a convex (converging) lens and cross at the focal point","file":"Lens1.svg","url":"https://commons.wikimedia.org/wiki/File:Lens1.svg","author":"DrBob at English Wikipedia","license":"CC BY-SA 3.0"},{"src":"img/deep/telescope/14-2.jpg","alt":"Diagram of a Newtonian reflector: the curved primary mirror and flat secondary mirror, plus its labeled equatorial mount","file":"Newton01.png","url":"https://commons.wikimedia.org/wiki/File:Newton01.png","author":"Szőcs TamásTamasflex","license":"CC BY-SA 3.0"},{"src":"img/deep/telescope/14-3.jpg","alt":"A big 20-inch Dobsonian telescope sitting on its simple wooden swiveling base","file":"20\" Obsession.jpg","url":"https://commons.wikimedia.org/wiki/File:20%22_Obsession.jpg","author":"NathanScientific","license":"CC0"}],"words":3915},{"n":15,"title":"Invisible Light: Radio Telescopes","when":"1932 – 2022","summary":"Our eyes see only a tiny slice of all the light in space. In 1932 a telephone engineer built a spinning antenna on car wheels and caught radio waves from the middle of our galaxy. Soon giant dishes found the glow left over from the Big Bang, blinking dead stars, and even took a picture of a black hole's shadow!","sections":[{"heading":"A Rainbow Much Wider Than Our Eyes","paragraphs":["Every telescope in this story so far, from Lipperhey's little spyglass to the giant 200-inch mirror on Palomar Mountain, did the same basic job: it collected visible light, the kind our eyes can see. But visible light is only a thin sliver of a much bigger family. Scientists call that whole family the electromagnetic spectrum. Imagine a piano keyboard kilometers long on which our eyes can play just one key.","All members of the family are the same kind of thing: waves of electric and magnetic energy that race through empty space at about 300,000 kilometers every second. What makes them different is their wavelength, the distance from one wave crest to the next. Visible light has waves only about 400 to 700 nanometers long (a nanometer is a billionth of a meter). Violet has the shortest waves we can see, red the longest.","Go beyond red and you reach infrared, which you feel as warmth from a campfire. Longer still are microwaves, the kind that heat food and carry Wi-Fi, and longest of all are radio waves, from about a meter up to many kilometers. Go the other way, beyond violet, and the waves get shorter and carry more energy: ultraviolet, which gives you sunburn, then X-rays, which doctors use to see bones, and finally gamma rays, made in the most violent explosions in the universe. Cold gas clouds glow in radio, warm dust in infrared, and super-hot gas near black holes in X-rays. Look only in visible light and you miss much of the action.","There is a catch, though. Earth's air acts like a filter. It lets visible light through, which is lucky for us and for every plant that needs sunlight. It also lets most radio waves through, from wavelengths of about a centimeter up to tens of meters. Astronomers call these open gaps the optical window and the radio window. But the atmosphere soaks up almost all X-rays and gamma rays, most ultraviolet light and much of the infrared. So the very first kind of invisible light that astronomers could study from the ground was radio, and nobody went looking for it on purpose. It was found by a telephone engineer trying to get rid of some annoying hiss.","One important warning before we meet him. Radio telescopes do not let us hear sounds from space. Sound needs air or some other material to travel through, and space is almost empty. Radio waves are light, not sound. When you hear a radio telescope recording turned into a crackle or a whoosh, scientists have converted the data into sound, the same way your radio at home turns invisible radio waves into music through its speaker."]},{"heading":"Karl Jansky and the Merry-Go-Round","paragraphs":["In 1928 a young American physicist named Karl Guthe Jansky joined Bell Telephone Laboratories, the research arm of the giant American telephone company. At that time, if you wanted to make a phone call from New York to London, your voice crossed the Atlantic Ocean as a shortwave radio signal. Those calls were often spoiled by crackles and hissing static. Bell Labs gave Jansky a clear job: find out where the static came from, so the engineers could design around it.","Jansky worked at a Bell Labs field site in Holmdel, New Jersey, surrounded by farmland. There he built a strange machine. It was a long, rectangular frame of metal pipes and wires, about 30 meters (100 feet) long and several meters high, designed to pick up radio waves at a frequency of 20.5 megahertz, which means waves about 14.6 meters long. To find which direction the static came from, the antenna had to point different ways, so Jansky mounted the whole thing on a turntable resting on four wheels taken from old Ford Model T cars. A motor pushed it slowly around in a full circle every 20 minutes. His coworkers nicknamed it Jansky's merry-go-round.","For more than a year, starting around 1930 and 1931, Jansky listened and recorded. He sorted the static into types. There was loud static from nearby thunderstorms and weaker static from distant thunderstorms. But there was also a third kind: a faint, steady hiss that did not seem to come from storms at all. Its strength rose and fell once a day, so at first Jansky wondered if it came from the Sun.","Then he noticed something sneaky. The hiss did not peak at the same time every day. It arrived about four minutes earlier each day. That might sound like a tiny detail, but to an astronomer it is a giant clue. The Sun returns to the same spot in our sky every 24 hours, but the stars return every 23 hours and 56 minutes, a period called a sidereal day. The four-minute difference happens because Earth moves along its orbit around the Sun while it spins. Jansky's hiss was keeping star time, not Sun time. So it had to be coming from far beyond the solar system.","When he worked out the direction, it pointed toward the constellation Sagittarius, the part of the sky where the center of our Milky Way galaxy lies, hidden behind thick clouds of dust. His records show the signal at its strongest on 16 September 1932. Jansky announced his findings at a scientific meeting in Washington, D.C., in April 1933, and on 5 May 1933 the New York Times put the story on its front page. Later that year he published a paper with the wonderful title Electrical Disturbances Apparently of Extraterrestrial Origin.","Jansky is said to have wanted to build a bigger antenna to study the cosmic hiss more closely, but Bell Labs said no. The company had its answer: the space hiss was too faint to ruin phone calls. Jansky was moved on to other projects and never returned to astronomy. He died in 1950 at just 44 years old. Today astronomers measure the brightness of radio sources in a unit called the jansky, and the Very Large Array in New Mexico carries his name. A full-size replica of his merry-go-round stands at the Green Bank Observatory in West Virginia."]},{"heading":"Grote Reber's Backyard Dish","paragraphs":["Professional astronomers mostly ignored Jansky's discovery. Most of them had trained in optics, not electronics, and radio receivers seemed like the business of engineers. But one person read about it and could not stop thinking about it: Grote Reber, a young radio engineer and keen ham radio operator from Wheaton, Illinois, a town outside Chicago.","In 1937 Reber decided to build his own radio telescope, in his mother's backyard, with his own money. Instead of Jansky's flat frame of wires, he chose a curved dish shaped like a bowl. The shape is a parabola, the same curve used in Newton's mirror telescopes and in car headlights. A parabolic dish has a lovely property: every wave that hits it straight on bounces to the same point, called the focus. Put a receiver at the focus and you can collect waves from a big area and concentrate them into one spot. Reber's dish was about 9 meters (31 feet) across, built from wood and galvanized sheet metal, and it could tilt up and down along a north-south line. As Earth spun, different parts of the sky drifted through its view. It was finished in September 1937, and the neighbors had never seen anything like it.","His first attempts failed. He built a receiver for 3,300 megahertz, which detected nothing from space. He tried again at 900 megahertz and found nothing. On his third try, using 160 megahertz, he finally picked up radio waves from the Milky Way in 1938, confirming Jansky's discovery. He often observed late at night, after his day job at a Chicago radio company, when there was less radio noise from the spark plugs of passing cars.","Reber then did something nobody had done: he made maps of the radio sky. Pointing step by step, he measured the strength of the radio glow across large parts of the heavens. His maps, made in the early 1940s after a first paper in 1940, showed the radio Milky Way stretched across the sky, brightest toward Sagittarius, with other strong spots in the constellations Cygnus and Cassiopeia. Those spots later turned out to be Cygnus A, a galaxy blasting out huge amounts of radio energy, and Cassiopeia A, the wreckage of an exploded star.","For about a decade, Reber was very nearly the only radio astronomer in the world. He later moved to Hawaii and then to Tasmania, in Australia, where he studied very long radio waves until his death in 2002, two days before his 91st birthday. His backyard dish was not thrown away. It was moved to the Green Bank Observatory in West Virginia, where it is still displayed. Reber showed that one curious person with a toolbox can open a whole new branch of science."]},{"heading":"Giants of Steel: Jodrell Bank and Arecibo","paragraphs":["After the Second World War, scientists who had built radar for the war turned their skills to the sky, and radio astronomy grew fast, especially in Britain, Australia and the Netherlands. One of those radar veterans was Bernard Lovell, a physicist at the University of Manchester. He had come to a quiet field at Jodrell Bank, a university botany site in the Cheshire countryside, because the electric trams of Manchester caused too much interference. Lovell dreamed of a giant dish that could be steered to point anywhere in the sky. Building started on 3 September 1952. The dish was 76.2 meters (250 feet) across, wider than three tennis courts placed end to end, held up between two towers on a circular railway track so the whole thing could turn. To save money, the engineers reused huge gear racks from the gun turrets of two old British battleships.","It was a struggle. The price of steel rose, the design had to be changed, and the cost more than doubled, from an original grant of 335,000 pounds to about 700,000 pounds. Then, in October 1957, history came to his rescue. The Soviet Union launched Sputnik 1, the first artificial satellite, and the Jodrell Bank telescope, just finished, was the only instrument in the world able to track the rocket that had carried Sputnik into orbit, using radar. Suddenly the giant dish was front-page news, and people could see that a nation might need such machines. The last of the debt was paid off in 1960 with help from the car-maker Lord Nuffield. Lovell was knighted, and in 1987 the dish was renamed the Lovell Telescope. It is still working today.","Across the Atlantic, an even bigger idea was taking shape. Engineers and scientists, led by William E. Gordon of Cornell University, wanted to study the ionosphere, the electrically charged upper layer of Earth's atmosphere, by bouncing powerful radar signals off it. To catch the faint echoes they needed an enormous dish. A dish that big could never be steered, so they found a natural bowl to put it in: a deep sinkhole in the limestone hills near the town of Arecibo, Puerto Rico.","The Arecibo telescope was completed in November 1963. Its dish was 305 meters (1,000 feet) across, so big that its bowl covered about the same area as 13 American football fields, and it was covered with thousands of aluminum panels. Because the dish could not move, a 900-ton platform holding the receivers hung about 150 meters above it on steel cables strung from three tall concrete towers. By sliding the receivers along a curved arm on that platform, scientists could point at different parts of the sky as Earth turned. For 53 years it was the largest single-dish radio telescope on Earth.","It became far more than an ionosphere station. In 1964 its radar showed that the planet Mercury spins once every 59 days, not 88 days as astronomers had believed. In 1974 Russell Hulse and Joseph Taylor used it to find the first pulsar orbiting another star, which let them test Einstein's ideas about gravity and earned them the 1993 Nobel Prize. In 1992, data from Arecibo revealed the first planets ever confirmed outside our solar system, circling a pulsar. Also in 1974, as a demonstration, it beamed a short coded picture message, the famous Arecibo message, toward a star cluster called Messier 13. But Arecibo was not built to search for aliens; that message was a one-time event at a celebration.","Sadly, the great dish is gone. After years of funding cuts and damage from Hurricane Maria in 2017, two support cables broke in August and November 2020. Engineers decided it was too dangerous to repair, and on 1 December 2020, before it could be safely taken down, the platform crashed into the dish below. Nobody was hurt, but scientists and many proud Puerto Ricans mourned it."]},{"heading":"Echoes of the Big Bang and Blazing Quasars","paragraphs":["Some of the most important discoveries in radio astronomy came from people who were trying to do something else. In 1964 two young radio astronomers at Bell Labs, Arno Penzias and Robert Wilson, got the use of an unusual antenna at Crawford Hill, not far from where Jansky had worked. It was a giant horn, shaped like an ear trumpet lying on its side, about 15 meters long, built in 1959 to talk to NASA's Echo balloon satellites. Its shape kept out stray noise from the ground, which made it perfect for measuring very faint signals.","Penzias and Wilson wanted to use it to measure radio waves from our galaxy. But first they had to understand every bit of noise in their equipment. There was a faint, steady hiss at microwave wavelengths that would not go away. It came from every direction in the sky, day and night, in every season. They checked their wiring and cooled their receiver. They even climbed into the horn and cleaned out droppings left by pigeons nesting inside, which Penzias jokingly called white dielectric material. The pigeons were removed. The hiss stayed.","Meanwhile, less than an hour's drive away at Princeton University, a team led by Robert Dicke had predicted that if the universe began in a hot, dense state, the Big Bang, its leftover glow should still fill all of space, stretched by the expanding universe into faint microwaves. Dicke's team was building an antenna to look for it. When a phone call connected the two groups, the Princeton scientists realized what Penzias and Wilson had found. Dicke reportedly told his team, Boys, we've been scooped.","The hiss was the cosmic microwave background, often shortened to CMB. It is light released about 380,000 years after the Big Bang, when the universe had cooled enough for light to travel freely for the first time. Since then, the expansion of space has stretched it from a hot glow into microwaves with a temperature of only about 2.7 degrees above absolute zero, the coldest possible temperature. It was powerful evidence that the universe really did have a hot beginning. Penzias and Wilson published in 1965 and won the 1978 Nobel Prize in Physics.","Radio astronomy also uncovered the most powerful lights in the universe. By the late 1950s, surveys at Cambridge, England, had listed hundreds of radio sources in catalogs such as the Third Cambridge Catalogue, or 3C. Some matched faint, ordinary-looking stars, which was puzzling, because ordinary stars do not blast out radio waves. In 1962 Cyril Hazard and colleagues in Australia used the Parkes dish to time exactly when the Moon slid in front of one of them, 3C 273, pinning down its position.","In 1963 Maarten Schmidt, a Dutch-born astronomer at Caltech, studied the spectrum of 3C 273's light using the 200-inch Palomar telescope. The lines in the spectrum made no sense until he realized they were familiar hydrogen lines, redshifted by about 16 percent. That huge redshift meant the object was billions of light-years away, so to look as bright as it does it had to be shining like hundreds of galaxies put together, from a region not much bigger than our solar system. These objects were named quasars, short for quasi-stellar radio sources, meaning star-like radio sources. Today we know quasars are powered by gas falling into supermassive black holes at the centers of young galaxies. The one inside 3C 273 is thought to weigh about 900 million times as much as our Sun."]},{"heading":"Little Green Men? Jocelyn Bell and the Pulsars","paragraphs":["In 1967, outside Cambridge, England, a field of about 4 acres was covered with more than a thousand wooden posts strung with over 4,000 wire antennas, connected by many kilometers of cable. A team of students, including a 24-year-old graduate student from Northern Ireland named Jocelyn Bell, had spent about two years helping to build it, hammering posts and fixing wires. Their supervisor, Antony Hewish, had designed it to study how radio signals from quasars twinkle as they pass through the stream of particles blowing out from the Sun.","Bell's job was to run the telescope and analyze its output. There were no computer screens. The data came out as wiggly ink lines on long rolls of chart paper, about 30 meters of paper every day. She read it all by eye, learning to tell the twinkling of quasars apart from interference made by cars, radios and other human gadgets.","In August 1967 she noticed something odd: a small mark, which she later described as a bit of scruff, taking up only about a centimeter of chart paper out of hundreds of meters. It did not look like twinkling or like ordinary interference. She noticed that it kept turning up from the same patch of sky. On 28 November 1967, using a faster chart recorder, she caught the signal in detail. It was a string of sharp pulses, each about 1.337 seconds apart, as regular as a ticking clock.","Nothing natural was known to produce such regular radio pulses. The team even half-seriously wondered whether they had picked up a signal from another civilization, and they gave the source the joke name LGM-1, for Little Green Men 1. But just before Christmas Bell found a second pulsing source in a completely different part of the sky, and soon more. It seemed very unlikely that two different groups of aliens would be signaling Earth at the same time on the same frequency. The answer had to be natural.","The discovery was published in the journal Nature on 24 February 1968, with Hewish listed first and Bell second among five authors. Within months, astronomers worked out what pulsars are: neutron stars, the collapsed cores of giant stars that exploded as supernovae. A neutron star packs more mass than our Sun into a ball only about 20 kilometers wide, and it spins very fast. It sends out beams of radio waves from its magnetic poles, and every time a beam sweeps past Earth, we see a pulse, just like the flash of a lighthouse. The first one is now called PSR B1919+21.","In 1974 the Nobel Prize in Physics went to Antony Hewish, for his role in the discovery of pulsars, and to Martin Ryle, for his pioneering radio techniques. Jocelyn Bell, by then Jocelyn Bell Burnell, was not included. Many astronomers, including the famous British astronomer Fred Hoyle, protested that she should have shared it. Bell Burnell herself has spoken about it calmly and generously. She has said that being a graduate student and a woman lowered her standing at the time. She went on to a long and distinguished career, and in 2018 she received the 3-million-dollar Special Breakthrough Prize in Fundamental Physics. She gave the money away to help women, students from minority backgrounds and refugee students become physicists."]},{"heading":"Many Dishes, One Giant Eye","paragraphs":["Radio telescopes have one big weakness. Remember from the last part that a telescope's resolution, its ability to see fine detail, depends on how wide it is compared with the wavelength of the light it collects. Radio waves are enormous compared with visible light, often millions of times longer. So a radio dish 76 meters wide sees fine detail even more poorly than your own naked eye does in visible light. To see sharp radio pictures, you would need a dish many kilometers across, which is impossible to build.","The clever solution is called interferometry. Instead of one gigantic dish, you use several smaller dishes spread far apart and combine their signals very precisely, timing exactly when each wave crest arrives at each dish. Together they can see detail as fine as one imaginary dish as wide as the distance between the farthest antennas. They do not collect as much total light as a solid dish that size would, but they see the fine detail. As Earth turns, each pair of dishes views the sky from slightly changing angles, gradually filling in the picture. Martin Ryle and his team at Cambridge developed this method, called aperture synthesis, in the 1950s and 1960s, which is why he shared that 1974 Nobel Prize.","The most famous example is the Very Large Array, or VLA, on the high, flat Plains of San Agustin in New Mexico, about 2,100 meters above sea level. It has 27 working dish antennas, each 25 meters across and weighing over 200 tons, arranged in a giant letter Y with each arm about 21 kilometers long. The dishes ride on railway tracks, and a special transporter moves them to new positions every few months: bunched close together for a wide view, or spread out across about 36 kilometers for the sharpest detail. Building began in 1973, and the VLA was dedicated in 1980. After a big electronics upgrade, it was renamed the Karl G. Jansky Very Large Array in 2012.","Bigger single dishes have kept coming too. In the mountains of Guizhou province in southwest China, engineers fitted a dish 500 meters across into a natural limestone bowl, a little like Arecibo but much larger. It is called FAST, the Five-hundred-meter Aperture Spherical radio Telescope, and its last panel was put in place in July 2016. Its surface is made of about 4,450 triangular panels, and motors underneath can pull them into shape so that a 300-meter-wide part of the dish forms a perfect focusing curve wherever the telescope needs to look. Its chief scientist, Nan Rendong, championed it for about 20 years but died in 2017, soon after it was finished. By late 2024, FAST had found more than 1,000 new pulsars.","The most mind-bending interferometer of all is the Event Horizon Telescope. It links radio dishes on different continents, from Hawaii and Arizona to Chile, Mexico, Spain and the South Pole, into one virtual telescope almost as wide as Earth itself. All the dishes look at the same target at the same moment, at a very short radio wavelength of about 1.3 millimeters, and each records its data with the help of an atomic clock. The data was so enormous that it was not sent over the internet. It was stored on hundreds of hard drives and shipped by plane to supercomputer centers to be combined.","In April 2017, eight telescopes at six sites observed together. Two years later, on 10 April 2019, the team of more than 200 researchers revealed the first image of a black hole's shadow: a glowing orange ring around a dark center in the galaxy Messier 87, about 55 million light-years away. That black hole weighs about 6.5 billion times as much as our Sun. Then, on 12 May 2022, they showed the black hole at the center of our own Milky Way, called Sagittarius A*. It weighs about 4 million Suns and lies about 27,000 light-years away, in the same direction where Karl Jansky first heard his mysterious hiss in 1932. From Earth, it looks about as big as a doughnut sitting on the Moon would look.","So in about 90 years, radio astronomy went from a merry-go-round on Model T wheels to a planet-sized eye that can photograph the shadow of a black hole. But radio waves pass easily through the air, while X-rays, most ultraviolet and much of the infrared do not. To see the whole sky in every kind of light, telescopes would have to leave Earth."]}],"deepDive":"Why do radio telescopes need to be so huge? Two reasons: weak signals and long waves. Cosmic radio sources are faint beyond imagination. Astronomers measure them in janskys, where one jansky is 10 to the power of minus 26 watts per square meter for each hertz of bandwidth. Radio astronomers like to point out that all the radio energy ever collected by every radio telescope in history adds up to less than the energy of a single falling snowflake. To catch more of it, you need a bigger collecting area, and receivers cooled to very low temperatures so that their own heat does not drown out the sky. The second reason is resolution. The finest detail a telescope can show is roughly the wavelength divided by the diameter of the dish (in radians). For a 2.4-meter mirror at 500 nanometers, that ratio is about 0.0000002, a twentieth of an arcsecond. For a 76-meter dish at the 21-centimeter wavelength of hydrogen, it is about 0.003, roughly ten arcminutes, a third the width of the full Moon. That is why interferometry is so powerful. The VLA, spread across about 36 km, reaches resolutions of a fraction of an arcsecond. Very Long Baseline Interferometry, where dishes thousands of kilometers apart record data separately with atomic clocks and combine it later, does even better. The Event Horizon Telescope, observing at 1.3 millimeters with an Earth-sized baseline, reached about 20 microarcseconds, sharp enough in principle to read a newspaper in New York from a cafe in Paris. There are trade-offs. An interferometer samples only some of the possible spacings between dishes, so the picture must be reconstructed with careful mathematics, and different teams in the EHT collaboration made images independently to check that the ring was real and not an artifact of the computer methods. Radio astronomy also gave cosmology its strongest early evidence: the cosmic microwave background matched the Big Bang prediction and not the rival Steady State theory, which said the universe had no beginning. Later satellites, COBE (1989), WMAP and Planck, mapped tiny ripples in the CMB, temperature differences of only tens of millionths of a degree, which became the seeds of galaxies. Finally, the hydrogen line at 21 cm, first detected in 1951, let astronomers map the spiral arms of our own galaxy, hidden from optical telescopes by dust.","funFact":"Karl Jansky's first radio telescope, which discovered radio waves from the center of the Milky Way, rolled around in circles on four wheels taken from Ford Model T cars.","check":{"q":"What did Jocelyn Bell discover in 1967 using a radio telescope near Cambridge?","a":"Pulsars, fast-spinning neutron stars that send out regular radio pulses","wrong":["The cosmic microwave background","The first quasar, 3C 273","Radio waves from the center of the Milky Way"]},"sources":[{"title":"Karl Guthe Jansky","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Karl_Guthe_Jansky"},{"title":"Grote Reber","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Grote_Reber"},{"title":"Lovell Telescope","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Lovell_Telescope"},{"title":"Arecibo Telescope","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Arecibo_Telescope"},{"title":"Cosmic microwave background","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Cosmic_microwave_background"},{"title":"Jocelyn Bell Burnell","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Jocelyn_Bell_Burnell"},{"title":"Astronomers Capture First Image of a Black Hole","publisher":"ESO","url":"https://www.eso.org/public/news/eso1907/"},{"title":"Astronomers reveal first image of the black hole at the heart of our galaxy","publisher":"ESO","url":"https://www.eso.org/public/news/eso2208-eht-mw/"}],"photos":[{"src":"img/deep/telescope/15-1.jpg","alt":"Karl Jansky with his rotating \"merry-go-round\" antenna on wheels at Bell Labs, Holmdel, New Jersey","file":"JanskyatAntenna hi.tif","url":"https://commons.wikimedia.org/wiki/File:JanskyatAntenna_hi.tif","author":"Minimum credit line: Image courtesy of NRAO/AUI (for details, see Image Use…","license":"CC BY 3.0"},{"src":"img/deep/telescope/15-2.jpg","alt":"The Lovell Telescope, a giant 76-meter radio dish at Jodrell Bank Observatory in England","file":"Lovell Telescope1.jpg","url":"https://commons.wikimedia.org/wiki/File:Lovell_Telescope1.jpg","author":"Mike Peel; Jodrell Bank Centre for Astrophysics, University of Manchester","license":"CC BY-SA 4.0"},{"src":"img/deep/telescope/15-3.jpg","alt":"The Event Horizon Telescope's 2019 picture of the black hole in galaxy M87: a glowing ring around a dark center","file":"Black hole - Messier 87 crop max res.jpg","url":"https://commons.wikimedia.org/wiki/File:Black_hole_-_Messier_87_crop_max_res.jpg","author":"Event Horizon Telescope, uploader cropped and converted TIF to JPG","license":"CC BY 4.0"}],"words":4389},{"n":16,"title":"Above the Air: Hubble and the Space Telescopes","when":"1946 – today","summary":"Earth's air makes stars twinkle and blocks lots of light, so scientists dreamed of a telescope in space. In 1990 the Hubble Space Telescope finally flew, but its first pictures were blurry! Astronauts gave it 'glasses' in 1993, and since then Hubble has shown us thousands of faraway galaxies and baby stars being born.","sections":[{"heading":"The Problem With Air","paragraphs":["Picture yourself lying on the bottom of a swimming pool, looking up at a streetlight through the water. Even if the water is perfectly clear, every ripple makes the light wobble and dance. That is roughly what astronomers on the ground are doing. We live at the bottom of an ocean of air about 100 kilometers deep, and that air is always moving. Warm and cool pockets bend starlight in slightly different directions, many times a second. To our eyes, this makes stars twinkle. To a big telescope, it smears every star into a fuzzy, jittering blob.","The air causes a second, even bigger problem: it blocks light. As we saw in the last part, radio waves and visible light pass through Earth's atmosphere quite easily. But the ozone layer soaks up most ultraviolet light, water vapor swallows much of the infrared, and the air completely stops X-rays and gamma rays from space. That protection is wonderful for living things, because those rays can harm our cells. But for astronomers, it means whole parts of the universe are hidden behind a curtain.","So here is an important point. Space telescopes do not see better because they are closer to the stars. Hubble is only a few hundred kilometers above the ground, while even the nearest star beyond the Sun is about 40 trillion kilometers away. Being a few hundred kilometers closer makes no difference at all. Space telescopes see better because they are above the blurring, light-blocking air. Up there, stars shine as sharp, steady points, the sky is truly black even in daytime, and ultraviolet, X-ray and infrared light can reach the telescope.","People had dreamed of observatories in space since rockets were still science fiction. The German rocket pioneer Hermann Oberth wrote about a telescope in orbit in the 1920s. But the person who turned the dream into a serious scientific plan was Lyman Spitzer Jr., a young American astrophysicist. In 1946, just after the Second World War, he wrote a report for Project RAND, a research group working for the United States military, called Astronomical Advantages of an Extra-Terrestrial Observatory.","Spitzer was 32 years old, and the first satellite would not be launched for another 11 years. Yet he explained clearly what a big telescope in space could do: see far finer detail without the air's blur, study ultraviolet and infrared light that never reaches the ground, and observe faint objects against a perfectly dark sky. He suggested a telescope with a mirror several meters across, and he said that such a telescope might reveal the structure of galaxies and the size of the universe. For the next 50 years he never stopped arguing for it, in meetings, reports and visits to Washington. Many people later said that without Spitzer's steady pushing, the Hubble Space Telescope might never have been built."]},{"heading":"First Eyes Above the Air","paragraphs":["Before anyone could launch a giant telescope, astronomers had to learn how to do any astronomy at all from space. The first attempts used rockets that zoomed above most of the atmosphere for just a few minutes before falling back. After the Second World War, American scientists packed instruments into captured German V-2 rockets and recorded the Sun's ultraviolet light for the first time in 1946.","In 1962 a team led by the Italian-born physicist Riccardo Giacconi launched a small X-ray detector on a rocket from New Mexico. They were hoping to see X-rays from the Moon. Instead they found an extremely bright X-ray source in the constellation Scorpius, now called Scorpius X-1, far beyond our solar system. Nobody had expected anything outside the Sun to glow so strongly in X-rays. It was the birth of X-ray astronomy.","Rocket flights were far too short for careful study, so the next step was satellites. NASA's Orbiting Astronomical Observatories studied ultraviolet starlight. OAO-2, launched in 1968, was the first truly successful one, and OAO-3, launched in 1972, was named Copernicus, honoring the 500th anniversary of the birth of the astronomer who put the Sun at the center, which fell the following year. It carried an ultraviolet telescope built by a team at Princeton led by none other than Lyman Spitzer.","X-ray astronomers got their own satellite on 12 December 1970. It was launched from an Italian-run platform in the sea off the coast of Kenya, because being close to the equator helped the rocket. That day was the seventh anniversary of Kenya's independence, so the satellite was named Uhuru, the Swahili word for freedom. Uhuru, built by Giacconi's team, made the first complete map of the sky in X-rays, listing 339 sources. It studied stars that were being torn apart by tiny, super-dense partners, and it helped show that one X-ray source, Cygnus X-1, contains an object so heavy and compact that it became one of the first strong candidates for a black hole. Giacconi later shared the 2002 Nobel Prize in Physics and became the first permanent director of the institute that runs Hubble's science.","Each of these missions taught engineers how to point a telescope precisely while racing around Earth, how to keep instruments working in the cold and radiation of space, and how to send data home by radio. They were the training ground for something much more ambitious."]},{"heading":"The Mother of Hubble","paragraphs":["In the 1930s, an 11-year-old girl named Nancy Grace Roman, who had been born in Nashville, Tennessee, started an astronomy club with her friends. When she told a school guidance counselor that she wanted to take extra mathematics so she could become an astronomer, the counselor reportedly looked down her nose and asked what kind of lady would take mathematics instead of Latin. Roman did not listen. She earned a PhD in astronomy from the University of Chicago in 1949 and worked at Yerkes Observatory, home of the giant 40-inch refractor we visited earlier in this story.","In 1959, a year after NASA was created, Roman joined the new space agency, and in 1960 she became its first chief of astronomy. She was the first woman to hold an executive job at NASA. Her task was huge: decide what astronomy NASA should do in space, and then make it happen. She helped plan the Orbiting Astronomical Observatories and many other missions. But her greatest project was the one Spitzer had dreamed of, at first called the Large Space Telescope.","Building a giant telescope in space was not only a scientific problem. It was a money and politics problem. Roman brought astronomers together to agree on what the telescope should do, set up its science working groups starting in 1971, and helped convince members of the United States Congress to pay for it. In the mid-1970s Congress threatened to cancel the project. Spitzer, Roman and other astronomers lobbied hard, and to save money the planned mirror was shrunk from 3 meters to 2.4 meters. The European Space Agency joined as a partner, supplying a camera and the solar panels in exchange for observing time for European astronomers. In 1977 Congress finally approved the money.","Roman left NASA in 1979, long before launch, but she is often called the mother of Hubble because the telescope might not exist without her organizing and persuading. In 2020 NASA named its next big space telescope after her: the Nancy Grace Roman Space Telescope. In 1983 the Large Space Telescope got its own famous name, the Hubble Space Telescope, after Edwin Hubble, who had shown that the universe is full of galaxies. Hubble the astronomer had nothing to do with building it. He died in 1953, decades before it flew.","Construction was long and complicated. The main mirror was ground and polished by the Perkin-Elmer company in Connecticut from a special low-expansion glass that would not change shape much when it warmed or cooled. The telescope was planned to launch in 1983, then 1986. Then, in January 1986, the Space Shuttle Challenger broke apart shortly after launch, and all shuttle flights stopped for more than two years. Hubble waited in a clean room, carefully stored, while costs kept rising."]},{"heading":"Launch Day, and a Terrible Surprise","paragraphs":["On the morning of 24 April 1990, the Space Shuttle Discovery roared away from the Kennedy Space Center in Florida on mission STS-31. Folded into its cargo bay was the Hubble Space Telescope: about 13 meters long, 4.2 meters wide, roughly the size of a school bus, and weighing about 11 tonnes. The next day, astronaut Steven Hawley used the shuttle's robotic arm to lift Hubble out of the cargo bay and release it into orbit about 610 kilometers above Earth (it has slowly sunk since, to under 500 kilometers today). Hubble began circling the planet roughly every 95 minutes, racing along at about 27,000 kilometers per hour, fast enough to cross the United States in about ten minutes.","Inside, Hubble works much like a Cassegrain telescope from part 7, just much bigger and far more precise. Light enters the open end of the tube and travels down to the 2.4-meter primary mirror, which is coated with a whisper-thin layer of aluminum. The curved mirror reflects the light back up to a smaller secondary mirror, about 30 centimeters across, which sends it back down through a hole in the middle of the primary mirror to the cameras and other instruments behind it. Hubble does not have an eyepiece; nobody looks through it. Its instruments are electronic detectors, and its pictures are radioed to the ground. To photograph faint galaxies, it must stay locked on a target with extraordinary steadiness, to within a tiny fraction of an arcsecond, which NASA compares to holding a laser beam on a dime about 320 kilometers (200 miles) away.","Excitement was enormous. Then, as engineers began testing and focusing the telescope in May and June 1990, they found something that made their stomachs drop. The images were blurry. A bright star did not shrink to a tight point; instead, it had a sharp center surrounded by a wide, fuzzy halo. No matter how they moved the secondary mirror, they could not bring it into focus. At a press conference in June 1990, NASA admitted that its brand-new, billion-dollar telescope had a flaw in its main mirror. Newspapers and late-night comedians mocked it as a giant mistake.","What had gone wrong? Not a forgotten focus knob. The mirror had been ground and polished extremely smoothly, among the smoothest large mirrors ever made, but to slightly the wrong shape. Near its outer edge, it was too flat by about 2.2 micrometers, roughly one-fiftieth the thickness of a sheet of paper. That tiny error was enough to cause spherical aberration, the same blurring problem from curved lenses that we met back in part 6: light from the edge of the mirror came to a focus at a slightly different place from light hitting the middle, so no single focus was sharp.","An investigation board, led by Lew Allen of NASA's Jet Propulsion Laboratory, tracked down the cause. While polishing the mirror, Perkin-Elmer had tested its shape using a device called a reflective null corrector, which shines light on the mirror and shows whether the curve is exactly right. One lens inside that testing device was out of position by about 1.3 millimeters, because a measuring rod had been set up wrongly. So the testing tool itself was wrong, and the polishers carefully and precisely shaped the mirror to match a faulty guide. Other simpler tests had hinted at a problem, but those warnings were not followed up. A backup mirror made by the Kodak company, which was never used, is now displayed at the Smithsonian's National Air and Space Museum.","The good news was hidden inside the bad news. Because the error was so precise and so well measured, engineers knew exactly how wrong the mirror was. And that meant they could design corrective optics with exactly the opposite error, just like the lenses in a pair of glasses. Hubble had been built to be visited and repaired by astronauts. Now that would be put to the test."]},{"heading":"Glasses in Orbit: The Servicing Missions","paragraphs":["On 2 December 1993, the Space Shuttle Endeavour launched on mission STS-61, one of the most difficult and closely watched spaceflights in NASA's history. Its seven astronauts had trained for many months in giant water tanks, practicing every move in bulky spacesuits. After catching up with Hubble, astronaut Claude Nicollier, a Swiss astronomer flying for the European Space Agency, used the shuttle's robotic arm to grab the telescope and settle it upright in the cargo bay.","Then came five spacewalks on five days, a record at the time, totaling more than 35 hours. Working in pairs, Story Musgrave and Jeffrey Hoffman took turns with Kathryn Thornton and Tom Akers. They replaced Hubble's main camera with a new one, the Wide Field and Planetary Camera 2, which had the correction built into its own optics. They installed a refrigerator-sized box called COSTAR, which slid tiny corrective mirrors into the light path in front of the other instruments, like putting glasses on them. They also replaced wobbly solar panels, gyroscopes and other worn parts. One damaged solar array would not fold up properly, so after Akers disconnected it, Thornton let it go and it drifted away into space.","Weeks later, in January 1994, NASA showed before-and-after pictures. Stars that had been blurry blobs were now sharp pinpoints. The fix had worked. From then on, Hubble produced some of the sharpest images astronomers had ever seen, several times sharper than the best ground-based photos of that era.","Astronauts went back to Hubble four more times, so there were five servicing missions in all: 1993, 1997, 1999, 2002 and 2009. In February 1997 the crew of Discovery installed an infrared camera and a powerful spectrograph. In December 1999, after several gyroscopes failed, another Discovery crew replaced all six of them and gave Hubble a new computer. In March 2002, Columbia's astronauts installed the Advanced Camera for Surveys and new solar arrays. Each visit made the telescope better than it was at launch, a little like taking a car to the garage and getting it back with a brand-new engine.","Then came tragedy. In February 2003, the Space Shuttle Columbia broke apart while returning to Earth, and its seven astronauts were killed. In 2004 NASA's leader, Sean O'Keefe, cancelled the last planned Hubble servicing mission, worried it was too risky. Astronomers, schoolchildren and members of the public protested, and many wrote letters to save Hubble. In 2006 the next NASA administrator, Michael Griffin, decided the mission could go ahead with extra safety plans.","In May 2009, the Space Shuttle Atlantis made the final visit. Over five spacewalks, its crew installed the Wide Field Camera 3 and the Cosmic Origins Spectrograph, repaired two broken instruments that had never been designed to be fixed in space, and added new batteries and gyroscopes. They also removed COSTAR, because all the newer instruments now carried their own correction. COSTAR came home and is now in the National Air and Space Museum too. Astronaut Mike Massimino, who struggled with a stuck bolt during one repair, became one of the first people to post updates on Twitter from space during that mission. In all, 32 astronauts flew to Hubble, and spacewalkers spent more than 170 hours working on it."]},{"heading":"Staring Into the Dark: The Deep Fields","paragraphs":["In 1995, Robert Williams, the director of the Space Telescope Science Institute in Baltimore, which runs Hubble's science, made a daring choice. As director he controlled a small share of Hubble's observing time to use as he saw fit. He decided to point the telescope at one tiny, empty-looking patch of sky in the constellation Ursa Major, near the Big Dipper, and simply stare at it for days. Some astronomers worried it was a waste of precious time. What if there was nothing there?","Between 18 and 28 December 1995, Hubble took 342 separate exposures of that patch, through filters for ultraviolet, blue, red and near-infrared light. The patch was only about 2.6 arcminutes wide, roughly one twelfth of the width of the full Moon, or about as big as a tennis ball seen from 100 meters away. It covered about one 24-millionth of the whole sky. Astronomers had chosen it precisely because it contained no bright stars or nearby galaxies that would get in the way.","When the combined image was released in January 1996, it stunned the world. The empty patch was crowded with about 3,000 objects, and nearly all of them were galaxies, not stars. Some were spirals and some were round blobs, many small, red and strangely shaped. Because light takes time to travel, the faintest of them were seen as they were billions of years ago, when the universe was young and galaxies were still forming and crashing together. This picture became known as the Hubble Deep Field.","The meaning was mind-boggling. If one tiny speck of sky holds thousands of galaxies, and the same is true in every direction, then the observable universe must contain an enormous number of galaxies, at least 100 billion and probably much more. Later deep views went even further. The Hubble Ultra Deep Field, collected in 2003 and 2004 in the southern constellation Fornax, combined about 11 days of exposures and showed about 10,000 galaxies in a patch about a tenth the width of the full Moon."]},{"heading":"Pillars, Comets and the Age of the Universe","paragraphs":["On 1 April 1995, astronomers Jeff Hester and Paul Scowen of Arizona State University used Hubble to photograph part of the Eagle Nebula, a star-forming cloud about 6,500 to 7,000 light-years away in the constellation Serpens. The picture showed three huge, dark, finger-like columns of cold gas and dust rising up, lit from behind and eaten away at their edges by ultraviolet light from hot young stars nearby. Inside the columns, new stars are being born. The tallest pillar is about four light-years long, so it would take light four years to travel from its bottom to its top. The image, called the Pillars of Creation, became one of the most famous science pictures ever taken, printed on posters, book covers and T-shirts.","In July 1994, just months after its repair, Hubble had a front-row seat for a cosmic crash. A comet called Shoemaker-Levy 9 had been torn into more than 20 pieces by Jupiter's gravity, and over about six days the fragments slammed into the giant planet. Hubble photographed dark scars, some bigger than Earth, spreading in Jupiter's clouds. It was the first time people had watched two solar system bodies collide.","One of the main reasons Hubble was built was to measure the Hubble constant, which tells how fast the universe is expanding. Remember Henrietta Leavitt's Cepheid stars from part 12: their regular pulsing tells you their true brightness, so you can work out their distance. Hubble's sharp vision let a team led by Wendy Freedman find Cepheids in galaxies far beyond the reach of ground telescopes. In 2001 they announced a value of about 72 kilometers per second per megaparsec, with an uncertainty of about 10 percent, where before astronomers had argued over values that differed by a factor of two. Running the expansion backward tells you how long ago it began. Hubble's measurements, combined with maps of the cosmic microwave background from other spacecraft, helped pin the age of the universe at about 13.8 billion years.","Then came a shock. In 1998 two teams of astronomers, one led by Saul Perlmutter and the other including Brian Schmidt and Adam Riess, studied a kind of exploding star called a Type Ia supernova. These explosions all reach about the same peak brightness, so they work like standard light bulbs: the dimmer one looks, the farther away it is. Using ground telescopes, with Hubble measuring some of the most distant ones, the teams found that faraway supernovae were fainter than expected. That meant the expansion of the universe is not slowing down, as everyone had assumed, but speeding up. Something, now called dark energy, seems to be pushing space apart. Perlmutter, Schmidt and Riess shared the 2011 Nobel Prize in Physics. Nobody yet knows what dark energy really is.","Hubble has done far more besides. It has measured the masses of supermassive black holes at the centers of galaxies, found small moons of Pluto, watched auroras on Jupiter and Saturn, and helped detect the atmospheres of planets around other stars. By 2024 it had made more than 1.7 million observations, and astronomers had written more than 23,000 scientific papers using its data."]},{"heading":"The Great Observatories, and Hubble Today","paragraphs":["Hubble sees mostly visible and ultraviolet light, plus a little near-infrared. To see the whole universe, NASA planned a family of four big space telescopes, called the Great Observatories, each looking at a different kind of light. Hubble was the first.","The second was the Compton Gamma Ray Observatory, launched by the Space Shuttle Atlantis in April 1991. Weighing about 17 tonnes, it was one of the heaviest science satellites ever carried by the shuttle. Compton studied gamma rays, including mysterious gamma-ray bursts, brief flashes that it showed come from all over the sky, from far beyond our galaxy. After one of its gyroscopes failed, NASA deliberately steered it down into the Pacific Ocean in June 2000 so that its heavy parts could not fall on anyone.","The third was the Chandra X-ray Observatory, named after the Indian-American astrophysicist Subrahmanyan Chandrasekhar. It was launched by the Space Shuttle Columbia in July 1999, on a mission commanded by Eileen Collins, the first woman to command a shuttle flight. X-rays are tricky to focus because they shoot straight into ordinary mirrors instead of bouncing off. So Chandra uses nested mirrors shaped like barrel-shaped tubes, which X-rays strike at a very shallow angle, like a stone skipping across water. Chandra studies exploded stars, hot gas in clusters of galaxies and matter swirling into black holes, and it is still working.","The fourth was the Spitzer Space Telescope, named after Lyman Spitzer and launched on a Delta II rocket in August 2003. It studied infrared light, so it had to be kept extremely cold, and instead of orbiting Earth it trailed behind Earth in its path around the Sun, away from Earth's warmth. Spitzer looked through dust clouds to see stars being born and measured light from planets around other stars. It kept working until January 2020. Together, the Great Observatories showed that the universe looks completely different in every kind of light.","And Hubble? More than 35 years after launch, it is still working, and it has not been replaced. The James Webb Space Telescope, which we meet in part 18, mainly sees infrared light, while Hubble mainly sees visible and ultraviolet light, so the two telescopes do different jobs and often team up. With no more shuttle visits, Hubble is slowly aging. Its gyroscopes, spinning wheels that sense how the telescope is turning, keep wearing out. Since 2024 Hubble has run on just one gyroscope at a time, keeping another in reserve, to stretch its life. This makes it a bit less efficient and unable to follow targets that move quickly across the sky, such as objects closer than Mars, but it can still do most of its science.","Its orbit is also very slowly sinking, because even at that height a faint trace of air drags on it. Someday, perhaps in the 2030s, it will need to be either boosted higher or guided safely down into the ocean. Until then, Hubble keeps circling, taking pictures that have changed how everyone on Earth imagines the universe. Space, though, was not the only place to fight the blur. Back on the ground, engineers were learning to build mirrors in pieces and bend them hundreds of times a second to undo the twinkling of the stars."]}],"deepDive":"Why exactly does a 2.4-meter telescope in orbit beat much larger telescopes on the ground? The answer is the difference between the diffraction limit and seeing. Every telescope has a theoretical sharpest detail it can show, set by its aperture and the wavelength of light: roughly 1.22 times the wavelength divided by the diameter. For Hubble at 500 nanometers this is about 0.05 arcseconds. A 10-meter telescope on the ground could in theory reach about 0.013 arcseconds, but the turbulent atmosphere typically blurs stars to 0.5 to 1 arcsecond even at the best mountain sites. So before adaptive optics, Hubble's images were often 10 to 20 times sharper in practice than those of much larger ground telescopes. A second advantage is the dark, stable sky: from orbit there is no airglow at many wavelengths, no clouds and no changing transparency, which makes Hubble excellent at precise measurements of brightness, essential for the supernova and Cepheid work behind the Hubble constant and dark energy. The mirror flaw is a classic engineering lesson. The primary mirror's shape, a hyperboloid in Hubble's Ritchey-Chretien design, was polished to within about 10 nanometers of the shape the faulty null corrector called for, but the conic constant came out about -1.0139 instead of the intended -1.0023. Investigators noted that two simpler test instruments had shown a disagreement that was dismissed because the null corrector was trusted as the most accurate tool. The lesson, test independently and take disagreements seriously, is now taught in engineering courses. There is also a lively debate about cost. Hubble cost about 4.7 billion dollars at launch (in 2010 dollars), and with servicing and operations its lifetime cost has grown past 10 billion, making it NASA's most expensive science mission. Supporters point to more than 23,000 scientific papers and an archive that scientists still mine for new discoveries. Today another debate continues over whether to boost Hubble's slowly sinking orbit; in 2024 NASA decided against a proposed private servicing mission, judging the risk to the telescope too high for now. Finally, Hubble's results helped open one of today's biggest puzzles: the Hubble tension. Measurements of the expansion rate from nearby Cepheids and supernovae come out near 73 km/s per megaparsec, while values inferred from the cosmic microwave background are near 67, and nobody yet knows why.","funFact":"The flaw that made Hubble's first pictures blurry was an error of only about 2.2 micrometers at the edge of its mirror, roughly one-fiftieth the thickness of a sheet of paper.","check":{"q":"How did astronauts fix Hubble's blurry vision in December 1993?","a":"They installed corrective optics, like glasses, including a new camera and the COSTAR device","wrong":["They polished the mirror again while in orbit","They turned the focus knob that had been forgotten","They brought Hubble back to Earth and replaced the mirror"]},"sources":[{"title":"Hubble Space Telescope","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Hubble_Space_Telescope"},{"title":"Hubble by the Numbers","publisher":"NASA","url":"https://science.nasa.gov/mission/hubble/overview/about-hubble/hubble-by-the-numbers/"},{"title":"Nancy Grace Roman","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Nancy_Grace_Roman"},{"title":"STS-61","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/STS-61"},{"title":"Hubble Deep Field","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Hubble_Deep_Field"},{"title":"Pillars of Creation","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Pillars_of_Creation"},{"title":"Great Observatories program","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Great_Observatories_program"},{"title":"The Uhuru Satellite","publisher":"NASA HEASARC","url":"https://heasarc.gsfc.nasa.gov/docs/uhuru/uhuru.html"}],"photos":[{"src":"img/deep/telescope/16-1.jpg","alt":"The Hubble Space Telescope in orbit, photographed from Space Shuttle Atlantis as it approached for the 2009 STS-125 servicing mission.","file":"STS-125 approaching the Hubble Space Telescope.jpg","url":"https://commons.wikimedia.org/wiki/File:STS-125_approaching_the_Hubble_Space_Telescope.jpg","author":"NASA","license":"Public domain"},{"src":"img/deep/telescope/16-2.jpg","alt":"Astronauts Story Musgrave and Jeffrey Hoffman working on Hubble during the first STS-61 repair spacewalk, December 1993.","file":"Astronauts Musgrave and Hoffman during First STS-61 Extravehicular Activity (28051107481).jpg","url":"https://commons.wikimedia.org/wiki/File:Astronauts_Musgrave_and_Hoffman_during_First_STS-61_Extravehicular_Activity_(28051107481).jpg","author":"NASA Hubble Space Telescope","license":"Public domain"},{"src":"img/deep/telescope/16-3.jpg","alt":"Hubble's famous 1995 \"Pillars of Creation\": towers of gas and dust where stars are born in the Eagle Nebula.","file":"Eagle nebula pillars.jpg","url":"https://commons.wikimedia.org/wiki/File:Eagle_nebula_pillars.jpg","author":"Credit: NASA, Jeff Hester, and Paul Scowen (Arizona State University)","license":"Public domain"}],"words":4322},{"n":17,"title":"Mirrors in Pieces and Twinkle-Cancelling","when":"1969 – today","summary":"Telescopes on the ground got three super-powers. A tiny chip called a CCD caught starlight far better than film, giant mirrors were built from honeycomb-shaped pieces, and bendy mirrors learned to cancel the twinkle of the air. Now mountaintop giants in Hawaii and Chile take some of the sharpest pictures ever made.","sections":[{"heading":"A Chip That Catches Light","paragraphs":["For about a hundred years, the eye at the back of every big telescope was a glass photographic plate. Astronomers loaded the plates in the dark, exposed them for hours, developed them in chemical baths, and then studied the tiny black specks with magnifiers. It worked brilliantly, as we saw with Hubble's Cepheid in Andromeda. But film and plates have a secret weakness: they are wasteful. Out of every 100 particles of light (photons) that land on a photographic plate, only about 2 actually leave a mark. The other 98 are simply lost.","The machine that fixed this was not invented by astronomers at all. In 1969, two physicists at Bell Telephone Laboratories in New Jersey, the same research lab where Karl Jansky had found radio waves from the Milky Way, were working on a new kind of computer memory. Willard Boyle, a Canadian, and George Smith, an American, were told their department needed a fresh idea for storing information on silicon chips. According to their own telling, they sketched the basic plan on a blackboard in a meeting that lasted about an hour.","Their invention was the charge-coupled device, or CCD. It is a flat chip of silicon divided into a grid of tiny squares called pixels. When a photon hits a pixel, it can knock loose an electron, a tiny particle with an electric charge. The longer the light shines, the more electrons pile up in each pixel, like rain filling a grid of buckets left out in a storm. Bright parts of the picture fill their buckets quickly; dark parts collect only a few drops.","Then comes the clever part, the 'charge-coupled' trick. At the end of an exposure, the chip uses carefully timed voltages to shuffle every bucket's charge, row by row, toward one corner, a bit like passing buckets along a line of firefighters. At the corner, an amplifier measures each little packet of charge, one at a time, and turns it into a number. Put all the numbers back in their grid and you have a digital picture. In April 1970, Smith and colleagues Gil Amelio and Michael Tompsett showed the first working device, and Tompsett soon led the way in turning it into a camera.","Astronomers realised quickly that the CCD was a gift. A good CCD records around 70 percent of the photons that land on it, and the best modern astronomy chips do even better. Compared with about 2 percent for film, that is like turning a small telescope into a huge one without touching the mirror. CCDs also give a straight, honest count: twice as much light means twice as many electrons, so astronomers can measure brightness precisely. And because the result is already numbers, a computer can add, subtract, sharpen and compare images in ways a glass plate never could.","By the late 1970s and 1980s, CCD cameras were spreading to observatories around the world, and photographic plates slowly disappeared. Hubble carried CCDs into orbit in 1990. Today almost every professional optical telescope uses electronic sensors. In 2009, Boyle and Smith shared the Nobel Prize in Physics for inventing the CCD. Most phone cameras now use a close cousin called a CMOS sensor, which reads each pixel in a slightly different way, but the basic idea is the same one born at Bell Labs: turn light into electric charge, pixel by pixel, then count it."]},{"heading":"Why Not Just Build One Bigger Mirror?","paragraphs":["Remember the most important rule of telescopes from Part 14: the bigger the aperture, the more light you collect and the finer the detail you can see. So after the 200-inch (5.1-meter) Hale Telescope at Palomar opened in 1948, astronomers naturally wanted something even larger. The problem was the mirror itself.","A traditional telescope mirror is a thick disk of glass. To keep its precise curve when the telescope tilts, it has to be stiff, and stiff usually means thick and heavy. The Palomar mirror weighs about 14.5 tons even though its back was cast as a honeycomb to save weight. Double the width of a solid mirror of the same shape and its weight goes up roughly eight times. A heavier mirror needs a heavier tube, a heavier mount and a bigger dome. Thick glass also takes many hours to cool down at night, and while it cools, warm air shimmering above it blurs the view. The Soviet Union built a 6-meter telescope in the Caucasus Mountains, which began work in the mid-1970s, and its huge solid mirror had exactly these troubles.","Astronomers came up with several escape routes. One was to make mirrors thin and floppy, then hold them in the right shape with computer-controlled pushers underneath, an idea called active optics. Another, used by the Steward Observatory Mirror Lab in Arizona, was to cast lightweight honeycomb mirrors inside a spinning furnace so the molten glass naturally curves into a bowl shape. But one young astronomer at the University of California came up with the boldest answer of all: do not build one giant mirror. Build lots of small ones and make them work together as if they were one."]},{"heading":"Keck: Thirty-Six Hexagons Pretending to Be One Mirror","paragraphs":["That astronomer was Jerry Nelson. In 1977, working with his colleague Terry Mast, he began developing a design for a 10-meter telescope whose main mirror would be made of many smaller pieces. Lots of experts doubted it could work. Each piece would need to be curved in a slightly different off-centre way, because each sits at a different spot on the big curved bowl. And all the pieces would have to line up with each other to a precision far smaller than a wavelength of light. If they didn't, you would just get dozens of separate blurry images instead of one sharp one.","Nelson's team solved both problems. They chose hexagons, six-sided shapes, because hexagons fit together with no gaps, just like the cells in a honeycomb or the tiles on a bathroom floor. To make each oddly curved segment, they invented a technique called stressed-mirror polishing: they bent a round blank of glass with carefully calculated forces, polished an ordinary simple curve into it, and then let go. When the forces were released, the glass sprang into exactly the strange off-centre shape it needed. The round pieces were then cut into hexagons.","The money came from a foundation set up by the oil businessman William Myron Keck. In 1985, the W. M. Keck Foundation gave 70 million dollars to start building, and private grants for the project eventually came to more than 140 million dollars. Construction began on the summit of Maunakea, the tallest mountain on the island of Hawaii, in September 1985. The Keck I telescope first looked at the sky on 24 November 1990 with only 9 of its segments in place. With all 36 segments installed, it began regular science in May 1993. Its twin, Keck II, saw first light on 27 April 1996 and started observing later that year, when NASA joined the partnership.","Each Keck telescope has a primary mirror 10 meters (about 33 feet) across, twice the width of Palomar's. It is made of 36 hexagonal segments, each about 1.8 meters across and only about 7.5 centimeters thick, weighing roughly half a tonne. Behind every segment are three motorised pushers called actuators, and along the edges are sensors that measure how each piece sits compared with its neighbours. About twice every second, a computer reads the sensors and nudges the actuators, keeping the whole surface in the right shape to within about 4 nanometers, which is thousands of times thinner than a human hair. Even so, each telescope still weighs about 300 tonnes, mostly steel, and the domes stand roughly eight stories tall.","The two Kecks sit about 85 meters apart, and for years they were the largest optical and infrared telescopes on Earth. Jerry Nelson's idea did not just give us two great telescopes; it showed the whole world how to build big. Spain's Gran Telescopio Canarias on La Palma in the Canary Islands, about 10.4 meters across, uses 36 hexagonal segments too. The giant telescopes being built today, which we will visit in Part 20, all borrow from his segmented-mirror recipe. Nelson kept working on new giant-telescope projects until his death in 2017."]},{"heading":"Cancelling the Twinkle: Adaptive Optics","paragraphs":["A 10-meter mirror should, in theory, see incredibly fine detail. In visible light it could split two points of light only about a hundredth of an arcsecond apart, which is like spotting a small coin from about 300 kilometers away. But in practice, on an ordinary night, Keck's raw images were not much sharper than those of a backyard telescope. The culprit is the one we met in Part 14: Earth's restless air.","Here is what happens. Starlight travels for years, sometimes billions of years, across nearly empty space as a perfectly flat 'wavefront', like a calm sheet of ripples marching in step. Then, in the last few thousandths of a second of its journey, it plunges through our atmosphere. Pockets of warmer and cooler air, each roughly the size of a hand or a dinner plate, bend the light by slightly different amounts. The flat wavefront gets crumpled like a sheet of aluminium foil. To your eye, this makes a star twinkle. To a giant telescope, it smears what should be a sharp point into a wobbling, boiling blob. And because the air keeps moving, the crumpling changes every few thousandths of a second.","The idea for fixing this came surprisingly early. In 1953, the American astronomer Horace Babcock suggested measuring the distortion and correcting it with a flexible optical surface, in real time. The technology to do it simply did not exist yet. During the Cold War, military scientists, especially in the United States, worked on similar systems so they could take sharp pictures of satellites passing overhead. Some of that work was later made public, and from the late 1980s and into the 1990s, as computers became fast enough, adaptive optics finally became a practical tool for astronomers.","An adaptive optics system has three main parts, and they work as a team. First, a wavefront sensor looks at a bright reference star and measures exactly how its light has been crumpled. One common type splits the beam into a grid of tiny lenses; if the air is calm, every little lens makes a dot in a neat pattern, and wherever the dots shift, the sensor knows the light arrived tilted. Second, a fast computer works out the opposite shape needed to un-crumple the light. Third, a deformable mirror, a thin, bendable mirror with hundreds or even thousands of tiny pushers on its back, changes shape to match. It does all this hundreds to about a thousand times every second, fighting the air faster than the air can change.","The result is like magic. A star that looked like a fuzzy cotton ball tightens into a crisp point. Two stars that were one blur become two. The improvement works best in infrared light, which has longer waves that are less disturbed, and on a big telescope it can make images sharper than Hubble's, because the ground-based mirror is far wider than Hubble's 2.4 meters. Keck II started using adaptive optics around 1999, and today all the world's biggest telescopes rely on it.","There was one catch. The wavefront sensor needs a fairly bright star very close to the thing you want to study, and most of the sky doesn't have one handy. So astronomers decided to make their own stars. About 90 kilometers above the ground lies a thin layer of sodium atoms, left behind by tiny meteors burning up. When a powerful laser tuned to exactly the right shade of yellow-orange light, the same colour as old sodium streetlamps, shines up into that layer, the atoms glow. From the telescope, the glowing spot looks like a small, faint star that can be placed anywhere. This is a laser guide star. Keck began using one in 2004, and the beams of orange-gold light shooting into the night sky from Maunakea and Chile have become one of the most beautiful sights in modern astronomy.","Adaptive optics helped win a Nobel Prize. For more than two decades, two teams tracked stars whirling around the very centre of our Milky Way. Andrea Ghez's team used the Keck telescopes, and Reinhard Genzel's team used telescopes in Chile, including the Very Large Telescope. One star, called S2, takes about 16 years to complete its orbit, racing around something invisible but about four million times heavier than the Sun. The only reasonable explanation was a supermassive black hole. Ghez and Genzel shared the 2020 Nobel Prize in Physics for this work, together with the mathematician Roger Penrose."]},{"heading":"The Best Seats in the House","paragraphs":["Even with adaptive optics, where you build a telescope matters enormously. Astronomers hunt for sites with four things: height, dryness, darkness and calm, steady air. Height puts you above the thickest, dustiest part of the atmosphere. Dry air matters because water vapour soaks up infrared and millimeter-wave light. Darkness means being far from city lights. And smooth airflow, often found on mountains near cool oceans where the wind flows evenly off the sea, means less twinkle.","Three regions of the world have become astronomy capitals. The first is Maunakea in Hawaii. Its summit rises about 4,200 meters above sea level, so the telescopes sit above roughly 40 percent of Earth's atmosphere and above most of its water vapour. It is in the middle of the Pacific Ocean, far from big cities, and the air flowing smoothly over the ocean keeps it steady. More than a dozen telescopes stand near the summit, including Keck, Subaru from Japan, and the Gemini North telescope. The mountain is also a deeply sacred place for Native Hawaiians, an important story we will explore carefully in Part 19.","The second is the Canary Islands, Spanish islands off the west coast of Africa. Observatories on La Palma and Tenerife sit above a layer of cloud that often spreads out below them like a white sea, trapping moisture and city glow underneath. The islands even have a special law to protect the night sky from light pollution.","The third, and the one where astronomy is growing fastest, is northern Chile, especially the Atacama Desert. Parts of the Atacama are among the driest places on Earth outside the polar regions; some weather stations have gone years without recording rain. The cold Humboldt Current in the Pacific and the high Andes mountains keep clouds away, so many sites enjoy more than 300 clear nights a year. That is why so many of the world's great observatories, from Europe, the United States, Japan and beyond, have been built on Chilean mountaintops. Working there is not always easy: the air at the highest sites has only about half the oxygen of air at sea level, so staff are checked by doctors and sometimes breathe extra oxygen."]},{"heading":"Giants in the Desert: the VLT and ALMA","paragraphs":["On a flattened mountaintop called Cerro Paranal, about 2,635 meters high in the Atacama, stand four identical white towers. Together they are the Very Large Telescope, or VLT, run by the European Southern Observatory (ESO), an organisation supported by many European countries. The name sounds like something a kid would invent, but it is the official one. Each of the four Unit Telescopes has a single main mirror 8.2 meters across but only about 17.5 centimeters thick, a thin meniscus of glass ceramic weighing about 23 tonnes. Because it is so thin, it would sag out of shape on its own, so about 150 computer-controlled supports underneath constantly push it back into perfect form. This is the active optics idea in action.","The four telescopes are named with words from the language of the Mapuche, an Indigenous people of Chile and Argentina: Antu (the Sun), Kueyen (the Moon), Melipal (the Southern Cross) and Yepun (Venus, the evening star). The first one began work in May 1998, and all four were in action a few years later. There are also four smaller movable 1.8-meter telescopes that can roll along tracks to different spots on the mountain. Using interferometry, the trick we met with radio dishes in Part 15, light from several telescopes can be combined through tunnels under the platform so that they act like one telescope up to about 130 to 140 meters wide, seeing details as fine as a few thousandths of an arcsecond.","The VLT is one of the most productive ground-based observatories in the world, with scientists publishing more than one research paper a day on average using its data. In 2004, its adaptive optics camera captured a faint speck next to a dim brown dwarf. In 2005 astronomers confirmed it was a giant planet-sized world travelling with the brown dwarf, making it one of the first pictures ever taken of a planet outside our solar system. It has tracked stars around the Milky Way's central black hole, and its lasers, four of them on the telescope Yepun, now create artificial guide stars. The skies at Paranal are so dark that on a clear, moonless night the Milky Way alone can cast a faint shadow. The site even appeared in a James Bond film, Quantum of Solace, in 2008.","About 300 kilometers to the north-east, on the Chajnantor plateau, sits an even higher and stranger observatory: ALMA, the Atacama Large Millimeter/submillimeter Array. At about 5,000 meters, it is one of the highest observatories on Earth. ALMA does not look like a telescope at all. It is a field of 66 big white dish antennas, most of them 12 meters across and some 7 meters across, built by partners in Europe, North America and East Asia together with Chile. It was officially inaugurated on 13 March 2013 and cost about 1.4 billion dollars.","ALMA studies millimeter and submillimeter waves, which sit between infrared light and radio waves. These waves come from cold things: dust and gas clouds where stars and planets are born, and very distant galaxies. Water vapour blocks them, which is why ALMA needs one of the driest, highest places on the planet. The antennas, each weighing more than 100 tonnes, can be picked up by giant 28-wheeled transporter trucks and moved, spreading them over as much as 16 kilometers to see finer detail or bunching them together for wider views. In 2014, ALMA released an astonishing picture of a young star called HL Tauri surrounded by a dusty disk with dark rings carved into it, probably by planets forming in the disk. ALMA also joined the Event Horizon Telescope network that photographed black hole shadows."]},{"heading":"Rubin: A Movie of the Whole Southern Sky","paragraphs":["Most big telescopes are like microscopes for the sky: they stare at one small spot for a long time. The Vera C. Rubin Observatory was built to do the opposite. Its job is to photograph the entire southern sky again and again, every few nights, for ten years, and turn the results into a giant time-lapse movie of the universe. The project is called the Legacy Survey of Space and Time, or LSST.","The observatory is named after Vera Rubin, an American astronomer born in 1928. In the 1970s, working with the instrument builder Kent Ford, she measured how fast stars and gas orbit around the centres of spiral galaxies. If galaxies contained only the stars and gas we can see, the outer parts should orbit slowly, just as Neptune creeps around the Sun far more slowly than Mercury. Instead, Rubin found the outer parts moving about as fast as the inner parts. Something unseen, adding a huge amount of extra gravity, had to be there. Her measurements became some of the strongest evidence for dark matter, a mysterious invisible substance that seems to outweigh normal matter by about five to one. Rubin died in 2016, and in 2019 the observatory, first called the Large Synoptic Survey Telescope, was renamed in her honor.","Rubin stands on a peak called Cerro Pachón, about 2,682 meters high in Chile, funded mainly by the U.S. National Science Foundation and the U.S. Department of Energy. Its telescope has an unusual design: the 8.4-meter primary mirror and a 5-meter third mirror were cast together from a single piece of glass, a ring with a bowl in the middle. The whole telescope is short and stiff so it can swing quickly from one patch of sky to the next, taking a new picture roughly every 40 seconds all night long.","At the heart of it all is the LSST Camera, the largest digital camera ever built for astronomy. Built at the SLAC National Accelerator Laboratory in California, it is about the size of a small car and weighs about 3 tonnes. Its focal plane, the flat surface where the image lands, is about 64 centimeters across and is tiled with 189 CCD chips, the great-great-grandchildren of Boyle and Smith's invention. Together they make about 3,200 megapixels, hundreds of times more than a typical phone camera. To show just one of its pictures at full detail, you would need several hundred ultra-high-definition TV screens. Each image covers a patch of sky nearly 50 times the area of the full Moon.","On 23 June 2025, the observatory released its first images to the world. One showed the glowing Trifid and Lagoon nebulae, star-forming clouds of gas thousands of light-years away, built from hundreds of exposures. Another revealed a huge region of the Virgo Cluster crowded with galaxies, and altogether the first images showed millions of them. In only about 10 hours of test observations, Rubin also found more than 2,000 asteroids nobody had seen before. Over its ten-year survey, the observatory is expected to collect millions of images and send out up to about 10 million alerts on a busy night whenever something in the sky changes: a star exploding, an asteroid moving, a black hole flaring. Scientists hope it will help map dark matter, track potentially dangerous asteroids and catch rare cosmic events as they happen."]},{"heading":"Are Space Pictures Painted? Understanding False Color","paragraphs":["If you have seen a glowing purple-and-gold picture of a nebula and wondered, 'Is that what it really looks like?', you are asking a very good scientific question. The honest answer is: usually not exactly, and that's on purpose.","Here is why. A CCD does not see colour at all. Each pixel only counts how many photons arrived, so every raw astronomy image is black and white. To get colour, astronomers put a filter in front of the camera that lets through only one band of light, take a picture, then swap to another filter and take another. Afterwards they assign each black-and-white picture a colour, often red for the longest wavelengths, green for the middle and blue for the shortest, and combine them. If the filters match the red, green and blue our eyes see, the result is close to 'true colour'.","But many filters capture light our eyes can't see at all, like infrared, ultraviolet, X-rays or radio waves. There is no 'real' colour for an X-ray, so scientists choose one. Other filters pick out the exact glow of a single element. A famous version, sometimes called the Hubble palette, shows glowing sulfur as red, hydrogen as green and oxygen as blue. Hydrogen and sulfur actually both glow red, so without this trick they would blend together; by spreading them into different colours, astronomers can see at a glance where each element lies. This is sometimes called representative or false colour.","So false colour is not fake. It is a kind of map, like a weather map where blue means cold and red means hot. The data underneath are real measurements, and the colour rules are written down so that anyone can check them. When you look at a picture from Rubin, ALMA, Chandra or JWST, you are seeing real light, translated into a language your eyes can read.","Segmented mirrors, electronic eyes and twinkle-cancelling lasers turned the mountaintops into astronomy superpowers. But some engineers dreamed of something even bolder: fold a giant segmented mirror like origami, rocket it into space, and unfold it a million miles away."]}],"deepDive":"Why do ground telescopes need adaptive optics at all? The answer lies in a number astronomers call the Fried parameter, written r0. It describes the size of a patch of air through which light stays roughly smooth and in step. At a good site in visible light, r0 is typically about 10 to 20 centimeters. That means a 10-meter telescope, however perfect its mirror, behaves for fine detail like a telescope only 10 to 20 centimeters wide: the image smears to about 0.5 to 1 arcsecond, the typical 'seeing' at top observatories. The diffraction limit of a 10-meter mirror, set by the wave nature of light and roughly equal to 1.22 times the wavelength divided by the diameter, is about 0.013 arcseconds at 500 nanometers. The air throws away a factor of 50 or more in sharpness. Because r0 grows with wavelength (roughly as wavelength to the power 6/5), seeing is gentler in the infrared, and the number of actuators needed to correct it falls. That is why most adaptive optics systems work best in the near-infrared, around 1 to 2.5 micrometers, and why the quality of correction, measured by the Strehl ratio (the peak brightness of a star image compared with a perfect one), is much higher there than in visible light. A laser guide star solves one problem and creates another. Because the sodium layer is only about 90 kilometers up, the laser beam forms a cone rather than a cylinder, and it misses some of the turbulence that starlight crosses, an error called the cone effect. Lasers also cannot measure the overall tilt of the image, because the beam is bent going up and coming down, so a faint natural star is still needed for tip-tilt correction. Newer systems use several lasers and several deformable mirrors at different heights, a technique called multi-conjugate adaptive optics, to correct a wider field. Segmented mirrors have their own subtleties: gaps and edges between hexagons scatter light into a six-pointed spike pattern, which is why stars in Keck and JWST images show distinctive spikes. Engineers must also 'phase' the segments, aligning their heights to a small fraction of a wavelength, often using special cameras that look at how light from neighbouring segments interferes.","funFact":"The laser guide stars used by big telescopes shine at the same yellow-orange wavelength as old sodium streetlights, because both make sodium atoms glow.","check":{"q":"What does an adaptive optics system bend hundreds of times a second to cancel the blur of Earth's air?","a":"A thin, flexible (deformable) mirror","wrong":["The telescope's whole dome","The main lens of the eyepiece","A spinning filter wheel"]},"sources":[{"title":"W. M. Keck Observatory","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/W._M._Keck_Observatory"},{"title":"Charge-coupled device","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Charge-coupled_device"},{"title":"Adaptive optics","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Adaptive_optics"},{"title":"Very Large Telescope","publisher":"European Southern Observatory","url":"https://www.eso.org/public/teles-instr/paranal-observatory/vlt/"},{"title":"Very Large Telescope","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Very_Large_Telescope"},{"title":"Atacama Large Millimeter Array","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Atacama_Large_Millimeter_Array"},{"title":"Vera C. Rubin Observatory","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Vera_C._Rubin_Observatory"},{"title":"First Imagery from NSF-DOE Vera C. Rubin Observatory","publisher":"Rubin Observatory","url":"https://rubinobservatory.org/news/first-imagery-rubin"}],"photos":[{"src":"img/deep/telescope/17-1.jpg","alt":"The twin white domes of the W. M. Keck Observatory near the summit of Maunakea, Hawaii.","file":"W M Keck Observatory (840A5793-CC).jpg","url":"https://commons.wikimedia.org/wiki/File:W_M_Keck_Observatory_(840A5793-CC).jpg","author":"International Gemini Observatory/NOIRLab/NSF/AURA","license":"CC BY 4.0"},{"src":"img/deep/telescope/17-2.jpg","alt":"A Very Large Telescope at Paranal, Chile, shoots a laser guide star toward the centre of the Milky Way (2010).","file":"Laser Towards Milky Ways Centre.jpg","url":"https://commons.wikimedia.org/wiki/File:Laser_Towards_Milky_Ways_Centre.jpg","author":"ESO/Yuri Beletsky (ybialets at eso.org)","license":"CC BY 4.0"},{"src":"img/deep/telescope/17-3.jpg","alt":"ALMA radio antennas spread across the Chajnantor plateau, 5,000 metres up in Chile's Atacama Desert.","file":"Nineteen ALMA antennas on the Chajnantor plateau (wallpaper).jpg","url":"https://commons.wikimedia.org/wiki/File:Nineteen_ALMA_antennas_on_the_Chajnantor_plateau_(wallpaper).jpg","author":"ALMA (ESO/NAOJ/NRAO)/W. Garnier (ALMA)","license":"CC BY 4.0"}],"words":4368},{"n":18,"title":"JWST: The Golden Eye","when":"1989 – today","summary":"The James Webb Space Telescope has a giant golden mirror made of 18 hexagons and a sunshade as big as a tennis court. It had to fold up to fit inside a rocket, then unfold all by itself far out in space. Now it sees heat-light from the very first galaxies and sniffs the air of faraway planets.","sections":[{"heading":"Light That Got Stretched on the Way Here","paragraphs":["Imagine shouting across a canyon. Your voice takes a moment to reach the other side, so anyone listening hears you slightly in the past. Light works the same way, only much faster. Light from the Moon is about 1.3 seconds old when it reaches you; sunlight is about 8 minutes old. Light from a galaxy billions of light-years away left it billions of years ago. That makes every big telescope a kind of time machine. The farther you look, the further back in time you see.","Astronomers wanted to look all the way back to the first galaxies, which formed in the first few hundred million years after the Big Bang about 13.8 billion years ago. But there was a problem, and it comes from the discovery we met in Part 13: the universe is expanding. As light travels across expanding space for billions of years, its waves get stretched along with space itself, like a wavy line drawn on a balloon that is being blown up. Stretched waves are longer, and longer waves are redder. This is called cosmological redshift.","For the most distant galaxies, the stretching is extreme. Light that left a young galaxy as ultraviolet or blue light, waves only a few hundred nanometers long, arrives at Earth stretched to many times that length, deep into the infrared, which our eyes cannot see at all. Hubble, which sees mainly visible and ultraviolet light with a little near-infrared, could glimpse some early galaxies, but the very first ones had slipped beyond its reach. To find them, astronomers needed a big, very sensitive infrared telescope.","Infrared has other superpowers too. Stars and planets are born inside thick clouds of dust that block visible light like fog. Infrared waves are long enough to slip through much of that dust, so an infrared telescope can peek inside the cosmic nurseries. And cool things, like newborn stars, brown dwarfs and planets, give off most of their own light as infrared, the same 'heat light' that William Herschel discovered with his thermometers in 1800.","But infrared astronomy has a huge problem: everything warm glows in infrared, including the telescope itself. A telescope at room temperature shines in infrared far brighter than the faint galaxies it is trying to see, like trying to spot fireflies while holding a burning torch. Earlier infrared space telescopes such as IRAS in 1983 and NASA's Spitzer, launched in 2003, solved this by being small and chilled. The new telescope would have to be enormous and freezing cold at the same time."]},{"heading":"Designing a Golden Giant","paragraphs":["Planning began before Hubble had even launched. In September 1989, astronomers met at the Space Telescope Science Institute in Baltimore for a workshop on a 'Next Generation Space Telescope'. In 1996, a committee led by the astronomer Alan Dressler recommended that NASA build a large infrared telescope of at least 4 meters to follow Hubble. Over the next years, the plan grew into the design that would eventually fly. In 2002, the telescope received its official name: the James Webb Space Telescope, usually shortened to JWST or simply Webb.","The heart of Webb is its primary mirror, 6.5 meters (about 21 feet) across. Hubble's mirror is 2.4 meters wide, so Webb's mirror has roughly 25 square meters of collecting area, about six times as much as Hubble's. That would be far too big to fit inside any rocket as one solid piece. So, borrowing Jerry Nelson's idea from the Keck telescopes, the engineers split it into 18 hexagonal segments, each about 1.3 meters across. The two outer columns of segments, three on each side, fold back like the leaves of a drop-leaf table so the mirror can squeeze into the rocket.","The segments are made of beryllium, a rare, light, very stiff metal. Beryllium was chosen because it is strong for its weight and, crucially, it keeps its shape well when it gets extremely cold. Each bare beryllium segment weighs only about 20 kilograms, and the whole primary mirror only about 705 kilograms, much lighter than a glass mirror of the same size would be. The back of each segment was machined into a honeycomb of ribs to save weight. Behind each segment sit seven tiny motors called actuators: six to move it in any direction and tilt it, and one to adjust its curve. They can make moves smaller than a thousandth of the width of a human hair.","The front of each segment is covered with an extremely thin layer of gold, about 100 nanometers thick. Gold is one of the best materials in the world at reflecting infrared light. Because the layer is so thin, the gold on all 18 segments together weighs only about 48 grams, roughly the weight of a golf ball. On top of the gold is a thin protective layer of glass, so the soft metal does not get scratched.","To keep the telescope cold enough, Webb has a sunshield about 21 meters by 14 meters, roughly the size of a tennis court. It is made of five layers of a special plastic film called Kapton, each thinner than a human hair, coated with aluminium, and with the two layers facing the Sun also coated with doped silicon, which gives them a purple-pink tint. The gaps between the layers let heat escape sideways into space. The result is astonishing: the side facing the Sun can reach about 85 degrees Celsius, hot enough to cook an egg, while the telescope side falls to about minus 233 degrees Celsius. NASA describes the protection as like sunscreen with an SPF of about one million.","Behind the mirror sit four scientific instruments, all kept below about 50 kelvin, which is minus 223 degrees Celsius. NIRCam, the main near-infrared camera, was built by the University of Arizona and Lockheed Martin. NIRSpec, a spectrograph that can study up to about a hundred objects at once through a grid of about a quarter of a million tiny shutters, was provided by the European Space Agency. MIRI, the mid-infrared instrument, was built by a team of European institutes together with NASA's Jet Propulsion Laboratory. Because MIRI sees even longer infrared waves, it has its own refrigerator, a cryocooler, that chills it to only about 7 degrees above absolute zero. The fourth instrument, the Fine Guidance Sensor with a science instrument called NIRISS, was built by Canada; it keeps the telescope pointed with extreme accuracy. Together they cover wavelengths from about 0.6 to 28.5 micrometers."]},{"heading":"Three Agencies, Many Years and a Big Price Tag","paragraphs":["Webb is a partnership between NASA, the European Space Agency (ESA) and the Canadian Space Agency (CSA), with thousands of scientists, engineers and technicians from 14 countries. The prime contractor that built much of the telescope was Northrop Grumman, and the Space Telescope Science Institute in Baltimore, which also runs Hubble, operates the telescope and handles its science. ESA provided NIRSpec, much of MIRI and the Ariane 5 rocket and launch; Canada provided the Fine Guidance Sensor and NIRISS. In return, European and Canadian astronomers get guaranteed shares of observing time.","Building something this complicated, which had never been attempted before, turned out to be far harder than expected. In the late 1990s, early estimates suggested a launch around 2007 and a cost of perhaps a billion dollars or so. Those hopes were wildly optimistic. Engineers had to invent new technologies: the beryllium mirrors, the folding sunshield, new infrared detectors, the microshutters and coolers that could survive launch and then work for years at deep-space temperatures. Every new part had to be tested in giant vacuum chambers that recreated the cold of space, including the huge Chamber A at NASA's Johnson Space Center in Houston, the same chamber used to test Apollo spacecraft.","Problems kept piling up. In 2011, after costs had grown sharply, a committee of the U.S. House of Representatives even proposed cancelling the telescope, though Congress kept it alive with a cost cap, a story we will return to in Part 19. In 2018, during testing, the sunshield tore and some screws and washers came loose after a shake test, adding more delays. The launch slipped year after year. In the end, Webb's total cost, including development and its first years of operations, came to about 10 billion dollars, making it one of the most expensive science projects ever.","Why keep going? Because astronomers argued that Webb could answer questions no other machine could: how the first galaxies formed, how stars and planets are born, and what the atmospheres of distant planets are made of. And, unlike Hubble, Webb would be far beyond the reach of astronauts. There would be no repair missions. Everything had to work the first time."]},{"heading":"Christmas Morning Launch and a Month of Nail-Biting","paragraphs":["On the morning of 25 December 2021, while many families were opening presents, an Ariane 5 rocket stood on its launch pad at Europe's Spaceport near Kourou in French Guiana, on the north-east coast of South America. Folded inside its nose cone, like a giant butterfly in a cocoon, was the James Webb Space Telescope, weighing about 6 tonnes. At 12:20 Universal Time, the rocket roared into the sky. About 27 minutes later, Webb separated from the rocket's upper stage, and cameras on the rocket filmed the telescope drifting gently away, its solar panel unfolding almost at once. Engineers in the control room cheered.","Why launch from South America on a European rocket? The Ariane 5 was part of Europe's contribution to the mission, and it had a long record of reliable launches. Kourou also sits only about 5 degrees north of the equator, where Earth's surface spins fastest, so rockets launched eastward from there get a free boost of speed. Even so, fitting Webb inside was a squeeze: the rocket's nose cone is about 5.4 meters wide, smaller than Webb's 6.5-meter mirror and far smaller than its sunshield. Everything had to be folded, rolled and tucked like a giant piece of origami.","Launch was only the start of the danger. NASA's engineers had counted 344 'single-point failures': individual parts or steps that, if any one of them failed, could ruin the whole mission. Most of them were in the deployment, the long sequence of unfolding. Hubble had been launched mostly ready to use; Webb had to assemble itself in deep space, by remote control, with no astronauts to help.","Over the next two weeks, the steps came one after another. The antenna swung out to talk to Earth. On 28 December, the two big pallets holding the folded sunshield lowered into place. Then booms slid out to stretch the sunshield wide, and over several nervous days, motors and pulleys pulled each of the five thin layers tight, one by one. The tensioning finished on 4 January 2022. On 5 January, a tripod of struts swung out and locked the small secondary mirror into place in front of the big one. Finally, on 7 and 8 January, the two folded wings of the primary mirror swung forward and latched, completing the golden hexagon. When the last latch clicked, the flight team in Baltimore erupted in applause. The hardest part of the unfolding was done.","Meanwhile, Webb kept coasting outward. On 24 January 2022, about a month after launch, a final short thruster burn placed it into its working orbit. But it still could not see clearly. Its 18 mirror segments were each pointing at slightly different places, so the first test images showed 18 separate, blurry copies of the same star. Over several months, engineers used the actuators to move each segment by tiny amounts, merging the 18 dots into one, then lining up the segments' heights to within about 50 nanometers so that they acted like a single seamless mirror. By the spring of 2022, a test picture of a star looked astonishingly sharp, and the instruments were cooled, switched on and checked one by one.","There was one more piece of good news. Because the Ariane 5 had placed Webb on its path so precisely, and the first course corrections went so well, Webb used much less fuel than expected. It was designed with enough propellant for at least 10 years of work, but NASA now estimates it has enough to keep going for about 20 years."]},{"heading":"A Home a Million Miles Away","paragraphs":["Hubble circles Earth only a few hundred kilometers up. Webb lives much farther away: near a spot called the second Lagrange point, or L2, about 1.5 million kilometers (roughly a million miles) from Earth, on the opposite side from the Sun. That is about four times farther than the Moon.","Why there? L2 is one of five special places, named after the 18th-century mathematician Joseph-Louis Lagrange, where the pulls of the Sun and Earth balance out in a useful way. Normally, something farther from the Sun than Earth would orbit more slowly and fall behind. But at L2, Earth's extra gravity adds to the Sun's, giving just enough extra pull for an object there to keep pace with Earth, circling the Sun once a year while staying lined up behind our planet.","For Webb, that line-up is perfect. The Sun, Earth and Moon are all in roughly the same direction, so a single sunshield can block the heat and light from all three at once, keeping the telescope permanently in its own cold shadow. Its solar panel and the hot side of the shield face the Sun, while the mirror looks out into the dark. And because it is not circling Earth, Webb does not spend half its time passing in and out of Earth's shadow, heating up and cooling down as Hubble does.","Webb was not the first visitor to this neighbourhood. Earlier spacecraft had used the L2 region too, including NASA's WMAP, which mapped the afterglow of the Big Bang, and ESA's Herschel infrared telescope, named after William Herschel, and its Planck mission, launched together in 2009. ESA's Gaia spacecraft, which measured the positions and motions of more than a billion stars in our galaxy, also worked from an orbit around L2. Astronomers like it there for the same reasons Webb does: a calm, cold, steady view of the sky, with the Sun and Earth always behind you.","Webb does not sit perfectly still at L2, though. The balance there is unstable, like a marble balanced on top of a hill, so Webb actually travels in a big looping path called a halo orbit around the L2 point, taking about six months to go around. Every few weeks it fires small thrusters to stay on course. From its loop, Webb sends its data home through NASA's Deep Space Network, giant radio dishes in California, Spain and Australia."]},{"heading":"First Light: Thousands of Galaxies in a Grain of Sand","paragraphs":["On 11 July 2022, at the White House in Washington, U.S. President Joe Biden revealed Webb's first full-colour image. It was called Webb's First Deep Field, and it showed a galaxy cluster named SMACS 0723. The cluster's enormous gravity acts like a natural magnifying glass, bending and stretching the light of even more distant galaxies behind it into glowing arcs. The picture covered a patch of sky about as big as a grain of sand held at arm's length, yet it was packed with thousands of galaxies, some seen as they were more than 13 billion years ago. It took about 12.5 hours of observing, much less time than Hubble needed for its famous deep fields.","The next day, 12 July, the rest of the first images were released. The 'Cosmic Cliffs' in the Carina Nebula looked like a mountain range of glowing gas, sparkling with hundreds of newborn stars that had been hidden in dust. The Southern Ring Nebula showed the shells of gas thrown off by a dying star. Stephan's Quintet, a group of five galaxies, revealed shock waves rippling through the gas as some of the galaxies collided. And a spectrum of a giant planet called WASP-96 b showed the clear fingerprint of water vapour in its atmosphere. Notice the six-pointed spikes around bright stars in Webb's pictures: they come from the hexagonal mirror segments and the struts that hold the secondary mirror.","Discoveries came quickly. On 25 August 2022, NASA announced that Webb had detected carbon dioxide in the atmosphere of WASP-39 b, a hot, puffy gas giant about 700 light-years away. It has roughly the mass of Saturn but is wider than Jupiter, and it circles its Sun-like star in just over four days at a temperature of about 900 degrees Celsius. When the planet passed in front of its star on 10 July 2022, a little of the starlight shone through its atmosphere on the way to Webb. NIRSpec spread that light into a spectrum and found a small bump between 4.1 and 4.6 micrometers, the signature of carbon dioxide molecules absorbing light. It was the first clear evidence of carbon dioxide on a planet outside our solar system. Webb went on to find sulfur dioxide there too, made by starlight driving chemical reactions in the planet's air, the first time this kind of photochemistry was seen on an exoplanet.","Webb also began smashing distance records. In 2024, the JADES team (the JWST Advanced Deep Extragalactic Survey) confirmed a galaxy called JADES-GS-z14-0, seen as it was about 300 million years after the Big Bang, when the universe was only about 2 percent of its present age. The galaxy is about 1,600 light-years across and surprisingly bright, and in 2025 the ALMA observatory in Chile even detected oxygen in it. Also in 2025, another team announced a galaxy called MoM-z14 that appears to be slightly more distant still. Records like these are likely to keep falling.","In October 2022, Webb also revisited one of Hubble's most famous targets, the Pillars of Creation in the Eagle Nebula. In Hubble's visible-light picture, the pillars are thick, dark towers of dust. In Webb's near-infrared view, the dust turns into a see-through haze, and hundreds of young stars, some only a few hundred thousand years old, shine out from inside and around the pillars. Side by side, the two images show exactly why an infrared telescope was worth building.","Many of these early galaxies turned out to be brighter and more mature than most astronomers had expected so soon after the Big Bang, a puzzle scientists are still working on. Webb has also found mysterious compact red objects in the young universe, nicknamed 'little red dots', studied the atmospheres of small rocky planets like those around the star TRAPPIST-1, and peered into star-forming clouds in our own galaxy. Webb and Hubble often team up: Hubble sees in visible and ultraviolet light, Webb in infrared, and together they show far more than either alone. Neither has replaced the other; both are still working."]},{"heading":"What's in a Name?","paragraphs":["James Edwin Webb was not an astronomer. He was a government official who led NASA from 1961 to 1968, during the years when the agency was racing to put people on the Moon. He fought hard to make sure NASA did serious science, not just rocket launches, which is why NASA administrator Sean O'Keefe chose to honour him when the telescope was named in 2002.","Later, some people raised concerns. Before he led NASA, Webb had been a senior official at the U.S. State Department from 1949 to 1952, a time when the government was pushing gay and lesbian employees out of their jobs, a campaign historians now call the Lavender Scare. Starting around 2015, and especially in 2021, a number of astronomers and others asked whether Webb had played a part, and some signed a petition urging NASA to rename the telescope. Other names, such as Harriet Tubman, were suggested.","NASA asked its chief historian, Brian Odom, to investigate. After studying more than 50,000 documents in archives, the report published in November 2022 found no evidence that Webb led or encouraged the firings of people because of their sexual orientation, either at the State Department or at NASA. NASA kept the name. Some critics accepted the report, while others argued that, as a top official, Webb still bore responsibility for policies that harmed people, and some scientists and journals choose to call the telescope simply JWST. Historians continue to discuss how to judge people from the past fairly, using the evidence that survives.","Whatever you call it, the telescope itself keeps working, a golden eye floating in the dark a million miles from home. JWST shows how far telescopes have come since a Dutch spectacle maker's three-times spyglass. But building, placing and protecting telescopes has never been free of trouble, and some of those troubles are the subject of our next part."]}],"deepDive":"Astronomers describe cosmic distance with redshift, written z. If light leaves a galaxy with wavelength L and arrives with wavelength (1 + z) times L, the galaxy has redshift z. For JADES-GS-z14-0, z is about 14.2, so every wave has been stretched about 15 times. Hydrogen's strong ultraviolet Lyman-alpha line at 121.6 nanometers arrives near 1.85 micrometers, in the near-infrared, and almost all light shorter than that line is absorbed by neutral hydrogen gas that filled the early universe. This produces a sharp 'break' in the galaxy's colours; galaxies that vanish in bluer filters but appear in redder ones are candidates for great distance. Such photometric guesses can be fooled by dusty, nearer galaxies, so confirmation needs a spectrum, which is why NIRSpec, and later ALMA's detection of an oxygen line, mattered so much for z14-0. Why must Webb be so cold? A warm object glows most strongly at a wavelength inversely proportional to its temperature (Wien's law). A mirror at room temperature, about 300 kelvin, glows most strongly near 10 micrometers, right in Webb's range. At about 40 kelvin, the peak moves out past 70 micrometers and the glow in Webb's band is tiny. MIRI goes further, cooled to about 7 kelvin by a cryocooler, because its detectors are sensitive out to 28 micrometers. Webb's sharpness is set mainly by diffraction: at 2 micrometers, a 6.5-meter aperture gives about 0.07 arcseconds, similar to Hubble's visible-light sharpness, because Webb's larger mirror is offset by its longer wavelengths. The L2 halo orbit is unstable on a timescale of weeks, so small station-keeping burns are needed roughly every three weeks; the sunshield also acts like a small solar sail, and engineers use a trim flap and mirror pointing choices to manage the gentle push of sunlight. Scientists still debate the high abundance of bright early galaxies. Proposed explanations include more efficient star formation in early dark-matter halos, top-heavy populations of massive stars, bursts of star formation that temporarily brighten galaxies, and contributions from growing black holes. Most researchers think standard cosmology survives, but the details of early galaxy growth need revising.","funFact":"All the gold on Webb's 18 mirror segments put together weighs only about 48 grams, roughly the weight of a golf ball.","check":{"q":"Why does JWST observe mainly in infrared light?","a":"Light from the earliest galaxies has been stretched into infrared by the expanding universe, and infrared can see through dust","wrong":["Because infrared light travels faster than visible light","Because it is closer to the stars than Hubble","Because gold mirrors cannot reflect visible light at all"]},"sources":[{"title":"James Webb Space Telescope","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/James_Webb_Space_Telescope"},{"title":"Webb Fact Sheet","publisher":"NASA Science","url":"https://science.nasa.gov/mission/webb/fact-sheet/"},{"title":"James Webb Space Telescope (mission page)","publisher":"NASA Science","url":"https://science.nasa.gov/mission/webb/"},{"title":"NASA's Webb Detects Carbon Dioxide in Exoplanet Atmosphere","publisher":"NASA Science","url":"https://science.nasa.gov/missions/webb/nasas-webb-detects-carbon-dioxide-in-exoplanet-atmosphere/"},{"title":"JADES-GS-z14-0","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/JADES-GS-z14-0"},{"title":"WASP-39b","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/WASP-39b"},{"title":"James E. Webb","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/James_E._Webb"}],"photos":[{"src":"img/deep/telescope/18-1.jpg","alt":"Webb's golden 18-segment primary mirror, fully unfolded, with technicians in a NASA Goddard clean room.","file":"James Webb Space Telescope Mirror Seen in Full Bloom (33433274343).jpg","url":"https://commons.wikimedia.org/wiki/File:James_Webb_Space_Telescope_Mirror_Seen_in_Full_Bloom_(33433274343).jpg","author":"NASA's James Webb Space Telescope from Greenbelt, MD, USA","license":"Public domain"},{"src":"img/deep/telescope/18-2.jpg","alt":"An Ariane 5 rocket lifts off from Kourou, French Guiana, carrying the James Webb Space Telescope on 25 December 2021.","file":"Webb Liftoff on Ariane 5 (potm2201a).jpeg","url":"https://commons.wikimedia.org/wiki/File:Webb_Liftoff_on_Ariane_5_(potm2201a).jpeg","author":"ESA/CNES/Arianespace/Optique Vidéo du CSG - JM Guillon","license":"CC BY 4.0"},{"src":"img/deep/telescope/18-3.jpg","alt":"Webb's First Deep Field (2022): galaxy cluster SMACS 0723, with thousands of galaxies and bent arcs of light.","file":"Webb's First Deep Field.jpg","url":"https://commons.wikimedia.org/wiki/File:Webb%27s_First_Deep_Field.jpg","author":"NASA, ESA, CSA, and STScI","license":"Public domain"}],"words":3762},{"n":19,"title":"Trouble in Sight","when":"1600s – today","summary":"Telescopes are amazing, but they have caused plenty of arguments. City lights hide the stars, new satellites draw streaks across the sky, and some telescopes were built on mountains that people hold sacred. Some telescopes broke, some cost far too much, and some brilliant people were left out when the prizes were handed out.","sections":[{"heading":"The Oldest Telescope Argument","paragraphs":["From the very first day, the telescope has been a troublemaker. Not because a tube with two lenses is dangerous, but because of what it shows, who gets to use it, where it is built and who gets the praise afterwards. Every time telescopes grew more powerful, new kinds of arguments grew with them.","The oldest of these arguments is the one you already met in Part 5. In 1633, Galileo Galilei stood before Church officials in Rome because his telescope observations, and his book defending a Sun-centered universe, clashed with the teaching of the time. He was made to take back his views and spent his last years under house arrest near Florence. We will not retell that story here. What matters for this chapter is the lesson it started: a telescope does not just collect light. It collects trouble too, because the things it reveals can upset what powerful people believe, want or own.","Four hundred years later, the arguments look very different. Nobody is put on trial for saying the Earth goes around the Sun. Instead, astronomers worry about city glow, swarms of shiny satellites, sacred mountains, runaway budgets, broken giants and discoverers who never got fair credit.","None of this means telescopes are bad. It means they are part of the real world, and a good scientist looks at the trouble honestly. So let's take a tour of the problems, starting with the one you can probably see from your own window tonight."]},{"heading":"Where Did the Milky Way Go?","paragraphs":["Step outside on a clear night in a big city and count the stars. You might find twenty, or fifty if you are lucky. Your great-great-great-grandparents, standing in the same spot two hundred years ago, would have seen thousands of stars and a pale river of light stretching from one side of the sky to the other: the Milky Way, the glow of hundreds of billions of distant suns in our own galaxy. Many children today have only seen it in photos.","The thief is light pollution. That means artificial light that spills where it is not needed: upward from streetlights, sideways from car parks and stadiums, out of billboards and office windows that stay lit all night. Some of that light bounces off dust and water droplets in the air and turns the whole sky into a dim gray or orange dome. Astronomers call this skyglow. It is like trying to spot a firefly while someone shines a flashlight in your face.","In 2016, a team of scientists led by the Italian researcher Fabio Falchi published a new world atlas of night-sky brightness. They combined satellite measurements of light coming up from the ground with thousands of measurements taken by people on the ground. The results were startling. More than 80 percent of the world's people live under skies brightened by artificial light. About one-third of all humans, including roughly 80 percent of North Americans and about 60 percent of Europeans, can no longer see the Milky Way from where they live. The atlas found that Singapore was the most light-polluted country of all; there, the sky never gets truly dark.","Astronomers measure how dark a place is with tools such as the Bortle scale, a nine-step rating invented by the American amateur astronomer John Bortle. Class 1 is a pristine sky crowded with stars; class 9 is an inner-city sky showing only the Moon, planets and the brightest stars. To see the Milky Way clearly, you generally need a sky of about class 4 or darker; by class 7 it has almost or completely vanished.","And the problem is growing. Studies based on satellite images found that the world's artificial light increased by at least 49 percent between 1992 and 2017. A citizen-science project called Globe at Night, in which ordinary people around the world report how many stars they can see, suggested that the sky seen by human eyes may be brightening by around 10 percent a year.","Light pollution is not only a problem for astronomers. Many animals depend on darkness. Baby sea turtles hatch on beaches at night and crawl toward the brightest horizon, which should be the moonlit sea. Bright beachfront lights can lead them inland instead, toward roads and danger. Migrating birds, many of which fly at night, can become confused by brightly lit towers and buildings, circling them until they are exhausted or crash into glass. Moths and other insects swarm around lamps instead of feeding and pollinating flowers, and scientists think artificial light is one of several reasons insect numbers have fallen in many places. Even people are affected: bright light late at night can upset the body's sleep signals.","The good news is that light pollution is one of the easiest kinds of pollution to fix. Light does not linger like smoke or plastic. Switch it off, and the sky clears instantly. Lamps can be shielded so they shine down onto the street instead of up into space. Warmer, more orange bulbs scatter less in the air than harsh blue-white ones. Timers and motion sensors can turn lights off when nobody needs them. In 2001, Flagstaff, Arizona, home of Lowell Observatory, became the world's first International Dark Sky City, and today hundreds of parks, towns and reserves around the world have been recognized for protecting their night skies. France cut its light pollution by about a third in less than ten years with new lighting rules. The stars are not gone. They are just waiting for us to turn down the glare."]},{"heading":"Streaks Across the Sky","paragraphs":["On 24 May 2019, a SpaceX rocket lifted off from Florida carrying 60 flat-packed satellites for a new internet service called Starlink. A few nights later, people around the world spotted something strange: a line of bright dots gliding across the sky one after another, like a string of pearls or a train of glowing carriages. It was beautiful, and alarming.","The reason is simple geometry. Shortly after sunset and before sunrise, the ground where you stand is already dark, but satellites a few hundred kilometres up are still lit by the Sun. They reflect it down and shine like moving stars. A few satellites would not matter much. But companies were now planning thousands, then tens of thousands. By late 2026, Starlink alone had roughly 11,000 satellites in orbit, and other companies in the United States, Europe and China are launching their own swarms, often called megaconstellations.","To a big observatory camera, a passing satellite is a vandal with a marker pen. A telescope often stares at the same patch of sky for many minutes, collecting the faint light of distant galaxies. If a satellite crosses the field of view during that time, it leaves a bright streak right across the picture. In November 2019, just a week after a new batch of Starlinks was launched, a camera on the 4-meter Blanco Telescope in Chile recorded an image crossed by 19 bright lines from a single satellite train. Astronomers shared it around the world as a warning of what might come.","Survey telescopes, which photograph huge areas of sky night after night, are hit hardest. The Vera C. Rubin Observatory, which you met in Part 17, has an enormous field of view, so almost every image taken in twilight may catch at least one satellite. Software can find and hide streaks, but every hidden stripe is lost data.","Astronomers and satellite companies have tried to work together. SpaceX tested a satellite with a dark coating, nicknamed DarkSat, which was about half as bright as a normal one, but it was still too bright and got too hot. Next came VisorSat, with a sunshade that folded out to block sunlight from hitting the shiniest parts. Later satellites used special mirror-like surfaces that bounce sunlight away from Earth rather than toward it, and studies found some of these newer models were only about one-fifth as bright as the very first design. That helps, but they can still be seen, and the sheer number keeps rising. In 2022 the International Astronomical Union, the worldwide club of professional astronomers, set up a special center to protect the 'dark and quiet sky', working with companies and governments and building tools that let astronomers predict when satellites will pass.","Notice that word 'quiet'. Radio telescopes face their own invisible traffic jam. As you learned in Part 15, radio telescopes catch incredibly weak radio waves from space, often billions of times weaker than the signals from a mobile phone. Every phone, Wi-Fi router, car radar, microwave oven, power line and satellite transmitter on Earth leaks radio noise that can drown those signals out. That is why many radio observatories are built in remote places. Around the Green Bank Observatory in West Virginia, the United States set up the National Radio Quiet Zone in 1958, an area of about 13,000 square miles where powerful transmitters are tightly limited, and near the telescope itself even ordinary Wi-Fi and microwave ovens are discouraged.","But satellites are overhead everywhere, even above the most remote desert. In 2023, astronomers reported that unintended radio leakage from Starlink satellites could be brighter than any natural radio source in that part of the sky. Nobody is breaking the rules on purpose; the satellites' electronics simply hum, the way an old television buzzes. Engineers are now studying how to quiet them down. Satellite internet helps remote schools and villages, so the challenge is to share the sky fairly."]},{"heading":"A Mountain That Is More Than a Mountain","paragraphs":["Maunakea, on the Big Island of Hawaii, is one of the best places on Earth to look at the stars. Its summit rises about 4,200 meters above the Pacific Ocean, above most of the clouds and much of the water vapor in the air. The ocean around it keeps the air smooth and steady, and the island is far from big cities. Since the 1960s, about a dozen telescopes have been built near its top, including the giant Keck telescopes from Part 17.","But Maunakea is not just a telescope site. For many Native Hawaiians, it is the most sacred mountain in the islands. In traditional Hawaiian belief, the summit is a place of the gods, linked to Wākea, the sky father, and it is the home of ancestors and burial sites. Some describe it as the piko, the navel or connecting point, of the islands. Imagine how you might feel if someone built a large factory on top of a cathedral, a temple or a family grave, even if the factory did important work. That feeling helps explain why the telescopes have become a painful issue.","For decades, many Native Hawaiians felt ignored as more domes appeared. Their concerns were also tied to a much longer history. The Hawaiian Kingdom was overthrown in 1893 with the help of American businessmen and troops, and many Hawaiians feel that land and culture were taken from them without fair consent. A telescope on the sacred summit became, for some, a symbol of that history.","The biggest clash came over the Thirty Meter Telescope, or TMT, an enormous telescope planned by universities and partners from the United States, Canada, Japan, India and, at first, China. Its mirror would be built from 492 hexagon-shaped pieces. On 7 October 2014, protesters gathered on the mountain and interrupted the groundbreaking ceremony. In the spring of 2015, people blocked the road to stop construction crews, and police arrested dozens of protesters. In December 2015, the Hawaii Supreme Court cancelled the telescope's building permit because the proper legal steps had not been followed. A new permit was approved, and the court upheld it in October 2018.","Then, in July 2019, when construction was about to restart, thousands of people gathered at the base of the access road. Native Hawaiian elders, called kūpuna, sat in the road to block it. On 17 July 2019, police arrested 33 of them, many in their seventies and eighties, some carried away in wheelchairs. Pictures of elders being arrested for peacefully defending their sacred mountain spread across the world. The protest camp grew into a gathering place for Hawaiian language, dance and teaching, and it stayed for months. In December 2019, with no construction starting, the state reopened the road and police withdrew.","Since then, things have slowly changed. In 2023, a new state authority began a five-year process to take over the management of Maunakea, with Native Hawaiian members on its board and the idea that culture, nature and science should share control of the mountain. In 2024, the TMT's project manager publicly apologized for having 'contributed to division in the community'. Some older telescopes on the summit are being taken down and their sites restored. And in 2025, the United States National Science Foundation chose to support a different giant telescope in Chile instead of the TMT, leaving its future very uncertain.","It is important to know that people do not all agree. Some Native Hawaiians support astronomy on Maunakea and point out that their own ancestors were among the greatest sky-watchers in history, navigating thousands of kilometers of ocean by the stars. Others oppose any new building on the summit. The lesson is not that science and culture must be enemies. It is that discovering the universe does not give anyone the right to ignore the people who live on the land below it."]},{"heading":"Expensive Oops and Sad Goodbyes","paragraphs":["Big telescopes are some of the most complicated machines humans have ever built, and complicated machines can go wrong in spectacular ways.","The most famous mistake belongs to the Hubble Space Telescope. You read in Part 16 how its main mirror was polished beautifully but to slightly the wrong shape, so its first pictures came back blurry in 1990. The trouble that followed was not only scientific. An investigation called the Allen Commission found that a testing device had been put together with one lens about 1.3 millimeters out of place, and it blamed weak checking by the mirror's maker and by NASA, which had relied on a single test. Politicians asked whether NASA could be trusted with taxpayers' money. Comedians made jokes about it. Then came the happy ending: the 1993 repair mission fixed the eyesight, and Hubble became one of the most loved scientific instruments of all time. A spare mirror made by the Kodak company, which was never used, now sits in the Smithsonian's National Air and Space Museum.","The James Webb Space Telescope, from Part 18, had a different kind of trouble: its price kept growing. In the 1990s, early ideas for the telescope talked about a cost of around 500 million dollars. By 1999 the planners hoped to launch in 2007 for about 1 billion dollars. But a giant folding gold mirror that works at minus 230 degrees Celsius proved much harder to build than expected. The launch date slipped again and again, and the cost climbed. In 2010 the science magazine Nature called it 'the telescope that ate astronomy', because its huge budget was swallowing money that might have gone to other projects.","In July 2011, a committee of the United States House of Representatives proposed cancelling the telescope altogether, calling it billions of dollars over budget and badly managed. Astronomers, engineers and supporters in Congress fought back, and in November 2011 Congress saved the project, but put a limit on how much more it could cost. More problems followed, including a sunshield that tore during a practice unfolding in 2018. In the end, Webb launched on Christmas Day 2021 for a total of almost 10 billion dollars, about twenty times the earliest guesses. It works brilliantly, but scientists still debate how to keep future giant projects from growing out of control.","And sometimes, a great telescope simply dies. The Arecibo Telescope in Puerto Rico was built in a natural sinkhole in the hills and opened in 1963. Its dish was 305 meters across, and for more than fifty years it was the largest single-dish radio telescope in the world. It was first planned to study the upper atmosphere as part of a defense research program, but it became a scientific giant. Its radar showed in 1965 that Mercury spins once every 59 days, not 88 as people had thought. It found the first pulsar orbiting another star, a discovery that later earned a Nobel Prize, and it helped find the first planets ever confirmed around another star, circling a pulsar, in the early 1990s. In 1974 it beamed a famous coded picture-message toward a star cluster 25,000 light-years away.","Arecibo's instrument platform, weighing about 900 tons, hung about 140 meters above the dish from thick steel cables strung between three concrete towers. In 2017, Hurricane Maria damaged part of the telescope. Then, on 10 August 2020, one cable slipped out of its socket and tore a 30-meter gash in the dish. On 7 November 2020, a main cable snapped. Engineers decided the structure was too dangerous to repair, and on 19 November the National Science Foundation announced it would be carefully taken down. It never got the chance. On the morning of 1 December 2020, the remaining cables gave way and the giant platform crashed into the dish below. Thankfully, nobody was hurt, because the area had already been cleared. For many people in Puerto Rico, where Arecibo was a great source of pride, it felt like losing a friend. In 2022, the foundation decided not to rebuild a telescope there, but to turn the site into a center for science education."]},{"heading":"Who Gets the Credit?","paragraphs":["In science, the glory often lands on just one or two names, even when others did key work. The best-known modern example is Jocelyn Bell Burnell. In 1967 she was a 24-year-old PhD student at the University of Cambridge, helping to build a radio telescope made of more than a thousand posts and lots of wire spread over a field. Her job included checking the telescope's output, which came out as wiggly ink lines on paper charts, hundreds of meters of it. On 28 November 1967 she confirmed that a strange 'bit of scruff' she had noticed weeks earlier was a signal pulsing with amazing regularity, about once every 1.33 seconds. It was the first pulsar, a spinning, collapsed star. In 1974, the Nobel Prize in Physics went to her supervisor, Antony Hewish, and to Martin Ryle. Bell Burnell was not included.","Many scientists, including the famous astronomer Fred Hoyle, criticized the decision. Bell Burnell herself responded with remarkable generosity. In 1977 she said it would 'demean Nobel Prizes if they were awarded to research students, except in very exceptional cases, and I do not believe this is one of them.' Later in life she also said that being a student and a woman probably lowered her standing in the eyes of others at the time. She went on to a long, distinguished career, and in 2018 she won a special Breakthrough Prize worth 3 million dollars. She gave every penny away to set up a fund, run by the Institute of Physics, that helps women, students from under-represented ethnic groups and refugees train to become physics researchers.","Go back a century and you find the Harvard computers from Part 12. Edward Pickering, director of Harvard College Observatory, hired more than eighty women to study and measure tens of thousands of glass photographic plates of the sky. They were usually paid about 25 to 50 cents an hour, around what an unskilled worker earned and much less than a man would have been paid for the same job. That meant Pickering could afford more of them. Williamina Fleming, who began as a maid in Pickering's house, classified about 10,000 stars and became curator of Harvard's photographs. Annie Jump Cannon built the star-sorting system still used today, but it became known as the Harvard system, not the Cannon system. Antonia Maury's work was not always published under her own name.","Henrietta Swan Leavitt discovered the rule linking how fast a Cepheid star pulses to how bright it really is, the cosmic measuring stick that later let Edwin Hubble prove other galaxies exist. Her famous 1912 result was published in a short Harvard circular signed by Pickering, with a note saying Leavitt had prepared it. She died of cancer in 1921. A few years later, a Swedish mathematician wrote to Harvard hoping to nominate her for a Nobel Prize, not knowing she had already died; the prize cannot be given after death. Cecilia Payne, who in 1925 showed that stars are made mostly of hydrogen and helium, was persuaded by a senior astronomer to call her result 'almost certainly not real' in her thesis. A few years later, that same astronomer reached the same conclusion himself.","Even earlier, Caroline Herschel, from Part 9, discovered comets and nebulae and was paid a salary by King George III from 1787, making her the first woman known to be paid for scientific work. She was often described as her brother's helper, yet she won the Royal Astronomical Society's Gold Medal in 1828. In 1835, she and the mathematician Mary Somerville became the society's first women honorary members. Telling these stories properly today is not about blaming people from the past. It is about getting the history right, and making sure the next discoverer gets the credit she or he deserves."]},{"heading":"Telescopes That Keep Secrets","paragraphs":["Remember the very first telescope patent in 1608? The Dutch government was interested in Hans Lipperhey's device for one big reason: war. The Dutch were fighting for independence from Spain, and a tube that let a lookout see enemy ships or soldiers before they came close was a precious military secret. The government paid Lipperhey to make more, but the idea leaked out within months, because once people knew two lenses in a tube could do the trick, anyone with spectacle lenses could copy it. Commanders have carried telescopes ever since, from sailing warships to submarine periscopes.","Today, some of the most powerful telescopes ever built point not out at the universe, but down at the Earth. These are spy satellites. In 1960, the United States recovered the first photographs from a secret satellite program called Corona. The satellite took pictures on film, and capsules full of exposed film dropped back through the atmosphere on parachutes, where aircraft tried to snag them in midair. The program was kept secret for decades; its images were only made public in 1995.","In December 1976, the United States launched the first KH-11 satellite, which used electronic sensors instead of film and could send pictures back to the ground almost immediately. Few details have ever been officially released, but these satellites are believed to be similar in size and shape to the Hubble Space Telescope, with main mirrors thought to be roughly 2.4 meters across or a little larger. In 2019 a photo believed to be from one of these satellites, showing a damaged rocket launch pad in Iran, was posted publicly by the US president, and experts were amazed at how sharp it was.","Here is a surprising twist. In 2011 and 2012, the National Reconnaissance Office, the American agency that runs spy satellites, gave NASA two spare telescopes it no longer needed, each with a 2.4-meter mirror, the same size as Hubble's. One of them became the heart of the Nancy Grace Roman Space Telescope, which you will meet in the next part. A telescope first built to keep secrets will instead spend its life sharing discoveries with the whole world.","That might be the best summary of this whole chapter. Telescopes have been used for war and for wonder, built with care and with carelessness, celebrated and protested. Each problem has taught people something: to test more carefully, manage money better, share credit fairly, protect the dark sky and listen to the people whose land lies beneath the domes. Despite all the trouble, the biggest telescopes in history are being built right now, and the last part of our story looks ahead to them, and back at the long road that brought us here."]}],"deepDive":"How much do satellite streaks and skyglow actually hurt astronomy? Astronomers measure brightness on the magnitude scale, where every 5 magnitudes means a factor of 100 in brightness, and bigger numbers mean fainter objects. A truly dark, natural sky glows at about 22 magnitudes per square arcsecond; a suburban sky might be 19 or 20, and a city center 17 or brighter. That sounds like a small difference, but 22 versus 17 is a factor of 100. Since a faint galaxy must be detected against this background, the brighter the sky, the longer you must expose to reach the same depth, and for the faintest targets an observatory near a city would need many times more telescope time to do what a dark site does in one night. That is why professional observatories retreat to remote deserts and mountaintops, and why places like Chile and Hawaii protect their skies with lighting laws. Satellites add a different problem. The first Starlink satellites were easily visible to the naked eye from dark sites, especially soon after launch. After astronomers raised concerns, darkened and shaded designs cut the brightness by roughly 0.8 to 1 magnitude or more, and later models with mirror-like surfaces reached about one-fifth of the original brightness. Astronomers at international workshops have suggested that satellites at around 550 km should ideally be fainter than about magnitude 7, too dim for the naked eye and less likely to saturate camera pixels. The real issue is scale: a small number of streaks can be masked, but tens of thousands of satellites mean a growing share of wide-field twilight images will be crossed, and every masked stripe is lost data. Radio astronomy faces a parallel challenge. Rules agreed through the International Telecommunication Union protect a few narrow frequency bands for radio astronomy, but leakage outside a satellite's intended frequencies, from onboard electronics, is not well covered by older rules. Debates continue over who should pay for mitigation, whether limits should be voluntary or legally required, and how to balance global internet access with humanity's shared view of the sky. Historians note that this is an old pattern in a new form: from Galileo's trial to Maunakea, the telescope's story has always been entangled with power, money and whose values decide how a shared resource is used.","funFact":"In 2015, astronomers finally solved the mystery of strange radio bursts called perytons at Australia's Parkes radio telescope: they came from staff opening the observatory's microwave oven door before it had finished heating their lunch.","check":{"q":"What happened to the Arecibo radio telescope on 1 December 2020?","a":"Its cables failed and its huge instrument platform fell into the dish","wrong":["It was shut down to make room for the Thirty Meter Telescope","It was moved by ship to Chile","It was destroyed by a volcanic eruption"]},"sources":[{"title":"Light pollution","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Light_pollution"},{"title":"Starlink (impact on astronomy)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Starlink"},{"title":"Thirty Meter Telescope protests","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Thirty_Meter_Telescope_protests"},{"title":"James Webb Space Telescope","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/James_Webb_Space_Telescope"},{"title":"Arecibo Telescope","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Arecibo_Telescope"},{"title":"Jocelyn Bell Burnell","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Jocelyn_Bell_Burnell"},{"title":"Harvard Computers","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Harvard_Computers"},{"title":"KH-11 KENNEN","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/KH-11_KENNEN"}],"photos":[{"src":"img/deep/telescope/19-1.jpg","alt":"Diagonal streaks from a train of Starlink satellites cross a telescope image of a galaxy group, May 2019.","file":"Trails made by Starlink satellites (iau-ann19035a).jpg","url":"https://commons.wikimedia.org/wiki/File:Trails_made_by_Starlink_satellites_(iau-ann19035a).jpg","author":"Victoria Girgis/Lowell Observatory","license":"CC BY 4.0"},{"src":"img/deep/telescope/19-2.jpg","alt":"Telescope domes along the snowy summit ridge of Maunakea, Hawaii, about 4,200 metres high.","file":"Mauna Kea Eastern Telescopes.jpg","url":"https://commons.wikimedia.org/wiki/File:Mauna_Kea_Eastern_Telescopes.jpg","author":"Generic1139","license":"CC BY 4.0"},{"src":"img/deep/telescope/19-3.jpg","alt":"The broken Arecibo dish in December 2021, a year after its instrument platform fell; only the three towers remain.","file":"Arecibo Telescope, December 2021.jpg","url":"https://commons.wikimedia.org/wiki/File:Arecibo_Telescope,_December_2021.jpg","author":"Tedder","license":"CC BY-SA 4.0"}],"words":4376},{"n":20,"title":"Tomorrow's Telescopes and the Big Picture","when":"Today – 2040s","summary":"Right now, people are building the biggest telescopes in history, with mirrors as wide as a sports field is long. Some will hunt for signs of life on faraway planets, and some do not use light at all. The story that began with a tiny Dutch spyglass is still going, and you can be part of it tonight.","sections":[{"heading":"The Biggest Eye Ever Built","paragraphs":["Picture a bare, brown mountain in the Atacama Desert of northern Chile, one of the driest places on Earth. It is called Cerro Armazones, and it stands 3,046 meters high. A few years ago, workers sliced about 18 meters off its summit, moving roughly 220,000 cubic meters of rock, to make a flat platform the size of several football fields. On that platform, the European Southern Observatory, or ESO, an organization supported by more than a dozen countries, is building the Extremely Large Telescope, the ELT. When it is finished, it will be the largest telescope for visible and infrared light the world has ever seen.","Its main mirror is 39 meters across. That is wider than a basketball court is long, and about sixteen times wider than Hubble's mirror. No single piece of glass could ever be made that big; it would sag and crack under its own weight. So, like the Keck telescopes from Part 17, the ELT's mirror is built from pieces: 798 hexagonal segments, each about 1.45 meters wide, fitted together like a giant honeycomb. Together they form a collecting surface of about 978 square meters, more than 200 times the collecting area of Hubble's mirror.","Making 798 separate mirrors behave like one perfect mirror is an amazing feat. The segments must line up with an accuracy of a few tens of nanometers. A nanometer is a billionth of a meter, so this is thousands of times thinner than a human hair. To keep them in line, 4,608 tiny edge sensors constantly measure how each segment sits compared with its neighbors, and motors behind the segments nudge them back into place as the telescope tilts, the wind blows and the temperature changes. Even the glass is special: about 140 tonnes of a glass-ceramic called Zerodur, which hardly grows or shrinks when it warms or cools.","The ELT actually uses five mirrors to bounce and fold the light before it reaches the cameras. One of them, called M4, is a thin, flexible mirror that can change shape very quickly, pushed by thousands of small actuators behind it. This is adaptive optics, the twinkle-cancelling trick from Part 17, built right into the telescope itself. With it, the ELT should produce pictures about 15 times sharper than Hubble's. It will collect about 100 million times more light than a human eye, and roughly ten times more than the biggest optical telescopes working today.","All of this will sit inside a dome about 80 meters tall, as high as a 25-story building, and about 93 meters wide. The dome alone weighs around 6,100 tonnes, and it must still turn smoothly to follow the stars. ESO's budget for the project is about 1.45 billion euros. Technical first light, the moment light first travels through the whole telescope, is planned for about 2029, with science observations to follow around 2030. Like every big plan, those dates could change.","What will it look for? Astronomers hope the ELT will take pictures of planets around nearby stars and study their atmospheres, perhaps spotting gases that could hint at life. It will study the first galaxies that formed after the Big Bang, measure how the expansion of the universe is changing, and watch stars orbiting the black hole at the center of our Milky Way in finer detail than ever. ESO even says it could become the first telescope to find evidence of life beyond our solar system. That is a big claim, but it shows how far we have come from Galileo's few-centimeter lens."]},{"heading":"Seven Giant Eyes and a Telescope Without a Home","paragraphs":["The ELT is not the only giant on the way. Several hundred kilometers to the south, at Las Campanas Observatory in Chile, at about 2,500 meters, an international team is building the Giant Magellan Telescope, or GMT. It takes a completely different approach to the problem of making a huge mirror.","Instead of hundreds of small segments, the GMT uses seven enormous round mirrors, each 8.4 meters across: one in the middle and six around it, like the petals of a flower. Together they work as a single telescope about 25.4 meters wide, with a collecting area of about 368 square meters. Each mirror is one solid piece of glass, made in a remarkable workshop at the University of Arizona called the Richard F. Caris Mirror Lab, which is tucked underneath the east side of the university's football stadium.","The way these mirrors are made is wonderful. Workers pack tonnes of glass chunks into a mold with a honeycomb pattern inside, so the finished mirror will be strong but much lighter than a solid block. Then the whole furnace slowly spins while it heats to over 1,100 degrees Celsius. As the glass melts, the spinning pushes it outward and upward at the edges, so it naturally forms a curved bowl shape, close to the shape the mirror needs. This saves months of grinding. After cooling slowly for months, each mirror is polished for years until its surface is accurate to a tiny fraction of the wavelength of light. The first GMT mirror was cast in 2005, and the seventh in 2023. The project's cost is estimated at about 2 billion dollars, and its builders hope it will be working sometime in the 2030s.","The third giant has had a much rougher road. The Thirty Meter Telescope, which you met in the last part, was designed with a mirror of 492 hexagonal segments, and it was supposed to be built on Maunakea in Hawaii. Construction has been stopped since 2015 because of protests and legal battles. In June 2025, the United States National Science Foundation decided to put its support behind the Giant Magellan Telescope rather than the TMT, which left the TMT's future seriously in doubt. A backup site at the Roque de los Muchachos Observatory on La Palma in Spain's Canary Islands has been discussed for years, and in 2025 Spain offered a large sum of money to bring the telescope there, but no final decision on its fate had been made at the time this was written.","Why build several giants instead of one? Partly because the northern and southern skies are different: some of the most exciting objects, like the center of our galaxy and the Magellanic Clouds, are best seen from the Southern Hemisphere. Partly because different designs bring different strengths. And partly because, as in every age of telescope history, there is a race. Since Galileo improved his first spyglass, astronomers have always wanted the next telescope to see a little fainter and a little sharper than the last one."]},{"heading":"New Eyes in Space and in the Outback","paragraphs":["Some of tomorrow's telescopes have already arrived. On 30 August 2026, a Falcon Heavy rocket launched the Nancy Grace Roman Space Telescope, named after the NASA astronomer known as the 'mother of Hubble' from Part 16. Its main mirror is 2.4 meters across, the same size as Hubble's, and it is one of the two spare mirrors donated to NASA by the spy-satellite agency you read about in Part 19. By late October 2026, Roman was in the final stages of testing, called commissioning, far beyond the Moon in the same region of space as JWST, near the L2 point.","Roman's superpower is width. Its main camera, the Wide Field Instrument, has about 300 megapixels and sees an area of sky at least 100 times larger than Hubble's main camera in a single shot. Where Hubble looks at the universe through a drinking straw, Roman looks through a window. During its mission, it could measure light from around a billion galaxies, helping scientists study dark energy, the mysterious something that is making the expansion of the universe speed up. It will also hunt for planets in a clever way called microlensing: when a star with a planet passes in front of a more distant star, its gravity acts like a lens and briefly brightens the background star, and a planet adds a tiny extra blip. Roman also carries a coronagraph, a device that blocks a star's glare to photograph faint planets beside it, as a test for future missions.","Meanwhile, on the ground, the biggest radio telescope project ever attempted is rising in two countries at once. The Square Kilometre Array, or SKA, has its headquarters at Jodrell Bank in England, where Bernard Lovell's great dish from Part 15 still stands. Construction officially began on 5 December 2022.","In the remote outback of Western Australia, on the traditional lands of the Wajarri people, SKA-Low is being built from about 131,000 antennas, each about two meters tall and shaped a bit like a spiky metal Christmas tree. They have no moving parts at all; computers combine their signals to point the telescope electronically at different parts of the sky. In March 2025, using just over a thousand of these antennas, SKA-Low produced its first picture of the sky. Meanwhile, in the dry Karoo region of South Africa, SKA-Mid will have around 200 dishes, including the 64 dishes of an earlier telescope there called MeerKAT.","Why put it in such empty places? Remember the radio noise problem from Part 19. These sites are among the radio-quietest places on Earth, and they also have an excellent view of the center of the Milky Way. The SKA will map the faint radio glow of hydrogen gas in about a billion galaxies, test Einstein's theory of gravity using pulsars, and try to see the era when the very first stars switched on. Its computers will have to handle enormous floods of data. If everything goes to plan, the first phase should be doing science around the early 2030s."]},{"heading":"Dream Machines: Looking for Life and Hiding Behind the Moon","paragraphs":["Every ten years, American astronomers get together through the National Academies of Sciences to agree on their biggest wishes for the coming decades. Their 2020 report, called Astro2020, named one dream above all: a large space telescope able to look at Earth-like planets around other stars and search them for signs of life. NASA now calls this idea the Habitable Worlds Observatory.","The goal is breathtaking. The telescope would try to take direct pictures of at least 25 possibly habitable planets, rocky worlds orbiting at the right distance from their stars for liquid water. Then it would split each planet's faint light into a spectrum, the rainbow barcode you learned about in Part 12, to look for gases such as oxygen and methane. On Earth, those gases are pumped into the air in large amounts by living things. Finding them together on another world would not prove life exists there, but it would be one of the most exciting clues in history.","The challenge is enormous. In visible light, an Earth-like planet is roughly ten billion times fainter than its star, and from many light-years away it sits extremely close to that star in the sky. It is like trying to spot a firefly sitting next to a lighthouse from thousands of kilometers away. To do it, the telescope will need a mirror perhaps 6 to 8 meters across and an incredibly precise coronagraph, or a separate starshade flying far in front of it, to block the star's glare. Its mirror must stay steady to a fraction of the width of an atom during each observation.","Right now, the Habitable Worlds Observatory is still a plan, not a machine. NASA has been developing the technology since 2023, and a launch is imagined for the 2040s, perhaps on one of the giant new rockets being built today. Its cost has been estimated at 11 billion dollars or more, and in 2026 the US government's budget request proposed cutting its funding sharply, so its future depends on decisions still to be made. Like the Hubble and Webb telescopes before it, it may take decades of patience and argument to build.","Other dreamers are looking at the Moon. Radio waves longer than about 10 meters, or frequencies below about 30 megahertz, are blocked or scrambled by a layer of Earth's upper atmosphere called the ionosphere, so they can hardly be studied from the ground. Those long waves carry information about the cosmic Dark Ages, the time after the Big Bang before the first stars lit up. The far side of the Moon, which always faces away from Earth, is shielded from all our radio chatter by about 3,500 kilometers of rock. It may be the quietest place in the inner solar system.","One NASA-funded concept, the Lunar Crater Radio Telescope, imagines robots landing on the far side and stretching a giant wire-mesh dish inside a crater more than 3 kilometers wide, a little like a lunar version of Arecibo. Rovers would unroll and anchor the mesh, and a receiver would hang above it. The idea has received early-stage study money from NASA's program for bold, futuristic concepts. Smaller far-side radio experiments have already flown or are being prepared by several countries. A real radio observatory on the Moon is still a dream, but so was a telescope in space when Lyman Spitzer wrote about it in 1946."]},{"heading":"Telescopes With No Glass at All","paragraphs":["For four hundred years, every telescope in this story collected some kind of light, from radio waves to gamma rays. But the universe also sends us other messengers, and scientists have built strange new instruments to catch them. They are not telescopes in the usual sense, but they do the same job: they let us sense the cosmos in a new way.","Einstein predicted in 1916 that when very heavy objects speed around each other, they send out ripples in space itself, called gravitational waves. As a wave passes, it stretches space one way and squeezes it the other, back and forth, by an unbelievably small amount. For decades, nobody could measure anything so tiny. Then came LIGO, the Laser Interferometer Gravitational-Wave Observatory, with two detectors far apart in the United States, one in Hanford, Washington, and one in Livingston, Louisiana.","Each LIGO detector is shaped like a giant letter L, with two arms 4 kilometers long. A laser beam is split in two and sent down both arms, bounced back by mirrors, and then recombined. Normally the two beams cancel each other out perfectly. But if a gravitational wave passes, one arm gets a tiny bit longer while the other gets a tiny bit shorter, and a flicker of light leaks through. How tiny? About a thousandth of the width of a proton, one of the particles inside an atom's center.","On 14 September 2015, both detectors felt a wobble, with the Livingston detector catching it about 7 milliseconds before Hanford. The signal matched the death spiral of two black holes, about 36 and 29 times the mass of our Sun, colliding about 1.4 billion light-years away and merging into one. In a fraction of a second, the collision turned about three Suns' worth of mass into gravitational-wave energy. The discovery was announced in February 2016, and in 2017 Rainer Weiss, Barry Barish and Kip Thorne shared the Nobel Prize in Physics for it. Later that year, detectors caught waves from two colliding neutron stars, and ordinary telescopes around the world turned to the spot and saw the explosion too. Astronomers call this teamwork multi-messenger astronomy.","Another strange telescope is buried in the ice at the South Pole. IceCube, finished in December 2010 and run by the University of Wisconsin-Madison with partners worldwide, hunts for neutrinos, ghostly particles so tiny and shy that trillions pass harmlessly through your body every second. To catch a few, scientists drilled 86 holes deep into the Antarctic ice with hot water and lowered strings of light sensors, 60 on each string, between about 1,450 and 2,450 meters below the surface. Together they watch about a cubic kilometer of crystal-clear ancient ice. Very rarely, a neutrino bumps into the ice and makes a faint flash of blue light that the sensors can see.","In 2017, IceCube caught a high-energy neutrino that was traced back to a blazar, a galaxy with a giant black hole shooting a jet almost straight toward us, nearly 4 billion light-years away. In 2023, it made the first map of the Milky Way in neutrinos instead of light. An upgrade adding new sensor strings was completed in early 2026, and scientists are planning a much larger version. Telescopes made of lasers and ice would have astonished Galileo, but the purpose is the same as his: to notice what others cannot."]},{"heading":"From a Three-Times Spyglass to a 39-Meter Giant","paragraphs":["Let's stand back and look at the whole story at once. It is a long chain of problems and solutions, each step fixing something the last step could not.","In 1608, Dutch spectacle makers put two lenses in a tube and made things look about three times bigger. Galileo improved it to about 20 times and turned it on the sky, but his telescope showed only a tiny patch at once, so Kepler designed a better arrangement. Lenses blurred colors into rainbows, so astronomers built absurdly long telescopes, and then Newton built a mirror telescope that avoided the rainbow problem completely. Lens makers fought back with achromatic lenses made from two kinds of glass, and Fraunhofer turned them into precision instruments.","Next came the problem of faintness. The Herschels and Lord Rosse built ever bigger mirrors to gather more light. Metal mirrors tarnished, so silver-coated glass replaced them. Big lenses sagged, so mirrors won the size race. Eyes forget and get tired, so cameras took over, collecting light for hours. Spectroscopes split that light into barcodes that told us what stars are made of and how fast they move. Giant mirrors on mountaintops, like Mount Wilson and Palomar, revealed that the universe is filled with galaxies and is expanding.","Then the problem was our own air, which blurs and blocks. Engineers answered in two ways: lift telescopes above the air into space, like Hubble and JWST, and fight the air from the ground with adaptive optics and segmented mirrors, like Keck and the ELT. Our eyes see only a thin slice of light, so we built radio dishes, X-ray satellites and infrared observatories to see the rest. And now, with gravitational waves and neutrinos, we are learning to sense the universe without light at all.","Think about the numbers. Galileo's best telescopes had front lenses only a few centimeters across. The ELT's mirror will be 39 meters across, more than a thousand times wider, with a collecting area over a million times larger. A dark-adapted human eye can see a few thousand stars. Telescopes have now shown us that there are hundreds of billions of stars in our galaxy alone, and hundreds of billions of galaxies, perhaps far more, in the observable universe. Each step took clever ideas, patient craftspeople, a lot of money, many mistakes and, as Part 19 showed, plenty of arguments. But each step also changed how humans understand their place in the universe."]},{"heading":"Your Turn to Look Up","paragraphs":["Here is the most wonderful part of the whole story: you do not need a giant mirror in Chile to start. You can see much of what Galileo saw, from your own backyard or balcony, with a simple pair of binoculars. Many binoculars are labelled with two numbers, like 7x50 or 10x50. The first number is the magnification, and the second is the width of each front lens in millimeters. A 10x50 pair magnifies ten times and gathers about fifty times more light than your eye alone, which is better than Galileo's first telescope. Lean against a wall or a fence to hold them steady.","Start with the Moon. The best time is not full moon but when it is a half moon or a crescent. Look along the terminator, the line between the bright and dark parts. That is where the Sun is rising or setting on the Moon, and the long shadows make craters and mountains pop out, just as Galileo saw in 1609. Then find Jupiter, which looks like a very bright, steady star that does not twinkle much. Hold your binoculars still, and you may see up to four tiny points of light lined up beside it. Those are Io, Europa, Ganymede and Callisto, the same moons Galileo discovered in January 1610. Look again the next night, and you will see they have moved.","If you are somewhere dark, sweep your binoculars slowly along the Milky Way, and its glowing cloud will break up into countless stars, just as Galileo described. Look at the Pleiades, a little cluster of stars in the constellation Taurus, and see dozens of stars where your eyes saw six or seven. You can join a local astronomy club, many of which hold free star parties where people share their telescopes, or visit a public observatory or planetarium. Some amateurs still make real discoveries, from comets to exploding stars.","Just remember the one golden rule from Part 5: never point binoculars or a telescope anywhere near the Sun unless an expert has fitted a proper certified solar filter. Ask an adult to help you check the sky charts, dress warmly, and give your eyes about twenty minutes in the dark to adjust.","Four hundred years ago, a few curious people in the Netherlands, England and Italy held two lenses in a line and looked up. Everything in this Deep Dive grew from that simple act of curiosity. The universe is still out there, full of things nobody has ever seen. So tonight, if the sky is clear, go outside, let your eyes get used to the dark, and look up."]}],"deepDive":"Why do astronomers keep building bigger mirrors? Two numbers explain almost everything. The first is light-gathering power, which grows with the area of the mirror, that is, with the square of its diameter. The ELT's 39-meter mirror has roughly 260 times the area of Hubble's 2.4-meter mirror, and the actual collecting area, 978 square meters, is still more than 200 times Hubble's once gaps and the central holes are counted. For faint targets, the time needed to reach a given signal falls roughly in proportion to the area. The second is resolution. Because light behaves like a wave, even a perfect telescope blurs a point of light into a tiny disc. The smallest angle a telescope can separate is roughly 1.22 times the wavelength divided by the diameter. For Hubble at a visible wavelength of 500 nanometers, that works out to about 0.05 arcseconds. For the ELT at an infrared wavelength of 2.2 micrometers, it is about 0.014 arcseconds, provided adaptive optics can remove the blur of the atmosphere. Better resolution is doubly valuable: it reveals finer detail, and it concentrates a star's light into a smaller spot, so faint objects stand out more clearly against the sky background. Both effects matter for exoplanets. An Earth-like planet orbiting a Sun-like star 10 parsecs (about 33 light-years) away sits only about 0.1 arcseconds from its star and is roughly ten billion times fainter in visible light. To separate the two, a telescope needs enough resolution and an optical system able to suppress the starlight by that enormous factor. Ground-based giants like the ELT will probably first study planets around small, cool red dwarf stars, where the contrast is less extreme in infrared light. Space telescopes like the proposed Habitable Worlds Observatory aim at true Earth analogs around Sun-like stars, using ultra-stable mirrors and coronagraphs that must control the shape of the light at the level of tens of picometers. Engineers and scientists still debate the best route: bigger segmented mirrors that unfold in space, coronagraphs versus external starshades, and how to balance ambition against cost after the long and expensive road to JWST. Whatever is chosen, the logic is the same one that drove Galileo from a 3-times spyglass to a 20-times one: see fainter, see sharper.","funFact":"The giant mirrors for the Giant Magellan Telescope are cast in a slowly spinning furnace in a laboratory tucked underneath the University of Arizona's football stadium.","check":{"q":"How many hexagonal segments make up the main mirror of the Extremely Large Telescope?","a":"798","wrong":["36","18","7"]},"sources":[{"title":"ELT Facts","publisher":"European Southern Observatory (ESO)","url":"https://elt.eso.org/about/facts/"},{"title":"Extremely Large Telescope","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Extremely_Large_Telescope"},{"title":"Giant Magellan Telescope","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Giant_Magellan_Telescope"},{"title":"Nancy Grace Roman Space Telescope","publisher":"NASA Science","url":"https://science.nasa.gov/mission/roman-space-telescope/"},{"title":"Square Kilometre Array","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Square_Kilometre_Array"},{"title":"Habitable Worlds Observatory","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Habitable_Worlds_Observatory"},{"title":"First observation of gravitational waves","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/First_observation_of_gravitational_waves"},{"title":"IceCube Neutrino Observatory","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/IceCube_Neutrino_Observatory"}],"photos":[{"src":"img/deep/telescope/20-1.jpg","alt":"Bird's-eye view of the Extremely Large Telescope's giant round dome being built on Cerro Armazones, Chile, January 2022.","file":"The ELT's dome under construction (armazones 2022 5).jpg","url":"https://commons.wikimedia.org/wiki/File:The_ELT%27s_dome_under_construction_(armazones_2022_5).jpg","author":"G. Hüdepohl (atacamaphoto.com)/ESO","license":"CC BY 4.0"},{"src":"img/deep/telescope/20-2.jpg","alt":"Two staff at the University of Arizona's Caris Mirror Lab look up at the honeycomb back of a Giant Magellan Telescope mirror.","file":"Giant Magellan Telescope Primary Mirror Back Surface.tif","url":"https://commons.wikimedia.org/wiki/File:Giant_Magellan_Telescope_Primary_Mirror_Back_Surface.tif","author":"StudioDee10304","license":"CC BY-SA 4.0"},{"src":"img/deep/telescope/20-3.jpg","alt":"Aerial view of the LIGO Hanford gravitational-wave detector, with its two 4-kilometre arms forming an L in the desert.","file":"LIGO Hanford aerial 05.jpg","url":"https://commons.wikimedia.org/wiki/File:LIGO_Hanford_aerial_05.jpg","author":"LIGO Laboratory","license":"Public domain"}],"words":3943}],"words":82589};
